	public class EOSensitiveFormDataTable : DataTable
	{
		public EOSensitiveFormViewModel ParentViewModel { get; private set; }

		public EOSensitivePageWrapper Wrapper { get; private set; }

		public List<string> DependentVariables { get; private set; }

		public List<string> IndependentVariables { get; private set; }

		public bool IsCalculated { get; set; }

		public bool HasDataReady { get; private set; }

		public EOSensitiveFormDataTable(EOSensitiveFormViewModel parentViewModel)
		{
			if (parentViewModel == null)
			{
				throw new ArgumentNullException("parentViewModel");
			}
			ParentViewModel = parentViewModel;
			Wrapper = ParentViewModel.WrapperManager.CreatePageWrapper();
		}

		public void Update()
		{
			HasDataReady = Wrapper.BeginGetData(DataUpdateOption.ResetPointsAndClearCache);
			IList<string> dependentVariables = Wrapper.GetDependentVariables();
			DependentVariables = ((dependentVariables == null) ? new List<string>() : new List<string>(dependentVariables));
			IList<string> independentVariables = Wrapper.GetIndependentVariables();
			IndependentVariables = ((independentVariables == null) ? new List<string>() : new List<string>(independentVariables));
			base.Columns = new ReadOnlyCollection<DataColumn>(CreateColumns(DependentVariables, IsCalculated).ToList());
			base.Rows.Clear();
			if (base.GridControl != null)
			{
				base.GridControl.RefreshData();
			}
			foreach (string independentVariable in IndependentVariables)
			{
				DataRow dataRow = CreateRow();
				FillRow(dataRow, independentVariable);
				base.Rows.Add(dataRow);
			}
			Wrapper.EndGetData();
		}

		private void FillRow(DataRow row, string independentVariable)
		{
			foreach (DataColumn column in base.Columns)
			{
				string text = column.Tag as string;
				if (string.IsNullOrEmpty(text))
				{
					if (IsCalculated)
					{
						row[column] = new DataCellText
						{
							Value = GetVariableTextWithUnits(independentVariable)
						};
					}
					else
					{
						row[column] = new DataCellText
						{
							Value = independentVariable
						};
					}
				}
				else if (IsCalculated && HasDataReady)
				{
					object crossValue = Wrapper.GetCrossValue(text, independentVariable);
					if (crossValue is string)
					{
						string text2 = (string)crossValue;
						double result = 0.0;
						if (double.TryParse(text2, out result))
						{
							row[column] = DataRow.CreateDataCell(result);
						}
						else
						{
							row[column] = DataRow.CreateDataCell(text2);
						}
					}
					else
					{
						row[column] = DataRow.CreateDataCell(crossValue);
					}
				}
				else
				{
					row[column] = DataRow.CreateDataCell(string.Empty);
				}
			}
		}

		public void DoCalculation()
		{
			Wrapper.CalculateData();
			IsCalculated = true;
			Update();
		}

		private IEnumerable<DataColumn> CreateColumns(IEnumerable<string> dependentVariables, bool unitsIncluded)
		{
			List<DataColumn> list = new List<DataColumn>();
			list.Add(new DataColumn
			{
				IsFrozen = true,
				Width = 250.0,
				IsReadOnly = true
			});
			foreach (string dependentVariable in dependentVariables)
			{
				DataColumn dataColumn = null;
				dataColumn = ((!unitsIncluded) ? new DataColumn(dependentVariable) : new DataColumn(GetVariableTextWithUnits(dependentVariable)));
				dataColumn.IsReadOnly = true;
				dataColumn.Tag = dependentVariable;
				dataColumn.Width = 160.0;
				list.Add(dataColumn);
			}
			return list;
		}

		private string GetVariableTextWithUnits(string variable)
		{
			string variableUnits = Wrapper.GetVariableUnits(variable);
			if (!string.IsNullOrEmpty(variableUnits))
			{
				return $"{variable} [{variableUnits}]";
			}
			return variable;
		}
	}
