		public void CopyToClipboard(GridControlCopyEventArgs e)
		{
			DataColumn dataColumn = DataTable.Columns.FirstOrDefault();
			if (dataColumn != null)
			{
				e.ColumnPrefixes.Add(dataColumn, "#");
			}
			e.ClipboardContents.Add("AP_Text", ClipboardHelperNew.ConvertToStream(e.GenerateTextToCopy()));
			if (dataColumn != null)
			{
				e.ColumnPrefixes.Clear();
			}
		}

