		public EOVariableFormDataTable(EOVariableFormViewModel parentViewModel, StyleSheetInfo sheetInfo)
		{
			if (parentViewModel == null)
			{
				throw new ArgumentNullException("parentViewModel");
			}
			if (sheetInfo == null)
			{
				throw new ArgumentNullException("sheetInfo");
			}
			TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.EOVariableFormDataTable");
			ParentViewModel = parentViewModel;
			TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.ParentViewModel.WrapperManager.CreatePageWrapper");
			Wrapper = ParentViewModel.WrapperManager.CreatePageWrapper(sheetInfo);
			TimingDebugger.EndTimingBlock();
			SheetInfo = sheetInfo;
			base.Columns = new ReadOnlyCollection<DataColumn>(new List<DataColumn>());
			TimingDebugger.EndTimingBlock();
		}

		public override void Reset()
		{
			if (base.GridControl != null && base.Columns.Count > 0)
			{
				_lastSavedSettings = base.GridControl.SaveLayoutSettings();
			}
			base.Reset();
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				PostStatusMessage();
			});
		}

		protected override void OnCellValueChanged(IDataCell cell, object oldValue, object newValue)
		{
			TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.OnCellValueChanged");
			if (!IsUpdating && cell != null && KeyColumn != null && cell.Row[KeyColumn] != null)
			{
				try
				{
					int num = base.Rows.IndexOf(cell.Row);
					string engineName = EOVariableFormSettings.GetEngineName(cell.Column);
					CellValueUpdateResult cellValueUpdateResult = Wrapper.UpdateCellData(num + 1, engineName, TransformDataToSave(oldValue, cell.Column, cell.ValueType), TransformDataToSave(newValue, cell.Column, cell.ValueType));
					if (!cellValueUpdateResult.IsUpdateSucceeded)
					{
						string errorMessage = MessageHelper.GetErrorMessage(cellValueUpdateResult.ErrorNumber);
						if (!string.IsNullOrWhiteSpace(errorMessage))
						{
							MMMessageBox.Show(errorMessage, GridFormsResources.EOVariablePage_UpdateData_MessageHeader);
						}
					}
					else
					{
						if (engineName == "PHYSICAL_TYPE")
						{
							DataColumn index = cell.Row.DataTable.Columns.FirstOrDefault((DataColumn x) => string.Equals("UOM", ((EOVariableField)x.Tag).EngineName, StringComparison.InvariantCultureIgnoreCase));
							cell.Row[index].ItemsSource = null;
						}
						foreach (EOVariableFormDataTable formDataTable in ParentViewModel.FormDataTables)
						{
							formDataTable.DispatcherUpdate();
						}
					}
				}
				catch (Exception ex)
				{
					MMMessageBox.Show(Window.GetWindow(ParentViewModel.View as DependencyObject), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.EOVariablePage_UpdateData_MessageHeader);
				}
			}
			base.OnCellValueChanged(cell, oldValue, newValue);
			PostStatusMessage();
			TimingDebugger.EndTimingBlock();
		}

		public void DispatcherUpdate()
		{
			if (IsActive)
			{
				base.Dispatcher.BeginInvokeOnce(delegate
				{
					InternalUpdateData();
					_dataDirtyFlag = false;
				}, DispatcherPriority.Loaded);
			}
			else
			{
				_dataDirtyFlag = true;
			}
		}

		private void InternalUpdateData()
		{
			TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.InternalUpdateData");
			if (ParentViewModel.IsDataReadyToRender)
			{
				try
				{
					_updatingFlag++;
					TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.CreateFieldsForSavedSheet");
					List<DataColumn> list = CreateFieldsForSavedSheet().ToList();
					TimingDebugger.EndTimingBlock();
					bool flag = list.Count != base.Columns.Count;
					Point? currentActiveCellAsPoint = base.GridControl.GetCurrentActiveCellAsPoint();
					if (flag)
					{
						if (base.Columns.Count > 0)
						{
							_lastSavedSettings = base.GridControl.SaveLayoutSettings();
						}
						base.Rows.Clear();
						base.Columns = new ReadOnlyCollection<DataColumn>(list);
					}
					TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.Wrapper.GetRowCount");
					int rowCount = Wrapper.GetRowCount();
					TimingDebugger.EndTimingBlock();
					if (flag || base.Rows.Count != rowCount)
					{
						TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.UpdateDataRange");
						UpdateDataRange(rowCount);
						TimingDebugger.EndTimingBlock();
						TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.GridControl.RebindData");
						base.GridControl.RebindData();
						TimingDebugger.EndTimingBlock();
						if (currentActiveCellAsPoint.HasValue)
						{
							base.GridControl.SetCurrentActiveCellInPoint(currentActiveCellAsPoint.Value);
						}
						if (flag && base.Columns.Count > 0 && !string.IsNullOrEmpty(_lastSavedSettings))
						{
							base.GridControl.LoadLayoutSettings(_lastSavedSettings, LayoutOption.SortedColumns | LayoutOption.FilterHeaderVisibility | LayoutOption.ColumnWidth | LayoutOption.ColumnFilter);
						}
					}
					else
					{
						Wrapper.SaveRowData = true;
						RefreshData();
						Wrapper.SaveRowData = false;
					}
					EOVariableFormSettings.Apply(this);
				}
				finally
				{
					_updatingFlag--;
				}
			}
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				PostStatusMessage();
			});
			TimingDebugger.EndTimingBlock();
		}

		protected override void OnBoundToGridControl()
		{
			if (base.Columns == null || base.Columns.Count == 0)
			{
				base.GridControl.CoverText = GridFormsResources.EOVariablePage_NoDataToDisplay;
			}
			else
			{
				base.GridControl.CoverText = null;
			}
			base.OnBoundToGridControl();
		}

		protected override void OnFilteringChanged()
		{
			base.OnFilteringChanged();
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				PostStatusMessage();
			});
		}

		protected override IList<string> OnFilterOperandsQueried(DataColumn column)
		{
			try
			{
				TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.OnFilterOperandsQueried");
				if (!IsParameterGrid)
				{
					return Wrapper.GetAllValuesInColumn(((EOVariableDataColumn)column).WrapperFieldIndex, base.Rows.Count);
				}
				return base.OnFilterOperandsQueried(column);
			}
			finally
			{
				TimingDebugger.EndTimingBlock();
			}
		}

		protected override void OnRowValuesQueried(DataRow row)
		{
			int num = base.Rows.IndexOf(row);
			if (num >= 0)
			{
				Wrapper.SaveRowData = true;
				FillRowData(row, num);
				Wrapper.SaveRowData = false;
			}
			base.OnRowValuesQueried(row);
		}

		protected override IDataCell OnCellValueQueried(DataRow row, DataColumn column)
		{
			int num = base.Rows.IndexOf(row);
			if (num >= 0)
			{
				IList<EOVariableCellValue> rowDataAt = Wrapper.GetRowDataAt(num);
				if (rowDataAt != null)
				{
					EOVariableCellValue cellValue = rowDataAt[((EOVariableDataColumn)column).WrapperFieldIndex];
					return CreateCellData(cellValue, row, column);
				}
			}
			return base.OnCellValueQueried(row, column);
		}

		protected override void OnCellItemsSourceQueried(IDataCell cell)
		{
			try
			{
				TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.OnCellItemsSourceQueried");
				base.OnCellItemsSourceQueried(cell);
				if (cell == null || cell.IsItemsSourceLoaded)
				{
					return;
				}
				IList<string> cellItemsSource = Wrapper.GetCellItemsSource(base.Rows.IndexOf(cell.Row), ((EOVariableDataColumn)cell.Column).WrapperFieldIndex);
				if (string.Equals(EOVariableFormSettings.GetEngineName(cell.Column), "UOM", StringComparison.InvariantCultureIgnoreCase) || string.Equals(EOVariableFormSettings.GetEngineName(cell.Column), "BASEUOM", StringComparison.InvariantCultureIgnoreCase))
				{
					cell.ItemsSource = cellItemsSource.OrderBy((string x) => x);
				}
				else
				{
					cell.ItemsSource = cellItemsSource;
				}
			}
			finally
			{
				TimingDebugger.EndTimingBlock();
			}
		}

		protected override void OnColumnsVisibilityChanged()
		{
			if (!IsUpdating)
			{
				UpdateDataRange(base.Rows.Count);
				if (base.GridControl != null)
				{
					base.GridControl.InvalidateSorting();
				}
			}
			base.OnColumnsVisibilityChanged();
		}

		protected override object GetDirectCellValue(DataRow row, DataColumn column)
		{
			try
			{
				TimingDebugger.BeingTimingBlock("EOVariableFormDataTable.GetDirectCellValue");
				IDataCell dataCell = row[column];
				if (dataCell != null)
				{
					return dataCell.Value;
				}
				return DataColumn.ConvertStringToObject(Wrapper.GetValueAsStringOfCell(base.Rows.IndexOf(row), ((EOVariableDataColumn)column).WrapperFieldIndex), column.DefaultDataType);
			}
			finally
			{
				TimingDebugger.EndTimingBlock();
			}
		}

		public void UpdateExternalQueryString(string externalQueryString)
		{
			Wrapper.SetQueryString(externalQueryString);
			DispatcherUpdate();
		}

		public string GetExternalQueryString()
		{
			return Wrapper.GetQueryString();
		}

		private void FillRowData(DataRow row, int rowIndex)
		{
			IList<EOVariableCellValue> rowDataAt = Wrapper.GetRowDataAt(rowIndex);
			if (rowDataAt == null)
			{
				return;
			}
			for (int i = 0; i < base.Columns.Count; i++)
			{
				EOVariableDataColumn eOVariableDataColumn = base.Columns[i] as EOVariableDataColumn;
				if (eOVariableDataColumn.WrapperFieldIndex < rowDataAt.Count)
				{
					EOVariableCellValue cellValue = rowDataAt[eOVariableDataColumn.WrapperFieldIndex];
					row[eOVariableDataColumn] = CreateCellData(cellValue, row, eOVariableDataColumn);
				}
			}
		}

		private IDataCell CreateCellData(EOVariableCellValue cellValue, DataRow row, DataColumn fd)
		{
			Brush brush = null;
			brush = ((!(cellValue.BackgroundColor == Colors.Transparent)) ? new SolidColorBrush(cellValue.BackgroundColor) : ((!cellValue.IsManuallyChanged) ? Brushes.Transparent : ModifiedCellBackground));
			Brush brush2 = null;
			_ = cellValue.ForegroundColor;
			if (cellValue.ForegroundColor != Colors.Transparent)
			{
				brush2 = new SolidColorBrush(cellValue.ForegroundColor);
			}
			if (fd.DefaultDataType == typeof(bool) && !(cellValue.Value is bool))
			{
				if (cellValue.Value is int)
				{
					cellValue.Value = (int)cellValue.Value > 0;
				}
				else if (object.Equals(cellValue.Value, "0"))
				{
					cellValue.Value = false;
				}
				else if (object.Equals(cellValue.Value, "1"))
				{
					cellValue.Value = true;
				}
			}
			bool flag = cellValue.IsReadOnly;
			if (IsParameterGrid && !cellValue.IsReadOnly && fd.Tag is EOVariableField eOVariableField)
			{
				if (string.Equals(eOVariableField.EngineName, "VALUE", StringComparison.InvariantCultureIgnoreCase) || string.Equals(eOVariableField.EngineName, "UOM", StringComparison.InvariantCultureIgnoreCase))
				{
					DataColumn dataColumn = row.DataTable.Columns.FirstOrDefault((DataColumn x) => string.Equals(((EOVariableField)x.Tag).EngineName, "ACCESS", StringComparison.InvariantCultureIgnoreCase));
					if (dataColumn != null)
					{
						IDataCell dataCell = row[dataColumn];
						if (dataCell != null && string.Equals(dataCell.ValueAsString, "Read_Only", StringComparison.InvariantCultureIgnoreCase))
						{
							flag = true;
						}
					}
				}
				if (!flag && string.Equals(eOVariableField.EngineName, "UOM", StringComparison.InvariantCultureIgnoreCase) && IsCapeOpenParametersGrid)
				{
					flag = true;
				}
			}
			object value = cellValue.Value;
			bool isReadOnly = flag;
			IEnumerable itemsSource = cellValue.ItemsSource;
			int editorType = (cellValue.IsComboBox ? 3 : 0);
			Brush background = brush;
			Type defaultDataType = fd.DefaultDataType;
			string topRightWarningTooltip = cellValue.TopRightWarningTooltip;
			string bottomRightWarningTooltip = cellValue.BottomRightWarningTooltip;
			Brush foreground = brush2;
			return DataRow.CreateDataCell(value, isReadOnly, itemsSource, (CellUIType)editorType, cellValue, background, defaultDataType, topRightWarningTooltip, bottomRightWarningTooltip, null, null, null, foreground);
		}

		public string GlobaLizationColumnHeader(string header)
		{
			if (EOVariableForm.DataTableColumnDisplay.Keys.Contains(header))
			{
				return EOVariableForm.DataTableColumnDisplay[header];
			}
			return header;
		}

		[IteratorStateMachine(typeof(CreateFieldsForSavedSheetEnumerator))]
		private IEnumerable<DataColumn> CreateFieldsForSavedSheet()
		{
			return new CreateFieldsForSavedSheetEnumerator(-2)
			{
				iteratorOwner = this
			};
		}

		private object TransformDataToSave(object data, DataColumn column, Type cellValueType)
		{
			if (object.Equals(data, true))
			{
				if (string.Equals(EOVariableFormSettings.GetEngineName(column), "MARKED", StringComparison.InvariantCultureIgnoreCase))
				{
					return "1";
				}
				return "True";
			}
			if (object.Equals(data, false))
			{
				if (string.Equals(EOVariableFormSettings.GetEngineName(column), "MARKED", StringComparison.InvariantCultureIgnoreCase))
				{
					return "0";
				}
				return "False";
			}
			if (data == null)
			{
				if (cellValueType == typeof(double?) || cellValueType == typeof(double))
				{
					data = 0.0;
				}
				else if (cellValueType == typeof(int?) || cellValueType == typeof(int))
				{
					data = 0;
				}
			}
			return data;
		}

		public void PostStatusMessage()
		{
			if (base.GridControl == null)
			{
				return;
			}
			if (base.Columns.Count == 0)
			{
				ParentViewModel.PostStausMessage(null);
				return;
			}
			int num = 0;
			IEnumerable<DataRow> boundRows = base.GridControl.BoundRows;
			if (boundRows != null)
			{
				num = boundRows.Count();
			}
			string message = string.Format(GridFormsResources.EOVariablePage_StatusMessage, num);
			ParentViewModel.PostStausMessage(message);
		}

		public void InvalidateEOVariableFormSettings()
		{
			if (!_invalidateFormSettingsFlag)
			{
				_invalidateFormSettingsFlag = true;
				base.Dispatcher.BeginInvoke((Action)delegate
				{
					EOVariableFormSettings.Save(this);
					_invalidateFormSettingsFlag = false;
				}, DispatcherPriority.Loaded);
			}
		}
	}
	public static class EOVariableFormSettings
	{
		public static void Save(EOVariableFormDataTable table)
		{
			if (table == null)
			{
				throw new ArgumentNullException("table");
			}
			if (AllowSettings(table))
			{
				string text = GenerateSettingsFrom(table);
				if (!string.Equals(CaseFileSettings.Default.EOVariableFormSettings, text, StringComparison.InvariantCultureIgnoreCase))
				{
					CaseFileSettings.Default.EOVariableFormSettings = text;
					table.ParentViewModel.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EOVariableFormSettingsSavedEvent>().Publish(new EOVariableFormSettingsSavedEventArgs());
				}
			}
		}

		public static void Apply(EOVariableFormDataTable table)
		{
			if (table == null)
			{
				throw new ArgumentNullException("table");
			}
			if (!AllowSettings(table) || CaseFileSettings.Default.EOVariableFormSettings == GenerateSettingsFrom(table))
			{
				return;
			}
			try
			{
				table.IsApplyingEOVariableFormSettings = true;
				List<string> defaultDisplayColumns = GetDefaultDisplayColumns();
				foreach (DataColumn column in table.Columns)
				{
					if (defaultDisplayColumns.Contains(GetEngineName(column)))
					{
						column.Visibility = Visibility.Visible;
					}
					else
					{
						column.Visibility = Visibility.Collapsed;
					}
				}
				int num = 0;
				foreach (string header in defaultDisplayColumns)
				{
					DataColumn dataColumn = table.Columns.FirstOrDefault((DataColumn x) => string.Equals(GetEngineName(x), header, StringComparison.InvariantCultureIgnoreCase));
					if (dataColumn != null)
					{
						dataColumn.DisplayIndex = num++;
					}
				}
			}
			finally
			{
				table.IsApplyingEOVariableFormSettings = false;
			}
		}

		private static bool AllowSettings(EOVariableFormDataTable table)
		{
			if (table.ParentViewModel != null)
			{
				DataType? dataType = table.ParentViewModel.DataType;
				if (!dataType.HasValue)
				{
					return true;
				}
				if (dataType.Value == DataType.AcmVariable || dataType.Value == DataType.Variable)
				{
					return true;
				}
			}
			return false;
		}

		private static string GenerateSettingsFrom(EOVariableFormDataTable table)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (DataColumn item in from x in table.Columns
				where x.Visibility == Visibility.Visible
				orderby x.DisplayIndex
				select x)
			{
				if (stringBuilder.Length == 0)
				{
					stringBuilder.Append(GetEngineName(item));
				}
				else
				{
					stringBuilder.Append(',').Append(GetEngineName(item));
				}
			}
			return stringBuilder.ToString();
		}

		private static List<string> GetDefaultDisplayColumns()
		{
			List<string> list = new List<string>();
			string eOVariableFormSettings = CaseFileSettings.Default.EOVariableFormSettings;
			if (string.IsNullOrEmpty(eOVariableFormSettings))
			{
				list.AddRange(EOVariableForm.DefaultDisplayedColumns);
			}
			else
			{
				string[] array = eOVariableFormSettings.Split(',');
				foreach (string text in array)
				{
					if (!string.IsNullOrEmpty(text))
					{
						list.Add(text);
					}
				}
			}
			return list;
		}

		public static string GetEngineName(DataColumn column)
		{
			if (column == null)
			{
				throw new ArgumentNullException("column");
			}
			if (column.Tag is EOVariableField eOVariableField)
			{
				return eOVariableField.EngineName;
			}
			return null;
		}
	}
	public class EOVariableFormSettingsSavedEventArgs
	{
	}
	public class EOVariableFormSettingsSavedEvent : RoutedCompositePresentationEvent<EOVariableFormSettingsSavedEventArgs>
	{
		public EOVariableFormSettingsSavedEvent()
		{
			base.RoutingStrategy = CompositeEventRoutingStrategy.AllTopDown;
		}
