		protected override void OnUnityContainerChanged()
		{
			if (base.UnityContainer != null)
			{
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ViewFilterChangedEvent>().Subscribe(OnViewFilterChanged);
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EOVariableImportedEvent>().Subscribe(OnEOVariableImportedEvent);
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EOVariableFormSettingsSavedEvent>().Subscribe(OnEOVariableFormSettingsSavedEvent);
			}
			base.OnUnityContainerChanged();
		}

		protected override void OnSimulationIntegrationStepEvent(SimulationIntegrationStepEventArgs e)
		{
			if (!base.IsUnloaded)
			{
				UpdateData();
			}
		}

		protected override void OnUpdateData()
		{
			base.OnUpdateData();
			foreach (EOVariableFormDataTable formDataTable in FormDataTables)
			{
				EOVariablePageWrapper wrapper = formDataTable.Wrapper;
				if (wrapper.IsEquationsGrid() || wrapper.IsParameterGrid() || wrapper.IsVariableGrid())
				{
					formDataTable.DispatcherUpdate();
				}
			}
		}

		public override void OnViewClosed()
		{
			if (base.UnityContainer != null)
			{
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ViewFilterChangedEvent>().Unsubscribe(OnViewFilterChanged);
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EOVariableImportedEvent>().Unsubscribe(OnEOVariableImportedEvent);
				base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EOVariableFormSettingsSavedEvent>().Unsubscribe(OnEOVariableFormSettingsSavedEvent);
			}
			base.OnViewClosed();
		}

		private void OnEOVariableImportedEvent(EOVariableImportedEventArgs e)
		{
			foreach (EOVariableFormDataTable formDataTable in FormDataTables)
			{
				if (!formDataTable.Wrapper.IsParameterGrid())
				{
					formDataTable.DispatcherUpdate();
				}
			}
		}

		private void OnEOVariableFormSettingsSavedEvent(EOVariableFormSettingsSavedEventArgs e)
		{
			foreach (EOVariableFormDataTable formDataTable in FormDataTables)
			{
				EOVariableFormSettings.Apply(formDataTable);
			}
		}

		private void OnViewFilterChanged(ViewFilterChangedEventArgs e)
		{
			if (!string.Equals(e.NavigatorGroupKey, NavigationGroupKeys.SimulationGroup, StringComparison.InvariantCultureIgnoreCase))
			{
				return;
			}
			foreach (EOVariableFormDataTable formDataTable in FormDataTables)
			{
				if (e.NewFilter == ViewsFilterOption.AllViews)
				{
					formDataTable.Visibility = Visibility.Visible;
				}
				else if (e.NewFilter == ViewsFilterOption.InputViews)
				{
					int sheetView = formDataTable.Wrapper.GetSheetView();
					if (sheetView == 0 || sheetView == 1)
					{
						formDataTable.Visibility = Visibility.Visible;
					}
					else
					{
						formDataTable.Visibility = Visibility.Collapsed;
					}
				}
				else if (e.NewFilter == ViewsFilterOption.OutputViews)
				{
					int sheetView2 = formDataTable.Wrapper.GetSheetView();
					if (sheetView2 == 0 || sheetView2 == 2)
					{
						formDataTable.Visibility = Visibility.Visible;
					}
					else
					{
						formDataTable.Visibility = Visibility.Collapsed;
					}
				}
			}
			if (ActiveDataTable == null || ActiveDataTable.Visibility != Visibility.Visible)
			{
				EOVariableFormDataTable eOVariableFormDataTable = FormDataTables.FirstOrDefault((EOVariableFormDataTable x) => x.Visibility == Visibility.Visible);
				if (eOVariableFormDataTable != null)
				{
					eOVariableFormDataTable.IsActive = true;
				}
			}
		}

		protected override void OnSimulationReinitializedEvent(SimulationReinitializedEventArgs e)
		{
			foreach (EOVariableFormDataTable formDataTable in FormDataTables)
			{
				formDataTable.Reset();
			}
			base.OnSimulationReinitializedEvent(e);
		}

