		public void CopyToClipboard(GridControlCopyEventArgs e)
		{
			EOVariableFormDataTable activeDataTable = ActiveDataTable;
			if (activeDataTable != null)
			{
				string trimmedRecordPath = GetTrimmedRecordPath();
				if (!string.IsNullOrWhiteSpace(trimmedRecordPath))
				{
					e.ColumnPrefixes.Add(activeDataTable.KeyColumn, "#" + (trimmedRecordPath.EndsWith(".") ? trimmedRecordPath : (trimmedRecordPath + ".")));
				}
				else
				{
					e.ColumnPrefixes.Add(activeDataTable.KeyColumn, "#");
				}
				e.ClipboardContents.Add("AP_Text", ClipboardHelperNew.ConvertToStream(e.GenerateTextToCopy()));
				e.ColumnPrefixes.Clear();
				string value = GenerateAsiFormattedText();
				e.ClipboardContents.Add("ASI Format", ClipboardHelperNew.ConvertToStream(value));
			}
		}

		public string GenerateAsiFormattedText()
		{
			EOVariableFormDataTable activeDataTable = ActiveDataTable;
			string trimmedRecordPath = GetTrimmedRecordPath();
			return ClipboardHelperNew.GenerateAsiFormattedText(activeDataTable, activeDataTable.GridControl.SelectedRows.ToList(), activeDataTable.GridControl.SelectedColumns.ToList(), activeDataTable.GridControl.SelectedCells.ToList(), activeDataTable.KeyColumn, base.ResolvedCxsProvider.Case.CaseFullFilePath, trimmedRecordPath, base.ResolvedCxsProvider.Case.ApplicationName, SystemEnvironment.ExternalVersionString, base.DataType);
		}

