		public bool DoRenameSheet(string oldSheetName, string newSheetName)
		{
			if (FormDataTables.Where((EOVariableFormDataTable dataTable) => string.Equals(dataTable.SheetInfo.Name, newSheetName, StringComparison.CurrentCultureIgnoreCase) && !dataTable.IsActive).Count() > 0)
			{
				MMMessageBox.Show(GridFormsResources.EOVariablePage_RenamingSheetErrorMessage, GridFormsResources.EOVariablePage_RenamingSheetErrorTitle);
				return false;
			}
			ActiveDataTable.Wrapper.RenameStyleSheet(newSheetName);
			ActiveDataTable.SheetInfo.Name = newSheetName;
			return true;
		}

		public long DoCopySheet(StyleSheetInfo sourceSheet, string targetSheetName)
		{
			StyleSheetInfo styleSheetInfo = new StyleSheetInfo
			{
				Name = targetSheetName
			};
			WrapperManager.CopyStyleSheet(sourceSheet, styleSheetInfo);
			return styleSheetInfo.Handle;
		}

		public void DoQuery()
		{
			EOVariableFormDataTable activeDataTable = ActiveDataTable;
			if (activeDataTable != null)
			{
				bool flag = activeDataTable.Wrapper.IsVariableMode();
				QueryableFieldItem defaultSelectedItem = null;
				IEnumerable<QueryableFieldItem> queryableFieldItems = GetQueryableFieldItems(out defaultSelectedItem);
				VariableQueryDialog variableQueryDialog = new VariableQueryDialog
				{
					QueryString = activeDataTable.GetExternalQueryString(),
					Fields = queryableFieldItems,
					SelectedField = defaultSelectedItem,
					CanMatchWithModified = flag,
					CanMatchInObjectiveFunction = flag
				};
				bool? flag2 = OpenModalDialog(variableQueryDialog);
				if (flag2.HasValue && flag2.Value)
				{
					activeDataTable.UpdateExternalQueryString(variableQueryDialog.QueryString);
				}
			}
		}

		private IEnumerable<QueryableFieldItem> GetQueryableFieldItems(out QueryableFieldItem defaultSelectedItem)
		{
			List<QueryableFieldItem> list = new List<QueryableFieldItem>();
			defaultSelectedItem = null;
			foreach (DataColumn column in ActiveDataTable.Columns)
			{
				EOVariableField eOVariableField = column.Tag as EOVariableField;
				if (eOVariableField.CanQuery)
				{
					QueryableFieldItem queryableFieldItem = new QueryableFieldItem
					{
						DisplayName = eOVariableField.Header,
						EngineName = eOVariableField.EngineName,
						ItemsSource = eOVariableField.ItemsSource,
						DataType = eOVariableField.DataType,
						CanModify = eOVariableField.CanModify
					};
					list.Add(queryableFieldItem);
					if (eOVariableField.IsKeyField && defaultSelectedItem == null)
					{
						defaultSelectedItem = queryableFieldItem;
					}
				}
			}
			return list;
		}

		public void DoChangeType()
		{
			ChangeTypeDialog changeTypeDialog = new ChangeTypeDialog
			{
				SelectedType = ActiveDataTable.Wrapper.GetSheetType()
			};
			bool? flag = OpenModalDialog(changeTypeDialog);
			if (flag.HasValue && flag.Value)
			{
				ActiveDataTable.Wrapper.SetSheetType(changeTypeDialog.SelectedType);
			}
		}

		public void DoSave()
		{
			EOVariableFormDataTable activeDataTable = ActiveDataTable;
			if (activeDataTable != null && (!activeDataTable.IsDefault || MMMessageBox.Show(GridFormsResources.EOVariablePage_SaveDefaultSheetMessage, GridFormsResources.EOVariablePage_SaveSheetDialogTitle, MMMessageBoxButton.OKCancel) != MMMessageBoxResult.Cancel))
			{
				ActiveDataTable.Wrapper.SaveProperties();
			}
		}

		public void DoAutoSave()
		{
			ActiveDataTable.Wrapper.SetStyleSheetAutoSaveFlag(!IsActiveSheetAutoSaved);
		}

		public void DoDefault()
		{
			ActiveDataTable.Wrapper.SetDefaultFlag(!IsActiveSheetDefault);
		}

		public void DoChangeView()
		{
			ChangeViewDialog changeViewDialog = new ChangeViewDialog
			{
				SelectedView = ActiveDataTable.Wrapper.GetSheetView()
			};
			bool? flag = OpenModalDialog(changeViewDialog);
			if (flag.HasValue && flag.Value)
			{
				ActiveDataTable.Wrapper.SetSheetView(changeViewDialog.SelectedView);
			}
		}

		private string GetTrimmedRecordPath()
		{
			string text = ResolveParameter("main") as string;
			if (text.StartsWith("Top.appModelV8.Blocks.") && base.DataType.HasValue)
			{
				switch (base.DataType.Value)
				{
				case AspenTech.AspenPlus.MMForms.GridForms.DataType.AcmVariable:
				case AspenTech.AspenPlus.MMForms.GridForms.DataType.AcmPort:
				case AspenTech.AspenPlus.MMForms.GridForms.DataType.AcmParameter:
				case AspenTech.AspenPlus.MMForms.GridForms.DataType.AcmEqn:
					return text.Replace("Top.appModelV8.", "cxs:Top.appModel.");
				}
			}
			return GetCurrentRecordPath(text).Replace(".Data.", ".").Replace(".Blocks.", ".").Replace(".Streams.", ".")
				.Replace(".Flowsheeting Options.", ".")
				.Replace(".Design-Spec.", ".")
				.Replace(".Measurement.", ".")
				.Replace(".Calculator.", ".")
				.Replace(".EO Configuration", ".");
		}

		private string GetCurrentRecordPath(string longPath)
		{
			if (longPath.StartsWith("Top.appModelV8.Blocks."))
			{
				return longPath.Substring("Top.appModelV8.Blocks.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Streams."))
			{
				return longPath.Substring("Top.appModelV8.Streams.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Calculator."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Calculator.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Measurement."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Measurement.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.Flowsheeting Options.Design-Spec."))
			{
				return longPath.Substring("Top.appModelV8.Flowsheeting Options.Design-Spec.".Length);
			}
			if (longPath.StartsWith("Top.appModelV8.EO Configuration."))
			{
				return longPath.Substring("Top.appModelV8.EO Configuration.".Length);
			}
			if (string.Equals(longPath, "Top.appModelV8.EO Configuration.".Substring(0, "Top.appModelV8.EO Configuration.".Length - 1), StringComparison.InvariantCultureIgnoreCase))
			{
				return string.Empty;
			}
			return longPath;
		}

		public override bool? CheckComplete(string[] completionPaths)
		{
			string[] completionPaths2 = ResolveParameter("_CCNodes") as string[];
			return base.CheckComplete(completionPaths2);
		}

		public override int NextHit(out string messages, string[] completionPaths)
		{
			string[] completionPaths2 = ResolveParameter("_CCNodes") as string[];
			return base.NextHit(out messages, completionPaths2);
		}
	}
