		private void thePanel_GridControlAddedManually(object sender, GridControlEventArgs e)
		{
			long a_ = FormViewModel.DoAddSheet(e.GridControl.Title);
			InitializeGridControl(e.GridControl, new StyleSheetInfo(e.GridControl.Title, a_));
			if (thePanel.ActiveGridControl == e.GridControl)
			{
				((EOVariableFormDataTable)e.GridControl.DataSource).IsActive = true;
			}
		}

		private void thePanel_GridControlCloned(object sender, GridControlClonedEventArgs e)
		{
			EOVariableFormDataTable eOVariableFormDataTable = e.BasedGridControl.DataSource as EOVariableFormDataTable;
			long a_ = FormViewModel.DoCopySheet(eOVariableFormDataTable.SheetInfo, e.GridControl.Title);
			InitializeGridControl(e.GridControl, new StyleSheetInfo(e.GridControl.Title, a_));
			if (thePanel.ActiveGridControl == e.GridControl)
			{
				((EOVariableFormDataTable)e.GridControl.DataSource).IsActive = true;
			}
		}

