		public void InitializeView()
		{
			string activeGridName = null;
			if (thePanel.GridControls.Count > 0)
			{
				activeGridName = thePanel.ActiveGridControl.Title;
				thePanel.GridControls.Clear();
			}
			foreach (StyleSheetInfo savedSheet in FormViewModel.GetSavedSheets())
			{
				GridControl gridControl = new GridControl
				{
					Title = savedSheet.Name
				};
				InitializeGridControl(gridControl, savedSheet);
				thePanel.GridControls.Add(gridControl);
			}
			if (string.IsNullOrEmpty(activeGridName))
			{
				thePanel.ActiveGridControl = thePanel.GridControls.FirstOrDefault();
				return;
			}
			thePanel.ActiveGridControl = thePanel.GridControls.FirstOrDefault((GridControl grid) => grid.Title.Equals(activeGridName));
		}

