		public void PostStausMessage(string message)
		{
			if (thePanel == null)
			{
				return;
			}
			if (thePanel.PostTabItem == null)
			{
				thePanel.PostTabItem = new PostTabItem();
			}
			thePanel.PostTabItem.PostTabItemText = message;
			if (!FormViewModel.DataType.HasValue || !FormViewModel.DataType.Value.ToString().StartsWith("ACM", StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			CxsDataProvider cxsDataProvider = FormViewModel.UnityContainer.Resolve<CxsDataProvider>(Array.Empty<ResolverOverride>());
			string text = FormViewModel.ResolveParameter("main").ToString();
			int num = text.IndexOf(".Data.Blocks.");
			string text2 = string.Empty;
			if (num > 0)
			{
				text2 = text.Substring(num).Replace(".Data.Blocks.", ".").Trim('.');
				text = text.Substring(0, num);
			}
			string text3 = CxsConverter.ValueToString(cxsDataProvider.BatchGet(text, "id", null));
			if (string.IsNullOrEmpty(text3))
			{
				return;
			}
			if (num > 0)
			{
				text3 = text3 + "." + text2;
			}
			int aCMBlockDOF = EOVariableUtils.GetACMBlockDOF(text3);
			thePanel.PostTabItem.ACMState = aCMBlockDOF;
			base.EventAggregator.GetEvent<UpdateACMModelDOFEvent>().Publish(new UpdateACMModelDOFEventArg
			{
				ModelId = text3
			});
			string text4 = FormViewModel.ExpandDataPathAndGet("@main", "type") as string;
			string text5 = string.Empty;
			if (!string.IsNullOrEmpty(text4))
			{
				object obj = ACMModelLibraryHelper.ACM_FindModel(text4);
				if (obj != null)
				{
					text5 = ACMModelLibraryHelper.ACM_GetModelProperty(obj, "Help");
				}
				if (string.IsNullOrEmpty(text5) || !File.Exists(text5))
				{
					thePanel.PostTabItem.HelpVisibility = Visibility.Collapsed;
				}
				else
				{
					thePanel.PostTabItem.HelpVisibility = Visibility.Visible;
					thePanel.PostTabItem.ModelType = text4;
				}
				ACMModelLibraryHelper.ACM_UnlockModel(text4);
			}
		}

