		private void InitializeGridControl(GridControl gc, StyleSheetInfo sheetInfo)
		{
			if (gc.DataSource == null)
			{
				EOVariableFormDataTable eOVariableFormDataTable = FormViewModel.CreateDataTableSource(sheetInfo);
				gc.SetBinding(UIElement.VisibilityProperty, new Binding("Visibility")
				{
					Source = eOVariableFormDataTable,
					Mode = BindingMode.OneWay
				});
				FormViewModel.FormDataTables.Add(eOVariableFormDataTable);
				gc.DataSource = eOVariableFormDataTable;
				gc.ReservedColumnChooserCommand = new Tuple<string, ICommand>(GridFormsResources.EOVariablePage_ColumnsSelector_ResetDefault, new ApwnCommand<object>(ResetDefaultCommand_Executed, ResetDefaultCommand_CanExecute));
				gc.ColumnDisplayIndexChanged += gc_ColumnDisplayIndexChanged;
				gc.ColumnsVisibilityChanged += gc_ColumnsVisibilityChanged;
				TryRestoreLayoutSettings(gc);
			}
		}

		private void ResetDefaultCommand_Executed(object parameter)
		{
			if (!(parameter is ColumnChooserWindow columnChooserWindow))
			{
				return;
			}
			foreach (ColumnChooserItem item in columnChooserWindow.Items)
			{
				if (DefaultDisplayedColumns.Contains(EOVariableFormSettings.GetEngineName(item.Column)))
				{
					item.IsChecked = true;
				}
				else
				{
					item.IsChecked = false;
				}
			}
		}

		private bool ResetDefaultCommand_CanExecute(object parameter)
		{
			if (parameter is ColumnChooserWindow columnChooserWindow)
			{
				List<string> list = (from x in columnChooserWindow.Items
					where x.IsChecked
					select EOVariableFormSettings.GetEngineName(x.Column)).ToList();
				if (list.Count == 7 && list.Except(DefaultDisplayedColumns).Count() == 0)
				{
					return false;
				}
				return true;
			}
			return false;
		}

