		private void OnCommandExecuting(CommandExecutingEventArgs e)
		{
			if (FormViewModel != null)
			{
				if (e.Command == GridControlPanel.AddNewGridCommand)
				{
					e.Cancel = !FormViewModel.CanDoAddSheet;
				}
				else if (e.Command == GridControlPanel.RenameCurrentGridCommand)
				{
					e.Cancel = !FormViewModel.CanDoRenameSheet;
				}
				else if (e.Command == GridControlPanel.CloneCurrentGridCommand)
				{
					e.Cancel = !FormViewModel.CanDoCopySheet;
				}
				else if (e.Command == GridControlPanel.RemoveCurrentGridCommand)
				{
					e.Cancel = !FormViewModel.CanDoRemoveSheet;
				}
			}
		}

