		public override string SaveFormSettings()
		{
			Dictionary<long, string> dictionary = new Dictionary<long, string>();
			foreach (GridControl gridControl in thePanel.GridControls)
			{
				EOVariableFormDataTable eOVariableFormDataTable = gridControl.DataSource as EOVariableFormDataTable;
				string value = gridControl.SaveLayoutSettings();
				if (!string.IsNullOrEmpty(value))
				{
					dictionary.Add(eOVariableFormDataTable.SheetInfo.Handle, value);
				}
			}
			if (dictionary.Count > 0)
			{
				XDocument xDocument = new XDocument(new XElement("root"));
				foreach (KeyValuePair<long, string> item in dictionary)
				{
					XElement xElement = new XElement("grid");
					xElement.SetAttributeValue("id", item.Key);
					xElement.SetValue(item.Value);
					xDocument.Root.Add(xElement);
				}
				return xDocument.ToString();
			}
			return null;
		}

		public override void RestoreFormSettings(string settings)
		{
			if (string.IsNullOrEmpty(settings))
			{
				return;
			}
			XDocument xDocument = XDocument.Parse(settings);
			if (xDocument == null)
			{
				return;
			}
			foreach (XElement item in xDocument.Root.Elements("grid"))
			{
				long key = (long)item.Attribute("id");
				string value = item.Value;
				if (_settingsToRestore == null)
				{
					_settingsToRestore = new Dictionary<long, string>();
				}
				_settingsToRestore[key] = value;
			}
			foreach (GridControl gridControl in thePanel.GridControls)
			{
				TryRestoreLayoutSettings(gridControl);
			}
		}

		private void TryRestoreLayoutSettings(GridControl gc)
		{
			if (gc != null && _settingsToRestore != null)
			{
				EOVariableFormDataTable eOVariableFormDataTable = gc.DataSource as EOVariableFormDataTable;
				if (_settingsToRestore.ContainsKey(eOVariableFormDataTable.SheetInfo.Handle))
				{
					gc.LoadLayoutSettings(_settingsToRestore[eOVariableFormDataTable.SheetInfo.Handle], LayoutOption.SortedColumns | LayoutOption.FilterHeaderVisibility | LayoutOption.ColumnWidth | LayoutOption.ColumnFilter);
					_settingsToRestore.Remove(eOVariableFormDataTable.SheetInfo.Handle);
				}
			}
		}

