		private void TabControl_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (base.UnityContainer == null || base.UnityContainer.Resolve<IApwnApplication>(Array.Empty<ResolverOverride>()).ActiveDocument.ActiveMode != ProblemModes.PSVPlus || !(sender is TabControl tabControl))
			{
				return;
