			base.Dispatcher.BeginInvoke((Action)delegate
			{
				if (tabItem.Content is GridControl parent && Utilities.GetDescendantFromName(parent, "PART_DataGrid") is GridControlDataGrid gridControlDataGrid)
				{
					gridControlDataGrid.IsEnabled = false;
				}
			}, DispatcherPriority.Loaded);
		}

