				else if (value >= 999999)
				{
					PostTabItemImage = GetImageSource("Incomplete16.ico");
					PostTabItemImageToolTip = GridFormsResources.ToolTip_Incomplete;
				}
				else if (value < 0)
				{
					PostTabItemImage = GetImageSource("OverSpecified32.ico");
					PostTabItemImageToolTip = string.Format(GridFormsResources.ToolTip_OverSpec, value * -1);
				}
				else if (value > 0)
				{
					PostTabItemImage = GetImageSource("UnderSpecified32.ico");
					PostTabItemImageToolTip = string.Format(GridFormsResources.ToolTip_UnderSpec, value);
				}
			}
		}

