		private void OnMainNodeChanged(IHNode oldValue, IHNode newValue)
		{
			if (oldValue != null && oldValue.Application is HappLS target)
			{
				target.OnDataChanged -= happLs_OnDataChanged;
				target.OnUpdateMessage -= happLs_OnUpdateMessage;
			}
			if (newValue != null && newValue.Application is HappLS target2)
			{
				target2.OnDataChanged += happLs_OnDataChanged;
				target2.OnUpdateMessage += happLs_OnUpdateMessage;
			}
		}

