		{
			if (oldValue != null)
			{
				oldValue.Message -= cxsCase_Message;
			}
			if (newValue != null)
			{
				newValue.Message += cxsCase_Message;
			}
		}

		public void UnsubscribeEvents()
		{
			if (MainNode != null && MainNode.Application is HappLS target)
			{
				target.OnDataChanged -= happLs_OnDataChanged;
				target.OnUpdateMessage -= happLs_OnUpdateMessage;
			}
			if (ActiveCase != null)
			{
				ActiveCase.Message -= cxsCase_Message;
			}
		}

