		private void SubscribeSimulationEvents(IEventAggregator aggregator)
		{
			aggregator.GetEvent<SimulationRunStartedEvent>().Subscribe(OnSimulationRunStartedEvent);
			aggregator.GetEvent<SimulationReinitializedEvent>().Subscribe(OnSimulationReinitializedEvent);
			aggregator.GetEvent<SimulationIntegrationStepEvent>().Subscribe(OnSimulationIntegrationStepEvent);
			aggregator.GetEvent<SimulationRunCompletedEvent>().Subscribe(OnSimulationRunCompletedEvent);
			aggregator.GetEvent<SimulationRunFailedEvent>().Subscribe(OnSimulationRunFailedEvent);
		}

		private void UnsubscribeSimulationEvents(IEventAggregator aggregator)
		{
			aggregator.GetEvent<SimulationRunStartedEvent>().Unsubscribe(OnSimulationRunStartedEvent);
			aggregator.GetEvent<SimulationReinitializedEvent>().Unsubscribe(OnSimulationReinitializedEvent);
			aggregator.GetEvent<SimulationIntegrationStepEvent>().Unsubscribe(OnSimulationIntegrationStepEvent);
			aggregator.GetEvent<SimulationRunCompletedEvent>().Unsubscribe(OnSimulationRunCompletedEvent);
			aggregator.GetEvent<SimulationRunFailedEvent>().Unsubscribe(OnSimulationRunFailedEvent);
		}

