		{
			_notifier.UpdateDataRequiredByHappLSAction = delegate
			{
				OnUpdateDataRequiredByHappLS();
			};
			_notifier.UnityContainer = base.ResolvedCxsProvider.UnityContainer;
			_notifier.MainNode = MainNode;
			_notifier.ActiveCase = base.ResolvedCxsProvider.Case;
			base.OnUpdateData();
		}

		public override void OnViewClosed()
		{
			IUnityContainer unityContainer = base.UnityContainer;
			IEventAggregator eventAggregator = ((unityContainer != null) ? UnityContainerHelper.TryResolve<IEventAggregator>(unityContainer) : null);
			if (eventAggregator != null)
			{
				UnsubscribeSimulationEvents(eventAggregator);
			}
			_notifier.UnsubscribeEvents();
			base.OnViewClosed();
		}

		protected virtual void OnUpdateDataRequiredByHappLS()
		{
		}
	}
