		public AddToStreamGroupWindow(IStreamGroupPresenter sgp, IEnumerable<string> streams)
		{
			if (sgp == null)
			{
				throw new ArgumentNullException("sgp");
			}
			if (streams == null)
			{
				throw new ArgumentNullException("streams");
			}
			_sgp = sgp;
			_streams = streams;
			InitializeComponent();
		}

		protected override void OnInitialized(EventArgs e)
		{
			InitializeStreamGroups();
			base.OnInitialized(e);
		}

		private void InitializeStreamGroups()
		{
			IEnumerable<StreamGroupInfo> allUserDefinedGroups = _sgp.GetAllUserDefinedGroups();
			if (allUserDefinedGroups != null)
			{
				_userDefinedGroups.Clear();
				_userDefinedGroups.AddRange(from x in allUserDefinedGroups
					where !x.IsConditional
					select x.Name);
			}
			List<string> list = new List<string>(_userDefinedGroups);
			list.Add(GridFormsResources.StreamReport_AddToStreamGroupWindow_DropDownCreateNew);
			comboStreamGroups.ItemsSource = list;
			comboStreamGroups.SelectedIndex = 0;
			comboStreamGroups.SelectionChanged += comboStreamGroups_SelectionChanged;
		}

		private void comboStreamGroups_SelectionChanged(object sender, SelectionChangedEventArgs e)
		{
			if (string.Equals(comboStreamGroups.SelectedItem as string, GridFormsResources.StreamReport_AddToStreamGroupWindow_DropDownCreateNew))
			{
				base.Dispatcher.BeginInvoke(new Action(DoCreateNew), DispatcherPriority.Loaded);
			}
		}

		private void DoCreateNew()
		{
			if (!string.IsNullOrEmpty(_sgp.CreateNewUserDefinedGroup(_streams)))
			{
				Close();
			}
		}

		private void buttonOK_Click(object sender, RoutedEventArgs e)
		{
			string text = comboStreamGroups.SelectedItem as string;
			if (string.Equals(text, GridFormsResources.StreamReport_AddToStreamGroupWindow_DropDownCreateNew))
			{
				DoCreateNew();
			}
			else if (!string.IsNullOrEmpty(text))
			{
				IEnumerable<string> streams = _sgp.GetSelectedStreams(text).ToListAnyway().Union(_streams);
				_sgp.SaveUserDefinedGroup(text, streams);
				Close();
			}
			else
			{
				Close();
			}
		}

