		private static TemplatePropertyItem CreateCalculationPropertyItem(TemplatePropertyItem udtpi, IAdbUnitsProvider unitsProvider)
		{
			TemplatePropertyItem templatePropertyItem = new TemplatePropertyItem(udtpi.StreamProperty);
			foreach (SettingItem setting in udtpi.Settings)
			{
