				string value = setting.Value;
				string text = setting.Unit;
				if (string.Equals(name, "Temp", StringComparison.CurrentCultureIgnoreCase))
				{
					string temperatureSIUnit = unitsProvider.GetTemperatureSIUnit();
					if (!string.Equals(text, temperatureSIUnit, StringComparison.CurrentCultureIgnoreCase))
					{
						value = ConvertSettingValueIntoSI(unitsProvider, setting.ResolvedValues, text, temperatureSIUnit, AdbUnitsProviderExtensions.TemperatureUnitRow);
						text = temperatureSIUnit;
					}
				}
				else if (string.Equals(name, "Pres", StringComparison.CurrentCultureIgnoreCase))
				{
					string pressureSIUnit = unitsProvider.GetPressureSIUnit();
					if (!string.Equals(text, pressureSIUnit, StringComparison.CurrentCultureIgnoreCase))
					{
						value = ConvertSettingValueIntoSI(unitsProvider, setting.ResolvedValues, text, pressureSIUnit, AdbUnitsProviderExtensions.PressureUnitRow);
						text = pressureSIUnit;
