			}
			EnsureSubstreamAndPhaseIntialized(templatePropertyItem);
			return templatePropertyItem;
		}

		private static string ConvertSettingValueIntoSI(IAdbUnitsProvider unitsProvider, string[] svalues, string sunit, string siUnit, int unitRow)
		{
			if (svalues == null)
			{
				return null;
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string text in svalues)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(',');
				}
				double result = 0.0;
				NumberStyles style = NumberStyles.Any;
				CultureInfo provider = CultureInfo.CreateSpecificCulture("en-US");
				if (double.TryParse(text, style, provider, out result))
				{
					stringBuilder.Append(unitsProvider.XConvert(unitRow, result, sunit, siUnit).GetValueOrDefault().ToString(CultureInfo.InvariantCulture));
				}
				else
				{
					stringBuilder.Append(text);
				}
			}
			return stringBuilder.ToString();
		}

