				"DisplayName", "Comps", "Format", "Units", "Trace", "Trace-Label", "Scale", "Scale-Label", "PPM", "PPB",
				"Normalize", "Substream", "Phase", "Basis", "Base-Comp", "L2-Comps", "Temp", "Pres", "TB-Upper", "TB-Lower",
				"Comp-Group", "Base-Comp-Group", "Base-TB-Upper", "Base-TB-Lower", "Liq-Vol%"
			};

			public static ReportTemplateItem ReadFile(string file, IAdbUnitsProvider unitsProvider)
			{
				ReportTemplateItem reportTemplateItem = InitializeNewTemplate(Path.GetFileNameWithoutExtension(file));
				string[] originalLines = File.ReadAllLines(file);
				string text = ReadDescription(originalLines);
				if (!string.IsNullOrEmpty(text))
				{
					reportTemplateItem.Description = text;
				}
				IEnumerable<string> validLines = GetValidLines(originalLines);
				List<string> list = new List<string>();
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				List<string> list2 = new List<string>();
				foreach (string item in validLines)
				{
					if (StartsWithWord(item, "BEGLOOP"))
					{
						string beginLoopLine = TrimStartWord(item, "BEGLOOP");
						list.AddRange(GetLoopSubstreams(beginLoopLine));
					}
					else if (StartsWithWord(item, "ENDLOOP"))
					{
						list.Clear();
					}
					else if (StartsWithWord(item, "display"))
					{
						string text2 = TrimStartWord(item, "display");
						if (StartsWithWord(text2, "only"))
						{
							dictionary = TransformQualifiers(SplitIntoDictionary(TrimStartWord(text2, "only")));
						}
						else if (StartsWithWord(text2, "remain"))
						{
							reportTemplateItem.Settings.GeneralOptions.BatchProperties = true;
							dictionary = TransformQualifiers(SplitIntoDictionary(TrimStartWord(text2, "remain")));
							foreach (string item2 in AllStreamProperties.Except(list2))
							{
								if (string.Equals(item2, "comp-attr", StringComparison.CurrentCultureIgnoreCase))
								{
									reportTemplateItem.Settings.GeneralOptions.ComponentAttributes = true;
									continue;
								}
								if (string.Equals(item2, "SUBS-ATTR", StringComparison.CurrentCultureIgnoreCase))
								{
									reportTemplateItem.Settings.GeneralOptions.ParticleSizeDistributions = true;
									continue;
								}
								if (string.Equals(item2, "stcost", StringComparison.CurrentCultureIgnoreCase))
								{
									reportTemplateItem.Settings.GeneralOptions.CostFlow = true;
									continue;
								}
								string engineName = ConvertPropertyName(item2).ToLowerInvariant();
								AppendProperty(reportTemplateItem, engineName, list, dictionary, unitsProvider);
							}
						}
						else if (StartsWithWord(text2, "all"))
						{
							dictionary = TransformQualifiers(SplitIntoDictionary(TrimStartWord(text2, "all")));
						}
						else
						{
							dictionary.Clear();
						}
						list2.Clear();
					}
					else if (StartsWithWord(item, "prop"))
					{
						string line = TrimStartWord(item, "prop");
						string nextWord = GetNextWord(line);
						if (string.IsNullOrEmpty(nextWord))
						{
							continue;
						}
						if (string.Equals(nextWord, "comp-attr", StringComparison.CurrentCultureIgnoreCase))
						{
							reportTemplateItem.Settings.GeneralOptions.ComponentAttributes = true;
							continue;
						}
						if (string.Equals(nextWord, "SUBS-ATTR", StringComparison.CurrentCultureIgnoreCase))
						{
							reportTemplateItem.Settings.GeneralOptions.ParticleSizeDistributions = true;
							continue;
						}
						if (string.Equals(nextWord, "stcost", StringComparison.CurrentCultureIgnoreCase))
						{
							reportTemplateItem.Settings.GeneralOptions.CostFlow = true;
							continue;
						}
						Dictionary<string, string> localQualifiers = TransformQualifiers(SplitIntoDictionary(TrimStartWord(line, nextWord)));
						IDictionary<string, string> combinedQualifiers = JoinDictionary(dictionary, localQualifiers);
						string text3 = ConvertPropertyName(nextWord).ToLowerInvariant();
						AppendProperty(reportTemplateItem, text3, list, combinedQualifiers, unitsProvider);
						if (!list2.Contains(text3))
						{
							list2.Add(text3);
						}
					}
					else
					{
						IDictionary<string, string> dict = SplitIntoDictionary(item);
						ReadHeaderInformation(reportTemplateItem, dict);
					}
				}
				return reportTemplateItem;
			}

			private static void ReadHeaderInformation(ReportTemplateItem result, IDictionary<string, string> dict)
			{
				foreach (KeyValuePair<string, string> item in dict)
				{
					if (string.Equals(item.Value, "yes", StringComparison.CurrentCultureIgnoreCase))
					{
						if (string.Equals("source-label", item.Key, StringComparison.CurrentCultureIgnoreCase))
						{
							result.Settings.GeneralOptions.SourceAndDestination = true;
						}
						else if (string.Equals("dest-label", item.Key, StringComparison.CurrentCultureIgnoreCase))
						{
							result.Settings.GeneralOptions.SourceAndDestination = true;
						}
						else if (string.Equals("phase-label", item.Key, StringComparison.CurrentCultureIgnoreCase))
						{
							result.Settings.GeneralOptions.PhaseLabel = true;
						}
					}
				}
			}

			private static string ReadDescription(string[] originalLines)
			{
				bool flag = false;
				StringBuilder stringBuilder = new StringBuilder();
				foreach (string text in originalLines)
				{
					if (string.IsNullOrWhiteSpace(text))
					{
						continue;
					}
					string text2 = text.Trim();
					switch (text2.FirstOrDefault())
					{
					case ';':
						if (text2.Length > 1)
						{
							string text3 = text2.Substring(1).Trim();
							if (text3.StartsWith("-"))
							{
								stringBuilder.Clear();
								flag = true;
							}
							else if (flag)
							{
								stringBuilder.AppendLine(text3);
							}
						}
						continue;
					case '#':
						continue;
					}
					break;
				}
				if (stringBuilder.Length <= 0)
				{
					return null;
				}
				return stringBuilder.ToString().Trim();
			}

			[IteratorStateMachine(typeof(GetValidLinesEnumerator))]
			private static IEnumerable<string> GetValidLines(string[] originalLines)
			{
				return new GetValidLinesEnumerator(-2)
				{
					initialOriginalLines = originalLines
				};
			}

			private static bool StartsWithWord(string text, string word)
			{
				if (text.StartsWith(word, StringComparison.CurrentCultureIgnoreCase))
				{
					if (text.Length == word.Length)
					{
						return true;
					}
					return char.IsWhiteSpace(text, word.Length);
				}
				return false;
			}

			private static string TrimStartWord(string line, string word)
			{
				if (line.Length > word.Length)
				{
					return line.Substring(word.Length).Trim();
				}
				return string.Empty;
			}

			[IteratorStateMachine(typeof(GetLoopSubstreamsEnumerator))]
			private static IEnumerable<string> GetLoopSubstreams(string beginLoopLine)
			{
				return new GetLoopSubstreamsEnumerator(-2)
				{
					initialBeginLoopLine = beginLoopLine
				};
			}

			private static IDictionary<string, string> SplitIntoDictionary(string text)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				if (!string.IsNullOrEmpty(text))
				{
					int? num = null;
					int? num2 = null;
					bool flag = false;
					List<string> list = new List<string>();
					for (int i = 0; i < text.Length; i++)
					{
						char c = text[i];
						if (c == '"')
						{
							flag = !flag;
							if (!flag && num.HasValue)
							{
								num2 = i - 1;
							}
						}
						else if (char.IsWhiteSpace(c))
						{
							if (!flag && num.HasValue)
							{
								num2 = i - 1;
							}
						}
						else if (!num.HasValue)
						{
							num = i;
						}
						else if (i == text.Length - 1)
						{
							num2 = i;
						}
						if (num.HasValue && num2.HasValue)
						{
							list.Add(text.Substring(num.Value, num2.Value + 1 - num.Value));
							num2 = null;
							num = num2;
						}
					}
					foreach (string item in list)
					{
						if (!string.IsNullOrWhiteSpace(item))
						{
							string[] array = item.Split('=');
							if (array.Length == 2)
							{
								string key = array[0].Trim('"').Trim();
								string value = array[1].Trim('"').Trim();
								dictionary[key] = value;
							}
						}
					}
				}
				return dictionary;
			}

			private static string GetNextWord(string line)
			{
				for (int i = 0; i < line.Length; i++)
				{
					if (char.IsWhiteSpace(line[i]))
					{
						return line.Substring(0, i).Trim();
					}
				}
				return line;
			}

			private static Dictionary<string, string> TransformQualifiers(IDictionary<string, string> dict)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				foreach (KeyValuePair<string, string> item in dict)
				{
					string key = TransformPropertyKey(item.Key);
					string text = item.Value;
					string text2 = NewQualifiers.FirstOrDefault((string x) => string.Equals(x, key, StringComparison.CurrentCultureIgnoreCase));
					if (string.IsNullOrEmpty(text2))
					{
						continue;
					}
					if (string.Equals(text2, "DisplayName", StringComparison.OrdinalIgnoreCase))
					{
						if (!string.IsNullOrEmpty(text))
						{
							int num = text.IndexOf('@');
							if (num > 0)
							{
								text = text.Substring(0, num).Trim();
							}
							dictionary[text2] = text;
						}
					}
					else if (string.Equals(text2, "Substream", StringComparison.OrdinalIgnoreCase))
					{
						if (string.Equals(text, "$total", StringComparison.CurrentCultureIgnoreCase))
						{
							dictionary[text2] = "ALL";
						}
						else if (!string.Equals(text, "all", StringComparison.CurrentCultureIgnoreCase))
						{
							dictionary[text2] = text;
						}
					}
					else if (string.Equals(text2, "Phase", StringComparison.OrdinalIgnoreCase))
					{
						string value = TransformPhase(text);
						if (!string.IsNullOrEmpty(value))
						{
							dictionary[text2] = value;
						}
					}
					else if (string.Equals(text2, "Format", StringComparison.OrdinalIgnoreCase))
					{
						AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification formatSpecification = AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification.ParseShortTermText(text);
						if (formatSpecification != null)
						{
							dictionary[text2] = formatSpecification.ToString();
						}
					}
					else
					{
						dictionary[text2] = text;
					}
				}
				return dictionary;
			}

			private static string TransformPropertyKey(string propertyKey)
			{
				if (string.Equals(propertyKey, "prop-label", StringComparison.CurrentCultureIgnoreCase))
				{
					return "DisplayName";
				}
				return propertyKey;
			}

			private static string TransformPhase(string phase)
			{
				return phase.ToUpper() switch
				{
					"V" => "Vapor", 
					"L" => "Liquid", 
					"L1" => "Liquid1", 
					"L2" => "Liquid2", 
					"S" => "Solid", 
					"T" => "Total", 
					_ => null, 
				};
			}

			private static IDictionary<string, string> JoinDictionary(IDictionary<string, string> displayQualifiers, IDictionary<string, string> localQualifiers)
			{
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				foreach (KeyValuePair<string, string> displayQualifier in displayQualifiers)
				{
					dictionary[displayQualifier.Key] = displayQualifier.Value;
				}
				foreach (KeyValuePair<string, string> localQualifier in localQualifiers)
				{
					dictionary[localQualifier.Key] = localQualifier.Value;
				}
				return dictionary;
			}

			private static string ConvertPropertyName(string name)
			{
				return name.ToLower() switch
				{
					"hmx_mass" => "masshmx", 
					"hmx_flow" => "hflmx", 
					"smx_mass" => "masssmx", 
					"rhomx_mass" => "massrhom", 
					"d25d75" => "D25:D75", 
					_ => name, 
				};
			}

			private static void AppendProperty(ReportTemplateItem result, string engineName, IEnumerable<string> substreams, IDictionary<string, string> combinedQualifiers, IAdbUnitsProvider unitsProvider)
			{
				if (TryUpdateQuickAcessProperties(result, engineName))
				{
					TemplatePropertyItem templatePropertyItem = result.Settings.Properties.FirstOrDefault((TemplatePropertyItem x) => string.Equals(x.EngineName, engineName, StringComparison.CurrentCultureIgnoreCase));
					if (templatePropertyItem == null)
					{
						return;
					}
					foreach (KeyValuePair<string, string> combinedQualifier in combinedQualifiers)
					{
						if (string.Equals(combinedQualifier.Key, "Units"))
						{
							CheckPropertyUnits(templatePropertyItem, combinedQualifier.Value, unitsProvider);
						}
						else
						{
							templatePropertyItem[combinedQualifier.Key] = combinedQualifier.Value;
						}
					}
					RemoveCalculationQualifiers(templatePropertyItem);
					return;
				}
				TemplatePropertyItem templatePropertyItem2 = new TemplatePropertyItem(new PhysicalProperty(engineName));
				if (!templatePropertyItem2.StreamProperty.IsValid)
				{
					SystemEnvironment.LogDebug("Physical property {" + engineName + "} does not exist.");
				}
				templatePropertyItem2.SetMetadata("Substream", substreams);
				foreach (KeyValuePair<string, string> combinedQualifier2 in combinedQualifiers)
				{
					if (string.Equals(combinedQualifier2.Key, "Units"))
					{
						CheckPropertyUnits(templatePropertyItem2, combinedQualifier2.Value, unitsProvider);
					}
					else
					{
						templatePropertyItem2[combinedQualifier2.Key] = combinedQualifier2.Value;
					}
				}
				result.Settings.Properties.Add(templatePropertyItem2);
			}

			private static void CheckPropertyUnits(TemplatePropertyItem tpi, string units, IAdbUnitsProvider unitsProvider)
			{
				if (string.IsNullOrWhiteSpace(units) || !tpi.StreamProperty.IsValid)
				{
					return;
				}
				IList<string> list = unitsProvider.XGetPropertyUnitsList(tpi.StreamProperty).ToListAnyway();
				List<string> list2 = new List<string>();
				if (list.Count > 0)
				{
					string[] array = units.Split(',');
					foreach (string segment in array)
					{
						if (!string.IsNullOrWhiteSpace(segment))
						{
							string text = list.FirstOrDefault((string x) => string.Equals(x, segment.Trim(), StringComparison.CurrentCultureIgnoreCase));
							if (text != null && !list2.Contains(text))
							{
								list2.Add(text);
							}
						}
					}
				}
				if (list2.Count > 0)
				{
					tpi.SetMetadata("Units", list2);
				}
			}
		}

		private const string ApsstExtension = ".apsst";

		private const string ApcsvExtension = ".apcsv";

		private const string TffExtension = ".tff";

		public static ReportTemplateItem Read(string file, IAdbUnitsProvider unitsProvider)
		{
			if (File.Exists(file))
			{
				if (file.EndsWith(".apsst", StringComparison.CurrentCultureIgnoreCase))
				{
					return ApsstReader.ReadFile(file, unitsProvider);
				}
				if (file.EndsWith(".apcsv", StringComparison.CurrentCultureIgnoreCase))
				{
					return ApcsvReader.ReadFile(file, unitsProvider);
				}
				if (file.EndsWith(".tff", StringComparison.CurrentCultureIgnoreCase))
				{
					return TffReader.ReadFile(file, unitsProvider);
				}
			}
			return null;
		}

		public static void PopulateCssTemplateSettings(ReportTemplateItem rti, string apcsvXmlContent)
		{
			XDocument xDocument = null;
			try
			{
				if (!string.IsNullOrWhiteSpace(apcsvXmlContent))
				{
					xDocument = XDocument.Parse(apcsvXmlContent);
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.LogDebug("Error in ReportTemplateReader.PopulateCssTemplateSettings: " + ex.Message);
			}
			if (xDocument != null)
			{
				rti.Settings.InitializeAllOptions(flag: false);
				rti.Settings.ScopeOptions.TotalStream = true;
				rti.Settings.ScopeOptions.Substreams = true;
				rti.Settings.ScopeOptions.PhasesForMixedSubstream = true;
				ApcsvReader.PopulateTemplateSettings(rti, xDocument.Root);
			}
			else
			{
				rti.Settings.InitializeAllOptions(flag: true);
			}
		}

		private static ReportTemplateItem InitializeNewTemplate(string name)
		{
			ReportTemplateItem reportTemplateItem = new ReportTemplateItem();
			reportTemplateItem.Name = name;
			reportTemplateItem.Type = ReportTemplateType.UserDefined;
			reportTemplateItem.Settings.ScopeOptions.TotalStream = true;
			reportTemplateItem.Settings.ScopeOptions.Substreams = true;
			reportTemplateItem.Settings.ScopeOptions.PhasesForMixedSubstream = true;
			return reportTemplateItem;
		}

		private static string GetAttributeValue(XElement element, string attribute)
		{
			return element.Attribute(attribute)?.Value;
		}

		private static bool TryUpdateQuickAcessProperties(ReportTemplateItem result, string engineName)
		{
			TemplateGeneralOptions generalOptions = result.Settings.GeneralOptions;
			if (Matches(BasisStreamProperties.Temperature, engineName))
			{
				return generalOptions.Temperature = true;
			}
			if (Matches(BasisStreamProperties.Pressure, engineName))
			{
				return generalOptions.Pressure = true;
			}
			if (Matches(BasisStreamProperties.MolarVaporFraction, engineName))
			{
				return generalOptions.MolarVaporFraction = true;
			}
			if (Matches(BasisStreamProperties.MolarLiquidFraction, engineName))
			{
				return generalOptions.MolarLiquidFraction = true;
			}
			if (Matches(BasisStreamProperties.MolarSolidFraction, engineName))
			{
				return generalOptions.MolarSolidFraction = true;
			}
			if (Matches(BasisStreamProperties.MassVaporFraction, engineName))
			{
				return generalOptions.MassVaporFraction = true;
			}
			if (Matches(BasisStreamProperties.MassLiquidFraction, engineName))
			{
				return generalOptions.MassLiquidFraction = true;
			}
			if (Matches(BasisStreamProperties.MassSolidFraction, engineName))
			{
				return generalOptions.MassSolidFraction = true;
			}
			if (Matches(BasisStreamProperties.MolarEnthalpy, engineName))
			{
				return generalOptions.MolarEnthalpy = true;
			}
			if (Matches(BasisStreamProperties.MassEnthalpy, engineName))
			{
				return generalOptions.MassEnthalpy = true;
			}
			if (Matches(BasisStreamProperties.EnthalpyFlow, engineName))
			{
				return generalOptions.EnthalpyFlow = true;
			}
			if (Matches(BasisStreamProperties.MolarEntropy, engineName))
			{
				return generalOptions.MolarEntropy = true;
			}
			if (Matches(BasisStreamProperties.MassEntropy, engineName))
			{
				return generalOptions.MassEntropy = true;
			}
			if (Matches(BasisStreamProperties.MolarDensity, engineName))
			{
				return generalOptions.MolarDensity = true;
			}
			if (Matches(BasisStreamProperties.MassDensity, engineName))
			{
				return generalOptions.MassDensity = true;
			}
			if (Matches(BasisStreamProperties.AverageMolecularWeight, engineName))
			{
				return generalOptions.AverageMolecularWeight = true;
			}
			TemplateScopeOptions scopeOptions = result.Settings.ScopeOptions;
			if (Matches(BasisStreamProperties.MolarComponentFlows, engineName))
			{
				return scopeOptions.MoleFlows = true;
			}
			if (Matches(BasisStreamProperties.MassComponentFlows, engineName))
			{
				return scopeOptions.MassFlows = true;
			}
			if (Matches(BasisStreamProperties.VolumetricFlow, engineName))
			{
				return scopeOptions.VolumeFlows = true;
			}
			if (Matches(BasisStreamProperties.MoleFractions, engineName))
			{
				return scopeOptions.MoleFractions = true;
			}
			if (Matches(BasisStreamProperties.MassFractions, engineName))
			{
				return scopeOptions.MassFractions = true;
			}
			if (BasisStreamProperties.FindBatchProperty(engineName) != null)
			{
				return generalOptions.BatchProperties = true;
			}
			return false;
		}

		private static bool Matches(IStreamProperty property, string engineName)
		{
			return string.Equals(property.EngineName, engineName, StringComparison.OrdinalIgnoreCase);
		}

		private static void RemoveCalculationQualifiers(TemplatePropertyItem tpi)
		{
			foreach (SettingItem item in tpi.Settings.Where((SettingItem x) => x.IsCalculationQualifier).ToList())
			{
				tpi.Settings.Remove(item);
			}
		}
	}
