		public static IStreamProperty Find(string engineName)
		{
			IStreamProperty streamProperty = FindQuickAccessProperty(engineName);
			return streamProperty ?? FindBatchProperty(engineName);
		}

		public static StateConditionProperty FindQuickAccessProperty(string engineName)
		{
			return QuickAccessProperties.FirstOrDefault((StateConditionProperty x) => string.Equals(x.EngineName, engineName, StringComparison.OrdinalIgnoreCase));
		}

		public static BatchProperty FindBatchProperty(string engineName)
		{
			return BatchProperties.FirstOrDefault((BatchProperty x) => string.Equals(x.EngineName, engineName, StringComparison.OrdinalIgnoreCase));
		}

		private static bool Mixed(string substreamType)
		{
			return string.Equals(substreamType, "MIXED", StringComparison.OrdinalIgnoreCase);
		}

		private static bool MixedAndCisolid(string substreamType)
		{
			if (!string.Equals(substreamType, "MIXED", StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(substreamType, "CISOLID", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static bool MixedAndTotal(string substreamType)
		{
			if (!string.Equals(substreamType, "MIXED", StringComparison.OrdinalIgnoreCase))
			{
				return string.Equals(substreamType, "ALL", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private static bool NoTotal(string substreamType)
		{
			return !string.Equals(substreamType, "ALL", StringComparison.OrdinalIgnoreCase);
		}

		private static bool MixedAndCisolidAndTotal(string substreamType)
		{
			return !string.Equals(substreamType, "NC", StringComparison.OrdinalIgnoreCase);
		}

		private static bool MixedAndTotalWhenNoNC(string substreamType)
		{
			if (string.Equals(substreamType, "ALL", StringComparison.OrdinalIgnoreCase))
			{
				return !ResultContext.HasNCSubstream;
			}
			return string.Equals(substreamType, "MIXED", StringComparison.OrdinalIgnoreCase);
		}

		private static bool MixedAndCisolidAndTotalWhenNoNC(string substreamType)
		{
			if (string.Equals(substreamType, "ALL", StringComparison.OrdinalIgnoreCase))
			{
				return !ResultContext.HasNCSubstream;
			}
