		public static IEnumerable<string> GetVaildComponents(string nodePath)
		{
			if (!nodePath.Contains("Results Summary"))
			{
				string text = nodePath.Replace(".Data.", ".").Replace(".Blocks.", ".").Replace(".Streams.", ".")
					.Replace("Top.appModelV8.", "");
				if (nodePath.Contains("Streams"))
				{
					return GetSingleStreamComponents(AdbDataProvider.GetStreamElement(text));
				}
				if (text.Split('.').Length == 1)
				{
					return GetAllStreamsComponents(AdbDataProvider.GetAllStreamsElements());
				}
				AccessorElement blockElement = AdbDataProvider.GetBlockElement(text.Substring(0, text.LastIndexOf('.')));
				if (blockElement.success)
				{
					AccessorElement subElement = blockElement.GetSubElement("SubFlowsheets.Simulation.Streams");
					if (subElement.success)
					{
						return GetAllStreamsComponents(subElement.GetChildren());
					}
				}
			}
			return new List<string>();
		}

