		private static IEnumerable<string> GetAllStreamsComponents(IEnumerable<AccessorElement> streamElements)
		{
			List<string> list = new List<string>();
			if (streamElements != null)
			{
				foreach (AccessorElement streamElement in streamElements)
				{
					IEnumerable<string> singleStreamComponents = GetSingleStreamComponents(streamElement);
					list = list.Union(singleStreamComponents).ToList();
				}
			}
			return list;
		}

