	public static class StreamReportClipboardHelper
	{
		private static char[] dotsplit = new char[1] { '.' };

		internal static void DoDataCopy(StreamReportControl src, GridControlCopyEventArgs e)
		{
			if (src.ReportGrid != null && src.ReportGrid.DataSource != null && src.ReportGrid.HasSelection && src.UnityContainer != null)
			{
				string text = e.GenerateTextToCopy();
				CxsCase activeCxsCase = src.UnityContainer.GetActiveCxsCase();
				e.ClipboardContents.Add(DataFormats.Text, text);
				e.ClipboardContents.Add("CSV", ConvertToDefaultStream(GenerateCsvFormatContent(text)));
				e.ClipboardContents.Add("DatagridMetadata", ConvertToStream(GenerateDatagridMetadataFormatContent(src, e)));
				string asiSelectionGridXml = ClipboardHelper.GetAsiSelectionGridXml(CreateCellDataPackage(src, e.ResolvedIncludeHeader), activeCxsCase.CaseFullFilePath, activeCxsCase.ApplicationName);
				e.ClipboardContents.Add("ASI Format", ConvertToStream(asiSelectionGridXml));
				e.ClipboardContents.Add("ASI File Format", ConvertToStream(GenerateAsiFileFormatContent(activeCxsCase.CaseFullFilePath, activeCxsCase.ApplicationName)));
				e.Handled = true;
			}
		}

		internal static void DoDataDrag(StreamReportControl src, GridControlDataDraggingEventArgs e)
		{
			if (src.ReportGrid != null && src.ReportGrid.DataSource != null && src.ReportGrid.HasSelection && src.UnityContainer != null)
			{
				string data = e.GenerateTextToCopy();
				e.DataObject.SetData(DataFormats.Text, data);
				CxsCase activeCxsCase = src.UnityContainer.GetActiveCxsCase();
				string asiSelectionGridXml = ClipboardHelper.GetAsiSelectionGridXml(CreateCellDataPackage(src, includesHeader: false), activeCxsCase.CaseFullFilePath, activeCxsCase.ApplicationName);
				e.DataObject.SetData(DataFormats.GetDataFormat("ASI Format").Name, asiSelectionGridXml);
			}
		}

		private static string ConvertPathToCxs(string adsPath)
		{
			string text = "";
			string[] array = adsPath.Split(dotsplit, StringSplitOptions.RemoveEmptyEntries);
			int i;
			for (i = 2; array[i].Equals("Blocks"); i += 4)
			{
				text = text + "Blocks." + array[i + 1] + ".Data.";
			}
			return text + "Streams." + array[i + 1] + ".SharedData";
		}

		internal static string FixSharedCxsPath(string originalSharedCxsPath)
		{
			if (string.IsNullOrEmpty(originalSharedCxsPath))
			{
				return originalSharedCxsPath;
			}
			string text = originalSharedCxsPath;
			if (!string.IsNullOrEmpty(text) && !text.StartsWith("cxs:", StringComparison.InvariantCultureIgnoreCase))
			{
				if (!text.StartsWith("Top.", StringComparison.InvariantCultureIgnoreCase))
				{
					text = "Top." + text;
				}
				text = "cxs:" + text;
			}
			string text2 = text;
			int num = text2.IndexOf("appModel.SharedData");
			int length = "appModel.".Length;
			if (num >= 0)
			{
				int num2 = text2.IndexOf("Flowsheet.Streams.", num);
				if (num2 == -1)
				{
					num2 = text2.IndexOf("Simulation.Streams.", num);
				}
				int num3 = text2.IndexOf(".", num2 + 1);
				num3 = text2.IndexOf(".", num3 + 1);
				num3 = text2.IndexOf(".", num3 + 1);
				string text3 = text2.Substring(num + length, num3 - (num + length));
				text2 = text2.Replace(text3, ConvertPathToCxs(text3));
			}
			return text2;
		}

