		private static List<IGridCellData> CreateCellDataPackage(StreamReportControl src, bool includesHeader)
		{
			List<IGridCellData> list = new List<IGridCellData>();
			int num = -1;
			int num2 = -1;
			List<int> list2 = new List<int>();
			if (src.ReportGrid.DataSource != null && src.ReportGrid.DataSource.Columns != null)
			{
				foreach (DataColumn column in src.ReportGrid.DataSource.Columns)
				{
					if (column.Visibility != Visibility.Visible)
					{
						list2.Add(column.DisplayIndex);
					}
				}
			}
			if (includesHeader)
			{
				foreach (DataColumn selectedColumn in src.ReportGrid.SelectedColumns)
				{
					CxsGridCellData item = new CxsGridCellData
					{
						TextValue = selectedColumn.Header,
						ColumnIndex = GetFinalColumnIndex(list2, selectedColumn),
						RowIndex = 0
					};
					list.Add(item);
					num = 0;
				}
			}
			List<DataRow> list3 = new List<DataRow>();
			if (src.ReportGrid != null && src.ReportGrid.BoundRows != null)
			{
				list3 = src.ReportGrid.BoundRows.ToList();
			}
			foreach (DataCellInfo totalOrderedSelectedCell in src.ReportGrid.TotalOrderedSelectedCells)
			{
				int num3 = list3.IndexOf(totalOrderedSelectedCell.Row);
				if (includesHeader)
				{
					num3++;
				}
				if (num3 < 0)
				{
					num3 = 0;
				}
				int finalColumnIndex = GetFinalColumnIndex(list2, totalOrderedSelectedCell.Column);
				if (num == -1 || num3 < num)
				{
					num = num3;
				}
				if (num2 == -1 || finalColumnIndex < num2)
				{
					num2 = finalColumnIndex;
				}
				CxsGridCellData item2 = new CxsGridCellData
				{
					Moniker = GetCellCxsDataPath(totalOrderedSelectedCell),
					RowIndex = num3,
					ColumnIndex = finalColumnIndex,
					TextValue = ((totalOrderedSelectedCell.Data != null) ? totalOrderedSelectedCell.Data.ToString() : string.Empty)
				};
				list.Add(item2);
			}
			foreach (IGridCellData item3 in list)
			{
				item3.RowIndex -= num;
				item3.ColumnIndex -= num2;
			}
			return list;
		}

		private static int GetFinalColumnIndex(List<int> hiddenColumns, DataColumn column)
		{
			int displayIndex = column.DisplayIndex;
			int num = 0;
			foreach (int hiddenColumn in hiddenColumns)
			{
				if (hiddenColumn < displayIndex)
				{
					num++;
				}
			}
			return displayIndex - num;
		}

		private static string GetCellCxsDataPath(DataCellInfo cell)
		{
			IDataCell data = cell.Data;
			if (data != null && data.Tag is ICellTag cellTag)
			{
				if (cellTag.ExtraPropertyTemplate != null)
				{
					return ComposeSpecialStreamReportCxsPath(cellTag.CxsPath, cellTag.FullStreamId, cellTag.ExtraPropertyTemplate);
				}
				return cellTag.CxsPath;
			}
			return null;
		}

		public static string ComposeSpecialStreamReportCxsPath(string originalCxsPath, string streamId, TemplatePropertyItem tpi)
		{
			XElement xElement = new XElement("metadata");
			xElement.SetAttributeValue("for", "streamReport");
			xElement.SetElementValue("streamId", streamId);
			XElement xElement2 = new XElement("property");
			xElement2.Add(tpi.Save());
			xElement.Add(xElement2);
			return originalCxsPath + xElement.ToString(SaveOptions.DisableFormatting);
		}

