			private static object FixOriginalValue(object originalValue)
			{
				if (originalValue != null)
				{
					if (originalValue is double num)
					{
						if (num == -1E+35 || num == 1E+35)
						{
							return null;
						}
					}
					else if (originalValue is double? && ((double?)originalValue == -1E+35 || (double?)originalValue == 1E+35))
					{
						return null;
					}
				}
				return originalValue;
			}
		}

