		private AdsData GetRecordOriginalValue(ILeafPropertyRecord record)
		{
			AdsData adsData = null;
			IAdsNativeProperty adsNativeProperty = record.AdsNativeProperty;
			if (adsNativeProperty != null)
			{
				return GetBuiltInProperty(record, adsNativeProperty);
			}
			return GetExtraProperty(record);
