		public string GetRecordPathValue(ILeafPropertyRecord record)
		{
			IAdsNativeProperty adsNativeProperty = record.AdsNativeProperty;
			string adsNativePropertyName = null;
			string text = null;
			string result = null;
			AccessorElement accessorElement = new AccessorElement();
			if (adsNativeProperty != null)
			{
				text = adsNativeProperty.AdsSubstreamPropertyName;
				if (string.IsNullOrEmpty(record.Phase) || string.Equals(record.Phase, "Total"))
				{
					accessorElement = GetSubstreamElement(record.Substream);
					if (!PhysicalProperty.TotalEngineNameToSumDictionary.Keys.Contains(text))
					{
						return null;
					}
					adsNativePropertyName = PhysicalProperty.TotalEngineNameToSumDictionary[text];
				}
				else if (!string.IsNullOrEmpty(adsNativeProperty.AdsPhasePropertyName))
				{
					accessorElement = StreamElement.GetSubElement(record.Phase);
					if (!PhysicalProperty.ChildEngineNameToSumDictionary.Keys.Contains(text))
					{
						return null;
					}
					adsNativePropertyName = PhysicalProperty.ChildEngineNameToSumDictionary[text];
				}
				if (accessorElement.success)
				{
					result = GetAdsNavtiveProperty(accessorElement, adsNativePropertyName, null).CxsPath;
				}
				return result;
			}
			if (ExtraProperties == null)
			{
				return null;
			}
			try
			{
				string path = CreatExtraPropertyMXKey(record, record.Substream, null);
				AdsData adsDataAtPath = GetAdsDataAtPath(ExtraProperties, path);
				if (adsDataAtPath != null)
				{
					return adsDataAtPath.CxsPath;
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.LogDebug(ex.Message + "\n" + ex.StackTrace);
				return null;
			}
			return null;
		}

		public int? GetComponentAttributeUnitRow(string substream, string componentName, string attributeName, string elementName)
