		public IDataCell GetComponentAttributeValue(string substream, string componentName, string attributeName, string elementName, string displayUnit, string format)
		{
			CompAttrItem componentAttribute = GetComponentAttribute(substream, componentName, attributeName, elementName);
			if (componentAttribute != null)
			{
				if (!componentAttribute.Value.HasValue)
				{
					return DoDefaultFormat(null, new AdsData(this, componentAttribute), format);
				}
				double value = componentAttribute.Value.Value;
				if (!string.IsNullOrEmpty(displayUnit))
				{
					double? num = Filler.AdbUnitsProvider.ConvertFromSI(componentAttribute.UnitRow, value, displayUnit);
					if (num.HasValue)
					{
						value = num.Value;
					}
				}
				return DoDefaultFormat(value, new AdsData(this, componentAttribute)
				{
					ValueAtCurrentUnit = value
				}, format);
			}
			return new DataCellText();
		}

		private CompAttrItem GetComponentAttribute(string substream, string componentName, string attributeName, string elementName)
		{
			EnsureComponentAttributesFlatterned();
			return _componentAttributes.FirstOrDefault((CompAttrItem x) => string.Equals(x.Substream, substream, StringComparison.InvariantCultureIgnoreCase) && string.Equals(x.Component, componentName, StringComparison.InvariantCultureIgnoreCase) && string.Equals(x.Attribute, attributeName, StringComparison.InvariantCultureIgnoreCase) && (string.IsNullOrEmpty(elementName) || string.Equals(x.Element, elementName, StringComparison.InvariantCultureIgnoreCase)));
		}

		private void EnsureComponentAttributesFlatterned()
		{
			if (_componentAttributes != null)
			{
				return;
			}
			_componentAttributes = new List<CompAttrItem>();
			AccessorElement subElement = StreamElement.GetSubElement("ComponentAttributes");
			if (!subElement.success)
			{
				return;
			}
			foreach (AccessorElement child in subElement.GetChildren())
			{
				if (!child.success)
				{
					continue;
				}
				AccessorElement subElement2 = child.GetSubElement("PropertyArray");
				if (!subElement2.success)
				{
					continue;
				}
				string attribute = child.attribute;
				foreach (AccessorElement child2 in subElement2.GetChildren())
				{
					if (child2.success && child2.attribute != null)
					{
						string[] array = child2.attribute.Split(',');
						if (array.Length >= 4)
						{
							string element = array[0];
							string substream = array[1];
							string component = array[3];
							_componentAttributes.Add(new CompAttrItem(substream, component, attribute, element, child2.unitrow, child2.value as double?, child2.cxsPath));
						}
					}
				}
			}
		}

		public IDataCell GetPsdValue(string substream, string psdId, int psdElementIndex, string format)
