			{
				AdsData adsDataAtPath = GetAdsDataAtPath(substreamElement, $"PSD.WeightFractions.#{psdElementIndex}");
				if (adsDataAtPath != null)
				{
					return DoDefaultFormat(adsDataAtPath.OriginalValueAsDouble, adsDataAtPath, format);
				}
			}
			return new DataCellText();
		}

		private AdsData GetBuiltInProperty(ILeafPropertyRecord record, IAdsNativeProperty stpi)
		{
			if (string.Equals(record.Substream, "ALL"))
			{
				if (!string.IsNullOrEmpty(stpi.AdsStreamPropertyName))
				{
					AdsData adsNavtiveProperty = GetAdsNavtiveProperty(StreamElement, stpi.AdsStreamPropertyName, record.Component);
					if (adsNavtiveProperty != null)
					{
						return adsNavtiveProperty;
					}
				}
			}
			else if (string.IsNullOrEmpty(record.Phase) || string.Equals(record.Phase, "Total"))
			{
				if (!string.IsNullOrEmpty(stpi.AdsSubstreamPropertyName))
				{
					AccessorElement substreamElement = GetSubstreamElement(record.Substream);
					if (substreamElement.success)
					{
						AdsData adsNavtiveProperty2 = GetAdsNavtiveProperty(substreamElement, stpi.AdsSubstreamPropertyName, record.Component);
						if (adsNavtiveProperty2 != null)
						{
							return adsNavtiveProperty2;
						}
					}
				}
			}
			else if (!string.IsNullOrEmpty(stpi.AdsPhasePropertyName))
			{
				AccessorElement substreamElement2 = GetSubstreamElement(record.Substream);
				if (substreamElement2.success)
				{
					AccessorElement subElement = substreamElement2.GetSubElement(record.Phase);
					if (subElement.success)
					{
						AdsData adsNavtiveProperty3 = GetAdsNavtiveProperty(subElement, stpi.AdsPhasePropertyName, record.Component);
						if (adsNavtiveProperty3 != null && !adsNavtiveProperty3.IsNullValue)
						{
							return adsNavtiveProperty3;
						}
					}
				}
				AccessorElement subElement2 = StreamElement.GetSubElement(record.Phase);
				if (subElement2.success)
				{
					AdsData adsNavtiveProperty4 = GetAdsNavtiveProperty(subElement2, stpi.AdsPhasePropertyName, record.Component);
					if (adsNavtiveProperty4 != null)
					{
						return adsNavtiveProperty4;
					}
				}
			}
			return null;
		}

		private AdsData GetAdsNavtiveProperty(AccessorElement holder, string adsNativePropertyName, string component)
		{
			if (component != null && component.Contains("."))
			{
				AccessorElement nativeProperty = holder.GetNativeProperty(adsNativePropertyName, "'" + component + "'");
				if (nativeProperty != null)
				{
					return new AdsData(this, nativeProperty);
				}
			}
			else
			{
				AccessorElement nativeProperty2 = holder.GetNativeProperty(adsNativePropertyName, component);
				if (nativeProperty2 != null)
				{
					return new AdsData(this, nativeProperty2);
				}
			}
			return null;
		}



		private AdsData GetExtraPropertyValue(ILeafPropertyRecord record, string component = null)
		{
			string path = CreatExtraPropertyKey(record, record.Substream, component);
			AdsData adsDataAtPath = GetAdsDataAtPath(ExtraProperties, path);
			if (adsDataAtPath != null)
			{
				return adsDataAtPath;
			}
			if (string.Equals(record.Substream, ResultContext.TotalSubstream, StringComparison.InvariantCultureIgnoreCase))
			{
				return null;
			}
			if (ResultContext.ValidSubstreams.Count != 1)
			{
				return null;
			}
			string path2 = CreatExtraPropertyKey(record, ResultContext.TotalSubstream, component);
			return GetAdsDataAtPath(ExtraProperties, path2);
		}

		private string CreatExtraPropertyKey(ILeafPropertyRecord record, string substream, string component)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(record.PropertyNameInExtraProperties).Append(',');
			if (substream == null)
			{
				substream = record.Substream;
			}
			if (string.Equals(substream, "ALL", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("$TOTAL,");
			}
			else
			{
				stringBuilder.Append(substream).Append(',');
			}
			if (string.IsNullOrEmpty(record.Phase))
			{
				stringBuilder.Append(',');
			}
			else if (string.Equals(record.Phase, "Liquid1", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("LIQUID_1,");
			}
			else if (string.Equals(record.Phase, "Liquid2", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("LIQUID_2,");
			}
			else
			{
				stringBuilder.Append(record.Phase.ToUpperInvariant()).Append(',');
			}
			string text = component ?? record.Component;
			if (!string.IsNullOrEmpty(text))
			{
				stringBuilder.Append(text.Replace('.', '_').Replace(',', '!'));
			}
			stringBuilder.Append(',');
			if (!string.IsNullOrEmpty(record.WalterBasis) && !string.Equals(record.WalterBasis, "WET", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append(record.WalterBasis);
			}
			stringBuilder.Append(',');
			if (record.PressureBasis.HasValue)
			{
				stringBuilder.Append(record.PressureBasis.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			stringBuilder.Append(',');
			if (record.TemperatureBasis.HasValue)
			{
				stringBuilder.Append(record.TemperatureBasis.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			stringBuilder.Append(',');
			if (record.LiquidWeightOrVolumePercent.HasValue)
			{
				stringBuilder.Append(record.LiquidWeightOrVolumePercent.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			return stringBuilder.ToString();
		}

		private string CreatExtraPropertyMXKey(ILeafPropertyRecord record, string substream, string component)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (!PhysicalProperty.CorrespondingEngineNames.Keys.Contains(record.PropertyItem.EngineName))
			{
				return null;
			}
			string value = PhysicalProperty.CorrespondingEngineNames[record.PropertyItem.EngineName];
			stringBuilder.Append(value).Append(',');
			if (substream == null)
			{
				substream = record.Substream;
			}
			if (string.Equals(substream, "ALL", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("$TOTAL,");
			}
			else
			{
				stringBuilder.Append(substream).Append(',');
			}
			if (string.IsNullOrEmpty(record.Phase))
			{
				stringBuilder.Append(',');
			}
			else if (string.Equals(record.Phase, "Liquid1", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("LIQUID_1,");
			}
			else if (string.Equals(record.Phase, "Liquid2", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append("LIQUID_2,");
			}
			else
			{
				stringBuilder.Append(record.Phase.ToUpperInvariant()).Append(',');
			}
			stringBuilder.Append(',');
			if (!string.IsNullOrEmpty(record.WalterBasis) && !string.Equals(record.WalterBasis, "WET", StringComparison.InvariantCultureIgnoreCase))
			{
				stringBuilder.Append(record.WalterBasis);
			}
			stringBuilder.Append(',');
			if (record.PressureBasis.HasValue)
			{
				stringBuilder.Append(record.PressureBasis.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			stringBuilder.Append(',');
			if (record.TemperatureBasis.HasValue)
			{
				stringBuilder.Append(record.TemperatureBasis.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			stringBuilder.Append(',');
			if (record.LiquidWeightOrVolumePercent.HasValue)
			{
				stringBuilder.Append(record.LiquidWeightOrVolumePercent.Value.ToString(CultureInfo.InvariantCulture).Replace('.', '_'));
			}
			return stringBuilder.ToString();
		}

		public IDataCell FormatPropertyValue(TemplatePropertyItem tpi, bool isStateConditionProperty, double? siValue, string cxsPath, int unitRow, string displayUnit, string format)
		{
			AdsData adsData = new AdsData(this, siValue, cxsPath, unitRow);
			if (!isStateConditionProperty)
			{
				adsData.ExtraPropertyTemplate = tpi;
			}
			if (!siValue.HasValue)
			{
				return new DataCellDouble
				{
					Tag = adsData
				};
			}
			double value = siValue.Value;
			if (!string.IsNullOrEmpty(displayUnit))
			{
				double? num = Filler.AdbUnitsProvider.XConvertFromSI(unitRow, value, displayUnit);
				if (num.HasValue)
				{
					value = num.Value;
				}
			}
			adsData.ValueAtCurrentUnit = value;
			string format2 = (string.IsNullOrWhiteSpace(format) ? "g6" : format);
			string scaledText = GetScaledText(value, tpi, format2);
			if (!string.IsNullOrEmpty(scaledText))
			{
				return CreateCellData(scaledText, adsData);
			}
			string tracedText = GetTracedText(value, tpi, format2);
			if (!string.IsNullOrEmpty(tracedText))
			{
				return CreateCellData(tracedText, adsData);
			}
			string pPBText = GetPPBText(value, tpi, format2);
			if (!string.IsNullOrEmpty(pPBText))
			{
				return CreateCellData(pPBText, adsData);
			}
			string pPMText = GetPPMText(value, tpi, format2);
			if (!string.IsNullOrEmpty(pPMText))
			{
				return CreateCellData(pPMText, adsData);
			}
			return DoDefaultFormat(value, adsData, format);
		}

		private IDataCell FormatPropertyValue(double? value, string cxsPath, int unitRow, ILeafPropertyRecord record)
		{
			string text = record.Unit;
			if (string.IsNullOrEmpty(text) && unitRow != 0)
			{
				text = Filler.AdbUnitsProvider.GetDefaultDisplayUnits(unitRow);
			}
			return FormatPropertyValue(record.PropertyItem, record.AdsNativeProperty != null, value, cxsPath, unitRow, text, record.Format);
		}

		private IDataCell DoDefaultFormat(double? displayValue, ICellTag tag, string format)
		{
			if (displayValue.HasValue && double.IsNaN(displayValue.Value))
			{
				displayValue = null;
			}
			IDataCell dataCell = CreateCellData(displayValue, tag);
			if (!string.IsNullOrEmpty(format))
			{
				dataCell.Mask = format;
			}
			return dataCell;
		}

		private string GetScaledText(double value, TemplatePropertyItem pi, string format)
		{
			double? doubleSetting = GetDoubleSetting(pi, "Scale");
			if (doubleSetting.HasValue)
			{
				string text = (value / doubleSetting.Value).ToString(format);
				string text2 = pi["Scale-Label"];
				if (!string.IsNullOrEmpty(text2))
				{
					return $"{text} {text2}";
				}
				return text;
			}
			return null;
		}

		private string GetTracedText(double value, TemplatePropertyItem pi, string format)
		{
			double? doubleSetting = GetDoubleSetting(pi, "Trace");
			if (doubleSetting.HasValue && value < doubleSetting.Value)
			{
				if (value == 0.0)
				{
					return 0.0.ToString(format);
				}
				return pi["Trace-Label"];
			}
			return null;
		}



		private static double? GetDoubleSetting(TemplatePropertyItem pi, string setting)
		{
			string text = pi[setting];
			if (!string.IsNullOrEmpty(text))
			{
				double result = 0.0;
				if (double.TryParse(text, out result))
				{
					return result;
				}
			}
			return null;
		}

		private AccessorElement GetSubstreamElement(string substream)
		{
			return StreamElement.GetSubElement($"Substreams.{substream}");
		}

		private AdsData GetAdsDataAtPath(AccessorElement element, string path)
		{
			AccessorElement subElement = element.GetSubElement(path);
			if (subElement.success)
			{
				return new AdsData(this, subElement);
			}
			return null;
		}

		private bool NeedsNormalization(ILeafPropertyRecord record)
		{
			if (string.IsNullOrEmpty(record.Component))
			{
				return false;
			}
			if (record.AllowedComponents == null)
			{
				return false;
			}
			if (record.PropertyItem == null)
			{
				return false;
			}
			if (!string.Equals(record.PropertyItem["Normalize"], "YES", StringComparison.InvariantCultureIgnoreCase))
			{
				return false;
			}
			return string.IsNullOrEmpty(record.PropertyItem["Comps"]);
		}

		private IDataCell CreateCellData(object value, ICellTag tag)
		{
			return DataRow.CreateDataCell(value, isReadOnly: false, null, CellUIType.Unknown, tag);
		}
	}
