		{
			Settings = new ReportTemplateSettings(this);
		}

		public void OnDataSubPropertyChanged(TemplateOptionsBase dataProperty, string propertyName)
		{
			ProcessPropertyChanged($"{dataProperty.GetType().Name}.{propertyName}");
		}

		public bool IsDirty(IUnityContainer unityContainer = null)
		{
			IUnityContainer unityContainer2 = unityContainer ?? UnityContainer;
			if (unityContainer2 != null)
			{
				ReportTemplateItem reportTemplateItem = unityContainer2.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>()).FindOriginalTemplate(this);
				if (reportTemplateItem != null)
				{
					ReportTemplatesManager.ReloadTemplateSettings(reportTemplateItem);
					string b = reportTemplateItem.Settings.Save().ToString(SaveOptions.DisableFormatting);
					return !string.Equals(Settings.Save().ToString(SaveOptions.DisableFormatting), b, StringComparison.CurrentCultureIgnoreCase);
				}
			}
			return false;
		}

		public void TagAsInMemory()
		{
			IsInMomory = true;
			FilePath = null;
		}

		public virtual string Save()
		{
			XElement xElement = new XElement("ReportTemplateItem");
			xElement.SetElementValue("Name", Name);
			xElement.SetElementValue("Description", Description);
			xElement.SetElementValue("Sequence", Sequence);
			xElement.SetElementValue("Type", Type);
			xElement.SetElementValue("Settings", Settings.Save().ToString(SaveOptions.DisableFormatting));
			return xElement.ToString(SaveOptions.DisableFormatting);
		}

		public static ReportTemplateItem Parse(string templateInText)
		{
			if (!string.IsNullOrWhiteSpace(templateInText))
			{
				XElement xElement = null;
				try
				{
					xElement = XElement.Parse(templateInText);
				}
				catch (Exception ex)
				{
					SystemEnvironment.LogDebug(ex.Message);
				}
				if (xElement != null)
				{
					ReportTemplateItem reportTemplateItem = new ReportTemplateItem();
					reportTemplateItem.Name = (string)xElement.Element("Name");
					reportTemplateItem.Description = (string)xElement.Element("Description");
					string text = (string)xElement.Element("Sequence");
					if (!string.IsNullOrWhiteSpace(text))
					{
						int result = 0;
						if (int.TryParse(text, out result))
						{
							reportTemplateItem.Sequence = result;
						}
					}
					string value = (string)xElement.Element("Type");
					if (!string.IsNullOrWhiteSpace(text))
					{
						ReportTemplateType result2 = ReportTemplateType.UserDefined;
						if (Enum.TryParse<ReportTemplateType>(value, out result2))
						{
							reportTemplateItem.Type = result2;
						}
					}
					string text2 = (string)xElement.Element("Settings");
					if (!string.IsNullOrWhiteSpace(text2))
					{
						try
						{
							XElement element = XElement.Parse(text2);
							reportTemplateItem.Settings.Parse(element);
						}
						catch (Exception ex2)
						{
							SystemEnvironment.LogDebug(ex2.Message);
						}
					}
					return reportTemplateItem;
				}
			}
			return null;
		}

		private void ProcessPropertyChanged(string propertyName)
		{
			if (!SuppressEvents && UnityContainer != null)
			{
				UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplatePropertyChangedEvent>().Publish(new ReportTemplatePropertyChangedEventArgs(Name, propertyName));
			}
		}
	}
	public class CssReportTemplateItem : ReportTemplateItem
	{
		private ReportTemplateSettings _settings;

		public CssTemplateHeaderInfo CssHeaderInfo { get; private set; }

		public override ReportTemplateSettings Settings
		{
			get
			{
				if (_settings == null)
				{
					_settings = new ReportTemplateSettings(this);
					if (CssHeaderInfo != null)
					{
						try
						{
							string cssTemplateContent = WrapperProxy.GetCssTemplateContent(CssHeaderInfo);
							ReportTemplateReader.PopulateCssTemplateSettings(this, cssTemplateContent);
						}
						catch (Exception ex)
						{
							SystemEnvironment.LogDebug("Error in CssReportTemplateItem.CreateTemplateSettings: " + ex.Message);
						}
					}
				}
				return _settings;
			}
		}

		public string LongName
		{
			get
			{
				if (!string.IsNullOrWhiteSpace(base.Description))
				{
					return $"{base.Name} ({base.Description})";
				}
				return base.Name;
			}
		}

		public CssReportTemplateItem(CssTemplateHeaderInfo cssHeaderInfo)
		{
			if (cssHeaderInfo == null)
			{
				throw new ArgumentNullException("cssHeaderInfo");
			}
			CssHeaderInfo = cssHeaderInfo;
			base.Description = cssHeaderInfo.Description;
			base.Type = ReportTemplateType.CssTemplate;
			base.Name = CreateUniqueName(cssHeaderInfo);
			TagAsInMemory();
		}

		public void ResetSettings()
		{
			_settings = null;
		}

		private static string CreateUniqueName(CssTemplateHeaderInfo cssHeaderInfo)
		{
			StringBuilder stringBuilder = new StringBuilder("CSS_").Append(cssHeaderInfo.Name);
			string cssTypeText = GetCssTypeText(cssHeaderInfo.Type);
			if (!string.IsNullOrEmpty(cssTypeText))
			{
				stringBuilder = stringBuilder.Append('_').Append(cssTypeText);
			}
			if (!string.IsNullOrWhiteSpace(cssHeaderInfo.ContextNavPath))
			{
				stringBuilder = stringBuilder.Insert(0, $"[{ConvertContextString(cssHeaderInfo.ContextNavPath)}] ");
			}
			return stringBuilder.ToString();
		}

		private static string GetCssTypeText(int cssType)
		{
			return cssType switch
			{
				0 => null, 
				1 => "Similar", 
				2 => "SimilarInHierarchy", 
				3 => "GlobalInHierarchy", 
				4 => "Global", 
				_ => null, 
			};
		}

		private static string ConvertContextString(string contextPath)
		{
			if (string.Equals(contextPath, "EO-VARS", StringComparison.InvariantCultureIgnoreCase))
			{
				return "PLANT";
			}
			contextPath = contextPath.Replace(".EO-VARS.", ".PLANT.");
			if (contextPath.EndsWith(".EO-VARS", StringComparison.InvariantCultureIgnoreCase))
			{
				contextPath = contextPath.Substring(0, contextPath.LastIndexOf('.')) + ".PLANT";
			}
			return contextPath;
		}
	}
