		}

		private void UpdateUserAddedProperties()
		{
			ObservableCollection<TemplatePropertyItem> userAddedProperties = _userAddedProperties;
			ObservableCollection<TemplatePropertyItem> properties = Properties;
			userAddedProperties.Clear();
			foreach (TemplatePropertyItem item in properties)
			{
				if (item.StreamProperty.PropertyType == StreamPropertyType.PhysicalProperty)
				{
					userAddedProperties.Add(item);
				}
			}
		}

		public XElement Save()
		{
			XElement xElement = new XElement("TFFTable");
			xElement.Add(new XElement("GeneralOptions", GeneralOptions.Save()));
			xElement.Add(new XElement("ScopeOptions", ScopeOptions.Save()));
			if (Properties.Count > 0)
			{
				xElement.Add(CreatePropertiesElement("Properties", Properties));
			}
			return xElement;
		}

		public void Parse(XElement element)
		{
			if (element == null)
			{
				throw new ArgumentNullException("elmement");
			}
			GeneralOptions.Parse((string)element.Element("GeneralOptions"));
			ScopeOptions.Parse((string)element.Element("ScopeOptions"));
			try
			{
				LockPropertiesChanged();
				Properties.Clear();
				foreach (TemplatePropertyItem item in ParseProperties(element, "Properties"))
				{
					Properties.Add(item);
				}
				EnsureStateConditionProperties();
			}
			finally
			{
				UnlockPropertiesChanged(raiseEvent: true);
			}
		}

		public void OnDataSubPropertyChanged(TemplateOptionsBase dataProperty, string propertyName)
		{
			EnsureStateConditionProperties();
			Parent.OnDataSubPropertyChanged(dataProperty, propertyName);
		}

		private XElement CreatePropertiesElement(string elementName, IEnumerable<TemplatePropertyItem> properties)
		{
			XElement xElement = new XElement(elementName);
			foreach (TemplatePropertyItem property in properties)
			{
				XElement xElement2 = property.Save();
				if (xElement2 != null)
				{
					xElement.Add(xElement2);
				}
			}
			return xElement;
		}

		[IteratorStateMachine(typeof(ParsePropertiesEnumerator))]
		private IEnumerable<TemplatePropertyItem> ParseProperties(XElement parent, string elementName)
		{
			return new ParsePropertiesEnumerator(-2)
			{
				initialParent = parent,
				initialElementName = elementName
			};
		}

		public void EnsureStateConditionProperties()
		{
			List<IStreamProperty> stps = CreateStateConditionProperties();
			List<IStreamProperty> list = stps.Except(Properties.Select((TemplatePropertyItem x) => x.StreamProperty)).ToList();
			List<TemplatePropertyItem> list2 = Properties.Where((TemplatePropertyItem x) => x.StreamProperty.PropertyType != StreamPropertyType.PhysicalProperty && !stps.Contains(x.StreamProperty)).ToList();
			try
			{
				LockPropertiesChanged();
				foreach (TemplatePropertyItem item in list2)
				{
					Properties.Remove(item);
				}
				if (list.Count <= 0)
				{
					return;
				}
				TemplatePropertyItem templatePropertyItem = Properties.FirstOrDefault((TemplatePropertyItem x) => x.StreamProperty.PropertyType == StreamPropertyType.PhysicalProperty);
				if (templatePropertyItem == null)
				{
					foreach (IStreamProperty item2 in list)
					{
						Properties.Add(new TemplatePropertyItem(item2));
					}
					return;
				}
				int num = Properties.IndexOf(templatePropertyItem);
				foreach (IStreamProperty item3 in list)
				{
					Properties.Insert(num++, new TemplatePropertyItem(item3));
				}
			}
			finally
			{
				UnlockPropertiesChanged(raiseEvent: true);
			}
		}

		public void InitializeAllOptions(bool flag)
		{
			try
			{
				LockPropertiesChanged();
				GeneralOptions.InitializeAllOptions(flag);
				ScopeOptions.InitializeAllOptions(flag);
			}
			finally
			{
				UnlockPropertiesChanged(raiseEvent: false);
			}
		}

		private List<IStreamProperty> CreateStateConditionProperties()
		{
			List<IStreamProperty> list = new List<IStreamProperty>();
			TemplateGeneralOptions generalOptions = GeneralOptions;
			if (generalOptions.Temperature)
			{
				list.Add(BasisStreamProperties.Temperature);
			}
			if (generalOptions.Pressure)
			{
				list.Add(BasisStreamProperties.Pressure);
			}
			if (generalOptions.MolarVaporFraction)
			{
				list.Add(BasisStreamProperties.MolarVaporFraction);
			}
			if (generalOptions.MolarLiquidFraction)
			{
				list.Add(BasisStreamProperties.MolarLiquidFraction);
			}
			if (generalOptions.MolarSolidFraction)
			{
				list.Add(BasisStreamProperties.MolarSolidFraction);
			}
			if (generalOptions.MassVaporFraction)
			{
				list.Add(BasisStreamProperties.MassVaporFraction);
			}
			if (generalOptions.MassLiquidFraction)
			{
				list.Add(BasisStreamProperties.MassLiquidFraction);
			}
			if (generalOptions.MassSolidFraction)
			{
				list.Add(BasisStreamProperties.MassSolidFraction);
			}
			if (generalOptions.MolarEnthalpy)
			{
				list.Add(BasisStreamProperties.MolarEnthalpy);
			}
			if (generalOptions.MassEnthalpy)
			{
				list.Add(BasisStreamProperties.MassEnthalpy);
			}
			if (generalOptions.MolarEntropy)
			{
				list.Add(BasisStreamProperties.MolarEntropy);
			}
			if (generalOptions.MassEntropy)
			{
				list.Add(BasisStreamProperties.MassEntropy);
			}
			if (generalOptions.MolarDensity)
			{
				list.Add(BasisStreamProperties.MolarDensity);
			}
			if (generalOptions.MassDensity)
			{
				list.Add(BasisStreamProperties.MassDensity);
			}
			if (generalOptions.EnthalpyFlow)
			{
				list.Add(BasisStreamProperties.EnthalpyFlow);
			}
			if (generalOptions.AverageMolecularWeight)
			{
				list.Add(BasisStreamProperties.AverageMolecularWeight);
			}
			TemplateScopeOptions scopeOptions = ScopeOptions;
			if (scopeOptions.MoleFlows)
			{
				list.Add(BasisStreamProperties.MolarComponentFlows);
			}
			if (scopeOptions.MoleFractions)
			{
				list.Add(BasisStreamProperties.MoleFractions);
			}
			if (scopeOptions.MassFlows)
			{
				list.Add(BasisStreamProperties.MassComponentFlows);
			}
			if (scopeOptions.MassFractions)
			{
				list.Add(BasisStreamProperties.MassFractions);
			}
			if (scopeOptions.VolumeFlows)
			{
				list.Add(BasisStreamProperties.VolumetricFlow);
			}
			if (generalOptions.BatchProperties)
			{
				if (scopeOptions.MoleFlows)
				{
					list.Add(BasisStreamProperties.CMoleCycle);
					list.Add(BasisStreamProperties.CMoleTime);
				}
				if (scopeOptions.MassFlows)
				{
					list.Add(BasisStreamProperties.CMassCycle);
					list.Add(BasisStreamProperties.CMassTime);
				}
				if (Properties.Any((TemplatePropertyItem x) => string.Equals(x.EngineName, "VLSTD-FL", StringComparison.InvariantCultureIgnoreCase)))
				{
					list.Add(BasisStreamProperties.CVolumeCycle);
					list.Add(BasisStreamProperties.CVolumeTime);
				}
				if (scopeOptions.VolumeFlows)
				{
					list.Add(BasisStreamProperties.VolumeCycle);
					list.Add(BasisStreamProperties.VolumeTime);
				}
				list.Add(BasisStreamProperties.EnthalpyCycle);
				list.Add(BasisStreamProperties.EnthalpyTime);
				list.Add(BasisStreamProperties.CycleTime);
				list.Add(BasisStreamProperties.OperationTime);
				list.Add(BasisStreamProperties.NumberOfTrains);
			}
			return list;
		}
	}
	public abstract class TemplateOptionsBase : NotifyPropertyChangedBase
	{
		private readonly Dictionary<string, bool> _dict = new Dictionary<string, bool>();

		private readonly ReportTemplateSettings _parent;

		protected ReportTemplateSettings Parent => _parent;

		protected TemplateOptionsBase(ReportTemplateSettings parent)
		{
			if (parent == null)
			{
				throw new ArgumentNullException("parent");
			}
			_parent = parent;
		}

		protected override void OnPropertyChanged(string propertyName)
		{
			base.OnPropertyChanged(propertyName);
			Parent.OnDataSubPropertyChanged(this, propertyName);
		}

		protected bool GetPropertyValue(string propertyName)
		{
			if (_dict.ContainsKey(propertyName))
			{
				return _dict[propertyName];
			}
			return false;
		}

		protected void SetPropertyValue(string propertyName, bool value)
		{
			if (_dict.ContainsKey(propertyName))
			{
				if (_dict[propertyName] != value)
				{
					_dict[propertyName] = value;
					OnPropertyChanged(propertyName);
				}
			}
			else
			{
				_dict.Add(propertyName, value);
				if (value)
				{
					OnPropertyChanged(propertyName);
				}
			}
		}

		public string Save()
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (KeyValuePair<string, bool> item in _dict)
			{
				if (item.Value)
				{
					stringBuilder.AppendIfNotEmpty(",").Append(item.Key);
				}
			}
			return stringBuilder.ToString();
		}

		public void Parse(string text)
		{
			_dict.Clear();
			if (string.IsNullOrWhiteSpace(text))
			{
				return;
			}
			string[] array = text.Split(',');
			foreach (string text2 in array)
			{
				if (text2 != null)
				{
					string text3 = text2.Trim();
					if (!string.IsNullOrEmpty(text3))
					{
						_dict[text3] = true;
					}
				}
			}
		}

		public void Clear()
		{
			_dict.Clear();
		}
	}
