			}
		}

		public string Name
		{
			get
			{
				return _name;
			}
			set
			{
				SetPropertyValue("Name", ref _name, value);
			}
		}

		public string Value
		{
			get
			{
				return _value;
			}
			set
			{
				SetPropertyValue("Value", ref _value, value);
			}
		}

		public string Unit
		{
			get
			{
				return _unit;
			}
			set
			{
				SetPropertyValue("Unit", ref _unit, value);
			}
		}

		public bool IsCalculationQualifier => CalculationQualifiers.Contains(Name, StringComparer.OrdinalIgnoreCase);

		private string ResolvedTooltipName
		{
			get
			{
				if (string.Equals(Name, "Temp", StringComparison.OrdinalIgnoreCase))
				{
					return GridFormsResources.Tootip_ReferenceTemperature;
				}
				if (string.Equals(Name, "Pres", StringComparison.OrdinalIgnoreCase))
				{
					return GridFormsResources.Tootip_ReferencePressure;
				}
				if (DisplayNames.ContainsKey(Name))
				{
					return DisplayNames[Name];
				}
				return Name;
			}
		}

		public string[] ResolvedValues => StringArraySerializer.Deserialize(Value).ToArray();

		public bool IsValueDefaulted
		{
			get
			{
				if (string.IsNullOrWhiteSpace(Name))
				{
					return true;
				}
				if (string.IsNullOrWhiteSpace(Value))
				{
					return true;
				}
				return false;
			}
		}

		public string CreateTooltip()
		{
			if (!string.IsNullOrWhiteSpace(Name) && !string.IsNullOrWhiteSpace(Value))
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(ResolvedTooltipName);
				stringBuilder.Append(':').Append(' ');
				stringBuilder.Append(Value);
				if (!string.IsNullOrWhiteSpace(Unit))
				{
					stringBuilder.Append(' ').Append(Unit);
				}
				return stringBuilder.ToString();
			}
			return null;
		}

		public override bool Equals(object obj)
		{
			if (!(obj is SettingItem settingItem))
			{
				return false;
			}
			if (!string.Equals(Name, settingItem.Name, StringComparison.InvariantCulture))
			{
				return false;
			}
			if (!string.Equals(Unit, settingItem.Unit, StringComparison.InvariantCulture))
			{
				return false;
			}
			return SameValue(Value, settingItem.Value);
		}

		private static bool SameValue(string first, string second)
		{
			return StringArraySerializer.ArrayEquals(first, second);
		}
	}
	public class TemplatePropertyItem : NotifyPropertyChangedBase
	{
		public IStreamProperty StreamProperty { get; private set; }

		public virtual string EngineName => StreamProperty.EngineName;

		public virtual string DisplayName
		{
			get
			{
				if (!string.IsNullOrEmpty(this["DisplayName"]))
				{
					return this["DisplayName"];
				}
				return StreamProperty.DisplayName;
			}
			set
			{
				if (!string.Equals(DisplayName, value))
				{
					this["DisplayName"] = value;
					OnPropertyChanged("DisplayName");
				}
			}
		}

		public IList<SettingItem> Settings { get; protected set; }

		public string this[string index]
		{
			get
			{
				return GetMetadata(index)?.Value;
			}
			set
			{
				SetMetadata(index, value);
			}
		}

		public TemplatePropertyItem(IStreamProperty sp)
		{
			if (sp == null)
			{
				throw new ArgumentNullException("sp");
			}
			StreamProperty = sp;
			Settings = new List<SettingItem>();
		}

		public bool HasSameOptions(TemplatePropertyItem other)
		{
			if (other == null)
			{
				return false;
			}
			if (this == other)
			{
				return true;
			}
			if (!string.Equals(EngineName, other.EngineName, StringComparison.InvariantCultureIgnoreCase))
			{
				return false;
			}
			if (Settings.Count != other.Settings.Count)
			{
				return false;
			}
			foreach (SettingItem ts in Settings)
			{
				if (!other.Settings.Any((SettingItem os) => os.Equals(ts)))
				{
					return false;
				}
			}
			return true;
		}

		public void SetMetadata(string settingName, IEnumerable<string> values, string units = null)
		{
			if (settingName == null)
			{
				throw new ArgumentNullException("settingName");
			}
			if (values == null)
			{
				throw new ArgumentNullException("values");
			}
			SetMetadata(settingName, StringArraySerializer.Serialize(values), units);
		}

		public void SetMetadata(string settingName, string value, string units = null)
		{
			if (settingName == null)
			{
				throw new ArgumentNullException("settingName");
			}
			SettingItem settingItem = GetMetadata(settingName);
			if (settingItem == null)
			{
				settingItem = new SettingItem
				{
					Name = settingName
				};
				Settings.Add(settingItem);
			}
			settingItem.Value = value;
			settingItem.Unit = units;
			OnPropertyChanged(settingName);
		}

		public SettingItem GetMetadata(string settingName)
		{
			return Settings.FirstOrDefault((SettingItem x) => string.Equals(x.Name, settingName, StringComparison.OrdinalIgnoreCase));
		}

		public void RemoveMetadata(string settingName)
		{
			SettingItem metadata = GetMetadata(settingName);
			if (metadata != null)
			{
				Settings.Remove(metadata);
			}
		}

		public XElement Save()
		{
			if (!string.IsNullOrEmpty(EngineName))
			{
				XElement xElement = new XElement("Property");
				xElement.SetAttributeValue("Type", StreamProperty.PropertyType.ToString());
				xElement.SetAttributeValue("EngineName", EngineName);
				if (!string.IsNullOrWhiteSpace(StreamProperty.UserPropertySetName))
				{
					xElement.SetAttributeValue("UserPropertySetName", StreamProperty.UserPropertySetName);
				}
				{
					foreach (SettingItem setting in Settings)
					{
						if (!setting.IsValueDefaulted)
						{
							XElement xElement2 = new XElement("Column");
							xElement2.SetAttributeValue("Name", setting.Name);
							xElement2.SetAttributeValue("Value", setting.Value);
							if (!string.IsNullOrWhiteSpace(setting.Unit))
							{
								xElement2.SetAttributeValue("Unit", setting.Unit);
							}
							xElement.Add(xElement2);
						}
					}
					return xElement;
				}
			}
			return null;
		}

		public static TemplatePropertyItem Parse(XElement element)
		{
			if (element == null)
			{
				throw new ArgumentNullException("element");
			}
			string engineName = (string)element.Attribute("EngineName");
			string typeText = (string)element.Attribute("Type");
			string userPropertySetName = (string)element.Attribute("UserPropertySetName");
			IStreamProperty streamProperty = CreateStreamProperty(engineName, typeText, userPropertySetName);
			if (streamProperty != null)
			{
				TemplatePropertyItem templatePropertyItem = new TemplatePropertyItem(streamProperty);
				{
					foreach (XElement item in element.Elements("Column"))
					{
						XAttribute xAttribute = item.Attribute("Name");
						if (xAttribute != null && !string.IsNullOrEmpty(xAttribute.Value))
						{
							XAttribute xAttribute2 = item.Attribute("Value");
							if (xAttribute2 != null && !string.IsNullOrEmpty(xAttribute2.Value))
							{
								string units = item.Attribute("Unit")?.Value;
								templatePropertyItem.SetMetadata(xAttribute.Value, xAttribute2.Value, units);
							}
						}
					}
					return templatePropertyItem;
				}
			}
			return null;
		}

		private static IStreamProperty CreateStreamProperty(string engineName, string typeText, string userPropertySetName)
		{
			if (!string.IsNullOrEmpty(engineName))
			{
				StreamPropertyType result = StreamPropertyType.PhysicalProperty;
				if (!string.IsNullOrEmpty(typeText))
				{
					Enum.TryParse<StreamPropertyType>(typeText, out result);
				}
				return result switch
				{
					StreamPropertyType.StateConditionProperty => BasisStreamProperties.FindQuickAccessProperty(engineName), 
					StreamPropertyType.BatchProperty => BasisStreamProperties.FindBatchProperty(engineName), 
					_ => new PhysicalProperty(engineName, userPropertySetName), 
				};
			}
			return null;
		}
	}
	public class ReportTemplatesManager
	{
		private const string LocalInstalledTemplatesFolderName = "Stream Summary Templates";

		private const string LocalUserDefinedTemplatesFolderName = "Templates";

		private const string TemplateFileExtension = ".apsst";

		private const string SearchPattern = "*.apsst";

		private static readonly string InstalledTemplatesFolder = GetInstalledTemplatesFolder();

		private static readonly string UserDefinedTemplatesFolder = GetUserDefinedTemplatesFolder();

		private readonly IUnityContainer _unityContainer;

		public ReportTemplatesManager(IUnityContainer unityContainer)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			_unityContainer = unityContainer;
		}

		public IEnumerable<ReportTemplateItem> GetTemplateItems(bool includeCssTemplates = false, IHNode contextNode = null)
		{
			List<string> list = new List<string>();
			List<ReportTemplateItem> list2 = new List<ReportTemplateItem>();
			List<ReportTemplateItem> list3 = new List<ReportTemplateItem>();
			if (Directory.Exists(InstalledTemplatesFolder))
			{
				string[] files = Directory.GetFiles(InstalledTemplatesFolder, "*.apsst");
				for (int i = 0; i < files.Length; i++)
				{
					ReportTemplateItem reportTemplateItem = GenerateTemplateItemFromFile(files[i], ReportTemplateType.Installed);
					if (reportTemplateItem != null)
					{
						list3.Add(reportTemplateItem);
						list.Add(reportTemplateItem.Name.ToLower());
					}
				}
			}
			list2.AddRange(list3.OrderBy((ReportTemplateItem x) => x.Sequence));
			List<ReportTemplateItem> list4 = new List<ReportTemplateItem>();
			if (includeCssTemplates)
			{
				foreach (CssReportTemplateItem cssTemplateItem in GetCssTemplateItems(contextNode))
				{
					if (!list.Contains(cssTemplateItem.Name, StringComparer.CurrentCultureIgnoreCase))
					{
						list4.Add(cssTemplateItem);
						list.Add(cssTemplateItem.Name);
					}
				}
			}
			string text = null;
			CxsCase activeCxsCase = _unityContainer.GetActiveCxsCase();
			if (activeCxsCase != null)
			{
				try
				{
					text = activeCxsCase.CaseWorkingDirectory;
				}
				catch (Exception)
				{
				}
			}
			if (text == null)
			{
				text = Environment.CurrentDirectory;
			}
			if (Directory.Exists(text))
			{
				string[] files = Directory.GetFiles(text, "*.apsst");
				for (int i = 0; i < files.Length; i++)
				{
					ReportTemplateItem reportTemplateItem2 = GenerateTemplateItemFromFile(files[i], ReportTemplateType.UserDefined);
					if (reportTemplateItem2 != null && !list.Contains(reportTemplateItem2.Name, StringComparer.CurrentCultureIgnoreCase))
					{
						list4.Add(reportTemplateItem2);
						list.Add(reportTemplateItem2.Name);
					}
				}
			}
			if (Directory.Exists(UserDefinedTemplatesFolder))
			{
				string[] files = Directory.GetFiles(UserDefinedTemplatesFolder, "*.apsst");
				for (int i = 0; i < files.Length; i++)
				{
					ReportTemplateItem reportTemplateItem3 = GenerateTemplateItemFromFile(files[i], ReportTemplateType.UserDefined);
					if (reportTemplateItem3 != null && !list.Contains(reportTemplateItem3.Name, StringComparer.CurrentCultureIgnoreCase))
					{
						list4.Add(reportTemplateItem3);
						list.Add(reportTemplateItem3.Name);
					}
				}
			}
			foreach (ReportTemplateItem referencedTemplate in StreamReportSettings.Default.ReferencedTemplates)
			{
				if (referencedTemplate != null && !list.Contains(referencedTemplate.Name, StringComparer.CurrentCultureIgnoreCase))
				{
					ReportTemplateItem reportTemplateItem4 = ReportTemplateItem.Parse(referencedTemplate.Save());
					reportTemplateItem4.TagAsInMemory();
					list4.Add(reportTemplateItem4);
					list.Add(reportTemplateItem4.Name);
				}
			}
			foreach (ReportTemplateItem item in list4.OrderBy((ReportTemplateItem x) => x.Sequence))
			{
				list2.Add(item);
			}
			return list2;
		}

		public IEnumerable<CssReportTemplateItem> GetCssTemplateItems(IHNode contextNode = null)
		{
			List<CssReportTemplateItem> list = new List<CssReportTemplateItem>();
			foreach (CssTemplateHeaderInfo item2 in (contextNode == null) ? WrapperProxy.GetAllCssTemplates() : WrapperProxy.GetCssTemplates(contextNode))
			{
				CssReportTemplateItem item = new CssReportTemplateItem(item2);
				list.Add(item);
			}
			return list;
		}

		public ReportTemplateItem FindOriginalTemplate(ReportTemplateItem template)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			if (template.Type == ReportTemplateType.CssTemplate)
			{
				CssReportTemplateItem cssTemplate = template as CssReportTemplateItem;
				if (cssTemplate != null)
				{
					return GetCssTemplateItems().FirstOrDefault((CssReportTemplateItem x) => x.CssHeaderInfo.Handle == cssTemplate.CssHeaderInfo.Handle);
				}
				return null;
			}
			return GetTemplateItems().FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, template.Name, StringComparison.CurrentCultureIgnoreCase));
		}

		public static void ReloadTemplateSettings(ReportTemplateItem template)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			if (!string.IsNullOrWhiteSpace(template.FilePath))
			{
				XDocument documentFromFile = GetDocumentFromFile(template.FilePath);
				if (documentFromFile != null)
				{
					template.Settings.Parse(documentFromFile.Root);
				}
			}
			else if (template is CssReportTemplateItem cssReportTemplateItem)
			{
				cssReportTemplateItem.ResetSettings();
			}
			else if (template.Type == ReportTemplateType.UserDefined && template.IsInMomory)
			{
				ReportTemplateItem reportTemplateItem = StreamReportSettings.Default.ReferencedTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, template.Name, StringComparison.CurrentCultureIgnoreCase));
				if (reportTemplateItem != null)
				{
					template.Settings.Parse(reportTemplateItem.Settings.Save());
				}
			}
		}

		public void SaveTemplate(ReportTemplateItem template)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			if (template.Type == ReportTemplateType.UserDefined)
			{
				XElement xElement = template.Settings.Save();
				if (!string.IsNullOrEmpty(template.Description))
				{
					xElement.SetAttributeValue("Description", template.Description);
				}
				SaveUserDefinedTemplateFile(template.Name, xElement.ToString(), template.FilePath);
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateSavedEvent>().Publish(new ReportTemplateSavedEventArgs(template.Name));
			}
		}

		public bool RenameTemplate(string oldName, string newName)
		{
			if (!IsValidTemplateName(newName))
			{
				MMMessageBox.Show(string.Format(GridFormsResources.StreamTemplate_ManageTemplates_InvalidTemplateName, newName), GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				return false;
			}
			IEnumerable<ReportTemplateItem> templateItems = GetTemplateItems();
			if (templateItems.FirstOrDefault((ReportTemplateItem p) => p.Name.Equals(newName, StringComparison.InvariantCultureIgnoreCase)) != null)
			{
				MMMessageBox.Show(string.Format(GridFormsResources.ManageStreamTemplate_TemplateNameConflicts, newName), GridFormsResources.ManageStreamTemplate_TemplateNameConflictsTitle, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				return false;
			}
			ReportTemplateItem reportTemplateItem = templateItems.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, oldName, StringComparison.CurrentCulture));
			string filePath = reportTemplateItem.FilePath;
			try
			{
				string destFileName = Path.Combine(reportTemplateItem.FilePath.Substring(0, reportTemplateItem.FilePath.LastIndexOf(Path.DirectorySeparatorChar)), newName + ".apsst");
				File.Move(filePath, destFileName);
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateRenamedEvent>().Publish(new ReportTemplateRenamedEventArgs(oldName, newName));
				return true;
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				return false;
			}
		}

		public string CreateTemplate(ReportTemplateItem baseTemplate, bool isRelatedFlowSheet = false, bool bSyncStreamGroup = false)
		{
			if (baseTemplate == null)
			{
				throw new ArgumentNullException("baseTemplate");
			}
			string description = null;
			string text = NewTemplateDialog.OpenNewTemplateDialog(_unityContainer, out description);
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			if (!IsValidTemplateName(text))
			{
				MMMessageBox.Show(string.Format(GridFormsResources.StreamTemplate_ManageTemplates_InvalidTemplateName, text), GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				return null;
			}
			if (!string.IsNullOrEmpty(text))
			{
				XElement xElement = baseTemplate.Settings.Save();
				xElement.SetAttributeValue("Description", description);
				if (isRelatedFlowSheet)
				{
					xElement.SetAttributeValue("SyncStreamGroup", bSyncStreamGroup);
				}
				SaveUserDefinedTemplateFile(text, xElement.ToString());
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateCreatedEvent>().Publish(new ReportTemplateCreatedEventArgs());
			}
			return text;
		}

		public void CrateNewTemplate(string templateName, string description)
		{
			if (string.IsNullOrEmpty(templateName))
			{
				throw new ArgumentNullException(templateName);
			}
			if (!IsValidTemplateName(templateName))
			{
				MMMessageBox.Show(string.Format(GridFormsResources.StreamTemplate_ManageTemplates_InvalidTemplateName, templateName), GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				return;
			}
			try
			{
				string text = $"<TFFTable Description=\"{description}\" />";
				SaveUserDefinedTemplateFile(templateName, text);
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateCreatedEvent>().Publish(new ReportTemplateCreatedEventArgs());
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
			}
		}

		private bool IsValidTemplateName(string templateName)
		{
			bool result = true;
			string text = "\\/:*?\"<>|";
			if (string.IsNullOrEmpty(templateName))
			{
				result = false;
			}
			else
			{
				string text2 = text;
				foreach (char value in text2)
				{
					if (templateName.Contains(value))
					{
						result = false;
					}
				}
			}
			return result;
		}

		public bool DeleteTemplate(ReportTemplateItem template)
		{
			if (template.Type == ReportTemplateType.UserDefined)
			{
				try
				{
					if (template.IsInMomory)
					{
						ReportTemplateItem reportTemplateItem = StreamReportSettings.Default.ReferencedTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, template.Name, StringComparison.CurrentCultureIgnoreCase));
						if (reportTemplateItem != null)
						{
							StreamReportSettings.Default.ReferencedTemplates.Remove(reportTemplateItem);
						}
					}
					else if (!string.IsNullOrEmpty(template.FilePath))
					{
						File.Delete(template.FilePath);
					}
				}
				catch (Exception ex)
				{
					MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
					return false;
				}
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateDeletedEvent>().Publish(new ReportTemplateDeletedEventArgs(template.Name));
				return true;
			}
			if (template.Type == ReportTemplateType.CssTemplate)
			{
				try
				{
					if (template is CssReportTemplateItem cssReportTemplateItem)
					{
						WrapperProxy.DeleteCssTemplate(cssReportTemplateItem.CssHeaderInfo);
					}
				}
				catch (Exception ex2)
				{
					MMMessageBox.Show(ex2.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
					return false;
				}
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateDeletedEvent>().Publish(new ReportTemplateDeletedEventArgs(template.Name));
				return true;
			}
			return false;
		}

		public void DuplicateTemplate(ReportTemplateItem template)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			EnsureUserDefinedTemplatesFolderExist();
			IEnumerable<ReportTemplateItem> templateItems = GetTemplateItems(includeCssTemplates: true);
			string newName = null;
			int num = 0;
			do
			{
				newName = $"{template.Name}_{++num}";
			}
			while (templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, newName, StringComparison.CurrentCultureIgnoreCase)));
			try
			{
				ReloadTemplateSettings(template);
				XElement xElement = template.Settings.Save();
				xElement.SetAttributeValue("Description", template.Description);
				SaveUserDefinedTemplateFile(newName, xElement.ToString());
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateCreatedEvent>().Publish(new ReportTemplateCreatedEventArgs());
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
			}
		}

		public void ImportTemplates()
		{
			OpenFileDialog openFileDialog = new OpenFileDialog();
			openFileDialog.Filter = GridFormsResources.StreamSummaryTemplate_FileFilter_AllFiles;
			openFileDialog.Multiselect = true;
			openFileDialog.CheckFileExists = true;
			if (openFileDialog.ShowDialog() != true)
			{
				return;
			}
			EnsureUserDefinedTemplatesFolderExist();
			List<string> list = (from x in GetTemplateItems(includeCssTemplates: true)
				select x.Name.ToLower()).ToList();
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			string[] fileNames = openFileDialog.FileNames;
			foreach (string text in fileNames)
			{
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(text);
				if (list.Contains(fileNameWithoutExtension.ToLower()))
				{
					dictionary[fileNameWithoutExtension] = string.Format(GridFormsResources.StreamTemplate_FileAlreadyExists, fileNameWithoutExtension);
					continue;
				}
				Path.Combine(UserDefinedTemplatesFolder, Path.GetFileName(text));
				try
				{
					ReportTemplateItem reportTemplateItem = ReportTemplateReader.Read(text, _unityContainer.Resolve<IAdbUnitsProvider>(Array.Empty<ResolverOverride>()));
					if (reportTemplateItem != null)
					{
						XElement xElement = reportTemplateItem.Settings.Save();
						if (!string.IsNullOrEmpty(reportTemplateItem.Description))
						{
							xElement.SetAttributeValue("Description", reportTemplateItem.Description);
						}
						SaveUserDefinedTemplateFile(reportTemplateItem.Name, xElement.ToString());
						list.Add(fileNameWithoutExtension.ToLower());
					}
					else
					{
						dictionary[fileNameWithoutExtension] = GridFormsResources.StreamTemplate_InvalideTemplate;
					}
				}
				catch (Exception ex)
				{
					dictionary[fileNameWithoutExtension] = ex.Message;
				}
			}
			if (dictionary.Count > 0)
			{
				StringBuilder stringBuilder = new StringBuilder();
				foreach (KeyValuePair<string, string> item in dictionary)
				{
					if (stringBuilder.Length > 0)
					{
						stringBuilder.AppendLine();
					}
					stringBuilder.Append(item.Key).Append(" : ").Append(item.Value);
				}
				MMMessageBox.Show(stringBuilder.ToString(), GridFormsResources.StreamSummaryTemplate_Import_DialogTitle, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
			}
			if (openFileDialog.FileNames.Length > dictionary.Count)
			{
				_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<ReportTemplateCreatedEvent>().Publish(new ReportTemplateCreatedEventArgs());
			}
		}

		public void ExportTemplate(ReportTemplateItem template)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			SaveFileDialog saveFileDialog = new SaveFileDialog();
			saveFileDialog.FileName = template.Name;
			saveFileDialog.Filter = GridFormsResources.StreamSummaryTemplate_FileFilter_Apsst;
			if (saveFileDialog.ShowDialog() != true)
			{
				return;
			}
			string fileName = saveFileDialog.FileName;
			try
			{
				if (!string.IsNullOrWhiteSpace(template.FilePath))
				{
					File.Copy(template.FilePath, fileName, overwrite: true);
					return;
				}
				XElement xElement = template.Settings.Save();
				xElement.SetAttributeValue("Description", template.Description);
				SaveUserDefinedTemplateFile(template.Name, xElement.ToString(), fileName);
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
			}
		}

		public void OpenTemplateManagementScreen()
		{
			IShellApplication shellApplication = _unityContainer.Resolve<IShellApplication>(Array.Empty<ResolverOverride>());
			if (shellApplication == null)
			{
				return;
			}
			IShellMainWindow activeWindow = shellApplication.ActiveWindow;
			if (activeWindow != null)
			{
				ScreenContentControl screenContentControl = activeWindow.FindScreen((ScreenContentControl x) => string.Equals(x.ScreenFactoryKey, "TemplatesManagementScreenFactoryKey", StringComparison.InvariantCulture));
				if (screenContentControl != null)
				{
					activeWindow.ActivateScreen(screenContentControl);
					return;
				}
				activeWindow.ShowScreen(new ShowScreenEventArgs
				{
					ScreenFactoryKey = "TemplatesManagementScreenFactoryKey",
					InitialLocation = ScreenLocation.DockableFloating,
					InitialSize = new Size(800.0, 500.0)
				});
			}
		}

		public ReportTemplateItem OpenTemplateEditor(ReportTemplateItem template, bool saveChanges = false, TemplateEditorTabMode selectedTab = TemplateEditorTabMode.GeneralOptions, Action<AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor> actionAfterLoaded = null, bool includeCssTemplates = false, IHNode contextNode = null, bool isReadOnly = false)
		{
			if (template == null)
			{
				throw new ArgumentNullException("template");
			}
			AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor templateEditor = new AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor(_unityContainer, template, includeCssTemplates, contextNode)
			{
				SelectedMode = selectedTab,
				SaveChanges = saveChanges,
				IsReadOnly = isReadOnly
			};
			IShellApplication shellApplication = _unityContainer.Resolve<IShellApplication>(Array.Empty<ResolverOverride>());
			if (shellApplication != null && shellApplication.ActiveWindow != null)
			{
				templateEditor.Owner = shellApplication.ActiveWindow as Window;
			}
			if (actionAfterLoaded != null)
			{
				templateEditor.Loaded += delegate(object sender, RoutedEventArgs args)
				{
					actionAfterLoaded(sender as AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor);
				};
			}
			if (templateEditor.ShowDialog() != true)
			{
				return null;
			}
			ReportTemplateItem selectedReportTemplate = templateEditor.SelectedReportTemplate;
			if (saveChanges && selectedReportTemplate != null && selectedReportTemplate.Type == ReportTemplateType.UserDefined)
			{
				SaveTemplate(selectedReportTemplate);
			}
			return selectedReportTemplate;
		}

		public static ReportTemplateItem GenerateTemplateItemFromFile(string file, ReportTemplateType type)
		{
			if (File.Exists(file))
			{
				string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(file);
				int result = 0;
				bool result2 = false;
				string description = null;
				XDocument documentFromFile = GetDocumentFromFile(file);
				if (documentFromFile != null)
				{
					XAttribute xAttribute = documentFromFile.Root.Attribute("Description");
					if (xAttribute != null)
					{
						description = xAttribute.Value;
					}
					XAttribute xAttribute2 = documentFromFile.Root.Attribute("Sequence");
					if (xAttribute2 != null)
					{
						int.TryParse(xAttribute2.Value, out result);
					}
					XAttribute xAttribute3 = documentFromFile.Root.Attribute("IsDefault");
					if (xAttribute3 != null)
					{
						bool.TryParse(xAttribute3.Value, out result2);
					}
					XAttribute xAttribute4 = documentFromFile.Root.Attribute("SyncStreamGroup");
					if (xAttribute4 != null && bool.TryParse(xAttribute4.Value, out var result3))
					{
						return new FlowSheetReportTemplateItem
						{
							Type = type,
							Name = fileNameWithoutExtension,
							Sequence = result,
							IsDefault = result2,
							Description = description,
							FilePath = file,
							SyncStreamGroup = result3
						};
					}
				}
				return new ReportTemplateItem
				{
					Type = type,
					Name = fileNameWithoutExtension,
					Sequence = result,
					IsDefault = result2,
					Description = description,
					FilePath = file
				};
			}
			return null;
		}

		public static XDocument GetDocumentFromFile(string file)
		{
			if (File.Exists(file))
			{
				try
				{
					string text = File.ReadAllText(file);
					if (!string.IsNullOrEmpty(text))
					{
						return XDocument.Parse(text);
					}
				}
				catch (Exception)
				{
				}
			}
			return null;
		}

		private static void SaveUserDefinedTemplateFile(string templateName, string text, string filePath = null)
		{
			EnsureUserDefinedTemplatesFolderExist();
			string path = filePath ?? Path.Combine(UserDefinedTemplatesFolder, templateName + ".apsst");
			if (File.Exists(path) && File.GetAttributes(path) == FileAttributes.ReadOnly)
			{
				File.SetAttributes(path, FileAttributes.Normal);
			}
			File.WriteAllText(path, text);
		}

		private static void EnsureUserDefinedTemplatesFolderExist()
		{
			if (!Directory.Exists(UserDefinedTemplatesFolder))
			{
				Directory.CreateDirectory(UserDefinedTemplatesFolder);
			}
		}

		private static string GetInstalledTemplatesFolder()
		{
			return Path.Combine(Directory.GetParent(Directory.GetParent(Assembly.GetEntryAssembly().Location).FullName).FullName, "Stream Summary Templates");
		}

		private static string GetUserDefinedTemplatesFolder()
		{
			return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Personal), "AspenTech", SystemEnvironment.ApplicationNameWithPathVersion, "Templates");
		}
	}
