		private static string GetScopeBlockName(string blockName, string scope, string baseStreamName)
		{
			if (!string.IsNullOrWhiteSpace(blockName))
			{
				int num = GetScopeTrimmedName(baseStreamName, scope).LastIndexOf('.');
				if (num > 0)
				{
					return baseStreamName.Substring(0, num + 1) + blockName;
				}
			}
			return blockName;
		}

		private static string GetScopeTrimmedName(string name, string scope)
		{
			if (!string.IsNullOrEmpty(name) && !string.IsNullOrEmpty(scope))
			{
				string text = ((scope.LastOrDefault() == '.') ? scope : (scope + "."));
				if (name.StartsWith(text))
				{
					return name.Substring(text.Length);
				}
			}
			return name;
		}
	}
	public static class DispatcherExtensions
	{
		private static readonly Dictionary<string, bool> _actions = new Dictionary<string, bool>();

		public static void InvalidateRun(this DispatcherObject dispatcherObject, string name, Action action, DispatcherPriority priority)
		{
			if (dispatcherObject == null)
			{
				throw new ArgumentNullException("dispatcherObject");
			}
			string key = $"{dispatcherObject.GetType().FullName}:{name}";
			if (!_actions.ContainsKey(key) || !_actions[key])
			{
				_actions[key] = true;
				dispatcherObject.Dispatcher.BeginInvoke((Action<Action>)delegate(Action act)
				{
					act();
					_actions[key] = false;
				}, priority, action);
			}
		}
	}
