	public static class StringComparerMethods
	{
		public static int AlphaCompareText(string first, string second)
		{
			if (string.IsNullOrWhiteSpace(first))
			{
				if (!string.IsNullOrWhiteSpace(second))
				{
					return -1;
				}
				return 0;
			}
			if (string.IsNullOrWhiteSpace(second))
			{
				return 1;
			}
			Tuple<int?, string> tuple = Extract(first.Trim());
			Tuple<int?, string> tuple2 = Extract(second.Trim());
			if (!tuple.Item1.HasValue)
			{
				if (!tuple2.Item1.HasValue)
				{
					return CompareString(tuple.Item2, tuple2.Item2);
				}
				return 1;
			}
			if (!tuple2.Item1.HasValue)
			{
				return -1;
			}
			int num = tuple.Item1.Value.CompareTo(tuple2.Item1.Value);
			if (num != 0)
			{
				return num;
			}
			return CompareString(tuple.Item2, tuple2.Item2);
		}

		private static int CompareString(string first, string second)
		{
			if (string.IsNullOrWhiteSpace(first))
			{
				if (!string.IsNullOrWhiteSpace(second))
				{
					return -1;
				}
				return 0;
			}
			if (string.IsNullOrWhiteSpace(second))
			{
				return 1;
			}
			string text = first.Trim();
			string text2 = second.Trim();
			int length = first.Length;
			int length2 = second.Length;
			for (int i = 0; i < int.MaxValue; i++)
			{
				if (i >= length || i >= length2)
				{
					return length.CompareTo(length2);
				}
				char c = text[i];
				char c2 = text2[i];
				bool flag = char.IsNumber(c);
				bool flag2 = char.IsNumber(c2);
				if (flag && flag2)
				{
					return AlphaCompareText(text.Substring(i), text2.Substring(i));
				}
				if (flag)
				{
					return -1;
				}
				if (flag2)
				{
					return 1;
				}
				if (c != c2)
				{
					return c.CompareTo(c2);
				}
			}
			return 0;
		}

		private static Tuple<int?, string> Extract(string text)
		{
			int? item = null;
			string item2 = null;
			for (int i = 0; i < text.Length; i++)
			{
				if (!char.IsNumber(text[i]))
				{
					if (i == 0)
					{
						item2 = text;
						break;
					}
					item = int.Parse(text.Substring(0, i));
					item2 = text.Substring(i);
					break;
				}
				if (i == text.Length - 1)
				{
					item = int.Parse(text);
					break;
				}
			}
			return new Tuple<int?, string>(item, item2);
		}
	}
