		private IEnumerable<StreamGroupItem> GetAllUserDefinedGroupItems()
		{
			List<StreamGroupItem> list = new List<StreamGroupItem>();
			if (_streamGroupPresenter != null)
			{
				IEnumerable<StreamGroupInfo> allUserDefinedGroups = _streamGroupPresenter.GetAllUserDefinedGroups();
				if (allUserDefinedGroups != null)
				{
					foreach (StreamGroupInfo item in allUserDefinedGroups)
					{
						list.Add(new StreamGroupItem
						{
							Type = StreamGroupType.UserDefined,
							Name = item.Name,
							Description = item.Description,
							IsConditional = item.IsConditional
						});
					}
				}
			}
			return list.OrderBy((StreamGroupItem x) => x.Name);
		}

