		public StreamReportContextualRibbonTabGroup(IUnityContainer unityContainer)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			_unityContainer = unityContainer;
			_initialized = false;
			InitializeComponent();
			foreach (RibbonTabItem tab in base.Tabs)
			{
				tab.DataContext = this;
			}
			SubscribeEvents();
			_initialized = true;
		}

		private void SubscribeEvents()
		{
			comboStreamGroup.DropDownOpened += comboStreamGroup_DropDownOpened;
			comboTemplate.DropDownOpened += comboTemplate_DropDownOpened;
			IEventAggregator eventAggregator = _unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
			eventAggregator.GetEvent<StreamGroupCreatedEvent>().Subscribe(OnStreamGroupCreated);
			eventAggregator.GetEvent<ReportTemplateCreatedEvent>().Subscribe(OnReportTemplateCreated);
			eventAggregator.GetEvent<ReportTemplateDeletedEvent>().Subscribe(OnReportTemplateDeleted);
			eventAggregator.GetEvent<ReportTemplateRenamedEvent>().Subscribe(OnReportTemplateRenamed);
			eventAggregator.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
			eventAggregator.GetEvent<StreamReportControlInitializedEvent>().Subscribe(OnStreamReportFormViewInitialized);
			eventAggregator.GetEvent<StreamReportControlGroupChangedEvent>().Subscribe(OnStreamReportControlGroupChanged);
			eventAggregator.GetEvent<StreamReportControlTemplateChangedEvent>().Subscribe(OnStreamReportControlTemplateChanged);
			eventAggregator.GetEvent<ActiveScreenChangedEvent>().Subscribe(OnActiveScreenChanged);
			eventAggregator.GetEvent<SimulationStatusChangedEvent>().Subscribe(OnSimulationStatusChanged);
		}

