		private void OnStreamReportControlGroupChanged(StreamReportControlGroupChangedEventArgs e)
		{
			if (TargetControl != null && TargetControl == e.Sender && (SelectedStreamGroup == null || !string.Equals(SelectedStreamGroup.Name, TargetControl.GroupName, StringComparison.CurrentCultureIgnoreCase)))
			{
				UpdateStreamGroups(TargetControl);
			}
		}

		private void OnStreamReportControlTemplateChanged(StreamReportControlTemplateChangedEventArgs e)
		{
			if (TargetControl != null && TargetControl == e.Sender)
			{
				if (SelectedReportTemplate == null || !string.Equals(SelectedReportTemplate.Name, TargetControl.TemplateName, StringComparison.CurrentCultureIgnoreCase))
				{
					UpdateTemplates(TargetControl);
				}
				InvalidateCheckBoxBindings();
			}
		}

