		private void UpdateStreamGroups(StreamReportControl control)
		{
			StreamGroups = GetAvailableStreamGroups().ToList();
			StreamGroupItem streamGroupItem = null;
			if (control != null && !string.IsNullOrEmpty(control.GroupName))
			{
				streamGroupItem = StreamGroups.FirstOrDefault((StreamGroupItem x) => string.Equals(control.GroupName, x.Name));
			}
			if (streamGroupItem == null)
			{
				streamGroupItem = StreamGroups.FirstOrDefault((StreamGroupItem x) => x.Type == StreamGroupType.Default);
			}
			if (streamGroupItem == null)
			{
				streamGroupItem = StreamGroups.FirstOrDefault();
			}
			SelectedStreamGroup = streamGroupItem;
		}

		private void UpdateTemplates(StreamReportControl control)
		{
			IHNode contextNode = ((control == null) ? null : control.MainNode);
			ReportTemplates = TemplatesManager.GetTemplateItems(includeCssTemplates: true, contextNode).ToList();
			ReportTemplateItem reportTemplateItem = null;
			if (control != null)
			{
				reportTemplateItem = ReportTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, control.TemplateName, StringComparison.InvariantCultureIgnoreCase));
			}
			if (reportTemplateItem == null && SelectedStreamGroup != null)
			{
				reportTemplateItem = ReportTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, GroupsManager.GetDefaultTemplateOfStreamGroup(SelectedStreamGroup), StringComparison.InvariantCultureIgnoreCase));
			}
			if (reportTemplateItem == null)
			{
				reportTemplateItem = ReportTemplates.FirstOrDefault();
			}
			SelectedReportTemplate = reportTemplateItem;
		}

