		protected virtual void OnSelectedStreamGroupChanged(StreamGroupItem oldValue, StreamGroupItem newValue)
		{
			if (TargetControl == null)
			{
				return;
			}
			string groupName = TargetControl.GroupName;
			TargetControl.GroupName = newValue?.Name;
			if (!_isFormInitialized || TargetControl.IsPendingForRestore || string.Equals(groupName, TargetControl.GroupName, StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			StreamGroupItem selectedStreamGroup = SelectedStreamGroup;
			if (selectedStreamGroup == null)
			{
				return;
			}
			string newTemplateName = GroupsManager.GetDefaultTemplateOfStreamGroup(selectedStreamGroup);
			if (!string.IsNullOrWhiteSpace(newTemplateName))
			{
				ReportTemplateItem reportTemplateItem = ReportTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, newTemplateName, StringComparison.CurrentCulture));
				if (reportTemplateItem != null)
				{
					TargetControl.TemplateName = reportTemplateItem.Name;
				}
			}
		}

