		private bool SaveCurrentGroupCommand_CanExecute()
		{
			if (TargetControl == null || SelectedStreamGroup == null || SelectedStreamGroup.Type != StreamGroupType.UserDefined)
			{
				return false;
			}
			if (SelectedStreamGroup.IsConditional)
			{
				return false;
			}
			IEnumerable<string> displayedStreamIds = TargetControl.GetDisplayedStreamIds();
			if (displayedStreamIds == null || displayedStreamIds.Count() == 0)
			{
				return false;
			}
			IEnumerable<string> streamsDefinedInStreamGroup = GroupsManager.GetStreamsDefinedInStreamGroup(SelectedStreamGroup);
			return !SameStringCollection(streamsDefinedInStreamGroup, displayedStreamIds);
		}

		private bool SameStringCollection(IEnumerable<string> first, IEnumerable<string> second)
		{
			if (first == null && second == null)
			{
				return true;
			}
			if (first == null || second == null)
			{
				return false;
			}
			return first.SequenceEqual(second, StringComparer.InvariantCultureIgnoreCase);
		}

