		private void SendToFlowsheetCommand_Executed()
		{
			SyncStreamGroupAndTemplateDialog syncStreamGroupAndTemplateDialog = new SyncStreamGroupAndTemplateDialog();
			bool num = syncStreamGroupAndTemplateDialog.ShowDialog() ?? false;
			bool flag = false;
			bool flag2 = false;
			if (!num)
			{
				return;
			}
			flag = syncStreamGroupAndTemplateDialog.chkSyncStreamGroup.IsChecked.Value;
			flag2 = syncStreamGroupAndTemplateDialog.chkSyncTemplate.IsChecked.Value;
			if (!flag && !flag2)
			{
				new StreamReportFlowsheetSender(TargetControl, flag2, flag).SendToFlowsheet();
				return;
			}
			IEnumerable<string> displayedStreamIds = TargetControl.GetDisplayedStreamIds();
			IEnumerable<string> streamsDefinedInStreamGroup = GroupsManager.GetStreamsDefinedInStreamGroup(SelectedStreamGroup);
			if (flag)
			{
				if (TargetControl != null && SelectedStreamGroup != null && SelectedStreamGroup.Type == StreamGroupType.UserDefined && !SelectedStreamGroup.IsConditional)
				{
					if (!SameStringCollection(streamsDefinedInStreamGroup, displayedStreamIds))
					{
						GroupsManager.SaveStreamGroup(SelectedStreamGroup, TargetControl.GetDisplayedStreamIds());
					}
				}
				else
				{
					string text = GroupsManager.CreateStreamGroup(TargetControl.GetDisplayedStreamIds());
					if (string.IsNullOrEmpty(text))
					{
						return;
					}
					TargetControl.GroupName = text;
					UpdateStreamGroups(TargetControl);
				}
			}
			if (flag2)
			{
				if (EditingTemplateItem.Type == ReportTemplateType.UserDefined && EditingTemplateItem.IsDirty(_unityContainer))
				{
					TemplatesManager.SaveTemplate(EditingTemplateItem);
				}
				else if (EditingTemplateItem.Type == ReportTemplateType.Installed)
				{
					string text2 = TemplatesManager.CreateTemplate(EditingTemplateItem, isRelatedFlowSheet: true, flag);
					if (string.IsNullOrEmpty(text2) || TargetControl == null)
					{
						return;
					}
					TargetControl.TemplateName = text2;
				}
			}
			new StreamReportFlowsheetSender(TargetControl, flag2, flag).SendToFlowsheet();
		}

		private bool SendToFlowsheetCommand_CanExecute()
		{
			if (TargetControl != null && TargetControl.ReportGrid != null && TargetControl.ReportGrid.DataSource != null && TargetControl.ReportGrid.DataSource.Columns.Count > 0 && TargetControl.UnityContainer != null)
			{
				return TargetControl.UnityContainer.GetDocumentActiveMode() == ProblemModes.Simulation;
			}
			return false;
		}

