		public void Initialize(IUnityContainer unityContainer, string mainNodePath)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			if (string.IsNullOrEmpty(mainNodePath))
			{
				throw new ArgumentException("Argument mainNodePath cannot be null or empty.");
			}
			TimingDebugger.BeingTimingBlock("StreamReportControl.Initialize");
			UnityContainer = unityContainer;
			MainNodePath = mainNodePath;
			string templateName = null;
			bool groupDefaulted = false;
			bool globalDefaulted = false;
			bool includesChildHierarchyStreams = false;
			string optionalStreamGroupName = null;
			StreamGroupItem streamGroupItem = StreamReportPresenter.PopContextStreamGroup();
			if (streamGroupItem != null)
			{
				optionalStreamGroupName = streamGroupItem.Name;
			}
			else
			{
				SSXMLSettings sSXMLSettings = UnityContainer.GetSSXMLSettings(MainNodePath);
				if (sSXMLSettings != null)
				{
					optionalStreamGroupName = sSXMLSettings.GroupName;
					templateName = sSXMLSettings.TemplateName;
					groupDefaulted = sSXMLSettings.IsTemplateGroupDefaulted;
					globalDefaulted = sSXMLSettings.IsTemplateGlobalDefaulted;
					includesChildHierarchyStreams = sSXMLSettings.IncludesChildHierarchyStreams;
				}
			}
			StreamGroupItem streamGroupItem2 = CalculateStreamGroup(optionalStreamGroupName);
			if (streamGroupItem2 != null)
			{
				GroupName = streamGroupItem2.Name;
				StreamGroup = streamGroupItem2;
			}
			TemplateName = CalculateTemplateName(templateName, groupDefaulted, globalDefaulted);
			UpdateReportTemplate();
			IncludesChildHierarchyStreams = includesChildHierarchyStreams;
			if (!string.IsNullOrWhiteSpace(_commonShellSettingsToRestore))
			{
				TryRestoreCommonShellSettings();
			}
			UpdateGlobalUnitSet();
			InvalidateGridData();
			SubscribeEvents();
			UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<StreamReportControlInitializedEvent>().Publish(new StreamReportControlInitializedEventArgs(this));
			StreamReportReferencedTemplatesManager.RegisterOpenedNode(MainNodePath);
			TimingDebugger.EndTimingBlock();
		}

		public string SaveCommonShellSettings()
		{
			XElement xElement = new XElement("srcSettings");
			StringBuilder stringBuilder = new StringBuilder();
			foreach (string displayedStreamId in GetDisplayedStreamIds())
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(',');
				}
				stringBuilder.Append(displayedStreamId);
			}
			xElement.SetAttributeValue("StreamIds", stringBuilder.ToString());
			xElement.SetAttributeValue("TemplateName", TemplateName);
			if (TemplateItem != null)
			{
				xElement.Add(TemplateItem.Settings.Save());
			}
			return xElement.ToString(SaveOptions.DisableFormatting);
		}

		public void RestoreCommonShellSettings(string settings)
		{
			if (!string.IsNullOrWhiteSpace(settings))
			{
				_commonShellSettingsToRestore = settings;
				TryRestoreCommonShellSettings();
			}
		}

		private void TryRestoreCommonShellSettings()
		{
			if (TemplateItem == null || string.IsNullOrEmpty(_commonShellSettingsToRestore))
			{
				return;
			}
			try
			{
				XElement xElement = XElement.Parse(_commonShellSettingsToRestore);
				string text = (string)xElement.Attribute("StreamIds");
				if (!string.IsNullOrEmpty(text))
				{
					string[] streamIds = text.Split(',');
					ApplyStreamIds(streamIds);
				}
				string a = (string)xElement.Attribute("TemplateName");
				XElement xElement2 = xElement.Elements().FirstOrDefault();
				if (string.Equals(a, TemplateName, StringComparison.CurrentCultureIgnoreCase) && xElement2 != null)
				{
					TemplateItem.Settings.Parse(xElement2);
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.LogDebug(ex.Message);
			}
			finally
			{
				_commonShellSettingsToRestore = null;
			}
		}

		private void ApplyStreamIds(IEnumerable<string> streamIds)
		{
			_forcedStreamIds = streamIds;
			InvalidateGridDataCompletely();
		}

