		public IEnumerable<StreamGroupItem> GetAvailableStreamGroups()
		{
			if (UnityContainer == null)
			{
				return new StreamGroupItem[0];
			}
			IEnumerable<StreamGroupItem> allGroupItems = GroupsManager.GetAllGroupItems();
			if (MainNodeType == 2)
			{
				return allGroupItems.Where((StreamGroupItem x) => x.IsAllowedForStream);
			}
			if (MainNodeType == 1)
			{
				return allGroupItems.Where((StreamGroupItem x) => x.IsAllowedForBlock);
			}
			return allGroupItems.Where((StreamGroupItem x) => x.IsAllowedForAnyHierachy);
		}

