		public void SaveStreamGroup()
		{
			if (NeedSyncStreamGroup && ((IAXEmbeddedObject)this).IsPFSObject)
			{
				IEnumerable<string> displayedStreamIds = GetDisplayedStreamIds();
				IEnumerable<string> streamsDefinedInStreamGroup = GroupsManager.GetStreamsDefinedInStreamGroup(StreamGroup);
				if (!SameStringCollection(streamsDefinedInStreamGroup, displayedStreamIds))
				{
					GroupsManager.SaveStreamGroup(StreamGroup, GetDisplayedStreamIds());
				}
			}
		}

		private bool SameStringCollection(IEnumerable<string> first, IEnumerable<string> second)
		{
			if (first == null && second == null)
			{
				return true;
			}
			if (first == null || second == null)
			{
				return false;
			}
			return first.SequenceEqual(second, StringComparer.InvariantCultureIgnoreCase);
		}

		public void OnRequestingClosingEvent(RequestingClosingEventArgs args)
		{
			if (TemplateItem == null || UnityContainer == null || !TemplateItem.IsDirty(UnityContainer))
			{
				return;
			}
			switch (MMMessageBox.Show(Window.GetWindow(this), GridFormsResources.StreamReport_SaveTemplateConfirmDialog_Message, GridFormsResources.StreamReport_SaveTemplateConfirmDialog_Title, MMMessageBoxButton.YesNoCancel))
			{
			case MMMessageBoxResult.Yes:
				try
				{
					if (TemplateItem.Type == ReportTemplateType.UserDefined)
					{
						TemplatesManager.SaveTemplate(TemplateItem);
						args.StopClosing = false;
						break;
					}
					string text = TemplatesManager.CreateTemplate(TemplateItem);
					if (!string.IsNullOrEmpty(text))
					{
						TemplateName = text;
					}
					args.StopClosing = true;
					break;
				}
				catch (Exception ex)
				{
					MMMessageBox.Show(ex.Message, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
					Console.WriteLine("An error occurred: '{0}'", ex);
					args.StopClosing = true;
					break;
				}
			case MMMessageBoxResult.No:
				args.StopClosing = false;
				break;
			case MMMessageBoxResult.Cancel:
				args.StopClosing = true;
				break;
			}
		}

		public void OpenTemplateEditor(TemplateEditorTabMode initialTab = TemplateEditorTabMode.GeneralOptions, bool saveChanges = false, Action<AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor> actionAfterLoaded = null)
		{
			if (UnityContainer == null || TemplateItem == null)
			{
				return;
			}
			ReportTemplateItem reportTemplateItem = null;
			reportTemplateItem = ((!((IAXEmbeddedObject)this).IsPFSObject) ? TemplatesManager.OpenTemplateEditor(TemplateItem, saveChanges: false, initialTab, actionAfterLoaded, includeCssTemplates: true, MainNode) : TemplatesManager.OpenTemplateEditor(TemplateItem, NeedSyncTheUserTemplate, initialTab, actionAfterLoaded, includeCssTemplates: true, MainNode));
			if (reportTemplateItem == null)
			{
				return;
			}
			if (string.Equals(reportTemplateItem.Name, TemplateItem.Name))
			{
				XElement xElement = TemplateItem.Settings.Save();
				XElement xElement2 = reportTemplateItem.Settings.Save();
				if (!string.Equals(xElement.ToString(SaveOptions.DisableFormatting), xElement2.ToString(SaveOptions.DisableFormatting), StringComparison.Ordinal))
				{
					TemplateItem.Settings.Parse(xElement2);
					RaiseTemplateChangedEvent();
					InvalidateGridData();
				}
			}
			else
			{
				TemplateName = reportTemplateItem.Name;
				TemplateItem.Settings.Parse(reportTemplateItem.Settings.Save());
				InvalidateGridData();
			}
		}

		public void InvalidateGridData(DispatcherPriority priority = DispatcherPriority.Normal)
		{
			if (_isInvalidatingGridData)
			{
				return;
			}
			_isInvalidatingGridData = true;
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				if (!IsClosed)
				{
					RefreshGridData();
					_isInvalidatingGridData = false;
				}
			}, priority);
		}

		private void RefreshGridData()
		{
			if (ReportGrid == null || StreamGroup == null || TemplateItem == null || MainNode == null || UnityContainer == null)
			{
				return;
			}
			AdbDataProvider.Reset();
			TimingDebugger.BeingTimingBlock("StreamReportControl.RefreshGridData");
			StreamReportDataTable streamReportDataTable = ReportGrid.DataSource as StreamReportDataTable;
			StreamReportDataTable streamReportDataTable2 = EnsureLatestDataSource(streamReportDataTable);
			if (streamReportDataTable2 != null)
			{
				if (streamReportDataTable != null && streamReportDataTable.Rows.Count > 0)
				{
					streamReportDataTable2.UpdateData(streamReportDataTable);
				}
				else
				{
					streamReportDataTable2.UpdateData(_lastNonEmptyDataSource);
				}
				if (streamReportDataTable2.Rows.Count > 0)
				{
					_lastNonEmptyDataSource = streamReportDataTable2;
				}
			}
			if (streamReportDataTable2 != null && ((IAXEmbeddedObject)this).IsPFSObject && UnityContainer != null)
			{
				UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<EmbeddedWPFFormDataChangedEvent>().Publish(new EmbeddedWPFFormDataChangedEventArgs(MainNodePath, EmbeddedActiveObjectType.StreamSummaryForm));
			}
			TimingDebugger.EndTimingBlock();
		}

		private StreamReportDataTable EnsureLatestDataSource(StreamReportDataTable lastTable)
		{
			bool flag = _isSimulationReinitialized;
			if (!flag)
			{
				flag = !SimulatorStatusHelperForControls.Default.IsRunning && !this.IsResultsAvailable();
			}
			if (flag)
			{
				StreamReportDataTable streamReportDataTable = new StreamReportDataTable(this, new StreamData[0], new StreamData[0]);
				ReportGrid.DataSource = streamReportDataTable;
				return streamReportDataTable;
			}
			if (_invalidateStreamIdsFlag || lastTable == null || lastTable.Columns.Count == 0)
			{
				IList<StreamData> list = GetAvailableStreams().OrderBy((StreamData x) => x, StreamDataComparer.Default).ToListAnyway();
				IEnumerable<StreamData> enumerable = null;
				if (_forcedStreamIds != null)
				{
					List<StreamData> list2 = new List<StreamData>();
					foreach (string id in _forcedStreamIds)
					{
						StreamData streamData = list.FirstOrDefault((StreamData x) => string.Equals(x.Name, id, StringComparison.CurrentCultureIgnoreCase));
						if (streamData != null)
						{
							list2.Add(streamData);
						}
					}
					enumerable = list2;
					_forcedStreamIds = null;
				}
				else
				{
					enumerable = GetFilteredStreams(list, StreamGroup, IncludesChildHierarchyStreams);
				}
				ReportGrid.DataSource = new StreamReportDataTable(this, enumerable, list);
				_invalidateStreamIdsFlag = false;
			}
			else if (_checkExistingStreamIdsFlag)
			{
				IList<StreamData> list3 = GetAvailableStreams().OrderBy((StreamData x) => x, StreamDataComparer.Default).ToListAnyway();
				IEnumerable<string> displayedStreamIds = GetDisplayedStreamIds();
				List<StreamData> list4 = new List<StreamData>();
				foreach (string id2 in displayedStreamIds)
				{
					StreamData streamData2 = list3.FirstOrDefault((StreamData x) => string.Equals(x.Name, id2, StringComparison.CurrentCultureIgnoreCase));
					if (streamData2 != null)
					{
						list4.Add(streamData2);
					}
				}
				ReportGrid.DataSource = new StreamReportDataTable(this, list4, list3);
				_checkExistingStreamIdsFlag = false;
			}
			return ReportGrid.DataSource as StreamReportDataTable;
		}

		[IteratorStateMachine(typeof(GetAvailableStreamsEnumerator))]
		private IEnumerable<StreamData> GetAvailableStreams()
