		private void InvalidateGridDataCompletely(bool onlyCheckExisting = false, DispatcherPriority priority = DispatcherPriority.Normal)
		{
			if (onlyCheckExisting)
			{
				_checkExistingStreamIdsFlag = true;
			}
			else
			{
				_invalidateStreamIdsFlag = true;
			}
			InvalidateGridData(priority);
		}

		private void SaveMainNodeSettings(bool includeTemplateSettings = false)
		{
			if (UnityContainer == null || string.IsNullOrEmpty(MainNodePath))
			{
				return;
			}
			bool groupDefaulted = false;
			bool globalDefaulted = false;
			CheckTemplateDefaultInfo(TemplateName, out groupDefaulted, out globalDefaulted);
			SSXMLSettings sSXMLSettings = new SSXMLSettings
			{
				GroupName = GroupName,
				TemplateName = TemplateName,
				IsTemplateGroupDefaulted = groupDefaulted,
				IsTemplateGlobalDefaulted = globalDefaulted,
				IncludesChildHierarchyStreams = IncludesChildHierarchyStreams
			};
			if (includeTemplateSettings)
			{
				string text = SaveCommonShellSettings();
				if (!string.IsNullOrWhiteSpace(text))
				{
					sSXMLSettings.CommonShellSettings = text;
				}
			}
			UnityContainer.SaveSSXMLSettings(MainNodePath, sSXMLSettings);
		}

		private void CheckTemplateDefaultInfo(string templateName, out bool groupDefaulted, out bool globalDefaulted)
		{
			groupDefaulted = (globalDefaulted = false);
			if (UnityContainer != null && !string.IsNullOrWhiteSpace(templateName))
			{
				if (StreamGroup != null && string.Equals(GroupsManager.GetDefaultTemplateOfStreamGroup(StreamGroup), templateName, StringComparison.CurrentCultureIgnoreCase))
				{
					groupDefaulted = true;
				}
				IStreamReportPresenter streamReportPresenter = UnityContainerHelper.TryResolve<IStreamReportPresenter>(UnityContainer);
				if (streamReportPresenter != null && string.Equals(streamReportPresenter.GetDefaultTemplate(), templateName, StringComparison.CurrentCultureIgnoreCase))
				{
					globalDefaulted = true;
				}
			}
		}

