		private void OnObjectRenamedAnywhereEvent(ObjectRenamedAnywhereEventArgs e)
		{
			VerifyMainNodePath(e);
			if (HasStreamRenamedOrDeleted())
			{
				List<string> newStreamsList = null;
				if (HasDisplayedStreamRenamed(e, out newStreamsList))
				{
					_forcedStreamIds = newStreamsList;
					InvalidateGridDataCompletely();
				}
				else
				{
					InvalidateGridDataCompletely(onlyCheckExisting: true);
				}
			}
			else
			{
				InvalidateGridData();
			}
		}

		private void OnObjectDeletedAnywhereEvent(ObjectDeletedAnywhereEventArgs e)
		{
			if (HasStreamRenamedOrDeleted())
			{
				InvalidateGridDataCompletely(onlyCheckExisting: true);
			}
			else
			{
				InvalidateGridData();
			}
		}

		private void VerifyMainNodePath(ObjectRenamedAnywhereEventArgs e)
		{
			if (e.IsCxsPathImpacted(MainNodePath))
			{
				MainNodePath = e.GetNewPathAfterRenamed(MainNodePath);
				_ihNode = null;
				_hierarchyScope = null;
			}
		}

		private bool HasStreamRenamedOrDeleted()
		{
			if (ReportGrid != null && ReportGrid.DataSource is StreamReportDataTable { AllContextAvailableStreams: not null } streamReportDataTable)
			{
				foreach (StreamData allContextAvailableStream in streamReportDataTable.AllContextAvailableStreams)
				{
					AccessorElement streamElement = AdbDataProvider.GetStreamElement(allContextAvailableStream.Name);
					if (streamElement == null || !streamElement.success)
					{
						return true;
					}
				}
			}
			return false;
		}

		private bool HasDisplayedStreamRenamed(ObjectRenamedAnywhereEventArgs renameArgs, out List<string> newStreamsList)
		{
			newStreamsList = null;
			if (ReportGrid != null)
			{
				bool result = false;
				IList<string> list = GetDisplayedStreamIds().ToListAnyway();
				if (list.Count > 0)
				{
					string text = ExtractStreamIdFromRenameArgs(renameArgs.OldPath);
					string text2 = ExtractStreamIdFromRenameArgs(renameArgs.NewPath);
					newStreamsList = new List<string>();
					foreach (string item2 in list)
					{
						if (string.Equals(item2, text, StringComparison.CurrentCulture))
						{
							newStreamsList.Add(text2);
							result = true;
						}
						else if (item2.StartsWith(text + "."))
						{
							string item = text2 + item2.Substring(text.Length);
							newStreamsList.Add(item);
							result = true;
						}
						else
						{
							newStreamsList.Add(item2);
						}
					}
				}
				return result;
			}
			return false;
		}

		private static string ExtractStreamIdFromRenameArgs(string streamName)
		{
			if (!string.IsNullOrWhiteSpace(streamName))
			{
				string text = streamName.Trim().Replace(".Data.", ".");
				if (text.StartsWith("Blocks.", StringComparison.CurrentCultureIgnoreCase))
				{
					text = text.Substring(7);
				}
				if (text.StartsWith("Streams.", StringComparison.CurrentCultureIgnoreCase))
				{
					text = text.Substring(8);
				}
				return text.Replace(".Blocks.", ".").Replace(".Streams.", ".");
			}
			return streamName;
		}

		private void OnUpdateDisplayEvent(UpdateDisplayEventArgs e)
		{
			if (UnityContainer == null)
			{
				return;
