			if (StreamGroup == null || StreamGroup.Type == StreamGroupType.UserDefined)
			{
				StreamGroupItem streamGroupItem = CalculateStreamGroup(GroupName);
				if (streamGroupItem != null && !string.Equals(streamGroupItem.Name, GroupName, StringComparison.CurrentCultureIgnoreCase))
				{
					GroupName = streamGroupItem.Name;
				}
			}
			UpdateGlobalUnitSet();
		}

