		private void OnStreamReportControlModifyVariablesEvent(StreamReportControlModifyVariablesEventArgs e)
		{
			if (((IAXEmbeddedObject)this).IsPFSObject && MainNodePath == e.SMainNodePath)
			{
				if (TemplateItem.Type == ReportTemplateType.UserDefined)
				{
					NeedSyncTheUserTemplate = e.SyncTemplateForPFSobject;
					NeedSyncStreamGroup = e.SyncStreamGroupForPFSobject;
					TemplateItem = e.pfsTemplateItem;
				}
				else if (string.Equals(e.pfsTemplateItem.Name, TemplateItem.Name))
				{
					XElement element = e.pfsTemplateItem.Settings.Save();
					TemplateItem.Settings.Parse(element);
					RaiseTemplateChangedEvent();
					InvalidateGridData();
				}
				else
				{
					NeedSyncTheUserTemplate = e.SyncTemplateForPFSobject;
					NeedSyncStreamGroup = e.SyncStreamGroupForPFSobject;
					TemplateItem = e.pfsTemplateItem;
				}
			}
		}

