		private List<string> GetStreamIdsForColumns(IEnumerable<DataColumn> columns)
		{
			List<string> list = new List<string>();
			if (columns != null)
			{
				foreach (DataColumn column in columns)
				{
					if (column.Tag is SrdtColumnTag { Stream: not null } srdtColumnTag && !list.Contains(srdtColumnTag.Stream.Name))
					{
						list.Add(srdtColumnTag.Stream.Name);
					}
				}
			}
			return list;
		}

