		private void CopyAllCommand_Executed()
		{
			if (!CanCopyAll)
			{
				return;
			}
			var list = (from x in ReportGrid.DataSource.Rows
				where x.GroupingRowsCount > 0
				select new
				{
					Row = x,
					State = x.GroupingState
				}).ToList();
			bool isAllSelected = ReportGrid.IsAllSelected;
			try
			{
				ReportGrid.SupressSelectionChangedEvent = true;
				ExpandAllGroupRowsCommand_Executed();
				ReportGrid.SelectAll();
				ApplicationCommands.Copy.Execute(null, ReportGrid);
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(this), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
			foreach (var item in list)
			{
				item.Row.GroupingState = item.State;
			}
			if (!isAllSelected)
			{
				ReportGrid.DeselectAll();
			}
			else
			{
				ReportGrid.SelectAll();
			}
			ReportGrid.SupressSelectionChangedEvent = false;
		}

		private bool CopyAllCommand_CanExecute()
		{
			return CanCopyAll;
		}

