		private void FormatCommand_Executed(DataGridCell parameter)
		{
			List<DataRow> rowsOfSelection = GetRowsOfSelection();
			IEnumerable<IFormattableRecord> formattedPropertyRecords = GetFormattedPropertyRecords(rowsOfSelection);
			if (!formattedPropertyRecords.Any())
			{
				return;
			}
			AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification formatSpecification = AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification.Parse(formattedPropertyRecords.First().Format);
			ChangeFormatDialog changeFormatDialog = new ChangeFormatDialog
			{
				FormatSpecification = formatSpecification,
				Owner = Window.GetWindow(this)
			};
			bool? flag = changeFormatDialog.ShowDialog();
			if (!flag.HasValue || !flag.Value)
			{
				return;
			}
			string format = changeFormatDialog.FormatSpecification.ToString();
			foreach (IFormattableRecord item in formattedPropertyRecords)
			{
				item.Format = format;
			}
			foreach (DataRow item2 in rowsOfSelection)
			{
				item2.ClearData();
				item2.RaiseIndexerPropertyChanged();
			}
		}

		private bool FormatCommand_CanExecute(DataGridCell parameter)
		{
