		private List<DataRow> GetRowsOfSelection()
		{
			List<DataRow> list = new List<DataRow>();
			if (ReportGrid != null)
			{
				foreach (DataCellInfo totalSelectedCell in ReportGrid.TotalSelectedCells)
				{
					if (!list.Contains(totalSelectedCell.Row))
					{
						list.Add(totalSelectedCell.Row);
					}
				}
			}
			return list;
		}

		private void SubscribeEvents()
		{
