				eventAggregator.GetEvent<ObjectDeletedAnywhereEvent>().Subscribe(OnObjectDeletedAnywhereEvent);
				eventAggregator.GetEvent<UpdateDisplayEvent>().Subscribe(OnUpdateDisplayEvent);
				eventAggregator.GetEvent<StreamGroupSavedEvent>().Subscribe(OnStreamGroupSaved);
				eventAggregator.GetEvent<ReportTemplateSavedEvent>().Subscribe(OnReportTemplateSaved);
				eventAggregator.GetEvent<ReportTemplateDeletedEvent>().Subscribe(OnReportTemplateDeleted);
				eventAggregator.GetEvent<ReportTemplateRenamedEvent>().Subscribe(OnReportTemplateRenamed);
				eventAggregator.GetEvent<ReportTemplatePropertyChangedEvent>().Subscribe(OnReportTemplatePropertyChanged);
				eventAggregator.GetEvent<SimulationRunStartedEvent>().Subscribe(OnSimulationRunStartedEvent);
				eventAggregator.GetEvent<SimulationRunCompletedEvent>().Subscribe(OnSimulationRunCompletedEvent);
				eventAggregator.GetEvent<SimulationRunFailedEvent>().Subscribe(OnSimulationRunFailedEvent);
				eventAggregator.GetEvent<SimulationReinitializedEvent>().Subscribe(OnSimulationReinitializedEvent);
				eventAggregator.GetEvent<SimulationStatusChangedEvent>().Subscribe(OnSimulationStatusChangedEvent);
				eventAggregator.GetEvent<SimulationObjectSolvingEvent>().Subscribe(OnSimulationObjectSolvingEvent);
				eventAggregator.GetEvent<SimulationIntegrationStepEvent>().Subscribe(OnSimulationIntegrationStepEvent);
				eventAggregator.GetEvent<StreamGroupTemplateChangedEvent>().Subscribe(OnStreamGroupTemplateChangedEvent);
				eventAggregator.GetEvent<StreamReportControlModifyVariablesEvent>().Subscribe(OnStreamReportControlModifyVariablesEvent);
				eventAggregator.GetEvent<SelectedStreamGroupOrTemplateChangedEvent>().Subscribe(OnSelectedStreamGroupOrTemplateChangedEvent);
