		private StreamGroupItem CalculateStreamGroup(string optionalStreamGroupName = null)
		{
			IEnumerable<StreamGroupItem> availableStreamGroups = GetAvailableStreamGroups();
			if (!string.IsNullOrEmpty(optionalStreamGroupName))
			{
				StreamGroupItem streamGroupItem = availableStreamGroups.FirstOrDefault((StreamGroupItem x) => string.Equals(x.Name, optionalStreamGroupName, StringComparison.CurrentCultureIgnoreCase));
				if (streamGroupItem != null)
				{
					return streamGroupItem;
				}
			}
			if (MainNodeType == 1)
			{
				StreamGroupItem streamGroupItem2 = availableStreamGroups.FirstOrDefault((StreamGroupItem x) => x.Type == StreamGroupType.Boundary);
				if (streamGroupItem2 != null)
				{
					return streamGroupItem2;
				}
			}
			else if (MainNodeType == 2)
			{
				StreamGroupItem streamGroupItem3 = availableStreamGroups.FirstOrDefault((StreamGroupItem x) => x.Type == StreamGroupType.Default);
				if (streamGroupItem3 != null)
				{
					return streamGroupItem3;
				}
			}
			else
			{
				StreamGroupItem streamGroupItem4 = availableStreamGroups.FirstOrDefault((StreamGroupItem x) => x.Type == StreamGroupType.All);
				if (streamGroupItem4 != null)
				{
					return streamGroupItem4;
				}
			}
			return availableStreamGroups.FirstOrDefault();
		}

		private string CalculateTemplateName(string optionalTemplateName = null)
		{
			if (UnityContainer != null)
			{
				IEnumerable<ReportTemplateItem> templateItems = TemplatesManager.GetTemplateItems(includeCssTemplates: true, MainNode);
				if (!string.IsNullOrEmpty(optionalTemplateName) && templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, optionalTemplateName, StringComparison.CurrentCultureIgnoreCase)))
				{
					return optionalTemplateName;
				}
				if (StreamGroup != null)
				{
					string defaultTemplate = GroupsManager.GetDefaultTemplateOfStreamGroup(StreamGroup);
					if (templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, defaultTemplate, StringComparison.CurrentCultureIgnoreCase)))
					{
						return defaultTemplate;
					}
				}
				IStreamReportPresenter streamReportPresenter = UnityContainerHelper.TryResolve<IStreamReportPresenter>(UnityContainer);
				if (streamReportPresenter != null)
				{
					return streamReportPresenter.GetDefaultTemplate();
				}
			}
			return null;
		}

		private string CalculateTemplateName(string templateName, bool groupDefaulted, bool globalDefaulted)
		{
			if (UnityContainer != null)
			{
				IEnumerable<ReportTemplateItem> templateItems = TemplatesManager.GetTemplateItems(includeCssTemplates: true, MainNode);
				if (groupDefaulted)
				{
					string defaultTemplate = GroupsManager.GetDefaultTemplateOfStreamGroup(StreamGroup);
					if (templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, defaultTemplate, StringComparison.CurrentCultureIgnoreCase)))
					{
						return defaultTemplate;
					}
					return GetGlobalConfiguredDefaultTemplate();
				}
				if (globalDefaulted)
				{
					return GetGlobalConfiguredDefaultTemplate();
				}
				if (!string.IsNullOrEmpty(templateName) && templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, templateName, StringComparison.CurrentCultureIgnoreCase)))
				{
					return templateName;
				}
				if (StreamGroup != null)
				{
					string defaultTemplate2 = GroupsManager.GetDefaultTemplateOfStreamGroup(StreamGroup);
					if (templateItems.Any((ReportTemplateItem x) => string.Equals(x.Name, defaultTemplate2, StringComparison.CurrentCultureIgnoreCase)))
					{
						return defaultTemplate2;
					}
				}
				return GetGlobalConfiguredDefaultTemplate();
			}
			return null;
		}

		private string GetGlobalConfiguredDefaultTemplate()
		{
			return UnityContainerHelper.TryResolve<IStreamReportPresenter>(UnityContainer)?.GetDefaultTemplate();
		}

