		private IEnumerable<StreamData> GetFilteredStreams(IEnumerable<StreamData> hierarchyStreams, StreamGroupItem sgi, bool includesChildHierarchyStreams)
		{
			IEnumerable<StreamData> enumerable = hierarchyStreams.Where((StreamData x) => x.IsInCurrentLevel(HierarchyScope));
			switch (sgi.Type)
			{
			case StreamGroupType.All:
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams;
				}
				return enumerable;
			case StreamGroupType.Feeds:
				if (GetMainNodeType() == 1)
				{
					string nodeName = GetMainNodeName();
					return enumerable.Where((StreamData x) => x.IsFeedOf(nodeName));
				}
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams.Where((StreamData x) => x.IsFeedOf());
				}
				return enumerable.Where((StreamData x) => x.IsFeedOf());
			case StreamGroupType.Products:
				if (GetMainNodeType() == 1)
				{
					string nodeName4 = GetMainNodeName();
					return enumerable.Where((StreamData x) => x.IsProductOf(nodeName4));
				}
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams.Where((StreamData x) => x.IsProductOf());
				}
				return enumerable.Where((StreamData x) => x.IsProductOf());
			case StreamGroupType.Boundary:
				if (GetMainNodeType() == 1)
				{
					string nodeName5 = GetMainNodeName();
					return enumerable.Where((StreamData x) => x.IsFeedOf(nodeName5)).Union(enumerable.Where((StreamData x) => x.IsProductOf(nodeName5)));
				}
				return enumerable.Where((StreamData x) => x.IsFeedOf()).Union(enumerable.Where((StreamData x) => x.IsProductOf()));
			case StreamGroupType.Tears:
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams.Where((StreamData x) => x.IsTear());
				}
				return enumerable.Where((StreamData x) => x.IsTear());
			case StreamGroupType.Initialized:
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams.Where((StreamData x) => WrapperProxy.IsStreamInitialized(MainNode, x.Name));
				}
				return enumerable.Where((StreamData x) => WrapperProxy.IsStreamInitialized(MainNode, x.Name));
			case StreamGroupType.Streams:
				return new List<StreamData>();
			case StreamGroupType.Charge:
			case StreamGroupType.UserDefined:
				if (includesChildHierarchyStreams)
				{
					return FilterUserDefinedStreams(hierarchyStreams, sgi);
				}
				return FilterUserDefinedStreams(enumerable, sgi);
			case StreamGroupType.Default:
				switch (GetMainNodeType().GetValueOrDefault())
				{
				case 1:
				{
					string nodeName3 = GetMainNodeName();
					return enumerable.Where((StreamData x) => x.IsFeedOf(nodeName3)).Union(enumerable.Where((StreamData x) => x.IsProductOf(nodeName3)));
				}
				case 2:
				{
					string nodeName2 = GetFullNodeName();
					return enumerable.Where((StreamData x) => string.Equals(x.Name, nodeName2, StringComparison.InvariantCultureIgnoreCase));
				}
				default:
					if (includesChildHierarchyStreams)
					{
						return hierarchyStreams;
					}
					return enumerable;
				}
			default:
				if (includesChildHierarchyStreams)
				{
					return hierarchyStreams;
				}
				return enumerable;
			}
		}

		private IEnumerable<StreamData> FilterUserDefinedStreams(IEnumerable<StreamData> streams, StreamGroupItem sgi)
		{
			List<StreamData> list = new List<StreamData>();
			if (sgi.Type == StreamGroupType.UserDefined || sgi.Type == StreamGroupType.Charge)
			{
				IEnumerable<string> streamsDefinedInStreamGroup = GroupsManager.GetStreamsDefinedInStreamGroup(StreamGroup);
				if (streamsDefinedInStreamGroup != null)
				{
					foreach (string id in streamsDefinedInStreamGroup)
					{
						StreamData streamData = streams.FirstOrDefault((StreamData x) => string.Equals(id, x.Name, StringComparison.InvariantCulture));
						if (streamData != null)
						{
							list.Add(streamData);
						}
					}
				}
			}
			return list;
		}

