		private string GetFullNodeName()
		{
			if (string.IsNullOrEmpty(HierarchyScope))
			{
				return GetMainNodeName();
			}
			return $"{HierarchyScope}.{GetMainNodeName()}";
		}

		private string GetMainNodeName()
		{
			string mainNodePath = MainNodePath;
			if (!string.IsNullOrEmpty(mainNodePath))
			{
				int num = mainNodePath.LastIndexOf('.');
				if (num > 0)
				{
					return mainNodePath.Substring(num + 1);
				}
			}
			return null;
		}

