		void IAXEmbeddedObject.GetContentSize(ref int nContentWidth, ref int nContentHeight)
		{
			double val = 1800.0;
			double val2 = 1200.0;
			if (ReportGrid.DataSource == null)
			{
				RefreshGridData();
			}
			double num = 250.0;
			double num2 = 25.0;
			double num3 = 100.0;
			double num4 = 260.0;
			double num5 = 120.0;
			double num6 = 30.0;
			StreamReportDataTable streamReportDataTable = ReportGrid.DataSource as StreamReportDataTable;
			double num7 = num2 * 2.0;
			double num8 = 0.0;
			ShowOrHideOperateRowColumn(m_bEditModeInPFS);
			for (int i = 0; i < streamReportDataTable.Rows.Count; i++)
			{
				DataRow dataRow = streamReportDataTable.Rows[i];
				if (dataRow.Visibility == Visibility.Visible)
				{
					num7 += num2;
					if (dataRow.GroupingRowsCount > 0 && dataRow.GroupingState != RowGroupingState.Expanded)
					{
						i += dataRow.GroupingRowsCount;
					}
				}
			}
			bool flag = false;
			if (Utilities.GetDescendantFromName(this, "PART_ColumnHeadersPresenter") is DataGridColumnHeadersPresenter parent && Utilities.GetDescendantFromType(parent, typeof(DataGridCellsPanel), allowSubclassOfType: true) is DataGridCellsPanel { Children: not null } dataGridCellsPanel)
			{
				if (dataGridCellsPanel.Children.Count == streamReportDataTable.Columns.Count)
				{
					for (int j = 0; j < dataGridCellsPanel.Children.Count; j++)
					{
						UIElement uIElement = dataGridCellsPanel.Children[j];
						if (uIElement is DataGridColumnHeader)
						{
							DataGridColumnHeader dataGridColumnHeader = uIElement as DataGridColumnHeader;
							num8 = ((!double.IsNaN(dataGridColumnHeader.ActualWidth)) ? (num8 + dataGridColumnHeader.ActualWidth) : (j switch
							{
								0 => num8 + num4, 
								1 => num8 + num5, 
								_ => num8 + num3, 
							}));
						}
					}
					num8 += num6;
					flag = true;
				}
				else if (!double.IsNaN(dataGridCellsPanel.ActualWidth))
				{
					num8 = dataGridCellsPanel.DesiredSize.Width;
					num8 += num6;
					flag = true;
				}
			}
			if (!flag)
			{
				for (int k = 0; k < streamReportDataTable.Columns.Count; k++)
				{
					if (streamReportDataTable.Columns[k].Visibility == Visibility.Visible)
					{
						num8 = k switch
						{
							0 => num8 + num4, 
							1 => num8 + num5, 
							_ => num8 + num3, 
						};
					}
				}
				num8 += num6;
			}
			if (streamReportDataTable.Rows.Count == 0 || streamReportDataTable.Columns.Count == 0)
			{
				num8 += num;
			}
			nContentWidth = (int)Math.Min(num8, val);
			nContentHeight = (int)Math.Min(num7, val2);
		}

