		private void ShowOrHideOperateRowColumn(bool bEditMode)
		{
			if (!((IAXEmbeddedObject)this).IsPFSObject || !(ReportGrid.DataSource is StreamReportDataTable { Rows: not null, Columns: not null } streamReportDataTable))
			{
				return;
			}
			bool flag = false;
			for (int i = 0; i < streamReportDataTable.Rows.Count; i++)
			{
				DataRow dataRow = streamReportDataTable.Rows[i];
				if (dataRow.Tag != null && dataRow.Tag.GetType().Name == "CommandAddPropertiesRecord")
				{
					if ((bEditMode && dataRow.Visibility != Visibility.Visible) || (!bEditMode && dataRow.Visibility != Visibility.Collapsed))
					{
						flag = true;
					}
					dataRow.Visibility = ((!bEditMode) ? Visibility.Collapsed : Visibility.Visible);
					break;
				}
			}
			for (int j = 0; j < streamReportDataTable.Columns.Count; j++)
			{
				DataColumn dataColumn = streamReportDataTable.Columns[j];
				if (dataColumn.Header == null && dataColumn.HeaderItems != null && dataColumn.HeaderItems.Count() > 0)
				{
					if ((bEditMode && dataColumn.Visibility != Visibility.Visible) || (!bEditMode && dataColumn.Visibility != Visibility.Collapsed))
					{
						flag = true;
					}
					dataColumn.Visibility = ((!bEditMode) ? Visibility.Collapsed : Visibility.Visible);
					break;
				}
			}
			if (flag)
			{
				UpdateLayout();
			}
		}

