		public bool Preprocess(string cxsPathText, out string resolvedCxsPath)
		{
			resolvedCxsPath = cxsPathText;
			StreamReportComplexCxsPathInfo streamReportComplexCxsPathInfo = TryParse(cxsPathText);
			if (streamReportComplexCxsPathInfo != null)
			{
				Calculator.DoCalculationForRawProperties(new string[1] { streamReportComplexCxsPathInfo.StreamId }, new TemplatePropertyItem[1] { streamReportComplexCxsPathInfo.Property });
				resolvedCxsPath = streamReportComplexCxsPathInfo.CxsPath;
				return true;
			}
			return false;
		}

		public static bool IsComplexStreamReportCxsPath(string cxsPathText)
		{
			if (!string.IsNullOrWhiteSpace(cxsPathText) && cxsPathText.Contains("<metadata for=\"streamReport\">"))
			{
				return cxsPathText.EndsWith("</metadata>");
			}
			return false;
		}

		public static StreamReportComplexCxsPathInfo TryParse(string cxsPathText)
		{
			if (IsComplexStreamReportCxsPath(cxsPathText))
			{
				int num = cxsPathText.IndexOf("<metadata for=\"streamReport\">");
				string text = cxsPathText.Substring(0, num);
				if (!string.IsNullOrWhiteSpace(text))
				{
					return ExtractCxsPathInfo(cxsPathText.Substring(num), text);
				}
			}
			return null;
		}

		private static StreamReportComplexCxsPathInfo ExtractCxsPathInfo(string xmlText, string cxsPath)
		{
			try
			{
				XElement xElement = XElement.Parse(xmlText);
				if (xElement != null)
				{
					string text = (string)xElement.Element("streamId");
					if (!string.IsNullOrEmpty(text))
					{
						XElement xElement2 = xElement.Element("property");
						if (xElement2 != null && xElement2.HasElements)
						{
							TemplatePropertyItem templatePropertyItem = TemplatePropertyItem.Parse(xElement2.Elements().First());
							if (templatePropertyItem != null)
							{
								if (cxsPath.StartsWith("cxs:", StringComparison.InvariantCultureIgnoreCase))
								{
									cxsPath = cxsPath.Substring(4);
								}
								return new StreamReportComplexCxsPathInfo(cxsPath, text, templatePropertyItem);
							}
						}
					}
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message + ex.StackTrace, Category.Exception, Priority.High);
			}
			return null;
		}
	}
