			private IEnumerable<string> _templateSelectedLvpcts;

			private IEnumerable<string> ResolvedSubstreams
			{
				get
				{
					IEnumerable<string> enumerable = ResolveAttributeValues(ref _templateSelectedStreams, "Substream");
					if (enumerable.Any())
					{
						return enumerable;
					}
					return TemplatePropertyItem.StreamProperty.AllowedSubstreams;
				}
			}

			public IEnumerable<string> ResolvedPhases
			{
				get
				{
					IEnumerable<string> enumerable = ResolveAttributeValues(ref _templateSelectedPhases, "Phase");
					if (enumerable.Any())
					{
						return enumerable;
					}
					return TemplatePropertyItem.StreamProperty.AllowedPhases;
				}
			}

			private IEnumerable<string> ResolvedComponents
			{
				get
				{
					if (TemplatePropertyItem.StreamProperty.AllowedBaseComponents.Any())
					{
						return new string[0];
					}
					IEnumerable<string> enumerable = ResolveAttributeValues(ref _templateSelectedComponents, "Comps");
					if (enumerable.Any())
					{
						return enumerable;
					}
					List<string> list = ResolvedComponentGroups.ToList();
					if (list.Any())
					{
						List<string> list2 = new List<string>();
						foreach (string item in list)
						{
							foreach (string componentGroupComponent in WrapperProxy.GetComponentGroupComponents(item))
							{
								if (!list2.Contains(componentGroupComponent))
								{
									list2.Add(componentGroupComponent);
								}
							}
						}
						if (list2.Count > 0)
						{
							return list2;
						}
					}
					return TemplatePropertyItem.StreamProperty.AllowedComponents;
				}
			}

			private IEnumerable<string> ResolvedComponentGroups => ResolveAttributeValues(ref _templateSelectedComponentGroups, "Comp-Group");

			public IEnumerable<string> Basis => ResolveAttributeValues(ref _templateSelectedBasis, "Basis");

			public IEnumerable<string> Units => ResolveAttributeValues(ref _templateSelectedUnits, "Units");

			public IEnumerable<string> Temperatures => ResolveAttributeValues(ref _templateSelectedTemperatures, "Temp");

			public IEnumerable<string> Pressures => ResolveAttributeValues(ref _templateSelectedPressures, "Pres");

			public IEnumerable<string> Lvpcts
			{
				get
				{
					IEnumerable<string> enumerable = ResolveAttributeValues(ref _templateSelectedLvpcts, "Liq-Vol%");
					if (enumerable.Any())
					{
						return enumerable;
					}
					return TemplatePropertyItem.StreamProperty.BuiltinLiquidVolumeOrWeightPercents.Select((double x) => x.ToString(CultureInfo.InvariantCulture));
				}
			}

			public bool HasSpecificPhaseOnTotalStream
			{
				get
				{
					if (TemplatePropertyItem.StreamProperty.PropertyType == StreamPropertyType.PhysicalProperty)
					{
						return HasSpecificPhaseOnTotalStream(TemplatePropertyItem);
					}
					return false;
				}
			}

			public TemplatePropertyItem TemplatePropertyItem { get; private set; }

			public PropertyBag(TemplatePropertyItem tpi)
			{
				if (tpi == null)
				{
					throw new ArgumentNullException("tpi");
				}
				TemplatePropertyItem = tpi;
			}

			public bool IsFitForSubstream(string substream)
			{
				return ResolvedSubstreams.Contains(substream, StringComparer.CurrentCultureIgnoreCase);
			}

			public bool IsFitForPhase(string phase)
			{
				if (string.Equals(phase, "Total", StringComparison.OrdinalIgnoreCase))
				{
					if (ResolvedPhases.Count() != 0)
					{
						return ResolvedPhases.Contains("Total");
					}
					return true;
				}
				if (TemplatePropertyItem.StreamProperty is IAdsNativeProperty && string.IsNullOrEmpty(((IAdsNativeProperty)TemplatePropertyItem.StreamProperty).AdsPhasePropertyName))
				{
					return false;
				}
				return ResolvedPhases.Contains(phase, StringComparer.CurrentCultureIgnoreCase);
			}

			public IEnumerable<string> FilterComponentsToDisplay(IEnumerable<string> availableComponents)
			{
				if (TemplatePropertyItem.StreamProperty.AllowedBaseComponents.Any())
				{
					return new string[0];
				}
				return ResolvedComponents.Intersect(availableComponents, StringComparer.InvariantCultureIgnoreCase);
			}

			private IEnumerable<string> ResolveAttributeValues(ref IEnumerable<string> cache, string attribute)
			{
				if (cache == null)
				{
					SettingItem metadata = TemplatePropertyItem.GetMetadata(attribute);
					if (metadata != null)
					{
						cache = metadata.ResolvedValues;
					}
					if (cache == null)
					{
						return new string[0];
					}
				}
				return cache;
			}

			private bool HasBaseComponentsSpeicified()
			{
				if (!string.IsNullOrWhiteSpace(TemplatePropertyItem["Base-Comp"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(TemplatePropertyItem["Base-Comp-Group"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(TemplatePropertyItem["Base-TB-Lower"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(TemplatePropertyItem["Base-TB-Upper"]))
				{
					return true;
				}
				return false;
			}
		}

