				{
				case "Vapor":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_VaporPhaseName;
					break;
				case "Liquid":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_LiquidPhaseName;
