				case "Liquid1":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_Liquid1PhaseName;
					break;
				case "Liquid2":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_Liquid2PhaseName;
					break;
				case "Solid":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_SolidPhaseName;
					break;
				case "Total":
					result = GridFormsResources.StreamSummaryPage_PropertyLabel_TotalPhaseName;
					break;
				}
				return result;
			}
		}

