			public IAdbUnitsProvider AdbUnitsProvider { get; private set; }

			public TemplatePropertyItem PropertyItem { get; private set; }

			public int UnitRow { get; private set; }

			public string SIUnit { get; private set; }

			private DataCellText UnitDataCell
			{
				get
				{
					if (_unitDataCell == null)
					{
						_unitDataCell = new DataCellText
						{
							IsReadOnly = true
						};
					}
					return _unitDataCell;
				}
			}

			public ComponentsGroupRecord(TemplatePropertyItem propertyItem, IAdbUnitsProvider adbUnitsProvider, string unit, string format)
				: base(propertyItem.DisplayName)
			{
				if (propertyItem == null)
				{
					throw new ArgumentNullException("propertyItem");
				}
				if (adbUnitsProvider == null)
				{
					throw new ArgumentNullException("adbUnitsProvider");
				}
				AdbUnitsProvider = adbUnitsProvider;
				PropertyItem = propertyItem;
				base.Unit = unit;
				Format = format;
			}

			public void UpdateUnit(string unit)
			{
				base.Unit = unit;
			}

			public override IDataCell GetUnitDataCell()
			{
				return UnitDataCell;
			}

			public override IDataCell GetStreamDataCell(SrdtColumnTag tag)
			{
				int? unitRow = _resolvedUnitRow;
				string engineName = PropertyItem.EngineName;
				if (!PhysicalProperty.CorrespondingEngineNames.Keys.Contains(engineName))
				{
					return new DataCellText();
				}
				double? siValue = SummarizeChildren(tag, ref unitRow);
				if (siValue.HasValue)
				{
					if (!_resolvedUnitRow.HasValue && unitRow.HasValue)
					{
						_resolvedUnitRow = unitRow;
						UpdateUnitsRelated();
					}
					string cxsPath = SumarizePath(tag);
					bool isStateConditionProperty = GetAdsNativeProperty() != null;
					IDataCell dataCell = tag.FormatPropertyValue(PropertyItem, isStateConditionProperty, siValue, cxsPath, _resolvedUnitRow.GetValueOrDefault(), base.Unit, Format);
					if (dataCell != null)
					{
						dataCell.ContentHorizontalAlignment = HorizontalAlignment.Right;
					}
					return dataCell;
				}
				return new DataCellText();
			}

			private void UpdateUnitsRelated()
			{
				int valueOrDefault = _resolvedUnitRow.GetValueOrDefault();
				if (valueOrDefault != 0)
				{
					if (string.IsNullOrEmpty(base.Unit))
					{
						base.Unit = AdbUnitsProvider.GetDefaultDisplayUnits(valueOrDefault);
