			private readonly StreamReportControl _src;

			private readonly ICommand _addPropertiesCommand;

			public override string Header => GridFormsResources.StreamSummaryPage_PropertyLabel_CommandAddProperties;

			public CommandAddPropertiesRecord(StreamReportControl src)
			{
				if (src == null)
				{
					throw new ArgumentNullException("src");
				}
				_src = src;
				_addPropertiesCommand = new RelayActionCommand(_addPropertiesCommand_Executed);
			}

			public override IDataCell GetNameDataCell()
			{
				return new DataCellText(Header)
				{
					AllowDrag = false,
					Template = GenerateCommandTemplate(_addPropertiesCommand)
				};
			}

			private void _addPropertiesCommand_Executed()
			{
				_src.Dispatcher.BeginInvoke(new Action(PopupFindPropertyDialog), DispatcherPriority.Loaded);
			}

			private bool _addPropertiesCommand_CanExecute()
			{
				if (_src.UnityContainer != null)
				{
					return _src.TemplateItem != null;
				}
				return false;
			}

			private void PopupFindPropertyDialog()
			{
				_src.OpenTemplateEditor(TemplateEditorTabMode.SelectProperties, saveChanges: false, _templateEditor_Loaded);
			}

			private void _templateEditor_Loaded(AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.TemplateEditor editor)
			{
				if (editor.selectPropertiesEditor != null && editor.selectPropertiesEditor.AddPropertyCommand != null)
				{
					editor.selectPropertiesEditor.AddPropertyCommand.Execute(null);
				}
			}

			private DataTemplate GenerateCommandTemplate(ICommand command)
			{
				FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(Run));
				frameworkElementFactory.SetValue(Run.TextProperty, Header);
				FrameworkElementFactory frameworkElementFactory2 = new FrameworkElementFactory(typeof(Hyperlink));
				frameworkElementFactory2.SetValue(Hyperlink.CommandProperty, command);
				frameworkElementFactory2.AppendChild(frameworkElementFactory);
				FrameworkElementFactory frameworkElementFactory3 = new FrameworkElementFactory(typeof(TextBlock));
				frameworkElementFactory3.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Left);
				frameworkElementFactory3.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center);
				frameworkElementFactory3.SetValue(TextBlock.TextAlignmentProperty, TextAlignment.Center);
				frameworkElementFactory3.SetValue(FrameworkElement.MarginProperty, new Thickness(2.0, 0.0, 0.0, 0.0));
				frameworkElementFactory3.AppendChild(frameworkElementFactory2);
				return new DataTemplate
				{
					VisualTree = frameworkElementFactory3
				};
			}
		}

