		public IDataCell QueryDataCell(DataRow row, DataColumn column)
		{
			if (row == null)
			{
				throw new ArgumentNullException("row");
			}
			if (column == null)
			{
				throw new ArgumentNullException("column");
			}
			if (row.Tag is RecordBase recordBase)
			{
				if (column.HeaderItems == null)
				{
					if (string.IsNullOrEmpty(column.Header))
					{
						return recordBase.GetNameDataCell();
					}
					return recordBase.GetUnitDataCell();
				}
				if (!(column.Tag is SrdtColumnTag tag))
				{
					return null;
				}
				return recordBase.GetStreamDataCell(tag);
			}
			return null;
		}

		public void UpdateRecordUnit(DataRow row, string oldUnit, string newUnit)
		{
			if (row == null || string.Equals(oldUnit, newUnit, StringComparison.InvariantCultureIgnoreCase) || !(row.Tag is IUnitModifiable unitModifiable))
			{
				return;
			}
			try
			{
				unitModifiable.UpdateUnit(newUnit);
				foreach (DataColumn column in row.DataTable.Columns)
				{
					if (column.Tag != null)
					{
						row.ClearData(column);
					}
				}
				row.RaiseIndexerPropertyChanged();
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(ReportControl), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
		}

		public void Refresh(DataTable table, IParsedTemplateInfo info, DataTable oldDataTable = null)
		{
			if (table == null)
			{
				throw new ArgumentNullException("table");
			}
			if (info == null)
			{
