							RecordBase tag = list2[num + num3];
							dataRow2.Tag = tag;
							if (ReportControl.TemplateItem.Settings.ScopeOptions.HideComWithZeroFlow && HideZeroComponentsRows(dataRow2))
							{
								num2++;
							}
							list3.Add(dataRow2);
						}
						if (dictionary == null || dictionary.Count == 0)
						{
							dataRow.GroupingState = ((!flag.Value) ? RowGroupingState.Collapsed : RowGroupingState.Expanded);
						}
