		private bool HideZeroComponentsRows(DataRow row)
		{
			bool flag = true;
			int count = row.DataTable.Columns.Count;
			if (count <= 2)
			{
				return flag;
			}
			for (int i = 2; i < count - 1; i++)
			{
				if (row[i].Value != null && double.TryParse(row[i].Value.ToString(), out var result) && result != 0.0)
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				row.Visibility = Visibility.Collapsed;
			}
			return flag;
		}

		private List<RecordBase> ExpandRecords()
		{
			List<RecordBase> list = new List<RecordBase>();
			foreach (RecordBase record in _records)
			{
				list.Add(record);
				if (record is GroupRecord)
				{
					list.AddRange(((GroupRecord)record).ExpandChildren());
				}
			}
			return list;
		}

		private Dictionary<string, RowGroupingState> CollectionGroupingStates(DataTable table)
		{
			if (table != null)
			{
				Dictionary<string, RowGroupingState> dictionary = new Dictionary<string, RowGroupingState>();
				Stack<Tuple<GroupRecord, string>> stack = new Stack<Tuple<GroupRecord, string>>();
				{
					foreach (DataRow row in table.Rows)
					{
						if (!(row.Tag is GroupRecord groupRecord))
						{
							continue;
						}
						Tuple<GroupRecord, string> tuple = null;
						while (stack.Count > 0)
						{
							Tuple<GroupRecord, string> tuple2 = stack.Peek();
							if (tuple2.Item1.Children.Contains(groupRecord))
							{
								tuple = tuple2;
								break;
							}
							stack.Pop();
						}
						string text = ((tuple == null) ? groupRecord.Header : $"{tuple.Item2}.{groupRecord.Header}");
						dictionary[text] = row.GroupingState;
						stack.Push(new Tuple<GroupRecord, string>(groupRecord, text));
					}
					return dictionary;
				}
			}
			return null;
		}

		private static RowGroupingState CheckGroupingStatus(GroupRecord newGroupRecord, bool isFirstTopLevel, DataTable tableToCompare, ref int lastComparedGroupIndex)
		{
			bool flag = false;
			int num = lastComparedGroupIndex;
			for (int i = lastComparedGroupIndex; i < tableToCompare.Rows.Count; i++)
			{
				if (!flag)
				{
					num = i;
				}
				DataRow dataRow = tableToCompare.Rows[i];
				if (dataRow.Tag is GroupRecord groupRecord)
				{
					flag = true;
					if (string.Equals(newGroupRecord.Header, groupRecord.Header, StringComparison.CurrentCulture))
					{
						lastComparedGroupIndex = i;
						return dataRow.GroupingState;
					}
				}
			}
			lastComparedGroupIndex = num;
			if (!isFirstTopLevel)
			{
				return RowGroupingState.Collapsed;
			}
			return RowGroupingState.Expanded;
		}

		private void RebuildRecords(IParsedTemplateInfo info, IEnumerable<SrdtColumnTag> columnTags)
		{
			_records.Clear();
			ReportTemplateItem templateItem = ReportControl.TemplateItem;
			if (templateItem == null)
			{
				return;
			}
			TemplateGeneralOptions generalOptions = templateItem.Settings.GeneralOptions;
			TemplateScopeOptions scopeOptions = templateItem.Settings.ScopeOptions;
			_records.AddRange(GenerateHeaderRecords(generalOptions));
			if (scopeOptions.TotalStream || scopeOptions.Substreams)
			{
				ReadOnlyCollection<string> validSubstreams = ResultContext.ValidSubstreams;
				if (validSubstreams.Count > 0)
				{
					List<PropertyBag> source = info.DisplayPropertyItems.Select((TemplatePropertyItem x) => new PropertyBag(x)).ToList();
					IEnumerable<string> enumerable = ResultContext.GetVaildComponents(ReportControl.MainNodePath);
					if (enumerable == null || !enumerable.Any())
					{
						enumerable = ResultContext.AllComponents;
					}
					if (scopeOptions.TotalStream && ResultContext.HasTotalSubstream)
					{
						List<PropertyBag> pbs = source.Where((PropertyBag x) => x.IsFitForSubstream("ALL")).ToList();
						GroupRecord groupRecord = new GroupRecord(GridFormsResources.StreamSummaryPage_PropertyLabel_TotalStream);
						AppendTotalStreamPropertyRecords(groupRecord, pbs, enumerable);
						if (groupRecord.Children.Count > 0)
						{
							_records.Add(groupRecord);
						}
					}
					if (scopeOptions.Substreams)
					{
						IEnumerable<string> enumerable2 = null;
						if (!string.IsNullOrEmpty(ResultContext.MixedSubstream))
						{
							List<PropertyBag> propertyBags = source.Where((PropertyBag x) => x.IsFitForSubstream(ResultContext.MixedSubstream)).ToList();
							enumerable2 = enumerable.Intersect(ResultContext.ConventionalComponents, StringComparer.InvariantCultureIgnoreCase).ToList();
							RecordBase recordBase = GenerateMixedSubstreamRecord(propertyBags, columnTags, scopeOptions.PhasesForMixedSubstream, generalOptions.PhaseLabel, generalOptions.ComponentAttributes, generalOptions.ParticleSizeDistributions, enumerable2);
							if (recordBase != null)
							{
								_records.Add(recordBase);
							}
						}
						List<string> list = validSubstreams.Where((string x) => string.Equals(ResultContext.GetValidSubstreamType(x), "CISOLID", StringComparison.InvariantCultureIgnoreCase)).ToList();
						foreach (string sub in list)
						{
							if (enumerable2 == null)
							{
								enumerable2 = enumerable.Intersect(ResultContext.ConventionalComponents, StringComparer.InvariantCultureIgnoreCase).ToList();
							}
							List<PropertyBag> propertyBags2 = source.Where((PropertyBag x) => x.IsFitForSubstream(sub)).ToList();
							RecordBase recordBase2 = GenerateSubstreamRecord(sub, propertyBags2, generalOptions.ComponentAttributes, generalOptions.ParticleSizeDistributions, enumerable2);
							if (recordBase2 != null)
							{
								_records.Add(recordBase2);
							}
						}
						IEnumerable<string> enumerable3 = null;
						foreach (string sub2 in validSubstreams.Except(list).Except(new string[2]
						{
							ResultContext.TotalSubstream,
							ResultContext.MixedSubstream
						}))
						{
							if (enumerable3 == null)
							{
								enumerable3 = enumerable.Intersect(ResultContext.NCComponents, StringComparer.InvariantCultureIgnoreCase).ToList();
							}
							List<PropertyBag> propertyBags3 = source.Where((PropertyBag x) => x.IsFitForSubstream(sub2)).ToList();
							RecordBase recordBase3 = GenerateSubstreamRecord(sub2, propertyBags3, generalOptions.ComponentAttributes, generalOptions.ParticleSizeDistributions, enumerable3);
							if (recordBase3 != null)
							{
								_records.Add(recordBase3);
							}
						}
					}
				}
			}
			_records.Add(new CommandAddPropertiesRecord(ReportControl));
		}

		[IteratorStateMachine(typeof(GenerateHeaderRecordsEnumerator))]
		private IEnumerable<RecordBase> GenerateHeaderRecords(TemplateGeneralOptions options)
		{
			return new GenerateHeaderRecordsEnumerator(-2)
			{
				iteratorOwner = this,
				initialOptions = options
			};
		}

		private RecordBase CreateStreamCostRecord()
		{
			return new LeafPropertyRecord(new TemplatePropertyItem(BasisStreamProperties.StreamCost), AdbUnitsProvider, "ALL");
		}

		private RecordBase GenerateMixedSubstreamRecord(List<PropertyBag> propertyBags, IEnumerable<SrdtColumnTag> columnTags, bool includePhasesForMixedSubstream, bool includePhaseLabel, bool includeComponentAttributes, bool includeParticleSizeDistributions, IEnumerable<string> availableComponents)
		{
			GroupRecord groupRecord = new GroupRecord(string.Format(GridFormsResources.StreamSummaryPage_PropertyLabel_SubstreamFormat, ResultContext.MixedSubstream));
			if (includePhaseLabel)
			{
				groupRecord.Children.Add(new PhaseLabelRecord());
			}
			IEnumerable<PropertyBag> pbs = propertyBags.Where((PropertyBag x) => x.IsFitForPhase("Total"));
			AppendPropertyRecords(groupRecord, pbs, ResultContext.MixedSubstream, "Total", availableComponents);
			if (includePhasesForMixedSubstream)
			{
				List<string> obj = new List<string> { "Vapor", "Liquid", "Liquid1", "Liquid2", "Solid" };
				List<string> possiblePhasesForMixedSubstream = GetPossiblePhasesForMixedSubstream(propertyBags, columnTags);
				foreach (string phase in obj)
				{
					if (possiblePhasesForMixedSubstream.Contains(phase))
					{
						List<PropertyBag> list = propertyBags.Where((PropertyBag x) => x.IsFitForPhase(phase)).ToList();
						if (list.Count > 0)
						{
							GroupRecord groupRecord2 = new GroupRecord(string.Format(groupRecord.FindPhaseText(phase)));
							AppendPropertyRecords(groupRecord2, list, ResultContext.MixedSubstream, phase, availableComponents);
							groupRecord.Children.Add(groupRecord2);
						}
					}
				}
			}
			if (includeComponentAttributes)
			{
				AppendComponentAttributes(groupRecord, ResultContext.MixedSubstream, readFromAds: true);
			}
			if (includeParticleSizeDistributions)
			{
				AppendParticleSizeDistributions(groupRecord, ResultContext.MixedSubstream);
			}
			if (groupRecord.Children.Count > 0)
			{
				return groupRecord;
			}
			return null;
		}

		private static List<string> GetPossiblePhasesForMixedSubstream(List<PropertyBag> propertyBags, IEnumerable<SrdtColumnTag> columnTags)
		{
			List<string> list = new List<string>();
			foreach (SrdtColumnTag columnTag in columnTags)
			{
				foreach (string phase in columnTag.Phases)
				{
					if (!list.Contains(phase))
					{
						list.Add(phase);
					}
				}
			}
			return list;
		}

		private RecordBase GenerateSubstreamRecord(string substream, List<PropertyBag> propertyBags, bool includeComponentAttributes, bool includeParticleSizeDistributions, IEnumerable<string> availableComponents)
		{
			GroupRecord groupRecord = new GroupRecord(string.Format(GridFormsResources.StreamSummaryPage_PropertyLabel_SubstreamFormat, substream));
			IEnumerable<PropertyBag> enumerable = propertyBags.Where((PropertyBag x) => x.IsFitForPhase("Total"));
			AppendPropertyRecords(groupRecord, enumerable, substream, "Total", availableComponents);
			IEnumerable<PropertyBag> pbs = from x in propertyBags.Except(enumerable)
				where x.IsFitForPhase("Solid")
				select x;
			AppendPropertyRecords(groupRecord, pbs, substream, "Solid", availableComponents);
			if (includeComponentAttributes)
			{
				AppendComponentAttributes(groupRecord, substream);
			}
			if (includeParticleSizeDistributions)
			{
				AppendParticleSizeDistributions(groupRecord, substream);
			}
			if (groupRecord.Children.Count > 0)
			{
				return groupRecord;
			}
			return null;
		}

		private void AppendTotalStreamPropertyRecords(GroupRecord parent, IEnumerable<PropertyBag> pbs, IEnumerable<string> availableComponents)
		{
			foreach (PropertyBag pb in pbs)
			{
				if (pb.HasSpecificPhaseOnTotalStream)
				{
					foreach (string resolvedPhase in pb.ResolvedPhases)
					{
						foreach (RecordBase item in GenerateCommonPropertyRecords(pb, ResultContext.TotalSubstream, resolvedPhase, availableComponents))
						{
							parent.Children.Add(item);
						}
					}
					continue;
				}
				foreach (RecordBase item2 in GenerateCommonPropertyRecords(pb, ResultContext.TotalSubstream, "Total", availableComponents))
				{
					parent.Children.Add(item2);
				}
			}
		}

		private void AppendPropertyRecords(GroupRecord parent, IEnumerable<PropertyBag> pbs, string substream, string phase, IEnumerable<string> availableComponents)
		{
			foreach (PropertyBag pb in pbs)
			{
				foreach (RecordBase item in GenerateCommonPropertyRecords(pb, substream, phase, availableComponents))
				{
					parent.Children.Add(item);
				}
			}
		}

		private void AppendComponentAttributes(GroupRecord parent, string substream, bool readFromAds = false)
		{
			IEnumerable<ComponentAttributeTuple> enumerable = (readFromAds ? GetComponentAttributeTuplesFromAds(substream) : WrapperProxy.GetComponentAttributeTuples(substream));
			if (enumerable == null || !enumerable.Any())
			{
				return;
			}
			IOrderedEnumerable<ComponentAttributeTuple> orderedEnumerable = from t in enumerable
				orderby t.Component, t.Attribute
				select t;
			GroupRecord groupRecord = new GroupRecord(GridFormsResources.StreamSummaryPage_PropertyLabel_ComponentAttributes);
			parent.Children.Add(groupRecord);
			bool flag = false;
			string b = null;
			string b2 = null;
			GroupRecord groupRecord2 = null;
			GroupRecord groupRecord3 = null;
			List<string> list = new List<string>();
			foreach (ComponentAttributeTuple item2 in orderedEnumerable)
			{
				if (string.IsNullOrEmpty(item2.Component) || string.IsNullOrEmpty(item2.Attribute))
				{
					continue;
				}
				string item = $"{item2.Component}:{item2.Attribute}:{item2.Element}";
				if (!list.Contains(item))
				{
					list.Add(item);
					bool flag2 = !string.Equals(item2.Component, b, StringComparison.InvariantCultureIgnoreCase);
					bool flag3 = !string.Equals(item2.Attribute, b2, StringComparison.InvariantCultureIgnoreCase);
					if ((flag2 || flag3) && groupRecord3 != null && groupRecord3.Children.Count == 1 && flag)
					{
						groupRecord2.Children.Remove(groupRecord3);
						groupRecord2.Children.Add(groupRecord3.Children[0]);
					}
					if (flag2)
					{
						groupRecord2 = new GroupRecord(item2.Component);
						b = item2.Component;
						groupRecord.Children.Add(groupRecord2);
						groupRecord3 = new GroupRecord(item2.Attribute);
						b2 = item2.Attribute;
						groupRecord2.Children.Add(groupRecord3);
					}
					if (flag3 && !flag2)
					{
						groupRecord3 = new GroupRecord(item2.Attribute);
						b2 = item2.Attribute;
						groupRecord2.Children.Add(groupRecord3);
					}
					flag = string.IsNullOrWhiteSpace(item2.Element) || string.Equals(item2.Attribute, item2.Element, StringComparison.OrdinalIgnoreCase);
					groupRecord3.Children.Add(new ComponentAttributeLeafRecord(substream, item2.Component, item2.Attribute, item2.Element));
				}
			}
			if (groupRecord2 != null && groupRecord3 != null && groupRecord3.Children.Count == 1 && flag)
			{
				groupRecord2.Children.Remove(groupRecord3);
				groupRecord2.Children.Add(groupRecord3.Children[0]);
			}
		}

		[IteratorStateMachine(typeof(GetComponentAttributeTuplesFromAdsEnumerator))]
		private IEnumerable<ComponentAttributeTuple> GetComponentAttributeTuplesFromAds(string substream)
		{
			return new GetComponentAttributeTuplesFromAdsEnumerator(-2)
			{
				initialSubstream = substream
			};
		}

		private void AppendParticleSizeDistributions(GroupRecord parent, string substream)
		{
			string psdId = null;
			IEnumerable<string> psdLabels = WrapperProxy.GetPsdLabels(substream, out psdId);
			if (!psdLabels.Any())
			{
				return;
			}
			GroupRecord groupRecord = new GroupRecord(psdId ?? GridFormsResources.StreamSummaryPage_PropertyLabel_PSD);
			int num = 0;
			foreach (string item in psdLabels)
			{
				groupRecord.Children.Add(new PSDLeafRecord(substream, psdId, item, num++));
			}
			parent.Children.Add(groupRecord);
		}

		[IteratorStateMachine(typeof(GenerateCommonPropertyRecordsEnumerator))]
		private IEnumerable<RecordBase> GenerateCommonPropertyRecords(PropertyBag pb, string substream, string phase, IEnumerable<string> availableComponents)
		{
			return new GenerateCommonPropertyRecordsEnumerator(-2)
			{
				iteratorOwner = this,
				initialPb = pb,
				initialSubstream = substream,
				initialPhase = phase,
				initialAvailableComponents = availableComponents
			};
		}

		private bool ShouldCreateComponentSummary(PropertyBag pb, IEnumerable<string> components)
		{
			if ((pb.TemplatePropertyItem.StreamProperty.IsSumAllowed || pb.TemplatePropertyItem.StreamProperty.IsNormalizationAllowed) && components.Any())
			{
				return true;
			}
			return false;
		}

		private IEnumerable<RecordBase> SplitPropertyRecords(PropertyBag pb, string substream, string phase, LeafPropertyComponentsInfo componentsInfo)
		{
			List<string> list = pb.Units.ToList();
			List<string> basises = pb.Basis.ToList();
			List<string> temps = pb.Temperatures.ToList();
			List<string> pressures = pb.Pressures.ToList();
			List<string> lvpcs = pb.Lvpcts.ToList();
			List<RecordBase> list2 = new List<RecordBase>();
			if (list.Count == 0)
			{
				list2.AddRange(SplitPropertyRecordsU(pb, substream, phase, componentsInfo, null, basises, temps, pressures, lvpcs));
			}
			else
			{
				foreach (string item in list)
				{
					list2.AddRange(SplitPropertyRecordsU(pb, substream, phase, componentsInfo, item, basises, temps, pressures, lvpcs));
				}
			}
			return list2;
		}

		private IEnumerable<RecordBase> SplitPropertyRecordsU(PropertyBag pb, string substream, string phase, LeafPropertyComponentsInfo componentsInfo, string unit, List<string> basises, List<string> temps, List<string> pressures, List<string> lvpcs)
		{
			List<RecordBase> list = new List<RecordBase>();
			if (basises.Count == 0 || (basises.Count == 1 && string.Equals(basises[0], "WET", StringComparison.CurrentCultureIgnoreCase)))
			{
				list.AddRange(SplitPropertyRecordsUB(pb, substream, phase, componentsInfo, unit, null, temps, pressures, lvpcs));
			}
			else
			{
				foreach (string basise in basises)
				{
					list.AddRange(SplitPropertyRecordsUB(pb, substream, phase, componentsInfo, unit, basise, temps, pressures, lvpcs));
				}
			}
			return list;
		}

		private IEnumerable<RecordBase> SplitPropertyRecordsUB(PropertyBag pb, string substream, string phase, LeafPropertyComponentsInfo componentsInfo, string unit, string basis, List<string> temps, List<string> pressures, List<string> lvpcs)
		{
			List<RecordBase> list = new List<RecordBase>();
			if (temps.Count == 0)
			{
				list.AddRange(SplitPropertyRecordsUBT(pb, substream, phase, componentsInfo, unit, basis, null, pressures, lvpcs));
			}
			else
			{
				foreach (string temp in temps)
				{
					list.AddRange(SplitPropertyRecordsUBT(pb, substream, phase, componentsInfo, unit, basis, temp, pressures, lvpcs));
				}
			}
			return list;
		}

		private IEnumerable<RecordBase> SplitPropertyRecordsUBT(PropertyBag pb, string substream, string phase, LeafPropertyComponentsInfo componentsInfo, string unit, string basis, string temp, List<string> pressures, List<string> lvpcs)
		{
			List<RecordBase> list = new List<RecordBase>();
			if (pressures.Count == 0)
			{
				list.AddRange(SplitPropertyRecordsUBTP(pb, substream, phase, componentsInfo, unit, basis, temp, null, lvpcs));
			}
			else
			{
				foreach (string pressure in pressures)
				{
					list.AddRange(SplitPropertyRecordsUBTP(pb, substream, phase, componentsInfo, unit, basis, temp, pressure, lvpcs));
				}
			}
			return list;
		}

		private IEnumerable<RecordBase> SplitPropertyRecordsUBTP(PropertyBag pb, string substream, string phase, LeafPropertyComponentsInfo componentsInfo, string unit, string basis, string temp, string pressure, List<string> lvpcts)
		{
			double? temperatureBasis = ConvertToDouble(temp);
			double? pressureBasis = ConvertToDouble(pressure);
			List<RecordBase> list = new List<RecordBase>();
			if (lvpcts.Count == 0)
			{
				list.Add(new LeafPropertyRecord(pb.TemplatePropertyItem, AdbUnitsProvider, substream, componentsInfo, phase, basis, temperatureBasis, pressureBasis, null, unit));
			}
			else
			{
				foreach (string lvpct in lvpcts)
				{
					list.Add(new LeafPropertyRecord(pb.TemplatePropertyItem, AdbUnitsProvider, substream, componentsInfo, phase, basis, temperatureBasis, pressureBasis, ConvertToDouble(lvpct), unit));
				}
			}
			return list;
		}

		private static double? ConvertToDouble(string input)
		{
			if (!string.IsNullOrEmpty(input))
			{
				double result = 0.0;
				if (double.TryParse(input, NumberStyles.Number, CultureInfo.InvariantCulture, out result))
				{
					return result;
				}
			}
			return null;
		}

		public static bool HasSpecificPhaseOnTotalStream(TemplatePropertyItem tpi)
		{
			SettingItem metadata = tpi.GetMetadata("Substream");
			if (metadata == null)
			{
				return false;
			}
			SettingItem metadata2 = tpi.GetMetadata("Phase");
			if (metadata2 == null)
			{
				return false;
			}
			string[] resolvedValues = metadata.ResolvedValues;
			if (resolvedValues == null || !resolvedValues.Contains("ALL", StringComparer.InvariantCultureIgnoreCase))
			{
				return false;
			}
			string[] resolvedValues2 = metadata2.ResolvedValues;
			if (resolvedValues2 == null || resolvedValues2.Length == 0 || (resolvedValues2.Length == 1 && string.Equals(resolvedValues2[0], "Total", StringComparison.InvariantCultureIgnoreCase)))
			{
				return false;
			}
			return true;
		}
	}
	public class StreamReportDataTable : DataTable
	{
		private readonly StreamReportControl _reportControl;

		private readonly StreamReportDataFiller _dataFiller;

		private readonly List<StreamData> _selectedStreams = new List<StreamData>();

		private readonly List<StreamData> _allContextAvailableStreams = new List<StreamData>();

		private int _updatingColumnsFlag;

		private bool _isUpdatingData;

		public IEnumerable<StreamData> AllContextAvailableStreams => _allContextAvailableStreams;

		public StreamReportDataTable(StreamReportControl reportControl, IEnumerable<StreamData> selectedStreams, IEnumerable<StreamData> allContextAvailableStreams)
		{
			if (reportControl == null)
			{
				throw new ArgumentNullException("reportControl");
			}
			_reportControl = reportControl;
			_dataFiller = new StreamReportDataFiller(reportControl);
			_selectedStreams.AddRange(selectedStreams.ToListAnyway());
			_allContextAvailableStreams.AddRange(allContextAvailableStreams.ToListAnyway());
			base.Columns = new ReadOnlyCollection<DataColumn>(CreateColumns());
		}

		protected override void OnBoundToGridControl()
		{
			if (_allContextAvailableStreams.Count == 0)
			{
				base.GridControl.CoverText = GridFormsResources.StreamSummaryPage_NoDataToDisplay;
			}
			else
			{
				base.GridControl.CoverText = null;
			}
			base.OnBoundToGridControl();
		}

		protected override IDataCell OnCellValueQueried(DataRow row, DataColumn column)
		{
			return _dataFiller.QueryDataCell(row, column);
		}

		protected override void OnCellValueChanged(IDataCell cell, object oldValue, object newValue)
		{
			if (!_isUpdatingData && !object.Equals(oldValue, newValue) && base.Columns.IndexOf(cell.Column) == 1)
			{
				_dataFiller.UpdateRecordUnit(cell.Row, oldValue as string, newValue as string);
				if (cell.Row.Tag != null)
				{
					ChangeRecordUnit(cell, oldValue, newValue);
				}
			}
		}

		private void ChangeRecordUnit(IDataCell cell, object oldValue, object newValue)
		{
			if (cell.Row.Tag is ILeafPropertyRecord)
			{
				if (((ILeafPropertyRecord)cell.Row.Tag).Component != null)
				{
					ChangeComponentsGroupRecordUnit(cell, oldValue, newValue);
				}
			}
			else if (cell.Row.Tag is IComponentsGroupRecord)
			{
				base.Rows.IndexOf(cell.Row);
				ChangeComponentsLeafRecordUnit(cell, oldValue, newValue);
			}
		}

		private void ChangeComponentsGroupRecordUnit(IDataCell cell, object oldValue, object newValue)
		{
			int num = base.Rows.IndexOf(cell.Row);
			while (num > 1)
			{
				DataRow dataRow = base.Rows[num];
				if (dataRow.GroupingRowsCount > 0)
				{
					if (dataRow.Tag is IComponentsGroupRecord && dataRow[cell.Column] != null && dataRow[cell.Column].Value != newValue)
					{
						dataRow[cell.Column].Value = newValue;
					}
					break;
				}
				if (dataRow.Tag is ILeafPropertyRecord leafPropertyRecord && !string.IsNullOrEmpty(leafPropertyRecord.Component))
				{
					num--;
					continue;
				}
				break;
			}
		}

		private void ChangeComponentsLeafRecordUnit(IDataCell cell, object oldValue, object newValue)
		{
			int num = base.Rows.IndexOf(cell.Row);
			int expandedRecordsCount = ((IComponentsGroupRecord)cell.Row.Tag).ExpandedRecordsCount;
			for (int i = num + 1; i <= num + expandedRecordsCount; i++)
			{
				if (base.Rows[i][cell.Column].Value != newValue)
				{
					base.Rows[i][cell.Column].Value = newValue;
				}
			}
		}

		protected override void OnColumnHeaderChanged(DataColumn column, string oldHeader, string newHeader)
		{
			if (column == null || base.GridControl == null || !base.GridControl.IsLoaded || string.Equals(oldHeader, newHeader) || string.IsNullOrWhiteSpace(newHeader) || (string.IsNullOrWhiteSpace(oldHeader) && base.Columns.LastOrDefault() != column) || _updatingColumnsFlag > 0)
			{
				return;
			}
			try
			{
				_updatingColumnsFlag++;
				List<StreamData> list = new List<StreamData>();
				foreach (DataColumn item in base.Columns.OrderBy((DataColumn x) => x.LogicalDisplayIndex))
				{
					if (item.HeaderItems == null)
					{
						continue;
					}
					if (item == column)
					{
						StreamData streamData = _allContextAvailableStreams.FirstOrDefault((StreamData x) => string.Equals(x.GetScopedName(_reportControl.HierarchyScope), newHeader, StringComparison.CurrentCulture));
						if (streamData != null)
						{
							list.Add(streamData);
						}
					}
					else if (item.Tag != null)
					{
						list.Add((item.Tag as SrdtColumnTag).Stream);
					}
				}
				_selectedStreams.Clear();
				_selectedStreams.AddRange(list);
				base.Columns = new ReadOnlyCollection<DataColumn>(CreateColumns());
				UpdateData(this);
				base.GridControl.RefreshData();
				_reportControl.SaveStreamGroup();
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(_reportControl), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
			finally
			{
				_updatingColumnsFlag--;
			}
		}

		protected override object GetDirectCellValue(DataRow row, DataColumn column)
		{
			if (column.DisplayIndex == 1)
			{
				if (row.Tag is IUnitModifiable)
				{
					IDataCell dataCell = row[column];
					if (dataCell != null)
					{
						string valueAsString = dataCell.ValueAsString;
						if (!string.IsNullOrEmpty(valueAsString))
						{
							return valueAsString;
						}
					}
					EnsureUnitValueInitialized(row);
					return row[column]?.Value;
				}
				return null;
			}
			IDataCell dataCell2 = row[column];
			if (dataCell2 != null)
			{
				if (dataCell2.Tag is ICellTag cellTag)
				{
					if (!string.IsNullOrEmpty(cellTag.OriginalValueAsString))
					{
						return cellTag.OriginalValueAsString;
					}
					if (cellTag.ValueAtCurrentUnit.HasValue)
					{
						return cellTag.ValueAtCurrentUnit.Value;
					}
				}
				return dataCell2.Value;
			}
			return null;
		}

		private void EnsureUnitValueInitialized(DataRow row)
		{
			if (base.Columns.Count < 4)
			{
				return;
			}
			foreach (DataColumn item in base.Columns.Skip(2))
			{
				IDataCell dataCell = row[item];
				if (dataCell != null && dataCell.Tag != null)
				{
					break;
				}
			}
		}

		public void DeleteColumns(IEnumerable<DataColumn> columns)
		{
			if (columns == null)
			{
				throw new ArgumentNullException("colulmns");
			}
			try
			{
				List<StreamData> list = new List<StreamData>();
				foreach (DataColumn item in base.Columns.Except(columns))
				{
					if (item.Tag is SrdtColumnTag { Stream: not null } srdtColumnTag)
					{
						list.Add(srdtColumnTag.Stream);
					}
				}
				_selectedStreams.Clear();
				_selectedStreams.AddRange(list);
				base.Columns = new ReadOnlyCollection<DataColumn>(CreateColumns());
				UpdateData(this);
				base.GridControl.RefreshData();
				_reportControl.SaveStreamGroup();
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(_reportControl), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
		}

		public IEnumerable<string> GetDisplayStreamIds()
		{
			List<string> list = new List<string>();
			foreach (DataColumn item in base.Columns.OrderBy((DataColumn x) => x.DisplayIndex))
			{
				if (item.HeaderItems != null && !string.IsNullOrEmpty(item.Header))
				{
					string fullStreamId = GetFullStreamId(item.Header);
					if (!list.Contains(fullStreamId))
					{
						list.Add(fullStreamId);
					}
				}
			}
			return list;
		}

		public void UpdateData(StreamReportDataTable lastDataTable)
		{
			if (_allContextAvailableStreams.Count == 0 || _reportControl.TemplateItem == null || _isUpdatingData)
			{
				return;
			}
			Cursor overrideCursor = Mouse.OverrideCursor;
			int value = MmgSor.MMinqcpt();
			int value2 = MmgSor.MMinqpgc();
			int value3 = MmgSor.MMinqnec();
			try
			{
				_isUpdatingData = true;
				Mouse.OverrideCursor = Cursors.Wait;
				ResultContext.Reset();
				IParsedTemplateInfo templateInfo = _dataFiller.GetTemplateInfo();
				_reportControl.Calculator.DoCalculation(_reportControl.MainNode, _reportControl.MainNodePath, _selectedStreams.Select((StreamData x) => x.Name), templateInfo.CalculatePropertyItems);
				PopulateData(templateInfo, lastDataTable);
			}
			finally
			{
				Mouse.OverrideCursor = overrideCursor;
				_isUpdatingData = false;
				_reportControl.OnDataSourceUpdated();
				((IAXEmbeddedObject)_reportControl).NotifyUpdatedData();
			}
			MmgSor.MMsetcpt(value);
			MmgSor.MMsetpgc(value2);
			MmgSor.MMsetnec(value3);
		}

		private void PopulateData(IParsedTemplateInfo parsedTemplateInfo, StreamReportDataTable lastDataTable)
		{
			foreach (DataColumn column in base.Columns)
			{
				if (column.Tag is SrdtColumnTag srdtColumnTag)
				{
					srdtColumnTag.ResetData();
				}
			}
			_dataFiller.Refresh(this, parsedTemplateInfo, lastDataTable);
		}

		private IList<DataColumn> CreateColumns()
		{
			List<DataColumn> list = new List<DataColumn>();
			if (_allContextAvailableStreams.Count > 0)
			{
				list.Add(new DataColumn
				{
					IsReadOnly = true,
					IsFrozen = true,
					Width = 260.0
				});
				list.Add(new DataColumn
				{
					IsFrozen = true,
					Width = 120.0,
					Header = GridFormsResources.StreamSummaryPage_ColumnHeader_Units
				});
				Dictionary<string, string> dictionary = CreateHeaderItemTooltips();
				Dictionary<string, string>.KeyCollection keys = dictionary.Keys;
				foreach (StreamData selectedStream in _selectedStreams)
				{
					list.Add(new DataColumn(selectedStream.GetScopedName(_reportControl.HierarchyScope))
					{
						HeaderItems = keys,
						IsReadOnly = true,
						Width = 100.0,
						Tooltip = selectedStream.ToolTip,
						HeaderItemsTooltips = dictionary,
						Tag = new SrdtColumnTag(_dataFiller, selectedStream)
					});
				}
				list.Add(new DataColumn
				{
					HeaderItems = keys,
					IsReadOnly = true,
					Width = 100.0,
					HeaderItemsTooltips = dictionary
				});
			}
			return list;
		}

		private Dictionary<string, string> CreateHeaderItemTooltips()
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			foreach (StreamData allContextAvailableStream in _allContextAvailableStreams)
			{
				string scopedName = allContextAvailableStream.GetScopedName(_reportControl.HierarchyScope);
				dictionary[scopedName] = allContextAvailableStream.ToolTip;
			}
			return dictionary;
		}

		private string GetFullStreamId(string scopedId)
		{
			if (!string.IsNullOrEmpty(scopedId) && !string.IsNullOrEmpty(_reportControl.HierarchyScope))
			{
				return $"{_reportControl.HierarchyScope}.{scopedId}";
			}
			return scopedId;
		}
	}
	[ProgId("GridForms.StreamReportForm")]
	public class StreamReportForm : MMTabPage, IComponentConnector
	{
		public const string ProgId = "GridForms.StreamReportForm";

		internal StreamReportControl ReportControl;

		private bool _contentLoaded;

		public override bool CanPrintPreview => CanPrint;

		public override bool CanPrint
		{
			get
			{
				if (ReportControl != null && ReportControl.ReportGrid != null && ReportControl.ReportGrid.DataSource != null)
				{
					return ReportControl.ReportGrid.DataSource.Rows.Count > 0;
				}
				return false;
			}
		}

		static StreamReportForm()
		{
			MMTabItem.IsOuterTabItemAccessibleProperty.OverrideMetadata(typeof(StreamReportForm), new FrameworkPropertyMetadata(true, OnIsOuterTabItemAccessiblePropertyChanged));
		}

		public StreamReportForm()
		{
			base.RequiredContextualTabs.Add("StreamReportContextualRibbon");
			base.ViewModelType = typeof(StreamReportFormViewModel);
			InitializeComponent();
			SetBinding(MMTabPage.SubScreenTitleProperty, new Binding
			{
				Source = ReportControl,
				Path = new PropertyPath(StreamReportControl.GroupNameProperty),
				Mode = BindingMode.OneWay
			});
		}

