		private void ReportSelectionSum(GridControl gc)
		{
			List<DataCellInfo> list = gc.TotalSelectedCells.ToList();
			if (list.Count < 2)
			{
				PostStausMessage(null);
				return;
			}
			double num = 0.0;
			bool flag = false;
			foreach (DataCellInfo item in list)
			{
				IDataCell data = item.Data;
				if (data == null)
				{
					continue;
				}
				if (data is DataCellDouble dataCellDouble)
				{
					flag = true;
					num += dataCellDouble.Value.GetValueOrDefault();
				}
				else if (data is DataCellInteger dataCellInteger)
				{
					flag = true;
					num += (double)dataCellInteger.Value.GetValueOrDefault();
				}
				else if (data.Tag is ICellTag { ValueAtCurrentUnit: var valueAtCurrentUnit } cellTag)
				{
					if (valueAtCurrentUnit.HasValue)
					{
						flag = true;
						num += cellTag.ValueAtCurrentUnit.Value;
					}
					else if (cellTag.OriginalValueAsDouble.HasValue)
					{
						flag = true;
						num += cellTag.OriginalValueAsDouble.Value;
					}
				}
			}
			if (flag)
			{
				string text = string.Format(GridFormsResources.StreamSummaryPage_StatusMessage, num.ToString("G6"));
				PostStausMessage(text);
			}
			else
			{
				PostStausMessage(null);
			}
		}

		private void PostStausMessage(string text)
		{
			base.PostTabItemContent = text;
		}

