		public bool CanOpenReport(FlowsheetContextType contextType, object parameter)
		{
			if (!(parameter is StreamGroupItem streamGroupItem))
			{
				return true;
			}
			switch (contextType)
			{
			case FlowsheetContextType.StreamSelected:
				return streamGroupItem.IsAllowedForStream;
			case FlowsheetContextType.UnitOperationSelected:
				return streamGroupItem.IsAllowedForBlock;
			default:
				_ = 3;
				return streamGroupItem.IsAllowedForAnyHierachy;
			}
		}

		public void OpenStreamSummaryReport(FlowsheetContextType contextType, string selectedNodePath, object parameter)
		{
			PushContextStreamGroup(parameter as StreamGroupItem);
			if (string.IsNullOrWhiteSpace(selectedNodePath))
			{
				GotoTopResultsSummary();
				return;
			}
			switch (contextType)
			{
			case FlowsheetContextType.StreamSelected:
				GoToNode($"{selectedNodePath}.Results");
				break;
			case FlowsheetContextType.HierarchyBlockSelected:
				GoToNode($"{selectedNodePath}.Results Summary.Streams");
				break;
			case FlowsheetContextType.UnitOperationSelected:
				GoToNode($"{selectedNodePath}.Stream Results");
				break;
			case FlowsheetContextType.FlowsheetActivatedWithNoSelection:
				GoToNode($"{selectedNodePath}.Results Summary.Streams");
				break;
			default:
				GotoTopResultsSummary();
				break;
			}
		}

		public void SaveReferencedTemplates()
		{
