			int value2 = MmgSor.MMinqpgc();
			int value3 = MmgSor.MMinqnec();
			_unityContainer.SaveReferencedTemplates();
			MmgSor.MMsetcpt(value);
			MmgSor.MMsetpgc(value2);
			MmgSor.MMsetnec(value3);
		}

		private void GotoTopResultsSummary()
		{
			GoToNode("Results Summary.Streams");
		}

		private void GoToNode(string path)
		{
			ScreenContentControl screenContentControl = FindScreen(path);
			if (screenContentControl != null)
			{
				ActivateStreamReportForm(screenContentControl);
				return;
			}
			_unityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>()).GetEvent<NavigateToEvent>().Publish(new NavigateToEventArgs
			{
				Group = NavigationGroupKeys.SimulationGroup,
				Path = path,
				UseNewTab = false
			});
		}

		private ScreenContentControl FindScreen(string path)
		{
			return _unityContainer.GetActiveMainWindow()?.FindScreen((ScreenContentControl s) => s is IFormedScreenInfo si && string.Equals(si.GetFormKey(), path, StringComparison.CurrentCultureIgnoreCase));
		}

		private void ActivateStreamReportForm(ScreenContentControl screen)
		{
			screen.Activate();
			if (screen is ITabPageScreen tabPageScreen && tabPageScreen.Pages.FirstOrDefault((MMTabPage x) => x is StreamReportForm) is StreamReportForm { ReportControl: not null } streamReportForm && tabPageScreen.ActivatePage(streamReportForm))
			{
				StreamGroupItem streamGroupItem = PopContextStreamGroup();
				if (streamGroupItem != null)
				{
					streamReportForm.ReportControl.GroupName = streamGroupItem.Name;
				}
			}
		}

		public static void PushContextStreamGroup(StreamGroupItem sgi)
		{
			_contextStreamGroupItem = sgi;
		}

		public static StreamGroupItem PopContextStreamGroup()
		{
			StreamGroupItem contextStreamGroupItem = _contextStreamGroupItem;
			_contextStreamGroupItem = null;
			return contextStreamGroupItem;
		}
	}
