	internal static class StreamReportReferencedTemplatesManager
	{
		private const int NodeTypeBlock = 1;

		private const int NodeTypeStream = 2;

		private static readonly List<string> __mainNodePathList = new List<string>();

		public static void RegisterOpenedNode(string mainNodePath)
		{
			if (!string.IsNullOrWhiteSpace(mainNodePath))
			{
				string text = mainNodePath.Trim();
				if (!__mainNodePathList.Contains(text, StringComparer.InvariantCultureIgnoreCase))
				{
					__mainNodePathList.Add(text);
				}
			}
		}

		public static void SaveReferencedTemplates(this IUnityContainer unityContainer)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			try
			{
				List<string> validReferencedPaths = GetValidReferencedPaths(unityContainer);
				StreamReportSettings.Default.ReferencedPaths.Clear();
				foreach (string item in validReferencedPaths)
				{
					StreamReportSettings.Default.ReferencedPaths.Add(item);
				}
				List<string> list = new List<string>();
				foreach (string item2 in validReferencedPaths)
				{
					SSXMLSettings sSXMLSettings = unityContainer.GetSSXMLSettings(item2);
					if (sSXMLSettings != null && !string.IsNullOrWhiteSpace(sSXMLSettings.TemplateName) && !list.Contains(sSXMLSettings.TemplateName, StringComparer.InvariantCultureIgnoreCase))
					{
						list.Add(sSXMLSettings.TemplateName);
					}
				}
				List<ReportTemplateItem> list2 = new List<ReportTemplateItem>();
				foreach (ReportTemplateItem templateItem in unityContainer.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>()).GetTemplateItems())
				{
					if (templateItem.Type == ReportTemplateType.UserDefined && list.Contains(templateItem.Name, StringComparer.InvariantCultureIgnoreCase))
					{
						ReportTemplatesManager.ReloadTemplateSettings(templateItem);
						list2.Add(templateItem);
					}
				}
				StreamReportSettings.Default.ReferencedTemplates.Clear();
				foreach (ReportTemplateItem item3 in list2)
				{
					StreamReportSettings.Default.ReferencedTemplates.Add(item3);
				}
				StreamReportSettings.Default.Save();
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log("SaveReferencedTemplates error: " + ex.Message + "\n" + ex.StackTrace, Category.Exception, Priority.Low);
			}
		}

		private static List<string> GetValidReferencedPaths(IUnityContainer unityContainer)
		{
			List<string> list = new List<string>();
			foreach (string _mainNodePath in __mainNodePathList)
			{
				if (IsPathValid(unityContainer, _mainNodePath))
				{
					list.Add(_mainNodePath);
				}
			}
			List<string> list2 = new List<string>(__mainNodePathList);
			foreach (string referencedPath in StreamReportSettings.Default.ReferencedPaths)
			{
				if (!list2.Contains(referencedPath, StringComparer.InvariantCultureIgnoreCase))
				{
					if (IsPathValid(unityContainer, referencedPath))
					{
						list.Add(referencedPath);
					}
					list2.Add(referencedPath);
				}
			}
			return list;
		}

		private static bool IsPathValid(IUnityContainer unityContainer, string path)
		{
			return ApwnDocumentControl.IsMainNodeExisting(unityContainer, path);
		}

		public static SSXMLSettings GetSSXMLSettings(this IUnityContainer unityContainer, string mainNodePath)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			if (!string.IsNullOrEmpty(mainNodePath))
			{
				string sSXML = unityContainer.GetSSXML(mainNodePath);
				if (!string.IsNullOrEmpty(sSXML))
				{
					try
					{
						XElement xElement = XElement.Parse(sSXML);
						string groupName = (string)xElement.Element("GroupName");
						string templateName = (string)xElement.Element("TemplateName");
						bool? flag = (bool?)xElement.Element("IsTemplateGroupDefaulted");
						bool? flag2 = (bool?)xElement.Element("IsTemplateGlobalDefaulted");
						bool? flag3 = (bool?)xElement.Element("IncludesChildHierarchyStreams");
						string commonShellSettings = (string)xElement.Element("CommonShellSettings");
						return new SSXMLSettings
						{
							GroupName = groupName,
							TemplateName = templateName,
							IsTemplateGroupDefaulted = (flag == true),
							IsTemplateGlobalDefaulted = (flag2 == true),
							IncludesChildHierarchyStreams = (flag3 == true),
							CommonShellSettings = commonShellSettings
						};
					}
					catch (Exception)
					{
					}
				}
			}
			return null;
		}

		public static void SaveSSXMLSettings(this IUnityContainer unityContainer, string mainNodePath, SSXMLSettings settings)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			if (!string.IsNullOrEmpty(mainNodePath) && settings != null)
			{
				XElement xElement = new XElement("tffString");
				xElement.SetElementValue("GroupName", settings.GroupName);
				xElement.SetElementValue("TemplateName", settings.TemplateName);
				xElement.SetElementValue("IsTemplateGroupDefaulted", settings.IsTemplateGroupDefaulted);
				xElement.SetElementValue("IsTemplateGlobalDefaulted", settings.IsTemplateGlobalDefaulted);
				xElement.SetElementValue("IncludesChildHierarchyStreams", settings.IncludesChildHierarchyStreams);
				xElement.SetElementValue("CommonShellSettings", settings.CommonShellSettings);
				unityContainer.SaveSSXML(mainNodePath, xElement.ToString(SaveOptions.DisableFormatting));
			}
		}

		public static int? GetMainNodeType(string mainNodePath)
		{
			if (!string.IsNullOrEmpty(mainNodePath))
			{
				int num = mainNodePath.LastIndexOf('.');
				if (num > 0)
				{
					string text = mainNodePath.Substring(0, num);
					int num2 = text.LastIndexOf('.');
					if (num2 > 0)
					{
						string a = text.Substring(num2 + 1);
						if (string.Equals(a, "blocks", StringComparison.InvariantCultureIgnoreCase))
						{
							return 1;
						}
						if (string.Equals(a, "streams", StringComparison.InvariantCultureIgnoreCase))
						{
							return 2;
						}
					}
					return 0;
				}
			}
			return null;
		}

		private static string GetSSXML(this IUnityContainer unityContainer, string mainNodePath)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			string text = CalculateSSXmlNodePath(mainNodePath);
			if (!string.IsNullOrEmpty(text) && unityContainer != null)
			{
				CxsCase activeCxsCase = unityContainer.GetActiveCxsCase();
				if (activeCxsCase != null)
				{
					object obj = activeCxsCase.BatchGet(text, "value");
					if (obj != null && obj != DBNull.Value)
					{
						return obj as string;
					}
				}
			}
			return null;
		}

		private static void SaveSSXML(this IUnityContainer unityContainer, string mainNodePath, string xml)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			string text = CalculateSSXmlNodePath(mainNodePath);
			if (string.IsNullOrEmpty(text) || unityContainer == null)
			{
				return;
			}
			CxsCase activeCxsCase = unityContainer.GetActiveCxsCase();
			if (activeCxsCase != null)
			{
				int value = MmgSor.MMinqcpt();
				int value2 = MmgSor.MMinqpgc();
				int value3 = MmgSor.MMinqnec();
				try
				{
					activeCxsCase.BatchSet(text, "value", xml);
				}
				catch (Exception ex)
				{
					SystemEnvironment.LogDebug(ex.Message);
				}
				MmgSor.MMsetcpt(value);
				MmgSor.MMsetpgc(value2);
				MmgSor.MMsetnec(value3);
			}
		}

		private static string CalculateSSXmlNodePath(string mainNodePath)
		{
			int? mainNodeType = GetMainNodeType(mainNodePath);
			if (mainNodeType == 1 || mainNodeType == 2)
			{
				return $"{mainNodePath}.Input.SSXML";
			}
			if (mainNodePath.EndsWith(".Results Summary", StringComparison.InvariantCultureIgnoreCase))
			{
				return string.Format("{0}.EO Configuration.EO VarGrid.Input.SSXML", mainNodePath.Substring(0, mainNodePath.LastIndexOf(".Results Summary")));
			}
			return null;
		}
	}
	internal static class StreamReportResultsAvailableResolver
	{
		public static bool IsResultsAvailable(this StreamReportControl src)
		{
			if (src == null)
			{
				throw new ArgumentNullException("src");
			}
			if (string.IsNullOrWhiteSpace(src.MainNodePath))
			{
				return false;
			}
			CxsCase cxsCase = src.UnityContainer?.GetActiveCxsCase();
			if (cxsCase == null)
			{
				return false;
			}
			if (src.MainNodeType == 1)
			{
				return CxsConverter.ValueToBoolean(cxsCase.BatchGet(src.MainNodePath + ".Stream Results.Table", "value")) == true;
			}
			if (src.MainNodeType == 2)
			{
				return CxsConverter.ValueToBoolean(cxsCase.BatchGet(src.MainNodePath + ".Stream Results.Table", "value")) == true;
			}
			string mainNodePath = src.MainNodePath;
			string hierPath = (mainNodePath.EndsWith(".Results Summary") ? mainNodePath.Substring(0, mainNodePath.Length - ".Results Summary".Length) : mainNodePath);
			return HasMaterialResultsInHierarchy(cxsCase, hierPath);
		}

		private static bool HasMaterialResultsInHierarchy(CxsCase cc, string hierPath)
		{
			string[] array = CxsConverter.ValueToStringArray(cc.BatchGet(hierPath + ".Streams", "child_ids"));
			if (array != null && array.Length != 0)
			{
				string[] array2 = array;
				foreach (string text in array2)
				{
					string path = hierPath + ".Streams." + text + ".Stream Results.Table";
					if (CxsConverter.ValueToBoolean(cc.BatchGet(path, "value")) == true)
					{
						return true;
					}
				}
				return false;
			}
			string[] array3 = CxsConverter.ValueToStringArray(cc.BatchGet(hierPath + ".Blocks", "child_ids"));
			if (array3 != null)
			{
				string[] array2 = array3;
				foreach (string text2 in array2)
				{
					string text3 = hierPath + ".Blocks." + text2;
					string text4 = text3 + ".Data";
					if (CxsConverter.ValueToBoolean(cc.BatchGet(text4, "has_children")) == true)
					{
						if (HasMaterialResultsInHierarchy(cc, text4))
						{
							return true;
						}
					}
					else if (CxsConverter.ValueToBoolean(cc.BatchGet(text3 + ".Stream Results.Table", "value")) == true)
					{
						return true;
					}
				}
			}
			return false;
		}
	}
