		private void GetGridControlExportData(ref string[] FieldLabels, ref List<Export2DTemplate.Record> Records)
		{
			if (_src == null || _src.ReportGrid == null || !(_src.ReportGrid.DataSource is StreamReportDataTable { Rows: not null, Columns: not null } streamReportDataTable) || streamReportDataTable.Rows.Count <= 0 || streamReportDataTable.Columns.Count <= 0)
			{
				return;
			}
			List<DataRow> list = streamReportDataTable.Rows.ToList();
			List<DataColumn> list2 = streamReportDataTable.Columns.ToList();
			List<string> list3 = new List<string>();
			bool flag = false;
			Export2DTemplate.Record record = null;
			for (int i = 1; i < list2.Count; i++)
			{
				if (i == list2.Count - 1)
				{
					continue;
				}
				List<string> list4 = new List<string>();
				List<object> list5 = new List<object>();
				for (int j = 0; j < list.Count; j++)
				{
					if (j != list.Count - 1)
					{
						if (!flag)
						{
							list3.Add(list[j][0].ValueAsString);
						}
						IDataCell dataCell = streamReportDataTable.Rows[j][i];
						if (dataCell == null)
						{
							list5.Add(string.Empty);
							list4.Add("cxs:#Empty");
							continue;
						}
						string cxsDataPath = StreamReportSenderHelper.GetCxsDataPath(dataCell.Tag);
						list4.Add("cxs:" + (string.IsNullOrWhiteSpace(cxsDataPath) ? "#Empty" : cxsDataPath));
						object item = ((!(dataCell.Value is double num)) ? dataCell.ValueAsString : (string.IsNullOrEmpty(dataCell.Mask) ? ((object)num) : string.Format("{0:" + dataCell.Mask + "}", num)));
						list5.Add(item);
					}
				}
				flag = true;
				if (list4.Count > 0)
				{
					list5.Insert(0, list2[i].Header);
					list4.Insert(0, "cxs:#Empty");
					Export2DTemplate.Record record2 = new Export2DTemplate.Record
					{
						Name = list2[i].Header,
						Paths = list4.ToArray(),
						Values = list5.ToArray()
					};
					Records.Add(record2);
					if (i == 1)
					{
						record = record2;
					}
				}
				if (i != list2.Count - 2 || record == null)
				{
					continue;
				}
				for (int k = 0; k < list.Count; k++)
				{
					if (k != list.Count - 1)
					{
						string empty = string.Empty;
						string empty2 = string.Empty;
						IDataCell dataCell2 = streamReportDataTable.Rows[k][1];
						if (dataCell2 == null)
						{
							empty2 = string.Empty;
							empty = "cxs:#Empty";
						}
						else
						{
							string cxsDataPath2 = StreamReportSenderHelper.GetCxsDataPath(dataCell2.Tag);
							empty = "cxs:" + (string.IsNullOrWhiteSpace(cxsDataPath2) ? "#Empty" : cxsDataPath2);
							empty2 = dataCell2.ValueAsString;
						}
						record.Paths[k + 1] = empty;
						record.Values[k + 1] = empty2;
					}
				}
			}
			list3.Insert(0, "Stream Name");
			FieldLabels = list3.ToArray();
		}

		private void GenerateTableFrom2DArray(ref string[] FieldLabels, ref List<Export2DTemplate.Record> Records, Tuple<string, string>[,] arrTable)
		{
			if (arrTable == null || arrTable.GetLength(0) <= 0 || arrTable.GetLength(1) <= 0)
			{
				return;
			}
			List<string> list = new List<string>();
			bool flag = false;
			for (int i = 1; i < arrTable.GetLength(1); i++)
			{
				List<string> list2 = new List<string>();
				List<object> list3 = new List<object>();
				for (int j = 1; j < arrTable.GetLength(0); j++)
				{
					if (!flag)
					{
						list.Add(arrTable[j, 0].Item1);
					}
					Tuple<string, string> tuple = arrTable[j, i];
					if (string.IsNullOrEmpty(tuple.Item2))
					{
						list3.Add(tuple.Item1);
						list2.Add("cxs:#Empty");
					}
					else
					{
						string item = tuple.Item2;
						list2.Add("cxs:" + (string.IsNullOrWhiteSpace(item) ? "#Empty" : item));
						list3.Add(tuple.Item1);
					}
				}
				flag = true;
				if (list2.Count > 0)
				{
					list3.Insert(0, arrTable[0, i].Item1);
					list2.Insert(0, "cxs:#Empty");
					Records.Add(new Export2DTemplate.Record
					{
						Name = arrTable[0, i].Item1,
						Paths = list2.ToArray(),
						Values = list3.ToArray()
					});
				}
			}
			list.Insert(0, "Stream Name");
			FieldLabels = list.ToArray();
		}

		public string GetStreamFullPath(string strStreamFullName)
		{
			if (string.IsNullOrEmpty(strStreamFullName))
			{
				return string.Empty;
			}
			string empty = string.Empty;
			if (!strStreamFullName.Contains("."))
			{
				return "Top.appModelV8.Streams." + strStreamFullName;
			}
			empty = strStreamFullName.Substring(0, strStreamFullName.LastIndexOf("."));
			empty = empty.Replace(".", ".Data.Blocks.");
			empty = empty + ".Data.Streams." + strStreamFullName.Substring(strStreamFullName.LastIndexOf(".") + 1);
			if (empty.StartsWith("Data."))
			{
				empty = empty.Substring(5);
			}
			return "Top.appModelV8.Blocks." + empty;
		}

		private Tuple<string, string>[,] ConvertSummaryTableDictionaryTo2DArray(Dictionary<string, List<StreamTableItem>> dicTableX)
		{
			if (dicTableX == null || dicTableX.Count <= 0)
			{
				return null;
			}
			Dictionary<string, List<StreamTableItem>> dictionary = new Dictionary<string, List<StreamTableItem>>();
			foreach (KeyValuePair<string, List<StreamTableItem>> item in dicTableX)
			{
				if (!dictionary.Keys.Contains(item.Key))
				{
					dictionary.Add(item.Key, item.Value);
				}
				StreamTableItem streamTableItem = item.Value.FirstOrDefault();
				int num = 0;
				if (streamTableItem != null)
				{
					List<StreamTableItem> list = dictionary[item.Key];
					List<StreamTableItem> list2 = new List<StreamTableItem>();
					string text = string.Empty;
					foreach (StreamTableItem item2 in list)
					{
						if (text != item2.PropertyName)
						{
							if (double.TryParse(item2.Value, out var result))
							{
								item2.Value = result.ToString(CultureInfo.InvariantCulture);
							}
							text = item2.PropertyName;
							list2.Add(item2);
						}
					}
					dictionary[item.Key] = list2;
					foreach (StreamTableItem item3 in item.Value)
					{
						if (streamTableItem.PropertyName == item3.PropertyName)
						{
							num++;
						}
					}
				}
				for (int i = 1; i < num; i++)
				{
					string key = item.Key + "#" + i;
					dictionary.Add(key, dictionary[item.Key]);
				}
			}
			int num2 = 0;
			int num3 = dictionary.Keys.Count + 1;
			using (Dictionary<string, List<StreamTableItem>>.Enumerator enumerator = dictionary.GetEnumerator())
			{
				if (enumerator.MoveNext())
				{
					num2 = enumerator.Current.Value.Count + 1;
				}
			}
			KeyValuePair<string, List<StreamTableItem>> keyValuePair = default(KeyValuePair<string, List<StreamTableItem>>);
			using (Dictionary<string, List<StreamTableItem>>.Enumerator enumerator = dictionary.GetEnumerator())
			{
				if (enumerator.MoveNext())
				{
					keyValuePair = enumerator.Current;
				}
			}
			Tuple<string, string>[,] array = new Tuple<string, string>[num2, num3];
			for (int j = 0; j < num2; j++)
			{
				if (j == 0)
				{
					array[j, 0] = new Tuple<string, string>(string.Empty, string.Empty);
				}
				else
				{
					array[j, 0] = new Tuple<string, string>(keyValuePair.Value[j - 1].PropertyName + " " + keyValuePair.Value[j - 1].Unit, string.Empty);
				}
			}
			List<string> list3 = new List<string>();
			foreach (KeyValuePair<string, List<StreamTableItem>> item4 in dictionary)
			{
				string text2 = item4.Key;
				if (text2.Contains("#"))
				{
					text2 = text2.Substring(0, text2.IndexOf('#'));
				}
				list3.Add(text2);
			}
			for (int k = 0; k < num3; k++)
			{
				if (k == 0)
				{
					array[0, k] = new Tuple<string, string>(string.Empty, string.Empty);
					continue;
				}
				string strStreamFullName = list3[k - 1];
				array[0, k] = new Tuple<string, string>(list3[k - 1], GetStreamFullPath(strStreamFullName));
			}
			num3 = 1;
			foreach (KeyValuePair<string, List<StreamTableItem>> item5 in dictionary)
			{
				for (int l = 0; l < item5.Value.Count; l++)
				{
					array[l + 1, num3] = new Tuple<string, string>(item5.Value[l].Value, "cxs:" + item5.Value[l].Path);
				}
				num3++;
			}
			return array;
		}
	}
	internal class StreamReportSettings
	{
		public static readonly StreamReportSettings Default = new StreamReportSettings();

		public IList<string> ReferencedPaths { get; private set; }

		public IList<ReportTemplateItem> ReferencedTemplates { get; private set; }

		private StreamReportSettings()
		{
			ReferencedPaths = new List<string>();
			ReferencedTemplates = new List<ReportTemplateItem>();
			Load();
		}

		private void Load()
		{
			ReferencedPaths.Clear();
			ReferencedTemplates.Clear();
			string streamSummaryFormSettings = CaseFileSettings.Default.StreamSummaryFormSettings;
			if (string.IsNullOrWhiteSpace(streamSummaryFormSettings))
			{
				return;
			}
			try
			{
				XElement xElement = XElement.Parse(streamSummaryFormSettings);
				if (xElement == null)
				{
					return;
				}
				XElement xElement2 = xElement.Element("ReferencedPaths");
				if (xElement2 != null)
				{
					foreach (XElement item in xElement2.Elements("Path"))
					{
						string value = item.Value;
						if (value != null)
						{
							ReferencedPaths.Add(value);
						}
					}
				}
				XElement xElement3 = xElement.Element("ReferencedTemplates");
				if (xElement3 == null)
				{
					return;
				}
				foreach (XElement item2 in xElement3.Elements("Template"))
				{
					ReportTemplateItem reportTemplateItem = ReportTemplateItem.Parse(item2.Value);
					if (reportTemplateItem != null)
					{
						reportTemplateItem.TagAsInMemory();
						ReferencedTemplates.Add(reportTemplateItem);
					}
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.LogDebug(ex.Message);
			}
		}

		public void Save()
		{
			XElement xElement = new XElement("ReferencedPaths");
			foreach (string referencedPath in ReferencedPaths)
			{
				if (!string.IsNullOrWhiteSpace(referencedPath))
				{
					xElement.Add(new XElement("Path", referencedPath.Trim()));
				}
			}
			XElement xElement2 = new XElement("ReferencedTemplates");
			foreach (ReportTemplateItem referencedTemplate in ReferencedTemplates)
			{
				xElement2.Add(new XElement("Template", referencedTemplate.Save()));
			}
			XElement xElement3 = new XElement("src");
			xElement3.Add(xElement);
			xElement3.Add(xElement2);
			CaseFileSettings.Default.StreamSummaryFormSettings = xElement3.ToString(SaveOptions.DisableFormatting);
		}
	}
}
