	public enum FormatOption
	{
		Exponent,
		Fixed,
		General
	}
	public class FormatSpecification : DependencyObject
	{
		public static readonly DependencyProperty PrecisionProperty = DependencyProperty.Register("Precision", typeof(int), typeof(FormatSpecification));

		public static readonly DependencyProperty FormatOptionProperty = DependencyProperty.Register("FormatOption", typeof(FormatOption), typeof(FormatSpecification), new UIPropertyMetadata(FormatOption.Fixed));

		public int Precision
		{
			get
			{
				return (int)GetValue(PrecisionProperty);
			}
			set
			{
				SetValue(PrecisionProperty, value);
			}
		}

		public FormatOption FormatOption
		{
			get
			{
				return (FormatOption)GetValue(FormatOptionProperty);
			}
			set
			{
				SetValue(FormatOptionProperty, value);
			}
		}

		public string ShortTermText
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder("%.");
				stringBuilder.Append(Precision);
				switch (FormatOption)
				{
				case FormatOption.Exponent:
					stringBuilder.Append('e');
					break;
				case FormatOption.Fixed:
					stringBuilder.Append('f');
					break;
				case FormatOption.General:
					stringBuilder.Append('g');
					break;
				}
				return stringBuilder.ToString();
			}
		}

		public FormatSpecification()
		{
		}

		public FormatSpecification(FormatOption formatOption, int precision)
		{
			FormatOption = formatOption;
			Precision = precision;
		}

		public override string ToString()
		{
			if (FormatOption == FormatOption.Fixed)
			{
				return $"f{Precision}";
			}
			if (FormatOption == FormatOption.Exponent)
			{
				return $"e{Precision}";
			}
			return $"g{Precision}";
		}

		public static FormatSpecification Parse(string text)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				FormatSpecification formatSpecification = new FormatSpecification();
				string text2 = text.Trim().ToLower();
				switch (text2.FirstOrDefault())
				{
				case 'e':
					formatSpecification.FormatOption = FormatOption.Exponent;
					break;
				case 'g':
					formatSpecification.FormatOption = FormatOption.General;
					break;
				default:
					formatSpecification.FormatOption = FormatOption.Fixed;
					break;
				}
				if (text2.Length > 1)
				{
					string s = text2.Substring(1);
					int result = 0;
					if (int.TryParse(s, out result))
					{
						formatSpecification.Precision = result;
					}
				}
				return formatSpecification;
			}
			return null;
		}

		public static FormatSpecification ParseShortTermText(string shortTermText)
		{
			FormatSpecification formatSpecification = new FormatSpecification
			{
				Precision = 2
			};
			if (!string.IsNullOrWhiteSpace(shortTermText))
			{
				string text = shortTermText.ToLower().Trim();
				if (text.StartsWith("%"))
				{
					int num = text.IndexOf('.');
					if (num >= 0 && text.Length > num + 1)
					{
						string text2 = text.Substring(num + 1).Trim();
						if (!string.IsNullOrEmpty(text2))
						{
							string s = text2.Substring(0, text2.Length - 1);
							int result = 0;
							if (int.TryParse(s, out result))
							{
								formatSpecification.Precision = result;
								switch (text2.Last())
								{
								case 'e':
									formatSpecification.FormatOption = FormatOption.Exponent;
									break;
								case 'f':
									formatSpecification.FormatOption = FormatOption.Fixed;
									break;
								default:
									formatSpecification.FormatOption = FormatOption.General;
									break;
								}
							}
						}
					}
				}
			}
			return formatSpecification;
		}
	}
	public class TemplatePropertyItemToForegroundConverter : IValueConverter
	{
		public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
		{
			if (value is TemplatePropertyItem templatePropertyItem)
			{
				if (templatePropertyItem.StreamProperty.PropertyType != StreamPropertyType.PhysicalProperty)
				{
					return Brushes.Blue;
				}
				if (!templatePropertyItem.StreamProperty.IsValid)
				{
					return Brushes.Red;
				}
			}
			return DependencyProperty.UnsetValue;
		}

		public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
	public class PropertiesFilterConverter : IMultiValueConverter
	{
		public object Convert(object[] values, Type targetType, object parameter, CultureInfo culture)
		{
			if (values != null && values.Length == 3)
			{
				if (values[2] as bool? == true)
				{
					return values[1];
				}
				return values[0];
			}
			return null;
		}

		public object[] ConvertBack(object value, Type[] targetTypes, object parameter, CultureInfo culture)
		{
			throw new NotImplementedException();
		}
	}
