		protected virtual void OnCurrentPropertyItemChanged(TemplatePropertyItem oldValue, TemplatePropertyItem newValue)
		{
			gridQualifiers.IsEnabled = newValue != null;
			if (newValue == null)
			{
				comboBoxComponents.ReInitialize(null, null, suppressEvent: true);
				comboBoxSubstreams.ReInitialize(null, null, suppressEvent: true);
				comboBoxPhases.ReInitialize(null, null, suppressEvent: true);
				comboBoxWaterBasis.ReInitialize(null, null, suppressEvent: true);
				comboBoxBaseComponents.ReInitialize(null, null, suppressEvent: true);
				comboBoxSecondLiquidKeyComponents.ReInitialize(null, null, suppressEvent: true);
				comboBoxTemperature.SelectedItem = _defaultTemperatureUnits;
				comboBoxPressure.SelectedItem = _defaultPressureUnits;
				listBoxTemperature.ClearItems(suppressEvent: true);
				listBoxPressure.ClearItems(suppressEvent: true);
				comboBoxTemperature.IsEnabled = false;
				comboBoxPressure.IsEnabled = false;
				listBoxTemperature.IsEnabled = false;
				listBoxPressure.IsEnabled = false;
			}
			else
			{
				UpdateComponents(newValue);
				UpdateSubstreams(newValue);
				UpdatePhases(newValue);
				UpdateBasis(newValue);
				UpdateBaseComponents(newValue);
				UpdateSecondLiquidKeyComponents(newValue);
				UpdateTemperature(newValue);
				UpdatePressure(newValue);
			}
		}

		private void SuppressEvents(bool suppressed)
		{
			_suppressEvents = suppressed;
			comboBoxComponents.SuppressSelectionChanged = suppressed;
			comboBoxSubstreams.SuppressSelectionChanged = suppressed;
			comboBoxPhases.SuppressSelectionChanged = suppressed;
			comboBoxWaterBasis.SuppressSelectionChanged = suppressed;
			comboBoxBaseComponents.SuppressSelectionChanged = suppressed;
			comboBoxSecondLiquidKeyComponents.SuppressSelectionChanged = suppressed;
			listBoxTemperature.SuppressEvent = suppressed;
			listBoxPressure.SuppressEvent = suppressed;
		}

		private void UpdateComponents(TemplatePropertyItem tpi)
		{
			List<string> list = tpi.StreamProperty.AllowedComponents.ToList();
			if (list != null && list.Count > 0)
			{
				comboBoxComponents.IsEnabled = true;
				comboBoxComponents.EmptyText = GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultComponents;
				comboBoxComponents.ReInitialize(list, CurrentPropertyItem["Comps"], suppressEvent: true);
				if (comboBoxComponents.SelectedItems.Count > 0)
				{
					CurrentPropertyItem["Comp-Group"] = null;
					CurrentPropertyItem["TB-Lower"] = null;
					CurrentPropertyItem["TB-Upper"] = null;
				}
				else if (CheckOtherComponentOptions())
				{
					UpdateComboBox(comboBoxComponents, clearSelection: true, isEnabled: false, GridFormsResources.StreamSummaryTemplate_CalculationOptions_NotAllowed);
				}
				UpdatePropertyAttribute(comboBoxComponents, "Comps");
			}
			else
			{
				UpdateComboBox(comboBoxComponents, clearSelection: true, isEnabled: false, GridFormsResources.StreamSummaryTemplate_CalculationOptions_NotAllowed);
			}
		}

