		private void UpdateTemperature(TemplatePropertyItem tpi)
		{
			if (tpi.StreamProperty.IsTemperatureAllowed)
			{
				comboBoxTemperature.IsEnabled = true;
				listBoxTemperature.IsEnabled = true;
				SettingItem metadata = CurrentPropertyItem.GetMetadata("Temp");
				if (metadata != null)
				{
					listBoxTemperature.ReInitialize(metadata.Value, suppressEvent: true);
					if (comboBoxTemperature.Items.Contains(metadata.Unit))
					{
						comboBoxTemperature.SelectedItem = metadata.Unit;
					}
				}
				else
				{
					comboBoxTemperature.SelectedItem = _defaultTemperatureUnits;
					listBoxTemperature.ReInitialize(null, suppressEvent: true);
				}
			}
			else
			{
				comboBoxTemperature.IsEnabled = false;
				comboBoxTemperature.SelectedIndex = -1;
				listBoxTemperature.IsEnabled = false;
				listBoxTemperature.ClearItems(suppressEvent: true);
			}
		}

		private void UpdatePressure(TemplatePropertyItem tpi)
		{
			if (tpi.StreamProperty.IsPressureAllowed)
			{
				comboBoxPressure.IsEnabled = true;
				listBoxPressure.IsEnabled = true;
				SettingItem metadata = CurrentPropertyItem.GetMetadata("Pres");
				if (metadata != null)
