					}
				}
				else
				{
					comboBoxPressure.SelectedItem = _defaultPressureUnits;
					listBoxPressure.ReInitialize(null, suppressEvent: true);
				}
			}
			else
			{
				comboBoxPressure.IsEnabled = false;
				comboBoxPressure.SelectedIndex = -1;
				listBoxPressure.IsEnabled = false;
				listBoxPressure.ClearItems(suppressEvent: true);
			}
		}

		private void UpdateSecondLiquidKeyComponents(TemplatePropertyItem tpi)
		{
			IEnumerable<string> source = comboBoxPhases.SelectedItems.Cast<string>();
			bool flag = !string.IsNullOrEmpty(source.FirstOrDefault((string x) => string.Equals(x, "Liquid1", StringComparison.OrdinalIgnoreCase)));
			if (!flag)
			{
				flag = !string.IsNullOrEmpty(source.FirstOrDefault((string x) => string.Equals(x, "Liquid2", StringComparison.OrdinalIgnoreCase)));
			}
			if (flag)
			{
				List<string> list = tpi.StreamProperty.AllowedComponents.ToList();
				if (list.Count > 0)
				{
					comboBoxSecondLiquidKeyComponents.IsEnabled = true;
					comboBoxSecondLiquidKeyComponents.ReInitialize(list, CurrentPropertyItem["L2-Comps"], suppressEvent: true);
					if (comboBoxSecondLiquidKeyComponents.SelectedItems.Count == 0)
					{
						comboBoxSecondLiquidKeyComponents.EmptyText = null;
						if (list.Count == 1)
						{
							comboBoxSecondLiquidKeyComponents.SelectedItems.Add(list[0]);
							comboBoxSecondLiquidKeyComponents.IsEnabled = false;
						}
					}
					return;
				}
			}
			UpdateComboBox(comboBoxSecondLiquidKeyComponents, clearSelection: true, isEnabled: false, GridFormsResources.StreamSummaryTemplate_CalculationOptions_NotAllowed);
		}

		private static void UpdateComboBox(CheckableComboBox comboBox, bool clearSelection, bool isEnabled, string emptyText)
		{
			comboBox.IsEnabled = isEnabled;
			comboBox.EmptyText = emptyText;
			if (clearSelection)
			{
				comboBox.SelectedItems.Clear();
			}
		}

		public void Initialize(TemplateEditor parentEditor)
		{
			if (parentEditor == null)
			{
				throw new ArgumentNullException("parentEditor");
			}
			comboBoxComponents.EmptyText = GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultComponents;
			comboBoxSubstreams.EmptyText = GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultSubstreams;
			comboBoxPhases.EmptyText = GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultPhases;
			comboBoxWaterBasis.EmptyText = GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultBasis;
			IAdbUnitsProvider adbUnitsProvider = parentEditor.UnityContainer.GetAdbUnitsProvider();
			comboBoxTemperature.ItemsSource = adbUnitsProvider.GetTemperatureUnitsList();
			comboBoxTemperature.SelectedItem = (_defaultTemperatureUnits = adbUnitsProvider.GetTemperatureDefaultDisplayUnit());
			comboBoxPressure.ItemsSource = adbUnitsProvider.GetPressureUnitsList();
			comboBoxPressure.SelectedItem = (_defaultPressureUnits = adbUnitsProvider.GetPressureDefaultDisplayUnit());
			comboBoxTemperature.IsEnabled = false;
			comboBoxPressure.IsEnabled = false;
			listBoxTemperature.IsEnabled = false;
			listBoxPressure.IsEnabled = false;
			gridQualifiers.IsEnabled = false;
		}

		private void UpdatePropertyAttribute(object senderComboBox, string columnName)
		{
			if (CurrentPropertyItem != null && senderComboBox is CheckableComboBox checkableComboBox)
			{
				if (checkableComboBox.SelectedItems.Count > 0)
				{
					CurrentPropertyItem[columnName] = checkableComboBox.Text;
				}
				else
				{
					CurrentPropertyItem[columnName] = null;
				}
			}
		}

		private void UpdatePropertyAttribute(ComboBox unitsComboBox, EditableListBox valueListBox, string columnName)
		{
			if (CurrentPropertyItem != null && unitsComboBox.SelectedIndex >= 0)
			{
				CurrentPropertyItem.SetMetadata(columnName, valueListBox.ItemsAsString, unitsComboBox.SelectedItem.ToString());
			}
		}

		private bool CheckOtherComponentOptions()
		{
			if (CurrentPropertyItem != null)
			{
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["Comp-Group"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["TB-Lower"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["TB-Upper"]))
				{
					return true;
				}
			}
			return false;
		}

