		{
			if (CurrentPropertyItem != null)
			{
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["Base-Comp-Group"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["Base-TB-Lower"]))
				{
					return true;
				}
				if (!string.IsNullOrWhiteSpace(CurrentPropertyItem["Base-TB-Upper"]))
				{
					return true;
				}
			}
			return false;
		}

		private void MoreCommand_Executed()
		{
			bool? flag = new MoreQualifiersDialog(CurrentPropertyItem, comboBoxComponents.SelectedItems.Count > 0, comboBoxBaseComponents.SelectedItems.Count > 0)
			{
				Owner = Window.GetWindow(this)
			}.ShowDialog();
			if (!flag.HasValue || !flag.Value)
			{
				return;
			}
			List<string> list = CurrentPropertyItem.StreamProperty.AllowedComponents.ToList();
			if (list != null && list.Count > 0)
			{
				if (CheckOtherComponentOptions())
				{
					UpdateComboBox(comboBoxComponents, clearSelection: true, isEnabled: false, GridFormsResources.StreamSummaryTemplate_CalculationOptions_NotAllowed);
				}
				else
				{
					UpdateComboBox(comboBoxComponents, clearSelection: false, isEnabled: true, GridFormsResources.StreamSummaryTemplate_CalculationOptions_DefaultComponents);
				}
			}
			if (CurrentPropertyItem.StreamProperty.AllowedBaseComponents.ToList().Count > 0)
			{
				comboBoxBaseComponents.IsEnabled = !CheckOtherBaseComponentOptions();
			}
		}

		private bool MoreCommand_CanExecute()
		{
			return CurrentPropertyItem != null;
		}

		private void comboBoxComponents_SelectionChanged(object sender, RoutedEventArgs e)
		{
			UpdatePropertyAttribute(sender, "Comps");
		}

		private void comboBoxSubstreams_SelectionChanged(object sender, RoutedEventArgs e)
		{
			UpdatePropertyAttribute(sender, "Substream");
			int num = 0;
			foreach (string selectedItem in comboBoxSubstreams.SelectedItems)
			{
				if (string.Equals(selectedItem, "NC", StringComparison.CurrentCultureIgnoreCase) || string.Equals(selectedItem, "CISOLID", StringComparison.CurrentCultureIgnoreCase))
				{
					num++;
				}
			}
			if (num > 0 && num == comboBoxSubstreams.SelectedItems.Count)
			{
				comboBoxPhases.SelectedItems.Clear();
				comboBoxPhases.SelectedItems.Add("Solid");
				comboBoxPhases.IsEnabled = false;
			}
			else
			{
				comboBoxPhases.IsEnabled = true;
			}
		}

