		private void listBoxProperties_PreviewMouseMove(object sender, MouseEventArgs e)
		{
			if (!CanDragMove() || !_dragStarted)
			{
				return;
			}
			if (e.LeftButton == MouseButtonState.Pressed)
			{
				ListBoxItem ancestor = (e.OriginalSource as DependencyObject).GetAncestor<ListBoxItem>(listBoxProperties);
				if (ancestor != null)
				{
					int num = Properties.IndexOf(ancestor.Content as TemplatePropertyItem);
					if (num != _draggingIndex)
					{
						Properties.Move(_draggingIndex, num);
						_draggingIndex = num;
						listBoxProperties.SelectedIndex = num;
					}
				}
			}
			else
