		private void AddPropertyCommand_Executed()
		{
			FindPropertiesDialog findPropertiesDialog = new FindPropertiesDialog
			{
				Owner = Window.GetWindow(this)
			};
			bool? flag = findPropertiesDialog.ShowDialog();
			if (!flag.HasValue || !flag.Value)
			{
				return;
			}
			List<TemplatePropertyItem> list = new List<TemplatePropertyItem>();
			foreach (StreamPropertyData selectedProperty in findPropertiesDialog.SelectedProperties)
			{
				TemplatePropertyItem templatePropertyItem = new TemplatePropertyItem(new PhysicalProperty(selectedProperty.EngineName, selectedProperty.UserPropertySetName));
				if (!string.IsNullOrWhiteSpace(selectedProperty.UserPropertySetName))
				{
					templatePropertyItem.DisplayName = "(" + selectedProperty.UserPropertySetName + ") " + selectedProperty.DisplayName;
					InitializePropertySetProperty(templatePropertyItem, selectedProperty.EngineName, selectedProperty.UserPropertySetName);
				}
				Properties.Add(templatePropertyItem);
				list.Add(templatePropertyItem);
			}
			InitailizeOptions(list);
			EnsureBatchPropertiesUpdated(list);
		}

		private void InitializePropertySetProperty(TemplatePropertyItem tpi, string engineName, string userPropertySetName)
		{
			IDictionary<string, string> defaultQualifiers = WrapperProxy.GetDefaultQualifiers(engineName, userPropertySetName);
			if (defaultQualifiers == null)
			{
				return;
			}
			IAdbUnitsProvider adbUnitsProvider = _parentEditor.UnityContainer.Resolve<IAdbUnitsProvider>(Array.Empty<ResolverOverride>());
			foreach (KeyValuePair<string, string> item in defaultQualifiers)
			{
				if (string.Equals(item.Key, "Temp", StringComparison.InvariantCultureIgnoreCase))
				{
					tpi.SetMetadata("Temp", item.Value, adbUnitsProvider.GetTemperatureDefaultDisplayUnit());
				}
				else if (string.Equals(item.Key, "Pres", StringComparison.InvariantCultureIgnoreCase))
				{
					tpi.SetMetadata("Pres", item.Value, adbUnitsProvider.GetPressureDefaultDisplayUnit());
				}
				else
				{
					tpi.SetMetadata(item.Key, item.Value);
				}
			}
		}

