		public ManageCssTemplatesWindow(IUnityContainer unityContainer)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			_unityContainer = unityContainer;
			InitializeComponent();
			UpdateCssTemplates();
		}

		private void UpdateCssTemplates()
		{
			IEnumerable<CssReportTemplateItem> templates = TemplatesManager.GetCssTemplateItems();
			List<CssReportTemplateItem> list = templates.Where((CssReportTemplateItem x) => !CssTemplates.Any((ReportTemplateItem y) => string.Equals(x.Name, y.Name, StringComparison.CurrentCultureIgnoreCase))).ToList();
			foreach (ReportTemplateItem item in CssTemplates.Where((ReportTemplateItem x) => !templates.Any((CssReportTemplateItem y) => string.Equals(x.Name, y.Name, StringComparison.CurrentCultureIgnoreCase))).ToList())
			{
				CssTemplates.Remove(item);
			}
			foreach (CssReportTemplateItem item2 in list)
			{
				CssTemplates.Add(item2);
			}
		}

		private void ViewCommand_Executed()
		{
			CssReportTemplateItem cssReportTemplateItem = SelectedTemplates.FirstOrDefault();
			if (cssReportTemplateItem != null)
			{
				TemplatesManager.OpenTemplateEditor(cssReportTemplateItem, saveChanges: false, TemplateEditorTabMode.GeneralOptions, null, includeCssTemplates: true, null, isReadOnly: true);
			}
		}

		private bool ViewCommand_CanExecute()
		{
			return HasOnlyOneSelected();
		}

		private void SaveAsCommand_Executed()
		{
			CssReportTemplateItem cssReportTemplateItem = SelectedTemplates.FirstOrDefault();
			if (cssReportTemplateItem != null)
			{
				TemplatesManager.CreateTemplate(cssReportTemplateItem);
				DidSaveAs = true;
			}
		}

		private bool SaveAsCommand_CanExecute()
		{
			return HasOnlyOneSelected();
		}

		private void DeleteCommand_Executed()
		{
			if (MessageBox.Show(this, GridFormsResources.ManageCssTemplatesWindow_DeleteTemplateDialog_Question, GridFormsResources.ManageCssTemplatesWindow_DeleteTemplateDialog_Title, MessageBoxButton.YesNo) != MessageBoxResult.Yes)
			{
				return;
			}
			try
			{
				foreach (CssReportTemplateItem selectedTemplate in SelectedTemplates)
				{
					WrapperProxy.DeleteCssTemplate(selectedTemplate.CssHeaderInfo);
				}
			}
			catch (Exception ex)
			{
				MessageBox.Show("Error occured when delete templates: " + ex.Message);
			}
			finally
			{
				UpdateCssTemplates();
			}
			DidDelete = true;
		}

		private bool DeleteCommand_CanExecute()
		{
			return SelectedTemplates.Any();
		}

		private void ExitCommand_Executed()
		{
			Close();
		}

		private bool ExitCommand_CanExecute()
		{
			return true;
		}

		private bool HasOnlyOneSelected()
		{
			int num = -1;
			foreach (CssReportTemplateItem selectedTemplate in SelectedTemplates)
			{
				_ = selectedTemplate;
				num++;
				if (num > 0)
				{
					return false;
				}
			}
			return num == 0;
		}

