		public TemplateEditor(IUnityContainer unityContainer, ReportTemplateItem editingTemplate, bool includeCssTemplates = false, IHNode contextNode = null)
		{
			if (unityContainer == null)
			{
				throw new ArgumentNullException("unityContainer");
			}
			if (editingTemplate == null)
			{
				throw new ArgumentNullException("editingTemplate");
			}
			UnityContainer = unityContainer;
			_editingTemplate = editingTemplate;
			_contextNode = contextNode;
			InitializeComponent();
			ReportTemplates = UnityContainer.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>()).GetTemplateItems(includeCssTemplates, contextNode);
			foreach (ReportTemplateItem reportTemplate in ReportTemplates)
			{
				reportTemplate.SuppressEvents = true;
			}
			SelectedReportTemplate = ReportTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, editingTemplate.Name, StringComparison.InvariantCultureIgnoreCase));
		}

