		{
			ResultContext.Reset();
			generalOptionsEditor.Initialize(this);
			selectPropertiesEditor.Initialize(this);
			displayOptionsEditor.Initialize(this);
			calculationOptionsEditor.Initialize(this);
			base.OnInitialized(e);
		}

