		private void ApplyCommand_Executed()
		{
			UnityContainer.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>()).SaveTemplate(SelectedReportTemplate);
			if (string.Equals(SelectedReportTemplate.Name, _editingTemplate.Name, StringComparison.InvariantCultureIgnoreCase))
			{
				_editingTemplateApplied = true;
			}
		}

		private bool ApplyCommand_CanExecute()
		{
			if (SelectedReportTemplate != null && SelectedReportTemplate.Type == ReportTemplateType.UserDefined)
			{
				return SelectedReportTemplate.IsDirty(UnityContainer);
			}
			return false;
		}

		private void ExportCommand_Executed()
		{
			UnityContainer.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>()).ExportTemplate(SelectedReportTemplate);
		}

		private bool ExportCommand_CanExecute()
		{
			if (SelectedReportTemplate != null)
			{
				return SelectedReportTemplate.Type == ReportTemplateType.UserDefined;
			}
			return false;
		}

		private void ImportCommand_Executed()
		{
			ReportTemplatesManager reportTemplatesManager = UnityContainer.Resolve<ReportTemplatesManager>(Array.Empty<ResolverOverride>());
			reportTemplatesManager.ImportTemplates();
			UpdateTemplates(reportTemplatesManager);
		}

		private bool ImportCommand_CanExecute()
		{
			return true;
		}

		private void UpdateTemplates(ReportTemplatesManager mgr)
		{
			ReportTemplateItem lastSelected = SelectedReportTemplate;
			ReportTemplates = mgr.GetTemplateItems(_contextNode != null, _contextNode);
			if (lastSelected != null)
			{
				ReportTemplateItem reportTemplateItem = ReportTemplates.FirstOrDefault((ReportTemplateItem x) => string.Equals(x.Name, lastSelected.Name, StringComparison.CurrentCultureIgnoreCase));
				if (reportTemplateItem != null)
				{
					reportTemplateItem.Settings.Parse(lastSelected.Settings.Save());
					SelectedReportTemplate = reportTemplateItem;
					return;
				}
			}
			SelectedReportTemplate = ReportTemplates.FirstOrDefault();
		}

