		private void UpdateCssTemplatesButton()
		{
			if (WrapperProxy.HasCssTemplates())
			{
				cmdExport.CornerRadius = default(CornerRadius);
				cmdCssTemplates.Visibility = Visibility.Visible;
			}
			else
			{
				cmdExport.CornerRadius = new CornerRadius(0.0, 7.0, 7.0, 0.0);
				cmdCssTemplates.Visibility = Visibility.Collapsed;
			}
		}

		private void RefreshTemplatesGrid()
		{
			IEnumerable<ReportTemplateItem> templateItems = _templatesManager.GetTemplateItems();
			List<DataRow> list = new List<DataRow>();
			foreach (ReportTemplateItem item in templateItems)
			{
				DataRow dataRow = new DataRow(gridTemplates.DataSource)
				{
					Tag = item
				};
				dataRow[0] = new DataCellText(item.LocalizedName)
				{
					IsReadOnly = (item.Type == ReportTemplateType.Installed)
				};
				dataRow[1] = new DataCellText(item.Description)
				{
					IsReadOnly = (item.Type == ReportTemplateType.Installed)
				};
				dataRow[2] = new DataCellText((item.Type == ReportTemplateType.UserDefined) ? GridFormsResources.ManageStreamTemplate_Type_User : GridFormsResources.ManageStreamTemplate_Type_Installed);
				if (item.Type == ReportTemplateType.UserDefined)
				{
					DataTemplate dataTemplate = new DataTemplate();
					FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(MMDeleteButton));
					frameworkElementFactory.SetValue(Control.BackgroundProperty, Brushes.Transparent);
					frameworkElementFactory.SetValue(Control.BorderBrushProperty, Brushes.Transparent);
					frameworkElementFactory.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch);
					frameworkElementFactory.SetValue(ButtonBase.CommandProperty, cmdDelete_Command);
					frameworkElementFactory.SetValue(ButtonBase.CommandParameterProperty, item);
					dataTemplate.VisualTree = frameworkElementFactory;
					dataRow[3] = new DataCellText
					{
						Template = dataTemplate
					};
					dataRow[0].Foreground = Brushes.Blue;
					dataRow[1].Foreground = Brushes.Blue;
				}
				list.Add(dataRow);
			}
			gridTemplates.DataSource.UpdateRows(list);
		}

		private void gridTemplates_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
		}

		private void gridTemplates_SelectionChanged(object sender, RoutedEventArgs e)
		{
			(cmdEdit_Command as DelegateCommand<object>).RaiseCanExecuteChanged();
			(cmdDuplicate_Command as DelegateCommand<object>).RaiseCanExecuteChanged();
			(cmdExport_Command as DelegateCommand<object>).RaiseCanExecuteChanged();
		}

		private void gridTemplates_CellValueChanged(object sender, CellValueChangedEventArgs e)
		{
			ReportTemplateItem reportTemplateItem = e.Data.Row.Tag as ReportTemplateItem;
			switch (e.Data.Row.DataTable.Columns.IndexOf(e.Data.Column))
			{
			case 0:
			{
				string text2 = e.NewValue as string;
				string oldName = e.OldValue as string;
				if (!string.IsNullOrEmpty(text2))
				{
					if (text2.Length > 16)
					{
						MMMessageBox.Show(GridFormsResources.StreamTemplate_NameLengthLimit, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
					}
					else
					{
						_templatesManager.RenameTemplate(oldName, text2);
					}
				}
				break;
			}
			case 1:
			{
				string text = e.NewValue as string;
				if (text != null && text.Length > 64)
				{
					MMMessageBox.Show(GridFormsResources.StreamTemplate_DescLengthLimit, GridFormsResources.StreamTemplate_ManageTemplates, MMMessageBoxButton.OK, MMMessageBoxImage.Error);
				}
				else
				{
					reportTemplateItem.Description = text;
				}
				ReportTemplatesManager.ReloadTemplateSettings(reportTemplateItem);
				_templatesManager.SaveTemplate(reportTemplateItem);
				break;
			}
			}
			RefreshTemplatesGrid();
		}

		private void cmdNew_CommandExecuted(object obj)
		{
			string description = null;
			string templateName = NewTemplateDialog.OpenNewTemplateDialog(base.UnityContainer, out description);
			if (!string.IsNullOrEmpty(templateName))
			{
				_templatesManager.CrateNewTemplate(templateName, description);
				RefreshTemplatesGrid();
				ReportTemplateItem reportTemplateItem = _templatesManager.GetTemplateItems().FirstOrDefault((ReportTemplateItem p) => p.Name.Equals(templateName, StringComparison.InvariantCultureIgnoreCase));
				if (reportTemplateItem != null)
				{
					_templatesManager.OpenTemplateEditor(reportTemplateItem, saveChanges: true);
				}
			}
		}

