					BatchStreamInfo item = AvailableStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, newHeader, StringComparison.CurrentCulture));
					list.Add(item);
					UpdateStreamsInfo(list, AvailableStreams);
					UpdateRows();
					base.GridControl.RefreshData();
				}
				else if (brdtDataColumn.ColumnType == BrdtColumnType.Stream)
				{
					brdtDataColumn.Stream = AvailableStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, newHeader, StringComparison.CurrentCulture));
					SelectedStreams = (from BrdtDataColumn x in base.Columns
						where x.ColumnType == BrdtColumnType.Stream
						select x.Stream).ToList();
					RefreshData();
				}
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(base.GridControl), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
			finally
			{
				_updatingColumnsFlag--;
			}
		}

		public void DeleteColumns(IEnumerable<DataColumn> columns)
		{
			if (columns == null)
			{
				throw new ArgumentNullException("colulmns");
			}
			try
			{
				List<DataColumn> list = columns.Where((DataColumn x) => ((BrdtDataColumn)x).ColumnType == BrdtColumnType.Stream).ToList();
				if (list.Count > 0)
				{
					List<DataColumn> list2 = base.Columns.Except(list).ToList();
					IEnumerable<BatchStreamInfo> source = from BrdtDataColumn x in list2
						where x.ColumnType == BrdtColumnType.Stream
						select x.Stream;
					SelectedStreams = source.ToList();
					base.Columns = new ReadOnlyCollection<DataColumn>(list2);
					UpdateRows();
					base.GridControl.RefreshData();
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message + "\n" + ex.StackTrace, Category.Exception, Priority.High);
			}
		}

		public static BatchResultDataTable Create(IEnumerable<BatchStreamInfo> selectedStreams, IEnumerable<BatchStreamInfo> availableStreams, MaterialFormSharedSettingsForBatch scopeSettings)
		{
			if (selectedStreams == null)
			{
				throw new ArgumentNullException("selectedStreams");
			}
			if (availableStreams == null)
			{
				throw new ArgumentNullException("availableStreams");
			}
			if (scopeSettings == null)
			{
				throw new ArgumentNullException("scopeSettings");
			}
			IEnumerable<BrdtDataColumn> columns = CreateColumns(selectedStreams, availableStreams);
			return new BatchResultDataTable(selectedStreams, availableStreams, columns, scopeSettings);
		}

		private static IEnumerable<BrdtDataColumn> CreateColumns(IEnumerable<BatchStreamInfo> selectedStreams, IEnumerable<BatchStreamInfo> availableStreams)
		{
			List<BrdtDataColumn> list = new List<BrdtDataColumn>();
			if (availableStreams.Any())
			{
				List<string> headerItems = availableStreams.Select((BatchStreamInfo x) => x.DisplayName).ToList();
				list.Add(new BrdtDataColumn(BrdtColumnType.PropertyName)
				{
					IsReadOnly = true,
					IsFrozen = true,
					Width = 260.0
				});
				list.Add(new BrdtDataColumn(BrdtColumnType.Units)
				{
					IsFrozen = true,
					Width = 120.0,
					Header = BatchProcessResources.BatchStreamReport_ColumnHeader_Units
				});
				foreach (BatchStreamInfo selectedStream in selectedStreams)
				{
					list.Add(new BrdtDataColumn(BrdtColumnType.Stream, selectedStream)
					{
						Header = selectedStream.DisplayName,
						HeaderItems = headerItems,
						IsReadOnly = true,
						Width = 100.0
					});
				}
				list.Add(new BrdtDataColumn(BrdtColumnType.Blank)
				{
					HeaderItems = headerItems,
					IsReadOnly = true,
					Width = 100.0
				});
			}
			return list;
		}
	}
