	public class BrdtDataRow : DataRow
	{
		private string _stackedUnit;

		public BrdtRecordType RecordType { get; }

		public string Substream { get; }

		public string Component { get; }

		public string NumberFormat { get; set; }

		public string Key => $"RecordType={RecordType},Substream={Substream},Component={Component}";

		public int UnitRow => RecordType switch
		{
			BrdtRecordType.TotalMass => 18, 
			BrdtRecordType.ComponentMass => 18, 
			BrdtRecordType.TotalMole => 51, 
			BrdtRecordType.ComponentMole => 51, 
			BrdtRecordType.TotalEnergy => 53, 
			BrdtRecordType.TotalVolumn => 27, 
			_ => 0, 
		};

		public BrdtDataRow(BatchResultDataTable table, BrdtRecordType recordType, string substream, string component = null)
			: base(table)
		{
			RecordType = recordType;
			Substream = substream;
			Component = component;
		}

		public void PushUnit(string unit)
		{
			_stackedUnit = unit;
		}

		public string PopUnit()
		{
			string stackedUnit = _stackedUnit;
			_stackedUnit = null;
			return stackedUnit;
		}
	}
