	public class BatchStreamInfo : IComparable<BatchStreamInfo>
	{
		private BatchAccumulationInfo _accumulationInfo;

		private Dictionary<string, BatchAccumulationInfo> _substreamAccumulation;

		public AccessorElement StreamElement { get; }

		public string DisplayName { get; }

		public int HierarchyLevel { get; }

		public string SourceBlock => StreamElement.GetSubElement("Source.Block.ID").GetStringValue();

		public string DestinationBlock => StreamElement.GetSubElement("Destination.Block.ID").GetStringValue();

		public bool HasAccumulativeData => StreamElement.GetBooleanValueAtPath("HasAccumulativeData") == true;

		public BatchAccumulationInfo TotalAccumulation => _accumulationInfo ?? (_accumulationInfo = new BatchAccumulationInfo(StreamElement.GetSubElement("Accumulation")));

		public IReadOnlyDictionary<string, BatchAccumulationInfo> SubstreamAccumulations
		{
			get
			{
				if (_substreamAccumulation == null)
				{
					_substreamAccumulation = new Dictionary<string, BatchAccumulationInfo>();
					foreach (AccessorElement child in StreamElement.GetSubElement("Substreams").GetChildren())
					{
						string name = child.GetName();
						if (!string.IsNullOrEmpty(name))
						{
							_substreamAccumulation[name] = new BatchAccumulationInfo(child.GetSubElement("Accumulation"));
						}
					}
				}
				return _substreamAccumulation;
			}
		}

		public BatchStreamInfo(AccessorElement streamElement, string displayName, int hierarchyLevel)
		{
			StreamElement = streamElement ?? throw new ArgumentNullException("streamElement");
			DisplayName = displayName ?? throw new ArgumentNullException("displayName");
			HierarchyLevel = hierarchyLevel;
		}

		int IComparable<BatchStreamInfo>.CompareTo(BatchStreamInfo other)
		{
			if (other == null)
			{
				return 1;
			}
			if (this == other)
			{
				return 0;
			}
			return StringComparerMethods.AlphaCompareText(DisplayName, other.DisplayName);
		}
	}
	public class BatchResultFormViewModel : MMTabPageViewModel
	{
		private const string DotStreamsDot = ".Streams.";

		private const string DotBlocksDot = ".Blocks.";

		private string MainNodePath => ExpandDataPath("@main");

		public bool IsCurrentNodeValid
		{
			get
			{
				if (base.UnityContainer != null)
				{
					return ApwnDocumentControl.IsMainNodeExisting(base.UnityContainer, MainNodePath);
				}
				return false;
			}
		}

		public BatchResultFormNodeType NodeType
		{
			get
			{
				string mainNodePath = MainNodePath;
				if (mainNodePath.Contains(".Results Summary.") || mainNodePath.EndsWith(".Results Summary"))
				{
					return BatchResultFormNodeType.ResultsSummary;
				}
				if (mainNodePath.Contains(".Streams."))
				{
					return BatchResultFormNodeType.Stream;
				}
				return BatchResultFormNodeType.Block;
			}
		}

		public string GetCurrentStreamInShortName()
		{
			if (NodeType == BatchResultFormNodeType.Stream)
			{
				string mainNodePath = MainNodePath;
				int num = mainNodePath.IndexOf(".Streams.");
				if (num > 0)
				{
					string text = mainNodePath.Substring(num + ".Streams.".Length);
					int num2 = text.IndexOf('.');
					if (num2 > 0)
					{
						return text.Substring(0, num2);
					}
					return text;
				}
			}
			return null;
		}

		public string GetCurrentBlockInShortName()
		{
			if (NodeType == BatchResultFormNodeType.Block)
			{
				string mainNodePath = MainNodePath;
				int num = mainNodePath.LastIndexOf(".Blocks.");
				if (num > 0)
				{
					string text = mainNodePath.Substring(num + ".Blocks.".Length);
					int num2 = text.IndexOf('.');
					if (num2 > 0)
					{
						return text.Substring(0, num2);
					}
					return text;
				}
			}
			return null;
		}
	}
