			{
				XElement xElement = new XElement("batchFormSettings");
				if (DisplayedStreams.Count > 0)
				{
					XElement xElement2 = new XElement("streams");
					foreach (string displayedStream in DisplayedStreams)
					{
						xElement2.Add(new XElement("stream", displayedStream));
					}
					xElement.Add(xElement2);
				}
				if (GroupingStates.Count > 0)
				{
					XElement xElement3 = new XElement("rows");
					foreach (int key in GroupingStates.Keys)
					{
						XElement xElement4 = new XElement("row");
						xElement4.SetAttributeValue("id", key);
						xElement4.SetAttributeValue("state", GroupingStates[key]);
						xElement3.Add(xElement4);
					}
					xElement.Add(xElement3);
				}
				if (!xElement.HasElements)
				{
					return null;
				}
				return xElement.ToString(SaveOptions.DisableFormatting);
			}

			public IEnumerable<BatchStreamInfo> GetDisplayedStreams(IEnumerable<BatchStreamInfo> availableStreams)
			{
				List<BatchStreamInfo> list = new List<BatchStreamInfo>();
				foreach (string ds in DisplayedStreams)
				{
					BatchStreamInfo batchStreamInfo = availableStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, ds, StringComparison.CurrentCulture));
					if (batchStreamInfo != null)
					{
						list.Add(batchStreamInfo);
					}
				}
				return list;
			}

			public void ApplyGroupingStates(BatchResultDataTable table)
			{
				if (!(from x in table.Rows.Where((DataRow x) => x.GroupingRowsCount > 0).ToList()
					select table.Rows.IndexOf(x)).SequenceEqual(GroupingStates.Keys))
				{
					return;
				}
				foreach (int key in GroupingStates.Keys)
				{
					DataRow dataRow = table.Rows[key];
					if (dataRow.GroupingRowsCount > 0)
					{
						RowGroupingState rowGroupingState = GroupingStates[key];
						if (dataRow.GroupingState != rowGroupingState)
						{
							dataRow.GroupingState = rowGroupingState;
						}
					}
				}
			}

			public static BatchGridCommonShellSetting Parse(string text)
			{
				if (!string.IsNullOrWhiteSpace(text))
				{
					XElement xElement = null;
					try
					{
						xElement = XElement.Parse(text);
					}
					catch (Exception ex)
					{
						SystemEnvironment.Logger.Log(ex.Message, Category.Exception, Priority.High);
					}
					if (xElement != null)
					{
						BatchGridCommonShellSetting batchGridCommonShellSetting = new BatchGridCommonShellSetting();
						XElement xElement2 = xElement.Element("streams");
						if (xElement2 != null)
						{
							foreach (XElement item in xElement2.Elements("stream"))
							{
								if (!string.IsNullOrEmpty(item.Value))
								{
									batchGridCommonShellSetting.DisplayedStreams.Add(item.Value);
								}
							}
						}
						XElement xElement3 = xElement.Element("rows");
						if (xElement3 != null)
						{
							foreach (XElement item2 in xElement3.Elements("row"))
							{
								int? num = (int?)item2.Attribute("id");
								if (num.HasValue && Enum.TryParse<RowGroupingState>((string)item2.Attribute("state"), ignoreCase: true, out var result))
								{
									batchGridCommonShellSetting.GroupingStates[num.Value] = result;
								}
							}
						}
						return batchGridCommonShellSetting;
					}
				}
				return null;
			}

			public static BatchGridCommonShellSetting CollectFrom(BatchResultDataTable table)
			{
				BatchGridCommonShellSetting batchGridCommonShellSetting = new BatchGridCommonShellSetting();
				foreach (BatchStreamInfo selectedStream in table.SelectedStreams)
				{
					batchGridCommonShellSetting.DisplayedStreams.Add(selectedStream.DisplayName);
				}
				for (int i = 0; i < table.Rows.Count; i++)
				{
					DataRow dataRow = table.Rows[i];
					if (dataRow.GroupingRowsCount > 0)
					{
						batchGridCommonShellSetting.GroupingStates[i] = dataRow.GroupingState;
					}
				}
				return batchGridCommonShellSetting;
			}
		}

