		private void DeleteSelectedColumnsCommand_Executed()
		{
			if (theGridControl != null && theGridControl.DataSource != null && !SimulatorStatusHelperForControls.Default.IsRunning)
			{
				IEnumerable<DataColumn> enumerable = theGridControl.SelectedColumns.Where((DataColumn x) => ((BrdtDataColumn)x).ColumnType == BrdtColumnType.Stream);
				if (enumerable.Any())
				{
					((BatchResultDataTable)theGridControl.DataSource).DeleteColumns(enumerable);
				}
			}
		}

		private bool DeleteSelectedColumnsCommand_CanExecute()
		{
			if (theGridControl != null && theGridControl.DataSource != null && !SimulatorStatusHelperForControls.Default.IsRunning)
			{
				return theGridControl.SelectedColumns.Any((DataColumn x) => ((BrdtDataColumn)x).ColumnType == BrdtColumnType.Stream);
			}
			return false;
		}

		private void ExpandGroupRowCommand_Executed(DataRow row)
		{
			row.GroupingState = RowGroupingState.Expanded;
		}

