		private void CopyAllCommand_Executed()
		{
			bool isAllSelected = theGridControl.IsAllSelected;
			if (!isAllSelected)
			{
				theGridControl.SelectAll();
			}
			try
			{
				ApplicationCommands.Copy.Execute(null, theGridControl);
			}
			catch (Exception ex)
			{
				MMMessageBox.Show(Window.GetWindow(this), GridFormsResources.StreamSummaryPage_UpdateDataError_Message + "\n" + ex.Message, GridFormsResources.StreamSummaryPage_UpdateDataError_Title);
			}
			if (!isAllSelected)
			{
				theGridControl.DeselectAll();
			}
		}

		private bool CopyAllCommand_CanExecute()
		{
			if (theGridControl != null && theGridControl.DataSource != null)
			{
				return theGridControl.DataSource.Rows.Count > 0;
			}
			return false;
		}

		private void FormatCommand_Executed(object parameter)
		{
			IEnumerable<BrdtDataRow> formatableSelectedRows = GetFormatableSelectedRows();
			if (!formatableSelectedRows.Any())
			{
				return;
			}
			AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification formatSpecification = AspenTech.AspenPlus.MMForms.GridForms.StreamReport.Template.FormatSpecification.Parse(formatableSelectedRows.First().NumberFormat);
			ChangeFormatDialog changeFormatDialog = new ChangeFormatDialog
			{
				FormatSpecification = formatSpecification,
				Owner = Window.GetWindow(this)
			};
			bool? flag = changeFormatDialog.ShowDialog();
			if (!flag.HasValue || !flag.Value)
			{
				return;
			}
			string numberFormat = changeFormatDialog.FormatSpecification.ToString();
			foreach (BrdtDataRow item in formatableSelectedRows)
			{
				item.NumberFormat = numberFormat;
			}
			foreach (BrdtDataRow item2 in formatableSelectedRows)
			{
				item2.ClearData();
				item2.RaiseIndexerPropertyChanged();
			}
		}

		private bool FormatCommand_CanExecute(object parameter)
		{
			if (theGridControl.SelectedRows.Any((DataRow x) => IsFormatableRow(x)))
			{
				return true;
			}
			if (theGridControl.TotalSelectedCells.Any((DataCellInfo x) => IsFormatableRow(x.Row)))
			{
				return true;
			}
			return false;
		}

		[IteratorStateMachine(typeof(GetFormatableSelectedRowsEnumerator))]
		private IEnumerable<BrdtDataRow> GetFormatableSelectedRows()
		{
			return new GetFormatableSelectedRowsEnumerator(-2)
			{
				iteratorOwner = this
			};
		}

		private bool IsFormatableRow(DataRow row)
		{
			if (row is BrdtDataRow brdtDataRow)
			{
				if (brdtDataRow.RecordType != BrdtRecordType.Substream)
				{
					return brdtDataRow.RecordType != BrdtRecordType.TotalStream;
				}
				return false;
			}
			return false;
		}

		public BatchResultForm()
		{
			base.ViewModelType = typeof(BatchResultFormViewModel);
			InitializeComponent();
			theGridControl.CellValueQueried += TheGridControl_CellValueQueried;
			theGridControl.CellValueChanged += TheGridControl_CellValueChanged;
			theGridControl.DefaultContextMenuOpening += TheGridControl_DefaultContextMenuOpening;
			theGridControl.DataCopying += TheGridControl_DataCopying;
			theGridControl.DataDragging += TheGridControl_DataDragging;
		}

		private void TheGridControl_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
			BrdtDataRow brdtDataRow = e.Row as BrdtDataRow;
			BrdtDataColumn brdtDataColumn = e.Column as BrdtDataColumn;
			switch (brdtDataColumn.ColumnType)
			{
			case BrdtColumnType.PropertyName:
				e.Data = CreatePropertyNameCell(brdtDataRow);
				break;
			case BrdtColumnType.Units:
				if (brdtDataRow.RecordType != BrdtRecordType.TotalStream && brdtDataRow.RecordType != BrdtRecordType.Substream)
				{
					e.Data = CreateUnitsCell(brdtDataRow);
				}
				break;
			case BrdtColumnType.Stream:
				if (brdtDataRow.RecordType != BrdtRecordType.TotalStream && brdtDataRow.RecordType != BrdtRecordType.Substream)
				{
					e.Data = CreateStreamCell(brdtDataRow, brdtDataColumn.Stream);
				}
				break;
			}
		}

		private IDataCell CreatePropertyNameCell(BrdtDataRow row)
		{
			return row.RecordType switch
			{
				BrdtRecordType.TotalStream => new DataCellText(BatchProcessResources.BatchStreamReport_TotalStream), 
				BrdtRecordType.Substream => new DataCellText(string.Format(BatchProcessResources.BatchStreamReport_Substream, row.Substream)), 
				BrdtRecordType.TotalMole => new DataCellText(BatchProcessResources.BatchStreamReport_FormLabel_Mole), 
				BrdtRecordType.TotalMass => new DataCellText(BatchProcessResources.BatchStreamReport_FormLabel_Mass), 
				BrdtRecordType.TotalVolumn => new DataCellText(BatchProcessResources.BatchStreamReport_FormLabel_Volume), 
				BrdtRecordType.TotalEnergy => new DataCellText(BatchProcessResources.BatchStreamReport_FormLabel_Energy), 
				BrdtRecordType.ComponentMole => new DataCellText(row.Component), 
				BrdtRecordType.ComponentMass => new DataCellText(row.Component), 
				_ => null, 
			};
		}

		private IDataCell CreateUnitsCell(BrdtDataRow row)
		{
			int unitRow = row.UnitRow;
			if (unitRow != 0)
			{
				IEnumerable<string> unitsList = GetUnitsList(unitRow);
				string text = row.PopUnit();
				return new DataCellText((text != null && unitsList.Contains(text)) ? text : GetDisplayUnits(unitRow))
				{
					ItemsSource = unitsList
				};
			}
			return null;
		}

		private IDataCell CreateStreamCell(BrdtDataRow row, BatchStreamInfo stream)
		{
			BatchAccumulationInfo batchAccumulationInfo = (string.IsNullOrEmpty(row.Substream) ? stream.TotalAccumulation : (stream.SubstreamAccumulations.ContainsKey(row.Substream) ? stream.SubstreamAccumulations[row.Substream] : null));
			if (batchAccumulationInfo == null)
			{
				return null;
			}
			string displayUnit = row[row.DataTable.Columns[1]]?.Value as string;
			return row.RecordType switch
			{
				BrdtRecordType.TotalMole => CreateDataCellForElement(batchAccumulationInfo.MoleTotalElement, 51, displayUnit, row.NumberFormat), 
				BrdtRecordType.TotalMass => CreateDataCellForElement(batchAccumulationInfo.MassTotalElement, 18, displayUnit, row.NumberFormat), 
				BrdtRecordType.TotalVolumn => CreateDataCellForElement(batchAccumulationInfo.VolTotalElement, 27, displayUnit, row.NumberFormat), 
				BrdtRecordType.TotalEnergy => CreateDataCellForElement(batchAccumulationInfo.EnthalpyTotalElement, 53, displayUnit, row.NumberFormat), 
				BrdtRecordType.ComponentMole => CreateDataCellForElement(batchAccumulationInfo.GetMoleComponentElement(row.Component), 51, displayUnit, row.NumberFormat), 
				BrdtRecordType.ComponentMass => CreateDataCellForElement(batchAccumulationInfo.GetMassComponentElement(row.Component), 18, displayUnit, row.NumberFormat), 
				_ => null, 
			};
		}

		private IDataCell CreateDataCellForElement(AccessorElement element, int unitRow, string displayUnit, string numberFormat)
		{
			DataCellDouble dataCellDouble = new DataCellDouble(GetDisplayValue(element.GetDoubleValue(), unitRow, displayUnit))
			{
				Tag = element
			};
			if (!string.IsNullOrWhiteSpace(numberFormat))
			{
				dataCellDouble.Mask = numberFormat;
			}
			return dataCellDouble;
		}

		private double? GetDisplayValue(double? siValue, int unitRow, string displayUnit)
		{
			if (siValue.HasValue && UnitsProvider != null)
			{
				return UnitsProvider.ConvertFromSI(unitRow, siValue.Value, displayUnit);
			}
			return siValue;
		}

		private void TheGridControl_CellValueChanged(object sender, CellValueChangedEventArgs e)
		{
			if (_isRefreshingData)
			{
				return;
			}
			BrdtDataColumn brdtDataColumn = e.Data.Column as BrdtDataColumn;
			if (brdtDataColumn.ColumnType != BrdtColumnType.Units || e.OldValue == null)
			{
				return;
			}
			BrdtDataRow brdtDataRow = e.Data.Row as BrdtDataRow;
			foreach (BrdtDataColumn column in brdtDataRow.DataTable.Columns)
			{
				if (column.ColumnType == BrdtColumnType.Stream)
				{
					brdtDataRow.ClearData(column);
				}
			}
			brdtDataRow.RaiseIndexerPropertyChanged();
			if (brdtDataRow.GroupingRowsCount <= 0)
			{
				return;
			}
			DataTable dataTable = brdtDataRow.DataTable;
			int num = dataTable.Rows.IndexOf(brdtDataRow);
			if (num >= 0)
			{
				for (int i = 0; i < brdtDataRow.GroupingRowsCount; i++)
				{
					dataTable.Rows[num + i + 1][brdtDataColumn].Value = e.NewValue;
				}
			}
		}

		private void TheGridControl_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
		{
			GridControl gridControl = theGridControl;
			e.DefaultContextMenu.Items.Clear();
			if (e.IsOpenFromColumnHeader)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
					},
					Command = ApplicationCommands.Copy,
					CommandTarget = gridControl
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					IsCheckable = true,
					IsChecked = (e.SourceColumn != null && e.SourceColumn.IsColumnSelected),
					Command = GridControl.SelectColumnCommand,
					CommandTarget = gridControl,
					CommandParameter = e.SourceColumn
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.RecordsFreezeColumns16
					},
					Command = GridControl.FreezeColumnCommand,
					CommandTarget = gridControl,
					CommandParameter = e.SourceColumn
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = GridControl.UnfreezeColumnCommand,
					CommandTarget = gridControl,
					CommandParameter = e.SourceColumn
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.AspenPlus.MMForms.GridForms.Controls.Internal.ImageSourceHelper.CommonShellImages.Delete_16
					},
					Command = DeleteSelectedColumnsCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_DeleteSelectedColumns
				});
			}
			else if (e.IsOpenFromRowHeader)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
					},
					Command = ApplicationCommands.Copy,
					CommandTarget = gridControl
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					IsCheckable = true,
					IsChecked = (e.SourceRow != null && gridControl.SelectedRows.Contains(e.SourceRow)),
					Command = GridControl.SelectRowCommand,
					CommandTarget = gridControl,
					CommandParameter = e.SourceRow
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = ExpandGroupRowCommand,
					CommandParameter = e.SourceRow,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_Expand
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = CollapseGroupRowCommand,
					CommandParameter = e.SourceRow,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_Collapse
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = ExpandAllGroupRowsCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_ExpandAll
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = CollapseAllGroupRowsCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_CollapseAll
				});
			}
			else if (e.IsOpenFromGridCell)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
					},
					Command = ApplicationCommands.Copy,
					CommandTarget = gridControl
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = FormatCommand,
					CommandParameter = e.SourceCell,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_Format
				});
				if (e.SourceCell.Column.DisplayIndex == 0)
				{
					e.DefaultContextMenu.Items.Add(new Separator());
					e.DefaultContextMenu.Items.Add(new MenuItem
					{
						Command = ExpandAllGroupRowsCommand,
						Header = GridFormsResources.StreamSummaryPage_ContextMenu_ExpandAll
					});
					e.DefaultContextMenu.Items.Add(new MenuItem
					{
						Command = CollapseAllGroupRowsCommand,
						Header = GridFormsResources.StreamSummaryPage_ContextMenu_CollapseAll
					});
				}
			}
			else if (e.IsOpenFromHeaderPrefixArea)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = CopyAllCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_CopyAll
				});
				e.DefaultContextMenu.Items.Add(new Separator());
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = ExpandAllGroupRowsCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_ExpandAll
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Command = CollapseAllGroupRowsCommand,
					Header = GridFormsResources.StreamSummaryPage_ContextMenu_CollapseAll
				});
			}
		}

