		private string GetCxsMonikerForCopy(DataCellInfo cell)
		{
			if (cell.Data?.Tag is AccessorElement { success: not false } accessorElement)
			{
				return StreamReportClipboardHelper.FixSharedCxsPath(accessorElement.cxsPath);
			}
			return null;
		}

		private string GetCellTextForCopy(DataCellInfo cell)
		{
			return cell.Data?.ValueAsString;
		}

		protected override void OnViewModelChanged(CxvViewModel oldValue, CxvViewModel newValue)
		{
			SubscribeEvents();
			InvalidateData();
			base.OnViewModelChanged(oldValue, newValue);
		}

		protected override void OnPreviewKeyDown(KeyEventArgs e)
		{
			if (e.Key == Key.Delete || e.Key == Key.Back)
			{
				DeleteSelectedColumnsCommand.Execute(null);
			}
			base.OnPreviewKeyDown(e);
		}

		protected override void OnPreviewMouseDown(MouseButtonEventArgs e)
		{
			if (!theGridControl.IsKeyboardFocusWithin)
			{
				theGridControl.Focus();
			}
			base.OnPreviewMouseDown(e);
		}

