		{
			UnsubscribeEvents();
			base.OnClosed();
		}

		public override string SaveCommonShellSettings()
		{
			if (theGridControl.DataSource is BatchResultDataTable table)
			{
				return BatchGridCommonShellSetting.CollectFrom(table).Save();
			}
			return null;
		}

		public override void RestoreCommonShellSettings(string settings)
		{
			_commonShellSetting = BatchGridCommonShellSetting.Parse(settings);
			InvalidateData();
		}

		public MaterialFormSharedSettingsForBatch GetMaterialFormSharedSettings()
		{
			if (ResolveNeighborTabPage("GridForms.StreamReportForm") is StreamReportForm streamReportForm)
			{
				if (streamReportForm.ViewModel == null)
				{
					streamReportForm.EnsureInitialized();
					if (this.GetAncestor<ScreenContentControl>() is ITabPageScreen tabPageScreen)
					{
						tabPageScreen.ApplyCommonShellSettings();
					}
				}
				MaterialFormSharedSettingsForBatch sharedSettingsForBatch = streamReportForm.ReportControl.GetSharedSettingsForBatch();
				if (sharedSettingsForBatch != null)
				{
					return sharedSettingsForBatch;
				}
			}
			return new MaterialFormSharedSettingsForBatch(totalStream: true, substreams: true, moleFlows: true, massFlows: true, hideComponentsWithZeroFlow: false);
		}

		protected override void ApplyZoomFactor(double zoomFactor)
		{
			theGridControl.ZoomFactor = zoomFactor;
		}

		public override IEnumerable<FrameworkElement> GeneratePrintPages(Size availablePrintSize)
		{
			return theGridControl.GenerateGenericPrintPages(availablePrintSize, 0, 2, BatchProcessResources.BatchStreamReport_TabName, null, ignoreLastColumn: true);
		}

		private void SubscribeEvents()
		{
			if (!_subscribed && base.UnityContainer != null)
			{
				IEventAggregator eventAggregator = base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
				eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Subscribe(OnAplusGlobalUnitSetChangedEvent);
				eventAggregator.GetEvent<SimulationRunStartedEvent>().Subscribe(OnSimulationRunStartedEvent);
				eventAggregator.GetEvent<SimulationRunCompletedEvent>().Subscribe(OnSimulationRunCompletedEvent);
				eventAggregator.GetEvent<SimulationRunFailedEvent>().Subscribe(OnSimulationRunFailedEvent);
				eventAggregator.GetEvent<SimulationReinitializedEvent>().Subscribe(OnSimulationReinitializedEvent);
				eventAggregator.GetEvent<SimulationIntegrationStepEvent>().Subscribe(OnSimulationIntegrationStepEvent);
				eventAggregator.GetEvent<ObjectRenameEvent>().Subscribe(OnObjectRenameEvent);
				eventAggregator.GetEvent<ObjectDeleteEvent>().Subscribe(OnObjectDeleteEvent);
				eventAggregator.GetEvent<MaterialFormSharedBatchSettingChangedEvent>().Subscribe(OnMaterialFormSharedBatchSettingsChangedEvent);
				_subscribed = true;
			}
		}

		private void UnsubscribeEvents()
		{
			if (_subscribed && base.UnityContainer != null)
			{
				IEventAggregator eventAggregator = base.UnityContainer.Resolve<IEventAggregator>(Array.Empty<ResolverOverride>());
				eventAggregator.GetEvent<AplusGlobalUnitSetChangedEvent>().Unsubscribe(OnAplusGlobalUnitSetChangedEvent);
				eventAggregator.GetEvent<SimulationRunStartedEvent>().Unsubscribe(OnSimulationRunStartedEvent);
				eventAggregator.GetEvent<SimulationRunCompletedEvent>().Unsubscribe(OnSimulationRunCompletedEvent);
