				eventAggregator.GetEvent<SimulationReinitializedEvent>().Unsubscribe(OnSimulationReinitializedEvent);
				eventAggregator.GetEvent<SimulationIntegrationStepEvent>().Unsubscribe(OnSimulationIntegrationStepEvent);
				eventAggregator.GetEvent<ObjectRenameEvent>().Unsubscribe(OnObjectRenameEvent);
				eventAggregator.GetEvent<ObjectDeleteEvent>().Unsubscribe(OnObjectDeleteEvent);
				eventAggregator.GetEvent<MaterialFormSharedBatchSettingChangedEvent>().Unsubscribe(OnMaterialFormSharedBatchSettingsChangedEvent);
