		private IDictionary<BatchStreamInfo, string> GetRenamedDisplayedStreams(ObjectRenameEventArgs renameArgs)
		{
			Dictionary<BatchStreamInfo, string> dictionary = new Dictionary<BatchStreamInfo, string>();
			if (theGridControl?.DataSource is BatchResultDataTable batchResultDataTable && batchResultDataTable.SelectedStreams.Any())
			{
				string simpleHierarchyPath = GetSimpleHierarchyPath();
				bool flag = string.IsNullOrEmpty(simpleHierarchyPath);
				string text = simpleHierarchyPath + ".";
				string text2 = ExtractStreamIdFromRenameArgs(renameArgs.OldName);
				string text3 = ExtractStreamIdFromRenameArgs(renameArgs.NewName);
				if (flag || (text2.StartsWith(text) && text3.StartsWith(text)))
				{
					string b = (flag ? text2 : text2.Substring(text.Length));
					string value = (flag ? text3 : text3.Substring(text.Length));
					foreach (BatchStreamInfo selectedStream in batchResultDataTable.SelectedStreams)
					{
						if (string.Equals(selectedStream.DisplayName, b, StringComparison.CurrentCulture))
						{
							dictionary[selectedStream] = value;
						}
					}
				}
			}
			return dictionary;
		}

		private string GetSimpleHierarchyPath()
		{
			if (base.ViewModel is BatchResultFormViewModel { IsCurrentNodeValid: not false } batchResultFormViewModel)
			{
				string adsFlowsheetPathForStreamSummaryForms = batchResultFormViewModel.GetAdsFlowsheetPathForStreamSummaryForms();
				if (!string.IsNullOrWhiteSpace(adsFlowsheetPathForStreamSummaryForms) && !string.Equals(adsFlowsheetPathForStreamSummaryForms, "Flowsheet", StringComparison.InvariantCultureIgnoreCase))
				{
					return adsFlowsheetPathForStreamSummaryForms.Replace(".Blocks.", ".").Replace(".SubFlowsheets.", ".").Replace(".Simulation.", ".")
						.TrimStart("Flowsheet.".ToCharArray())
						.TrimEnd(".Simulation".ToCharArray());
				}
			}
			return string.Empty;
		}

		[IteratorStateMachine(typeof(GetDisplayedStreamsEnumerator))]
		private IEnumerable<BatchStreamInfo> GetDisplayedStreams()
		{
			return new GetDisplayedStreamsEnumerator(-2)
			{
				iteratorOwner = this
			};
		}

		private static string ExtractStreamIdFromRenameArgs(string streamName)
		{
			if (!string.IsNullOrWhiteSpace(streamName))
			{
				string text = streamName.Trim();
				if (text.StartsWith("Blocks.", StringComparison.CurrentCultureIgnoreCase))
				{
					text = text.Substring(7);
				}
				if (text.StartsWith("Streams.", StringComparison.CurrentCultureIgnoreCase))
				{
					text = text.Substring(8);
				}
				return text.Replace(".Blocks.", ".").Replace(".Streams.", ".");
			}
			return streamName;
		}

