		public void InvalidateData(DispatcherPriority priority = DispatcherPriority.Render, bool showDefaultStreams = false)
		{
			if (_refreshDataOperation != null)
			{
				return;
			}
			_refreshDataOperation = base.Dispatcher.BeginInvoke((Action<bool>)delegate(bool ds)
			{
				try
				{
					RefreshData(ds);
				}
				finally
				{
					_refreshDataOperation = null;
				}
			}, priority, showDefaultStreams);
		}

		private void RefreshData(bool showDefaultStreams = false)
		{
			AdbDataProvider.Reset();
			(IEnumerable<BatchStreamInfo>, IEnumerable<BatchStreamInfo>) streamsInfo = GetStreamsInfo();
			if ((streamsInfo.Item1 == null && streamsInfo.Item2 == null) || (SimulatorStatusHelperForControls.Default.IsRunning && theGridControl.DataSource is BatchResultDataTable batchResultDataTable && batchResultDataTable.AvailableStreams.Count() > streamsInfo.Item2.Count()))
			{
				return;
			}
			IEnumerable<BatchStreamInfo> enumerable;
			if (_commonShellSetting == null)
			{
				(enumerable, _) = streamsInfo;
			}
			else
			{
				enumerable = _commonShellSetting.GetDisplayedStreams(streamsInfo.Item2);
			}
			IEnumerable<BatchStreamInfo> defaultStreams = enumerable;
			_isRefreshingData = true;
			try
			{
				(BatchResultDataTable, bool) tuple2 = EnsureTable(defaultStreams, streamsInfo.Item2, showDefaultStreams);
				tuple2.Item1.UpdateRows();
				if (_commonShellSetting != null)
				{
					_commonShellSetting.ApplyGroupingStates(tuple2.Item1);
				}
				if (tuple2.Item2)
				{
					theGridControl.RefreshData();
				}
			}
			finally
			{
				if (_commonShellSetting != null)
				{
					_commonShellSetting = null;
				}
				_isRefreshingData = false;
			}
		}

		private (BatchResultDataTable Table, bool NeedsRebuild) EnsureTable(IEnumerable<BatchStreamInfo> defaultStreams, IEnumerable<BatchStreamInfo> hierarchyStreams, bool showDefaultStreams = false)
		{
			bool item = false;
			BatchResultDataTable batchResultDataTable = theGridControl.DataSource as BatchResultDataTable;
			if (batchResultDataTable == null)
			{
				batchResultDataTable = BatchResultDataTable.Create(defaultStreams, hierarchyStreams, GetMaterialFormSharedSettings());
				theGridControl.DataSource = batchResultDataTable;
			}
			else
			{
				batchResultDataTable.ScopeSettings.CopyValuesFrom(GetMaterialFormSharedSettings());
				if (!batchResultDataTable.AvailableStreams.SequenceEqual(hierarchyStreams))
				{
					List<BatchStreamInfo> list = new List<BatchStreamInfo>();
					if (!batchResultDataTable.SelectedStreams.Any())
					{
						list.AddRange(defaultStreams);
					}
					else if (SimulatorStatusHelperForControls.Default.IsRunning || showDefaultStreams)
					{
						foreach (string displayName in batchResultDataTable.SelectedStreams.Select((BatchStreamInfo x) => x.DisplayName))
						{
							BatchStreamInfo batchStreamInfo = hierarchyStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, displayName, StringComparison.CurrentCulture));
							if (batchStreamInfo != null)
							{
								list.Add(batchStreamInfo);
							}
						}
						foreach (BatchStreamInfo defaultStream in defaultStreams)
						{
							if (!list.Contains(defaultStream))
							{
								list.Add(defaultStream);
							}
						}
					}
					else
					{
						foreach (BatchStreamInfo selectedStream in batchResultDataTable.SelectedStreams)
						{
							string displayName2 = selectedStream.DisplayName;
							if (_cachedRenamedStreams != null && _cachedRenamedStreams.ContainsKey(selectedStream))
							{
								displayName2 = _cachedRenamedStreams[selectedStream];
							}
							BatchStreamInfo batchStreamInfo2 = hierarchyStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, displayName2, StringComparison.CurrentCulture));
							if (batchStreamInfo2 != null)
							{
								list.Add(batchStreamInfo2);
							}
						}
					}
					int count = batchResultDataTable.Columns.Count;
					batchResultDataTable.UpdateStreamsInfo(list, hierarchyStreams);
					item = count != batchResultDataTable.Columns.Count;
				}
			}
			_cachedRenamedStreams = null;
			return (Table: batchResultDataTable, NeedsRebuild: item);
		}

		private (IEnumerable<BatchStreamInfo> DefaultStreams, IEnumerable<BatchStreamInfo> HierarchyStreams) GetStreamsInfo()
		{
			if (base.ViewModel is BatchResultFormViewModel { IsCurrentNodeValid: not false } batchResultFormViewModel)
			{
				List<BatchStreamInfo> list = (from x in new BatchResultDataProvider(batchResultFormViewModel.GetAdsFlowsheetPathForStreamSummaryForms()).GetHierarchyStreamElements()
					where x.HasAccumulativeData
					orderby x
					select x).ToList();
				return (DefaultStreams: FilterDefaultStreams(list, batchResultFormViewModel), HierarchyStreams: list);
			}
			return (DefaultStreams: null, HierarchyStreams: null);
		}

		private IEnumerable<BatchStreamInfo> FilterDefaultStreams(IEnumerable<BatchStreamInfo> availableStreams, BatchResultFormViewModel vm)
		{
			switch (vm.NodeType)
			{
			case BatchResultFormNodeType.Stream:
			{
				BatchStreamInfo batchStreamInfo = availableStreams.FirstOrDefault((BatchStreamInfo x) => string.Equals(x.DisplayName, vm.GetCurrentStreamInShortName(), StringComparison.CurrentCultureIgnoreCase));
				if (batchStreamInfo != null)
				{
					return new BatchStreamInfo[1] { batchStreamInfo };
				}
				return new BatchStreamInfo[0];
			}
			case BatchResultFormNodeType.Block:
			{
				List<BatchStreamInfo> list = new List<BatchStreamInfo>();
				string currentBlockInShortName = vm.GetCurrentBlockInShortName();
				foreach (BatchStreamInfo availableStream in availableStreams)
				{
					if (string.Equals(availableStream.DestinationBlock, currentBlockInShortName, StringComparison.CurrentCultureIgnoreCase))
					{
						list.Add(availableStream);
					}
				}
				{
					foreach (BatchStreamInfo availableStream2 in availableStreams)
					{
						if (string.Equals(availableStream2.SourceBlock, currentBlockInShortName, StringComparison.CurrentCultureIgnoreCase))
						{
							list.Add(availableStream2);
						}
					}
					return list;
				}
			}
			case BatchResultFormNodeType.ResultsSummary:
				return availableStreams;
			default:
				return new BatchStreamInfo[0];
			}
		}

		private IEnumerable<string> GetUnitsList(int unitsRow)
		{
			if (_unitsLists == null)
			{
				_unitsLists = new Dictionary<int, IEnumerable<string>>();
			}
			if (_unitsLists.ContainsKey(unitsRow))
			{
				return _unitsLists[unitsRow];
			}
			List<string> list = UnitsProvider?.GetUnitsList(unitsRow)?.ToList();
			if (list != null)
			{
				_unitsLists[unitsRow] = list;
			}
			return list;
		}

		private string GetDisplayUnits(int unitsRow)
		{
			if (_displayUnits == null)
			{
				_displayUnits = new Dictionary<int, string>();
			}
			if (_displayUnits.ContainsKey(unitsRow))
			{
				return _displayUnits[unitsRow];
			}
			string text = UnitsProvider?.GetDefaultDisplayUnits(unitsRow);
			if (!string.IsNullOrEmpty(text))
			{
				_displayUnits[unitsRow] = text;
			}
			return text;
		}

