	public class CarpetPlotWindow : Window, INotifyPropertyChanged, IComponentConnector
	{
		private class BIP_Record : DataRow
		{
			private string _firstCellDisplay;

			public string FirstCellDisplay
			{
				get
				{
					return _firstCellDisplay;
				}
				set
				{
					_firstCellDisplay = value;
				}
			}

			public BIP_Record(IEnumerable<DataColumn> columns)
				: base(columns)
			{
			}

			public IDataCell GetFirstColumnDataCell()
			{
				DataCellText obj = new DataCellText(FirstCellDisplay)
				{
					AllowDrag = false
				};
				GradientStopCollection gradientStopCollection = new GradientStopCollection
				{
					new GradientStop
					{
						Offset = 0.0,
						Color = Color.FromRgb(byte.MaxValue, byte.MaxValue, byte.MaxValue)
					},
					new GradientStop
					{
						Offset = 0.4,
						Color = Color.FromRgb(247, 248, 250)
					},
					new GradientStop
					{
						Offset = 1.0,
						Color = Color.FromRgb(241, 242, 244)
					}
				};
				obj.Background = new LinearGradientBrush(gradientStopCollection, new Point(0.5, 0.0), new Point(0.5, 1.0));
				return obj;
			}
		}

		private class StringComparer : IComparer<string>
		{
			public bool IsAscendOrder { get; set; }

			public StringComparer(bool isAscendOrder)
			{
				IsAscendOrder = isAscendOrder;
			}

			public int Compare(string x, string y)
			{
				if (IsAscendOrder)
				{
					return x.ToString().CompareTo(y.ToString());
				}
				return y.ToString().CompareTo(x.ToString());
			}
		}

		private Dictionary<string, int> baseComponents;

		private Dictionary<string, string> baseComponentSourceDic;

		private bool isAscendOrder;

		private List<IDataCell> preSelectedCells = new List<IDataCell>();

		internal GridControl grid1;

		private bool _contentLoaded;

		public event PropertyChangedEventHandler PropertyChanged;

		public CarpetPlotWindow(IEnumerable<DataRow> rows)
		{
			InitializeComponent();
			base.DataContext = this;
			IntializeInFo(rows);
			InitializeGrid();
		}

		private void OnPropertyChanged(string propertyName)
		{
			if (this.PropertyChanged != null)
			{
				this.PropertyChanged(this, new PropertyChangedEventArgs(propertyName));
			}
		}

		private void IntializeInFo(IEnumerable<DataRow> rows)
		{
			baseComponents = new Dictionary<string, int>();
			baseComponentSourceDic = new Dictionary<string, string>();
			foreach (DataRow row in rows)
			{
				object value = row[0].Value;
				object value2 = row[1].Value;
				object value3 = row[2].Value;
				if (value != null)
				{
					if (!baseComponents.ContainsKey(value.ToString()))
					{
						baseComponents.Add(value.ToString(), 1);
					}
					else
					{
						baseComponents[value.ToString()]++;
					}
				}
				if (value2 != null)
				{
					if (!baseComponents.ContainsKey(value2.ToString()))
					{
						baseComponents.Add(value2.ToString(), 1);
					}
					else
					{
						baseComponents[value2.ToString()]++;
					}
				}
				if (value != null && value2 != null && value3 != null)
				{
					string key = $"{value.ToString()}-{value2.ToString()}";
					if (!baseComponentSourceDic.ContainsKey(key))
					{
						baseComponentSourceDic.Add(key, value3.ToString());
					}
				}
			}
		}

		private void InitializeGrid()
		{
			DataTable dataSource = CreateDataSource(baseComponents);
			grid1.DataSource = dataSource;
			grid1.CellValueQueried += Grid1_CellValueQueried;
			grid1.CellTooltipChecking += Grid1_CellTooltipChecking;
			grid1.DefaultContextMenuOpening += Grid1_DefaultContextMenuOpening;
			grid1.DataSorting += Grid1_DataSorting;
			grid1.SelectionChanged += Grid1_SelectionChanged;
		}

		private void Grid1_SelectionChanged(object sender, RoutedEventArgs e)
		{
			GridControl gridControl = sender as GridControl;
			foreach (IDataCell preSelectedCell in preSelectedCells)
			{
				preSelectedCell.Background.Opacity = 1.0;
			}
			preSelectedCells.Clear();
			foreach (DataCellInfo selectedCell in gridControl.SelectedCells)
			{
				if (selectedCell.Data != null && !selectedCell.Data.IsReadOnly)
				{
					preSelectedCells.Add(selectedCell.Data);
					selectedCell.Data.Background.Opacity = 0.3;
				}
			}
		}

		private void Grid1_DataSorting(object sender, GridControlDataSortingEventArgs e)
		{
		}

		private void Grid1_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
		{
			e.DefaultContextMenu.Items.Clear();
			e.DefaultContextMenu.Items.Add(new MenuItem
			{
				Icon = new Image
				{
					Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = grid1
			});
		}

		private void Grid1_CellTooltipChecking(object sender, GridControlCellEventArgs e)
		{
			IDataCell cell = e.GridControlCell.Cell;
			if (cell == null || cell.Background == Brushes.LightGray || cell.Background == new SolidColorBrush(Color.FromArgb(byte.MaxValue, 238, 245, byte.MaxValue)))
			{
				return;
			}
			string header = cell.Column.Header;
			string firstCellDisplay = (cell.Row as BIP_Record).FirstCellDisplay;
			if (!string.IsNullOrEmpty(header) && !string.IsNullOrEmpty(firstCellDisplay))
			{
				string componentsSource = GetComponentsSource(firstCellDisplay, header);
				if (!string.IsNullOrEmpty(componentsSource))
				{
					cell.Tooltip = string.Format(WpfFormsResources.CarpertPlotWindow_Tooltip_Source + " {0}", componentsSource);
				}
			}
		}

		private void Grid1_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
			int num = grid1.DataSource.Rows.IndexOf(e.Row);
			int index = e.Column.Index;
			int count = grid1.DataSource.Rows.Count;
			_ = grid1.DataSource.Columns.Count;
			BIP_Record bIP_Record = e.Row as BIP_Record;
			if (string.IsNullOrEmpty(e.Column.Header))
			{
				return;
			}
			string firstCellDisplay = bIP_Record.FirstCellDisplay;
			if (index > count - num)
			{
				e.Data = DataRow.CreateDataCell(string.Empty, isReadOnly: true, null, CellUIType.Unknown, null, new SolidColorBrush(Color.FromArgb(byte.MaxValue, 238, 245, byte.MaxValue)));
				return;
			}
			if (firstCellDisplay.Equals(e.Column.Header))
			{
				e.Data = DataRow.CreateDataCell(string.Empty);
				e.Data.Background = new SolidColorBrush(Colors.LightGray);
				return;
			}
			(Color?, string) styleForCell = GetStyleForCell(firstCellDisplay, e.Column.Header);
			if (styleForCell.Item1.HasValue)
			{
				e.Data = DataRow.CreateDataCell(styleForCell.Item2);
				e.Data.Background = new SolidColorBrush(styleForCell.Item1.Value);
				e.Data.ContentHorizontalAlignment = HorizontalAlignment.Center;
			}
		}

		private string GetComponentsSource(string componentI, string componentJ)
		{
			string text = null;
			if (baseComponentSourceDic.Keys.Contains(componentI + "-" + componentJ))
			{
				text = componentI + "-" + componentJ;
			}
			else if (baseComponentSourceDic.Keys.Contains(componentJ + "-" + componentI))
			{
				text = componentJ + "-" + componentI;
			}
			if (!string.IsNullOrEmpty(text))
			{
				return baseComponentSourceDic[text];
			}
			return null;
		}

		private (Color? color, string display) GetStyleForCell(string componentI, string componentJ)
		{
			string componentsSource = GetComponentsSource(componentI, componentJ);
			if (!string.IsNullOrEmpty(componentsSource))
			{
				if (componentsSource.Equals("USER", StringComparison.InvariantCultureIgnoreCase))
				{
					return (color: Color.FromRgb(81, 232, 136), display: "U");
				}
				if (componentsSource.StartsWith("R-"))
				{
					if (componentsSource.Equals("R-PCES"))
					{
						return (color: Color.FromRgb(byte.MaxValue, 242, 204), display: "E");
					}
					return (color: Color.FromRgb(249, 233, 231), display: "R");
				}
				if (componentsSource.StartsWith("E-"))
				{
					return (color: Color.FromRgb(byte.MaxValue, 242, 204), display: "E");
				}
				return (color: Color.FromRgb(123, 218, 249), display: "D");
			}
			return (color: Colors.LightGray, display: string.Empty);
		}

		private DataTable CreateDataSource(Dictionary<string, int> components)
		{
			List<DataColumn> list = new List<DataColumn>
			{
				new DataColumn
				{
					Width = 80.0,
					IsReadOnly = true,
					IsFrozen = true,
					HeaderContentTemplate = GetTemplate("firstColumnHeaderCell")
				}
			};
			List<string> list2 = (from kvp in components
				orderby kvp.Value
				select kvp.Key).ToList();
			for (int num = 0; num < list2.Count; num++)
			{
				DataColumn item = new DataColumn(list2[num])
				{
					Width = 80.0,
					IsReadOnly = true,
					CanSorting = false
				};
				list.Add(item);
			}
			DataTable dataTable = new DataTable(list);
			List<DataRow> list3 = new List<DataRow>();
			list2.Reverse();
			for (int num2 = 0; num2 < list2.Count; num2++)
			{
				string firstCellDisplay = list2[num2];
				BIP_Record bIP_Record = new BIP_Record(list)
				{
					FirstCellDisplay = firstCellDisplay
				};
				bIP_Record[0] = bIP_Record.GetFirstColumnDataCell();
				list3.Add(bIP_Record);
			}
			dataTable.UpdateRows(list3);
			return dataTable;
		}

