		{
			if (ItemsToReorder.Count > 0 && SelectedIndex > 0)
			{
				PositionChangedEventArgs e = new PositionChangedEventArgs(SelectedIndex, SelectedIndex - 1);
				OnItemRecordered(e);
				ItemsToReorder.Move(e.OldPosition, e.NewPosition);
			}
		}

		private bool MoveUpCommand_CanExecute()
		{
			if (ItemsToReorder.Count > 0 && SelectedIndex > 0)
			{
				return true;
			}
			return false;
		}

		private void MoveDownCommand_Executed()
		{
			if (SelectedIndex >= 0 && SelectedIndex < ItemsToReorder.Count() - 1)
			{
				PositionChangedEventArgs e = new PositionChangedEventArgs(SelectedIndex, SelectedIndex + 1);
				OnItemRecordered(e);
				ItemsToReorder.Move(e.OldPosition, e.NewPosition);
			}
		}

