		public void EnsureBuiltUp()
		{
			if (_builtCompleted)
			{
				return;
			}
			_isBuilding = true;
			try
			{
				CellMetadataQueriedEventArgs e = new CellMetadataQueriedEventArgs();
				OnCellMetadataQueried(e);
				ItemsSource = e.Values.Select((TdValueItem x) => x.Value).ToList();
				if (e.SelectedValue != null)
				{
					SelectedItem = e.SelectedValue.Value;
				}
				else
				{
					SelectedItem = null;
				}
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				foreach (TdValueItem value in e.Values)
				{
					if (!dictionary.ContainsKey(value.Value))
					{
						dictionary.Add(value.Value, value.Description);
					}
				}
				Prompts = dictionary;
			}
			finally
			{
				_isBuilding = false;
				_builtCompleted = true;
			}
		}

