		{
			TdCellMetadata tdCellMetadata = d as TdCellMetadata;
			if (tdCellMetadata._builtCompleted && !tdCellMetadata._isBuilding)
			{
				CellMetadataValueChangedEventArgs args = new CellMetadataValueChangedEventArgs((string)e.OldValue, (string)e.NewValue);
				tdCellMetadata.HasSelectedItemEverChanged = true;
				tdCellMetadata.OnValueChanged(args);
			}
		}

		private static DataTemplate CreateAesComboTemplate(bool isDoubleValueType)
		{
			FrameworkElementFactory frameworkElementFactory = new FrameworkElementFactory(typeof(AesXamComboEdit));
			frameworkElementFactory.SetValue(ValueEditor.IsInEditModeProperty, true);
			frameworkElementFactory.SetValue(ValueEditor.IsAlwaysInEditModeProperty, true);
			frameworkElementFactory.SetValue(AesXamComboEdit.ValueUpdateTriggerProperty, UpdateSourceTrigger.LostFocus);
			frameworkElementFactory.SetValue(AesXamComboEdit.IsInScrollAreaProperty, true);
			frameworkElementFactory.SetValue(Control.FontWeightProperty, FontWeights.Bold);
			frameworkElementFactory.SetValue(Control.ForegroundProperty, Brushes.Blue);
			frameworkElementFactory.SetBinding(FrameworkElement.DataContextProperty, new Binding("Tag")
			{
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory.SetBinding(XamComboEditor.ItemsSourceProperty, new Binding("ItemsSource")
			{
				Mode = BindingMode.OneWay
			});
			frameworkElementFactory.SetBinding(AesXamComboEdit.PromptsDictionaryProperty, new Binding("Prompts")
			{
				Mode = BindingMode.OneWay
			});
			if (isDoubleValueType)
			{
				frameworkElementFactory.SetBinding(ValueEditor.ValueProperty, new Binding("SelectedItem")
				{
					Mode = BindingMode.TwoWay,
					Converter = new SelectedItemToValueConverter()
				});
				frameworkElementFactory.SetValue(AesXamComboEdit.DisplayValueToRenderTextConverterProperty, new PairValueToDisplayTextConverter());
				frameworkElementFactory.SetValue(XamComboEditor.IsEditableProperty, true);
				frameworkElementFactory.SetValue(AesXamComboEdit.MaskProperty, AesMaskOption.Double);
				frameworkElementFactory.SetValue(AesXamComboEdit.MaxLengthProperty, 20);
			}
			else
			{
				frameworkElementFactory.SetBinding(ValueEditor.ValueProperty, new Binding("SelectedItem")
				{
					Mode = BindingMode.TwoWay
				});
			}
			return new DataTemplate
			{
				VisualTree = frameworkElementFactory
			};
		}
	}
	public class CellMetadataQueriedEventArgs : EventArgs
	{
		public IList<TdValueItem> Values { get; private set; }

		public TdValueItem SelectedValue { get; set; }

		public CellMetadataQueriedEventArgs()
		{
			Values = new List<TdValueItem>();
		}

		public void AddRange(IEnumerable<TdValueItem> values)
		{
			if (values == null)
			{
				return;
			}
			foreach (TdValueItem value in values)
			{
				Values.Add(value);
			}
		}

		public void UpdateSelectedValue(string value)
		{
			SelectedValue = Values.FirstOrDefault((TdValueItem x) => string.Equals(x.Value, value, StringComparison.CurrentCultureIgnoreCase));
		}

		public void UpdateSelectedValue(double? value)
		{
			if (!value.HasValue)
			{
				SelectedValue = null;
				return;
			}
			SelectedValue = Values.FirstOrDefault((TdValueItem x) => TdpcGridHelpers.ExtractDoubleValue(x.Value) == value);
		}
	}
