	internal static class TdpcGridHelpers
	{
		public static double? ExtractDoubleValue(string text, bool useInvariantCulture = true)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				if (TryParse(text, out var triedDoubleValue))
				{
					return triedDoubleValue;
				}
				string text2 = text.Trim();
				int num = text2.IndexOfAny(new char[2] { ' ', '\t' });
				if (num > 0 && TryParse(text2.Substring(0, num), out var triedDoubleValue2))
				{
					return triedDoubleValue2;
				}
			}
			return null;
			bool TryParse(string textToTry, out double result)
			{
				if (useInvariantCulture)
				{
					return double.TryParse(textToTry, NumberStyles.Any, CultureInfo.InvariantCulture, out result);
				}
				return double.TryParse(textToTry, out result);
			}
		}

		public static string ExtracDBValue(string text)
		{
			if (!string.IsNullOrWhiteSpace(text))
			{
				if (double.TryParse(text, out var _))
				{
					return null;
				}
				string text2 = text.Trim();
				int num = text2.IndexOfAny(new char[2] { ' ', '\t' });
				if (num > 0)
				{
					return text2.Substring(num + 1).Trim();
				}
			}
			return null;
		}
	}
