		private void cmdDechema_CommandExecute(object parameter)
		{
			if (SelectedFieldIndexes.Count != 1)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message38,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Exclamation,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Aspen_Plus
				});
				return;
			}
			int num = SelectedFieldIndexes[0];
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.Parameters.Add("y", ResolveParameter("y"));
			e.Parameters.Add("choice", ResolveParameter("choice"));
			e.Parameters.Add("z", "#" + num);
			e.LegacyFlags = 0;
			e.HelpId = 278;
			e.HelpFile = "PP-PARAM.CHM";
			e.ShowPrompts = false;
			switch (CxsConverter.ValueToString(ResolveParameter("choice")))
			{
			case "NRTL":
				e.FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Cor_NRTL";
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_DECHEMA_NRTL_Binary_Parameters;
				DisplayForm(e);
				break;
			case "UNIQ":
				e.FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Cor_UNIQ";
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_DECHEMA_UNIQUAC_Binary_Patameters;
				DisplayForm(e);
				break;
			case "WILSON":
				e.FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Cor_WIL";
				e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_DECHEMA_WILSON_Binary_Patameters;
				DisplayForm(e);
				break;
			}
			UpdateAll();
		}

		private void CmdReginfo_CommandExecute(object parameter)
		{
			if (ValidOneRowIndex < 0)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message39,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Binary_Parameter_Regression_Information,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Exclamation
				});
				return;
			}
			int validOneRowIndex = ValidOneRowIndex;
			string text = CxsConverter.ValueToString(ResolveParameter("choice"));
			string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.VAL1." + text + ".#" + validOneRowIndex, "id"));
			string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.VAL1." + text + ".#" + validOneRowIndex + ".#0", "id"));
			string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.BDBANK2." + text + ".#" + validOneRowIndex + "." + text3, "value"));
			if (text4 == "USER")
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message40,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Binary_Parameter_Integration_Information,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Exclamation
				});
				return;
			}
			RegInfoData regInfoData = new RegInfoData();
			string sigma;
			string tLimits;
			string pLimits;
			string xLimits;
			string x1Limits;
			string x2Limits;
			string henryLimits;
			string henryDeviation;
			string tDeviation;
			string pDeviation;
			string xDeviation;
			string x1Deviation;
			string x2Deviation;
			string xTDeviation;
			string sCitation;
			string compBasis;
			int num = this.RegInfoAped(text4, text2, text3, out sigma, out tLimits, out pLimits, out xLimits, out x1Limits, out x2Limits, out henryLimits, out henryDeviation, out tDeviation, out pDeviation, out xDeviation, out x1Deviation, out x2Deviation, out xTDeviation, out sCitation, out compBasis);
			regInfoData.dbank = text4;
			regInfoData.parameter = text;
			regInfoData.compi = text2;
			regInfoData.compj = text3;
			regInfoData.sigma = sigma;
			regInfoData.tLimits = tLimits;
			regInfoData.pLimits = pLimits;
			regInfoData.xLimits = xLimits;
			regInfoData.x1Limits = x1Limits;
			regInfoData.x2Limits = x2Limits;
			regInfoData.henryLimits = henryLimits;
			regInfoData.henryDeviation = henryDeviation;
			regInfoData.tDeviation = tDeviation;
			regInfoData.pDeviation = pDeviation;
			regInfoData.xDeviation = xDeviation;
			regInfoData.x1Deviation = x1Deviation;
			regInfoData.x2Deviation = x2Deviation;
			regInfoData.xTDeviation = xTDeviation;
			regInfoData.sCitation = sCitation;
			regInfoData.CompBasis = compBasis;
			switch (num)
			{
			case 1:
				DisplayForm(new DisplayFormEventArgs
				{
					FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Reg_VLE",
					LegacyFlags = 0,
					HelpId = 180,
					ShowPrompts = false,
					Parameters = { 
					{
						"RegInfo",
						(object)regInfoData.Save()
					} },
					ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_VLE_Binary_Parameters,
					HelpFile = "PP-PARAM.CHM"
				});
				break;
			case 2:
				DisplayForm(new DisplayFormEventArgs
				{
					FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Reg_LLE",
					LegacyFlags = 0,
					HelpId = 0,
					ShowPrompts = false,
					Parameters = { 
					{
						"RegInfo",
						(object)regInfoData.Save()
					} },
					ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_LLE_Binary_Parameters
				});
				break;
			case 3:
				DisplayForm(new DisplayFormEventArgs
				{
					FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Reg_Henry",
					LegacyFlags = 0,
					HelpId = 0,
					ShowPrompts = false,
					Parameters = { 
					{
						"RegInfo",
						(object)regInfoData.Save()
					} },
					ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Henry_Binary_Parameters
				});
				break;
			case 4:
				DisplayForm(new DisplayFormEventArgs
				{
					FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Reg_NIST",
					LegacyFlags = 0,
					HelpId = 0,
					ShowPrompts = false,
					Parameters = { 
					{
						"RegInfo",
						(object)regInfoData.Save()
					} },
					ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Henry_Binary_Parameters,
					ResizeMode = ResizeMode.CanResize
				});
				break;
			default:
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message40,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Binary_Parameter_Integration_Information,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Exclamation
				});
				break;
			}
		}

		private void cmdSearch_CommandExecute(object parameter)
		{
			DisplayFormEventArgs e = new DisplayFormEventArgs();
			e.FormProgId = "MMParam_Bi_Cor.MMParam_Bi_Cor_Search";
			e.LegacyFlags = 2;
			e.ShortName = AspenTech.AspenPlus.Localization.Properties.Resources.ShortName_Select_Components;
			e.ShowPrompts = false;
			e.Parameters.Add("choice", ResolveParameter("choice"));
			ObservableCollection<int> observableCollection = new ObservableCollection<int>();
			e.Parameters.Add("result", observableCollection);
			IUnityContainer unityContainer = base.UnityContainer;
			CommonMessageExchangeEvent obj = ((unityContainer == null) ? null : CxvUnityContainerExtensions.TryResolve<IEventAggregator>(unityContainer)?.GetEvent<CommonMessageExchangeEvent>());
			obj?.Subscribe(OnCommonMessageExchangeEvent);
			DisplayForm(e);
			obj?.Unsubscribe(OnCommonMessageExchangeEvent);
			if (observableCollection.Count > 0)
			{
				int num = observableCollection[0];
				if (num >= 0 && base.View is TDependentBinaryInteraction { theGrid: not null } tDependentBinaryInteraction)
				{
					tDependentBinaryInteraction.theGrid.ScrollIntoView(num);
				}
			}
			SelectedFieldIndexes = observableCollection;
		}

		private void OnCommonMessageExchangeEvent(CommonMessageExchangeEventArgs args)
		{
			if (args.Sender.GetType().ToString().Contains("MMParam_Bi_Cor_Search_ViewModel") && args.MessageKey == "SelectComponents" && args.MessageContent is ValueTuple<string, string> tuple && base.View is TDependentBinaryInteraction { theGrid: not null } tDependentBinaryInteraction)
			{
				int? num = tDependentBinaryInteraction.theGrid.FindComponentsPosition(tuple.Item1, tuple.Item2);
				args.AddResponse(this, num);
			}
		}

		private void cmdSwap_CommandExecute(object parameter)
		{
			int num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.VAL1.@choice", "child_count")).Value + 1;
			if (SelectedFieldIndexes.Count <= 0 || SelectedFieldIndexes[0] == num - 1)
			{
				ShowMessageBox(new ShowMessageBoxEventArgs
				{
					Message = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message11,
					MsgBoxButton = MessageBoxButton.OK,
					MsgBoxImage = MessageBoxImage.Exclamation,
					Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Binary_Interaction
				});
				return;
			}
			CxsDataProvider resolvedCxsProvider = base.ResolvedCxsProvider;
			resolvedCxsProvider?.SuspendNotifications();
			ObservableCollection<int> observableCollection = new ObservableCollection<int>();
			foreach (int selectedFieldIndex in SelectedFieldIndexes)
			{
				if (selectedFieldIndex != num - 1)
				{
					observableCollection.Add(selectedFieldIndex);
				}
			}
			try
			{
				foreach (int item in observableCollection)
				{
					string text = CxsConverter.ValueToString(ResolveParameter("choice"));
					string text2 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.VAL1." + text + ".#" + item, "id"));
					string text3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.VAL1." + text + ".#" + item + ".#0", "id"));
					string dataPath = "@main.Input.BDBANK2." + text + ".#" + item + ".#0";
					string text4 = CxsConverter.ValueToString(ExpandDataPathAndGet(dataPath, "value"));
					if (text4 == "USER")
					{
						ShowMessageBox(new ShowMessageBoxEventArgs
						{
							Message = string.Format(AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Message56, text2, text3),
							MsgBoxButton = MessageBoxButton.OK,
							MsgBoxImage = MessageBoxImage.Exclamation,
							Title = AspenTech.AspenPlus.Localization.Properties.Resources.MsgBox_Title_Binary_Interaction
						});
						continue;
					}
					AddChild("@main.Input.VAL1." + text, item);
					DeleteChildNoRefresh("@main.Input.VAL1." + text, item + 1);
					if (text3.StartsWith("#"))
					{
						text3 = string.Empty;
					}
					if (resolvedCxsProvider != null)
					{
						string text5 = ExpandDataPath("@main.Input.VAL1." + text + ".#" + item);
						if (!string.IsNullOrEmpty(text5))
						{
							CxsBatchRequestData cxsBatchRequestData = new CxsBatchRequestData();
							cxsBatchRequestData.AddRequest(text5, "ignore_errors", null, 1);
							cxsBatchRequestData.AddRequest(new CxsBatchRequest(text5, "id", null, text3));
							resolvedCxsProvider.BatchSetNoRefresh(cxsBatchRequestData);
						}
					}
					if (text2.StartsWith("#"))
					{
						text2 = string.Empty;
					}
					ExpandDataPathAndSet("@main.Input.VAL1." + text + ".#" + item + ".#0", "id", text2);
					if (!string.IsNullOrEmpty(text4))
					{
						string dataPath2 = $"@main.Input.BDBANK2.{text}.#{item.ToString()}.#0";
						ExpandDataPathAndSet(dataPath2, "value", text4);
					}
				}
			}
			catch (Exception)
			{
			}
			finally
			{
				resolvedCxsProvider?.ResumeNotifications();
			}
			UpdateDisplay();
			UpdateAll();
			SelectedFieldIndexes = observableCollection;
		}

		private void cmdShowPopup_CommandExecute(object parameter)
		{
			TDependentBinaryInteraction tDependentBinaryInteraction = base.View as TDependentBinaryInteraction;
			if (tDependentBinaryInteraction.theGrid == null || tDependentBinaryInteraction.theGrid.gc == null)
			{
				return;
			}
			DataTable dataSource = tDependentBinaryInteraction.theGrid.gc.DataSource;
			List<DataRow> list = new List<DataRow>();
			foreach (DataRow row in dataSource.Rows)
			{
				if (row.ResolvedVisibility == Visibility.Visible)
				{
					list.Add(row);
				}
			}
			CarpetPlotWindow carpetPlotWindow = new CarpetPlotWindow(list);
			carpetPlotWindow.Owner = Window.GetWindow(tDependentBinaryInteraction);
			carpetPlotWindow.WindowStartupLocation = WindowStartupLocation.CenterOwner;
			carpetPlotWindow.ShowDialog();
		}

		protected override void OnUpdateData()
		{
			if (base.IsInitialUpdate)
			{
				CxvVariableData cxvVariableData = txtRecordType_recordtype as CxvVariableData;
				ResolveUpdateParameter("choice", cxvVariableData.Value);
				ResolveUpdateParameter("z", 0);
				string value = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.SETNO.@choice", "value"));
				ResolveUpdateParameter("y", value);
				string dataPath = "@main.Input.DEFTUNIT";
				string value2 = CxsConverter.ValueToString(ExpandDataPathAndGet(dataPath, "value"));
				string value3 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.TUNITLABEL.#0", "value"));
				if (string.IsNullOrEmpty(value2) && !string.IsNullOrEmpty(value3))
				{
					ExpandDataPathAndSet(dataPath, "value", value3);
				}
				string dataPath2 = "@main.Input.DEFPROPUNIT";
				string value4 = CxsConverter.ValueToString(ExpandDataPathAndGet(dataPath2, "value"));
				string value5 = CxsConverter.ValueToString(ExpandDataPathAndGet("@main.Input.UNITLABEL.#0", "value"));
				if (string.IsNullOrEmpty(value4) && !string.IsNullOrEmpty(value5))
				{
					ExpandDataPathAndSet(dataPath2, "value", value5);
				}
			}
			string text = CxsConverter.ValueToString(ResolveParameter("choice"));
			int? num = CxsConverter.ValueToInt32(ExpandDataPathAndGet("@main.Input.VAL1." + text, "child_count"));
			if (num.HasValue && num.HasValue && num.Value > 0)
			{
				ResolveUpdateParameter("CmdSearchEnable", "1");
			}
			else
			{
				ResolveUpdateParameter("CmdSearchEnable", "0");
			}
			Show_RegInfo();
			base.OnUpdateData();
		}

		private void Show_RegInfo()
		{
			if (this.GrInqAped() == 0 || this.GrInqdbProvider() >= 1)
			{
				ResolveUpdateParameter("CmdReginfoVisible", "0");
				return;
			}
			switch (CxsConverter.ValueToString(ResolveParameter("choice")))
			{
			case "NRTL":
			case "HENRY":
			case "UNIQ":
			case "WILSON":
				ResolveUpdateParameter("CmdReginfoVisible", "1");
				break;
			default:
				ResolveUpdateParameter("CmdReginfoVisible", "0");
				break;
			}
		}
	}
	public class TDepenedentBinaryInteractionGrid : UserControl, IComponentConnector
	{
		private enum TdpcColumnType
		{
			ComponentI,
			ComponentJ,
			Source,
			TemperatureUnits,
			PropertyUnits,
			Value
		}

		private class TdGridColumn : DataColumn
		{
			public TdpcColumnType ColumnType { get; private set; }

			public int? ValueIndex { get; private set; }

			public TdGridColumn(TdpcColumnType columnType, string header, Type defaultDataType = null, double? width = null)
			{
				ColumnType = columnType;
				base.Header = header;
				base.DefaultDataType = defaultDataType;
				base.Width = width;
			}

			public string GetRecordName()
			{
				return ColumnType switch
				{
					TdpcColumnType.ComponentI => "VAL1", 
					TdpcColumnType.ComponentJ => "VAL1", 
					TdpcColumnType.Source => "BDBANK2", 
					TdpcColumnType.TemperatureUnits => "TUNITLABEL2", 
					TdpcColumnType.PropertyUnits => "UNITLABEL2", 
					_ => $"VAL{ValueIndex.GetValueOrDefault() + 1}", 
				};
			}

			public static TdGridColumn CreateValueColumn(int valueIndex, string header)
			{
				return new TdGridColumn(TdpcColumnType.Value, header, DataRow.DoubleType)
				{
					ValueIndex = valueIndex,
					Width = 80.0
				};
			}
		}

		private class TdGridRow : DataRow
		{
			public int RowIndex { get; private set; }

			public TdGridRow(DataTable parentDataTable, int rowIndex)
				: base(parentDataTable)
			{
				RowIndex = rowIndex;
			}
		}

		public static readonly DependencyProperty SelectedRowIndexesProperty = DependencyProperty.Register("SelectedRowIndexes", typeof(ObservableCollection<int>), typeof(TDepenedentBinaryInteractionGrid), new FrameworkPropertyMetadata(OnSelectedRowIndexesPropertyChanged));

		public static readonly DependencyProperty ValidOneRowIndexProperty = DependencyProperty.Register("ValidOneCellRowIndex", typeof(int), typeof(TDepenedentBinaryInteractionGrid), new PropertyMetadata(-1));

		private DispatcherOperation _updateSelectionOperation;

		private TDependentBinaryInteraction_ViewModel _vm;

		private TDependentBinaryInteractionWrapper _wrapper;

		private DispatcherOperation _refreshDataOperation;

		private string _mainNodePath;

		private IHNode _ihNode;

		private string _parameterMethod;

		private bool _isPastingData;

		private DispatcherOperation _showErrMsgOperation;

		private readonly List<string> _errorMessages = new List<string>();

		internal GridControl gc;

		private bool _contentLoaded;

		public ObservableCollection<int> SelectedRowIndexes
		{
			get
			{
				return (ObservableCollection<int>)GetValue(SelectedRowIndexesProperty);
			}
			set
			{
				SetValue(SelectedRowIndexesProperty, value);
			}
		}

		public int ValidOneRowIndex
		{
			get
			{
				return (int)GetValue(ValidOneRowIndexProperty);
			}
			set
			{
				SetValue(ValidOneRowIndexProperty, value);
			}
		}

		private bool IsHenryOrVlclkParameter
		{
			get
			{
				if (!string.Equals(_parameterMethod, "HENRY", StringComparison.InvariantCultureIgnoreCase))
				{
					return string.Equals(_parameterMethod, "VLCLK", StringComparison.InvariantCultureIgnoreCase);
				}
				return true;
			}
		}

		public object IEVentAggregator { get; private set; }

		protected virtual void OnSelectedRowIndexesChanged(ObservableCollection<int> oldValue, ObservableCollection<int> newValue)
		{
			InvalidateRowSelection();
			if (oldValue != null)
			{
				oldValue.CollectionChanged -= SelectedRowIndexes_CollectionChanged;
			}
			if (newValue != null)
			{
				newValue.CollectionChanged += SelectedRowIndexes_CollectionChanged;
			}
		}

		private void SelectedRowIndexes_CollectionChanged(object sender, NotifyCollectionChangedEventArgs e)
		{
			InvalidateRowSelection();
		}

		private void InvalidateRowSelection()
		{
			if (_updateSelectionOperation == null)
			{
				_updateSelectionOperation = base.Dispatcher.BeginInvoke((Action)delegate
				{
					UpdateGridRowSelection();
					_updateSelectionOperation = null;
				});
			}
		}

		private void UpdateGridRowSelection()
		{
			if (gc == null || gc.DataSource == null)
			{
				return;
			}
			gc.SupressSelectionChangedEvent = true;
			try
			{
				List<DataRow> list = new List<DataRow>();
				if (SelectedRowIndexes != null)
				{
					foreach (int rowIndex in SelectedRowIndexes)
					{
						DataRow dataRow = gc.DataSource.Rows.FirstOrDefault((DataRow x) => (x as TdGridRow).RowIndex == rowIndex);
						if (dataRow != null)
						{
							list.Add(dataRow);
						}
					}
				}
				if (list.SequenceEqual(gc.SelectedRows))
				{
					return;
				}
				gc.DeselectAll();
				foreach (DataRow item in list)
				{
					gc.SelectRow(item);
				}
			}
			finally
			{
				gc.SupressSelectionChangedEvent = false;
			}
		}

		private static void OnSelectedRowIndexesPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as TDepenedentBinaryInteractionGrid).OnSelectedRowIndexesChanged(e.OldValue as ObservableCollection<int>, e.NewValue as ObservableCollection<int>);
		}

		public TDepenedentBinaryInteractionGrid()
		{
			InitializeComponent();
			gc.CellValueQueried += gc_CellValueQueried;
			gc.CellValueChanged += gc_CellValueChanged;
			gc.CellValueLoaded += gc_CellValueLoaded;
			gc.CellTooltipChecking += gc_CellTooltipChecking;
			gc.CellControlEditModeChanged += gc_CellControlEditModeChanged;
			gc.DefaultContextMenuOpening += gc_DefaultContextMenuOpening;
			gc.DataCopying += gc_DataCopying;
			gc.DataDragging += gc_DataDragging;
			gc.DataPasting += Gc_DataPasting;
			gc.SelectionChanged += gc_SelectionChanged;
		}

		private void gc_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
			TdGridColumn tdGridColumn = e.Column as TdGridColumn;
			TdGridRow tdGridRow = e.Row as TdGridRow;
			if (tdGridColumn == null || tdGridRow == null)
			{
				return;
			}
			bool flag = tdGridRow.RowIndex == gc.DataSource.Rows.Count - 1;
			DataCellInfo cell = new DataCellInfo(tdGridRow, tdGridColumn);
			switch (tdGridColumn.ColumnType)
			{
			case TdpcColumnType.ComponentI:
				e.Data = CreateCellDataForComponent(flag ? null : _wrapper.GetComponentIValue(tdGridRow.RowIndex), cell);
				break;
			case TdpcColumnType.ComponentJ:
				e.Data = CreateCellDataForComponent(flag ? null : _wrapper.GetComponentJValue(tdGridRow.RowIndex), cell);
				break;
			case TdpcColumnType.Source:
				e.Data = CreateCellDataForSTP(flag ? null : _wrapper.GetSourceValue(tdGridRow.RowIndex), cell, flag);
				break;
			case TdpcColumnType.TemperatureUnits:
				e.Data = CreateCellDataForSTP(flag ? null : _wrapper.GetTemperatureUnitValue(tdGridRow.RowIndex), cell, flag);
				break;
			case TdpcColumnType.PropertyUnits:
				e.Data = CreateCellDataForSTP(flag ? null : _wrapper.GetPropertyUnitValue(tdGridRow.RowIndex), cell, flag);
				break;
			case TdpcColumnType.Value:
			{
				if (flag)
				{
					e.Data = new DataCellDouble
					{
						Foreground = Brushes.Blue
					};
					break;
				}
				DataCellDouble dataCellDouble = new DataCellDouble();
				dataCellDouble.Foreground = Brushes.Blue;
				dataCellDouble.Value = _wrapper.GetValueValue(tdGridRow.RowIndex, tdGridColumn.ValueIndex.GetValueOrDefault());
				e.Data = dataCellDouble;
				break;
			}
			}
			if (e.Data != null && e.Data.Tag != null && gc.CurrentCell == new DataCellInfo(tdGridRow, tdGridColumn) && e.Data.Tag is TdCellMetadata tdCellMetadata)
			{
				tdCellMetadata.EnsureBuiltUp();
			}
		}

		private IDataCell CreateCellDataForComponent(string value, DataCellInfo cell)
		{
			IDataCell dataCell = CreateEmptyCellData(DataRow.StringType, isEditable: true, cell);
			if (!string.IsNullOrEmpty(value))
			{
				dataCell.Value = value;
			}
			return dataCell;
		}

		private IDataCell CreateCellDataForSTP(string value, DataCellInfo cell, bool forLastRow)
		{
			if (forLastRow)
			{
				return CreateEmptyCellData(DataRow.StringType, isEditable: false, cell);
			}
			IDataCell dataCell = CreateEmptyCellData(DataRow.StringType, isEditable: true, cell);
			dataCell.Value = value;
			return dataCell;
		}

		private IDataCell CreateEmptyCellData(Type cellValueType, bool isEditable, DataCellInfo cell)
		{
			IDataCell dataCell = DataRow.CreateDataCell(null, !isEditable, null, CellUIType.Unknown, null, null, cellValueType);
			if (isEditable)
			{
				TdCellMetadata tdCellMetadata = new TdCellMetadata(cell, dataCell);
				tdCellMetadata.CellMetadataQueried += metadata_CellMetadataQueried;
				tdCellMetadata.ValueChanged += metadata_ValueChanged;
				dataCell.Tag = tdCellMetadata;
				if (cellValueType == DataRow.DoubleType)
				{
					dataCell.EditTemplate = TdCellMetadata.AesXamComboEditorTemplateForNumber;
				}
				else
				{
					dataCell.EditTemplate = TdCellMetadata.AesXamComboEditorTemplateForText;
				}
				dataCell.ShouldEnterEditModeWhenFocused = true;
				dataCell.Foreground = Brushes.Blue;
			}
			return dataCell;
		}

		private void metadata_CellMetadataQueried(object sender, CellMetadataQueriedEventArgs e)
		{
			TdCellMetadata metadata = sender as TdCellMetadata;
			TdGridColumn tdGridColumn = metadata.CellInfo.Column as TdGridColumn;
			TdGridRow tdGridRow = metadata.CellInfo.Row as TdGridRow;
			if (tdGridColumn == null || tdGridRow == null)
			{
				return;
			}
			bool flag = tdGridRow.RowIndex == gc.DataSource.Rows.Count - 1;
			switch (tdGridColumn.ColumnType)
			{
			case TdpcColumnType.ComponentI:
				e.AddRange(_wrapper.GetComponentListI());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.ComponentJ:
				e.AddRange(_wrapper.GetComponentListJ());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.Source:
				e.AddRange(_wrapper.GetSourceList(tdGridRow.RowIndex));
				if (metadata.CellData != null && !string.IsNullOrEmpty(metadata.CellData.ValueAsString) && !e.Values.Any((TdValueItem x) => string.Equals(x.Value, metadata.CellData.ValueAsString, StringComparison.CurrentCultureIgnoreCase)))
				{
					e.Values.Insert(0, new TdValueItem(metadata.CellData.ValueAsString));
				}
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.TemperatureUnits:
				e.AddRange(_wrapper.GetTemperatureUnitsList());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.PropertyUnits:
				e.AddRange(_wrapper.GetPropertyUnitsList());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			}
		}

		private void metadata_ValueChanged(object sender, CellMetadataValueChangedEventArgs e)
		{
			TdCellMetadata tdCellMetadata = sender as TdCellMetadata;
			TdGridColumn tdGridColumn = tdCellMetadata.CellInfo.Column as TdGridColumn;
			TdGridRow tdGridRow = tdCellMetadata.CellInfo.Row as TdGridRow;
			if (tdGridColumn != null && tdGridRow != null && tdGridColumn.ColumnType != TdpcColumnType.Value)
			{
				IDataCell dataCell = tdGridRow[tdGridColumn];
				if (dataCell != null && dataCell.HostControl != null)
				{
					dataCell.HostControl.EndEditModeIfPossible(commitChange: true);
				}
				CommitChange(tdGridColumn, tdGridRow, tdCellMetadata.SelectedItem);
			}
		}

		private void CommitChange(TdGridColumn column, TdGridRow row, string newValue)
		{
			UpdatingResult updatingResult = null;
			switch (column.ColumnType)
			{
			case TdpcColumnType.ComponentI:
				updatingResult = _wrapper.UpdateComponentI(row.RowIndex, newValue);
				break;
			case TdpcColumnType.ComponentJ:
				updatingResult = _wrapper.UpdateComponentJ(row.RowIndex, newValue);
				break;
			case TdpcColumnType.Source:
				updatingResult = UpdateSource(column, row, newValue);
				break;
			case TdpcColumnType.TemperatureUnits:
				updatingResult = _wrapper.UpdateTemperatureUnit(row.RowIndex, newValue);
				break;
			case TdpcColumnType.PropertyUnits:
				updatingResult = _wrapper.UpdatePropertyUnit(row.RowIndex, newValue);
				break;
			case TdpcColumnType.Value:
				updatingResult = UpdateValue(column, row, newValue);
				break;
			}
			if (updatingResult != null)
			{
				if (!updatingResult.Succeeded && !string.IsNullOrEmpty(updatingResult.ErrorMessage) && (!_isPastingData || column.ColumnType != TdpcColumnType.Source))
				{
					DispatcherShowErrorMessage(updatingResult.ErrorMessage);
				}
				base.Dispatcher.BeginInvokeOnce(PublishUpdateDisplayEvent);
			}
		}

		private UpdatingResult UpdateSource(TdGridColumn sourceColumn, TdGridRow row, string newValue)
		{
			return _wrapper.UpdateSource(row.RowIndex, newValue);
		}

		private UpdatingResult UpdateValue(TdGridColumn valueColumn, TdGridRow row, string newValue)
		{
			if (double.TryParse(newValue, out var result))
			{
				newValue = result.ToString(CultureInfo.InvariantCulture);
			}
			UpdatingResult updatingResult = _wrapper.UpdateValue(row.RowIndex, valueColumn.ValueIndex.GetValueOrDefault(), TdpcGridHelpers.ExtractDoubleValue(newValue));
			if (updatingResult.Succeeded && row.DataTable.Columns.FirstOrDefault((DataColumn x) => ((TdGridColumn)x).ColumnType == TdpcColumnType.Source) is TdGridColumn index && row[index]?.Tag is TdCellMetadata tdCellMetadata)
			{
				tdCellMetadata.EnsureBuiltUp();
				if (tdCellMetadata.ItemsSource != null)
				{
					string text = tdCellMetadata.ItemsSource.FirstOrDefault((string x) => x.Equals("USER", StringComparison.CurrentCultureIgnoreCase));
					if (text != null)
					{
						_wrapper.UpdateSource(row.RowIndex, text);
					}
				}
			}
			return updatingResult;
		}

		private void DispatcherShowErrorMessage(string errorMessage)
		{
			if (!string.IsNullOrEmpty(errorMessage) && !_errorMessages.Contains(errorMessage))
			{
				_errorMessages.Add(errorMessage);
			}
			if (_showErrMsgOperation != null)
			{
				return;
			}
			_showErrMsgOperation = base.Dispatcher.BeginInvoke((Action)delegate
			{
				try
				{
					if (_errorMessages.Count > 0)
					{
						StringBuilder stringBuilder = new StringBuilder();
						foreach (string errorMessage2 in _errorMessages)
						{
							stringBuilder.AppendLine(errorMessage2);
						}
						_errorMessages.Clear();
						AesMessageBox.Show(Window.GetWindow(this), stringBuilder.ToString(), SystemEnvironment.ApplicationName, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
					}
				}
				finally
				{
					_showErrMsgOperation = null;
				}
			});
		}

		private void gc_CellValueChanged(object sender, CellValueChangedEventArgs e)
		{
			if (e.Data != null)
			{
				CommitChange(e.Data.Column as TdGridColumn, e.Data.Row as TdGridRow, (e.NewValue == null) ? null : e.NewValue.ToString());
			}
		}

		private void gc_CellValueLoaded(object sender, CellValueLoadedEventArgs e)
		{
			IDataCell cell = e.Cell;
			TdGridColumn tdGridColumn = cell.Column as TdGridColumn;
			TdGridRow tdGridRow = cell.Row as TdGridRow;
			if (tdGridColumn != null && tdGridRow != null && tdGridRow.RowIndex != gc.DataSource.Rows.Count - 1)
			{
				switch (tdGridColumn.ColumnType)
				{
				case TdpcColumnType.ComponentI:
					UpdateCellAttributes(cell, _wrapper.IsDefaultComponentIValue(tdGridRow.RowIndex));
					break;
				case TdpcColumnType.ComponentJ:
					UpdateCellAttributes(cell, _wrapper.IsDefaultComponentJValue(tdGridRow.RowIndex));
					break;
				case TdpcColumnType.Source:
					UpdateCellAttributes(cell, _wrapper.IsDefaultSourceValue(tdGridRow.RowIndex));
					break;
				case TdpcColumnType.TemperatureUnits:
					UpdateCellAttributes(cell, _wrapper.IsDefaultTemperatureUnitValue(tdGridRow.RowIndex));
					break;
				case TdpcColumnType.PropertyUnits:
					UpdateCellAttributes(cell, _wrapper.IsDefaultPropertyUnitValue(tdGridRow.RowIndex));
					break;
				case TdpcColumnType.Value:
					UpdateCellAttributes(cell, _wrapper.IsDefaultValueValue(tdGridRow.RowIndex, tdGridColumn.ValueIndex.GetValueOrDefault()));
					break;
				}
			}
		}

		private void UpdateCellAttributes(IDataCell cell, bool isDefault)
		{
			cell.FontWeight = (isDefault ? FontWeights.Normal : FontWeights.Bold);
			cell.FontStyle = (isDefault ? FontStyles.Italic : FontStyles.Normal);
		}

		private void gc_CellTooltipChecking(object sender, GridControlCellEventArgs e)
		{
			IDataCell cell = e.GridControlCell.Cell;
			if (cell == null)
			{
				return;
			}
			TdGridColumn tdGridColumn = cell.Column as TdGridColumn;
			TdGridRow tdGridRow = cell.Row as TdGridRow;
			if (tdGridColumn != null && tdGridRow != null && tdGridRow.RowIndex != gc.DataSource.Rows.Count - 1)
			{
				switch (tdGridColumn.ColumnType)
				{
				case TdpcColumnType.ComponentI:
					cell.Tooltip = _wrapper.GetComponentIDescription(tdGridRow.RowIndex);
					break;
				case TdpcColumnType.ComponentJ:
					cell.Tooltip = _wrapper.GetComponentJDescription(tdGridRow.RowIndex);
					break;
				case TdpcColumnType.Source:
					cell.Tooltip = _wrapper.GetSourceDescription(tdGridRow.RowIndex);
					break;
				case TdpcColumnType.TemperatureUnits:
					cell.Tooltip = _wrapper.GetTemperatureUnitDescription(tdGridRow.RowIndex);
					break;
				case TdpcColumnType.PropertyUnits:
					cell.Tooltip = _wrapper.GetPropertyUnitDescription(tdGridRow.RowIndex);
					break;
				case TdpcColumnType.Value:
					cell.Tooltip = _wrapper.GetValueDescription(tdGridRow.RowIndex, tdGridColumn.ValueIndex.GetValueOrDefault());
					break;
				}
			}
		}

		private void gc_CellControlEditModeChanged(object sender, GridControlCellEventArgs e)
		{
			IDataCell cell = e.GridControlCell.Cell;
			if (cell == null || !(cell.Tag is TdCellMetadata tdCellMetadata))
			{
				return;
			}
			try
			{
				if (e.GridControlCell.IsInEditMode)
				{
					tdCellMetadata.EnsureBuiltUp();
					return;
				}
				TdGridColumn tdGridColumn = tdCellMetadata.CellInfo.Column as TdGridColumn;
				TdGridRow tdGridRow = tdCellMetadata.CellInfo.Row as TdGridRow;
				if (tdGridColumn != null && tdGridRow != null && tdGridColumn.ColumnType == TdpcColumnType.Value && tdCellMetadata.HasSelectedItemEverChanged)
				{
					CommitChange(tdGridColumn, tdGridRow, tdCellMetadata.SelectedItem);
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message, Category.Exception, Priority.High);
			}
		}

		private void gc_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
		{
			if (e.DefaultContextMenu.Items.Count > 0)
			{
				e.DefaultContextMenu.Items.Insert(0, new Separator());
			}
			e.DefaultContextMenu.Items.Add(new MenuItem
			{
				Icon = new Image
				{
					Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = e.GridControl
			});
			if (e.IsOpenFromGridCell || e.IsOpenFromColumnHeader)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Paste16
					},
					Command = ApplicationCommands.Paste,
					CommandTarget = e.GridControl
				});
			}
			if (e.IsOpenFromGridCell)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("Clear16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strClear,
					Command = new RelayActionCommand(ClearValuesCommand_Executed, ClearValuesCommand_CanExecute)
				});
			}
			if (e.IsOpenFromRowHeader || (e.IsOpenFromGridCell && gc.SelectedColumns.Count() == 0))
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("DeleteRow16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRecord,
					Command = new RelayActionCommand(DeleteRecordCommand_Executed, DeleteRecordCommand_CanExecute)
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("InsertRow16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertRecord,
					Command = new RelayActionCommand(InsertRecordCommand_Executed, InsertRecordCommand_CanExecute)
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strReorderRecord,
					Command = new RelayActionCommand(ReorderRecordCommand_Executed, ReorderRecordCommand_CanExecute)
				});
			}
		}

		private void ClearValuesCommand_Executed()
		{
			try
			{
				int lastRowIndex = gc.DataSource.Rows.Count - 1;
				if (gc.IsAllSelected)
				{
					List<int> list = (from x in gc.DataSource.Rows.OfType<TdGridRow>()
						where x.RowIndex != lastRowIndex
						select x.RowIndex).ToList();
					if (list.Count <= 0)
					{
						return;
					}
					AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
					if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
					{
						return;
					}
					UpdatingResult updatingResult = null;
					Cursor overrideCursor = Mouse.OverrideCursor;
					try
					{
						Mouse.OverrideCursor = Cursors.Wait;
						updatingResult = _wrapper.DeleteRecords(list);
					}
					finally
					{
						Mouse.OverrideCursor = overrideCursor;
					}
					if (updatingResult != null)
					{
						if (updatingResult.Succeeded)
						{
							PublishUpdateDisplayEvent();
						}
						else
						{
							AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
						}
					}
					return;
				}
				foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
				{
					if ((totalSelectedCell.Row as TdGridRow).RowIndex != lastRowIndex && totalSelectedCell.Data != null && !totalSelectedCell.Data.IsReadOnly)
					{
						totalSelectedCell.Data.ClearValue();
					}
				}
				PublishUpdateDisplayEvent();
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message, Category.Exception, Priority.High);
			}
		}

