		private void DeleteRecordCommand_Executed()
		{
			List<int> list = new List<int>();
			int num = gc.DataSource.Rows.Count - 1;
			foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
			{
				TdGridRow tdGridRow = totalSelectedCell.Row as TdGridRow;
				if (tdGridRow.RowIndex != num && !list.Contains(tdGridRow.RowIndex))
				{
					list.Add(tdGridRow.RowIndex);
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
			{
				return;
			}
			UpdatingResult updatingResult = null;
			Cursor overrideCursor = Mouse.OverrideCursor;
			try
			{
				Mouse.OverrideCursor = Cursors.Wait;
				updatingResult = _wrapper.DeleteRecords(list);
			}
			finally
			{
				Mouse.OverrideCursor = overrideCursor;
			}
			if (updatingResult != null)
			{
				if (updatingResult.Succeeded)
				{
					gc.DeselectAll();
					PublishUpdateDisplayEvent();
				}
				else
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
				}
			}
		}

