		{
			if (gc == null)
			{
				return false;
			}
			if (gc.DataSource == null)
			{
				return false;
			}
			if (gc.DataSource.Rows.Count <= 0)
			{
				return false;
			}
			if (_wrapper == null)
			{
				return false;
			}
			return true;
