		private void Gc_DataPasting(object sender, GridControlPastingEventArgs e)
		{
			DataCellInfo dataCellInfo = gc.TotalOrderedSelectedCells.FirstOrDefault();
			if (!dataCellInfo.IsEmpty)
			{
				_isPastingData = true;
				int num = gc.DataSource.Rows.IndexOf(dataCellInfo.Row) + e.PastingData.Count - gc.DataSource.Rows.Count + 1;
				int num2 = gc.DataSource.Rows.Count - 1;
				for (int i = 0; i < num; i++)
				{
					_wrapper.InsertNewReocrd(num2 + i);
				}
				if (num > 0)
				{
					TryRefreshData();
					e.TryOnceMoreAfterRender = true;
					e.ShouldDelayPasting = true;
				}
				base.Dispatcher.BeginInvoke((Action)delegate
				{
					_isPastingData = false;
				}, DispatcherPriority.Input);
			}
		}

		private void gc_SelectionChanged(object sender, RoutedEventArgs e)
		{
			List<int> list = new List<int>();
			foreach (DataRow selectedRow in gc.SelectedRows)
			{
				if (selectedRow is TdGridRow)
				{
					int rowIndex = (selectedRow as TdGridRow).RowIndex;
					list.Add(rowIndex);
				}
			}
			if (SelectedRowIndexes == null)
			{
				SelectedRowIndexes = new ObservableCollection<int>(list);
			}
			else if (!list.SequenceEqual(SelectedRowIndexes))
			{
				SelectedRowIndexes = new ObservableCollection<int>(list);
			}
			if (list.Count > 1)
			{
				ValidOneRowIndex = -1;
				return;
			}
			if (gc.SelectedCells.Count() < 1)
			{
				ValidOneRowIndex = -1;
				return;
			}
			List<int> list2 = new List<int>();
			foreach (DataCellInfo selectedCell in gc.SelectedCells)
			{
				if (selectedCell.Row is TdGridRow)
				{
					int rowIndex2 = (selectedCell.Row as TdGridRow).RowIndex;
					if (!list2.Contains(rowIndex2))
					{
						list2.Add(rowIndex2);
					}
					if (list2.Count > 1)
					{
						ValidOneRowIndex = -1;
						return;
					}
				}
			}
			ValidOneRowIndex = ((list2.Count == 1) ? list2[0] : (-1));
		}

		private string GetCxsMonikerForCopy(DataCellInfo cell)
		{
			TdGridColumn tdGridColumn = cell.Column as TdGridColumn;
			TdGridRow tdGridRow = cell.Row as TdGridRow;
			if (tdGridColumn.ColumnType == TdpcColumnType.ComponentI)
			{
				return $"cxs:{_mainNodePath}.Input.{tdGridColumn.GetRecordName()}.{_parameterMethod}.#{tdGridRow.RowIndex}";
			}
			return $"cxs:{_mainNodePath}.Input.{tdGridColumn.GetRecordName()}.{_parameterMethod}.#{tdGridRow.RowIndex}.#0";
		}

		private string GetCellTextForCopy(DataCellInfo cell)
		{
			if (cell.Data != null)
			{
				return cell.Data.ValueAsString;
			}
			return null;
		}

		public void InitializeWithParentViewModel(TDependentBinaryInteraction_ViewModel vm)
		{
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			_vm = vm;
			_mainNodePath = vm.ExpandDataPath("@main");
			_ihNode = _vm.UnityContainer.GetNode(_mainNodePath);
			_wrapper = new TDependentBinaryInteractionWrapper(_ihNode);
			string text = vm.ExpandDataPathAndGet("@main.Input.SETNO.#0", "id") as string;
			if (!string.IsNullOrEmpty(text))
			{
				_parameterMethod = text.ToUpperInvariant();
			}
			SetBinding(SelectedRowIndexesProperty, new Binding("SelectedFieldIndexes")
			{
				Source = vm,
				Mode = BindingMode.TwoWay
			});
			SetBinding(ValidOneRowIndexProperty, new Binding("ValidOneRowIndex")
			{
				Source = vm,
				Mode = BindingMode.TwoWay
			});
			InvalidateData();
		}

