		{
			_wrapper?.UnloadMe();
		}

		public int? FindComponentsPosition(string componentI, string componentJ)
		{
			if (gc != null && gc.DataSource != null)
			{
				for (int i = 0; i < gc.DataSource.Rows.Count; i++)
				{
					DataRow dataRow = gc.DataSource.Rows[i];
					if (string.Equals(dataRow[0]?.ValueAsString, componentI, StringComparison.CurrentCulture) && string.Equals(dataRow[1]?.ValueAsString, componentJ, StringComparison.CurrentCulture))
					{
						return i;
					}
				}
			}
			return null;
		}

		public void ScrollIntoView(int rowIndex)
		{
			if (gc != null && gc.DataSource != null && gc.DataSource.Rows.Count > rowIndex)
			{
				gc.ScrollIntoView(gc.DataSource.Rows[rowIndex]);
			}
		}

		private void InvalidateData()
		{
			if (_refreshDataOperation != null)
			{
				return;
			}
			_refreshDataOperation = base.Dispatcher.BeginInvoke((Action)delegate
			{
				try
				{
					TryRefreshData();
				}
				finally
				{
					_refreshDataOperation = null;
				}
			});
		}

		private void PublishUpdateDisplayEvent()
		{
			TDependentBinaryInteraction_ViewModel vm = _vm;
			if (vm != null)
			{
				IUnityContainer unityContainer = vm.UnityContainer;
				if (unityContainer != null)
				{
					UnityContainerHelper.TryResolve<IEventAggregator>(unityContainer)?.GetEvent<UpdateDisplayEvent>().Publish(new UpdateDisplayEventArgs());
				}
			}
		}

		private void TryRefreshData()
		{
			if (_vm != null)
			{
				DataTable dataTable = EnsureDataTable();
				gc.DataSource = dataTable;
				int rowsCount = _wrapper.GetRowsCount();
				if (dataTable.Rows.Count != rowsCount)
				{
					dataTable.UpdateRows(rowsCount, GenerateDataRow);
				}
				else
				{
					dataTable.RefreshData();
				}
			}
		}

		private DataTable EnsureDataTable()
		{
			DataTable dataTable = gc.DataSource;
			Dictionary<int, string> valueIndexes = GetValueIndexes();
			if (dataTable == null)
			{
				dataTable = new DataTable(RebuildDataColumns(valueIndexes));
			}
			else
			{
				IEnumerable<int> second = from TdGridColumn x in dataTable.Columns
					where x.ColumnType == TdpcColumnType.Value
					select x.ValueIndex.GetValueOrDefault();
				if (!valueIndexes.Keys.SequenceEqual(second))
				{
					dataTable = new DataTable(RebuildDataColumns(valueIndexes));
				}
			}
			return dataTable;
		}

		private Dictionary<int, string> GetValueIndexes()
		{
			Dictionary<int, string> dictionary = new Dictionary<int, string>();
			for (int i = 0; i < 12; i++)
			{
				string dataPath = $"@main.Input.LABEL{i + 1}.{_parameterMethod}";
				string text = _vm.ExpandDataPathAndGet(dataPath, "value") as string;
				if (!string.IsNullOrEmpty(text))
				{
					dictionary.Add(i, text.ToUpperInvariant());
				}
			}
			return dictionary;
		}

		private IEnumerable<DataColumn> RebuildDataColumns(Dictionary<int, string> valueColumns)
		{
			List<DataColumn> list = new List<DataColumn>();
			string parameterMethod = _parameterMethod;
			string header = ApwnResources.MMResults_BinaryTDep_MMFText0;
			string header2 = ApwnResources.MMResults_BinaryTDep_MMFText1;
			if (parameterMethod == "HENRY")
			{
				header = ApwnResources.MMResults_BinaryTDep_Solute;
				header2 = ApwnResources.MMResults_BinaryTDep_Solvent;
			}
			list.Add(new TdGridColumn(TdpcColumnType.ComponentI, header, DataRow.StringType, 120.0));
			list.Add(new TdGridColumn(TdpcColumnType.ComponentJ, header2, DataRow.StringType, 120.0));
			list.Add(new TdGridColumn(TdpcColumnType.Source, ApwnResources.MMParam_Bi_Cor_Inp_Param_MMFLabel3, DataRow.StringType, 120.0));
			list.Add(new TdGridColumn(TdpcColumnType.TemperatureUnits, ApwnResources.MMParam_PureCor_In_Para_MMFLabel1, DataRow.StringType, 100.0));
			if (IsHenryOrVlclkParameter)
			{
				list.Add(new TdGridColumn(TdpcColumnType.PropertyUnits, ApwnResources.MMParam_PureCor_In_Para_MMFLabel2, DataRow.StringType, 100.0));
			}
			foreach (int key in valueColumns.Keys)
			{
				list.Add(TdGridColumn.CreateValueColumn(key, valueColumns[key]));
			}
			return list;
		}

		private DataRow GenerateDataRow(int rowIndex)
		{
			return new TdGridRow(gc.DataSource, rowIndex);
		}

