	public class TDependentPureComponentGrid : UserControl, IComponentConnector
	{
		private enum TdpcColumnType
		{
			Component,
			Source,
			TemperatureUnits,
			PropertyUnits,
			Value
		}

		private class TdpcGridColumn : DataColumn
		{
			public TdpcColumnType ColumnType { get; private set; }

			public int? ValueIndex { get; private set; }

			public TdpcGridColumn(TdpcColumnType columnType, string header, Type defaultDataType = null, double? width = null)
			{
				ColumnType = columnType;
				base.Header = header;
				base.DefaultDataType = defaultDataType;
				base.Width = width;
			}

			public string GetRecordName()
			{
				return ColumnType switch
				{
					TdpcColumnType.Component => "VAL1", 
					TdpcColumnType.Source => "DBANK", 
					TdpcColumnType.TemperatureUnits => "TUNITLABEL2", 
					TdpcColumnType.PropertyUnits => "UNITLABEL2", 
					_ => $"VAL{ValueIndex.GetValueOrDefault() + 1}", 
				};
			}

			public static TdpcGridColumn CreateValueColumn(int valueIndex)
			{
				return new TdpcGridColumn(TdpcColumnType.Value, GetValueColumnHeader(valueIndex), DataRow.DoubleType)
				{
					ValueIndex = valueIndex,
					Width = 100.0
				};
			}

			private static string GetValueColumnHeader(int valueIndex)
			{
				if (_userDefineHeaderList.Count > 0 && valueIndex < _userDefineHeaderList.Count)
				{
					return _userDefineHeaderList[valueIndex];
				}
				return GetDefaultColumnHeader(valueIndex);
			}

			private static string GetDefaultColumnHeader(int valueIndex)
			{
				return valueIndex switch
				{
					0 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel3, 
					1 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel4, 
					2 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel5, 
					3 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel6, 
					4 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel7, 
					5 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel8, 
					6 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel9, 
					7 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel10, 
					8 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel11, 
					9 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel12, 
					10 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel13, 
					11 => ApwnResources.MMParam_PureCor_In_Para_MMFLabel14, 
					_ => null, 
				};
			}
		}

		private class TdpcGridRow : DataRow
		{
			public int RowIndex { get; private set; }

			public TdpcGridRow(DataTable parentDataTable, int rowIndex)
				: base(parentDataTable)
