		private TDependentPureComponent_ViewModel _vm;

		private TDependentPureComponentWrapper _wrapper;

		private DispatcherOperation _refreshDataOperation;

		private string _mainNodePath;

		private IHNode _ihNode;

		private bool _isPastingData;

		private static List<string> _userDefineHeaderList = new List<string>();

		private DispatcherOperation _showErrMsgOperation;

		private readonly List<string> _errorMessages = new List<string>();

		internal GridControl gc;

		private bool _contentLoaded;

		public TDependentPureComponentGrid()
		{
			InitializeComponent();
			gc.CellValueQueried += gc_CellValueQueried;
			gc.CellValueChanged += gc_CellValueChanged;
			gc.CellValueLoaded += gc_CellValueLoaded;
			gc.CellTooltipChecking += gc_CellTooltipChecking;
			gc.CellControlEditModeChanged += gc_CellControlEditModeChanged;
			gc.DefaultContextMenuOpening += gc_DefaultContextMenuOpening;
