		private void gc_CellValueQueried(object sender, CellValueQueriedEventArgs e)
		{
			TdpcGridColumn tdpcGridColumn = e.Column as TdpcGridColumn;
			TdpcGridRow tdpcGridRow = e.Row as TdpcGridRow;
			if (tdpcGridColumn == null || tdpcGridRow == null)
			{
				return;
			}
			bool flag = tdpcGridRow.RowIndex == gc.DataSource.Rows.Count - 1;
			DataCellInfo cell = new DataCellInfo(tdpcGridRow, tdpcGridColumn);
			switch (tdpcGridColumn.ColumnType)
			{
			case TdpcColumnType.Component:
			{
				IDataCell dataCell2 = CreateEmptyCellData(DataRow.StringType, isEditable: true, cell);
				if (!flag)
				{
					dataCell2.Value = _wrapper.GetComponentValue(tdpcGridRow.RowIndex);
				}
				e.Data = dataCell2;
				break;
			}
			case TdpcColumnType.Source:
			{
				if (flag)
				{
					e.Data = CreateCellDataForSTP(null, cell, forLastRow: true);
					break;
				}
				string source = _wrapper.GetSourceValue(tdpcGridRow.RowIndex);
				IDataCell dataCell3 = CreateCellDataForSTP(source, cell, forLastRow: false);
				IEnumerable<TdValueItem> sourceList = _wrapper.GetSourceList(tdpcGridRow.RowIndex);
				if (sourceList != null && sourceList.Any())
				{
					List<TdValueItem> source2 = sourceList.ToList();
					if (string.IsNullOrEmpty(source))
					{
						dataCell3.Value = source2.FirstOrDefault()?.Value;
					}
					else
					{
						TdValueItem tdValueItem = source2.FirstOrDefault((TdValueItem x) => x.Value != null && string.Equals(x.Value, source, StringComparison.CurrentCulture));
						if (tdValueItem == null)
						{
							tdValueItem = source2.FirstOrDefault((TdValueItem x) => x.Value != null && x.Value.EndsWith(source));
						}
						if (tdValueItem != null)
						{
							dataCell3.Value = tdValueItem.Value;
						}
					}
				}
				e.Data = dataCell3;
				break;
			}
			case TdpcColumnType.TemperatureUnits:
				e.Data = CreateCellDataForSTP(flag ? null : _wrapper.GetTemperatureUnitValue(tdpcGridRow.RowIndex), cell, flag);
				break;
			case TdpcColumnType.PropertyUnits:
				e.Data = CreateCellDataForSTP(flag ? null : _wrapper.GetPropertyUnitValue(tdpcGridRow.RowIndex), cell, flag);
				break;
			case TdpcColumnType.Value:
			{
				IDataCell dataCell = CreateEmptyCellData(DataRow.DoubleType, isEditable: true, cell);
				if (!flag)
				{
					dataCell.Value = _wrapper.GetValueValue(tdpcGridRow.RowIndex, tdpcGridColumn.ValueIndex.GetValueOrDefault());
				}
				e.Data = dataCell;
				break;
			}
			}
			if (e.Data != null && e.Data.Tag != null && gc.CurrentCell == new DataCellInfo(tdpcGridRow, tdpcGridColumn) && e.Data.Tag is TdCellMetadata tdCellMetadata)
			{
				tdCellMetadata.EnsureBuiltUp();
			}
		}

		private IDataCell CreateCellDataForSTP(string value, DataCellInfo cell, bool forLastRow)
		{
			if (forLastRow)
			{
				return CreateEmptyCellData(DataRow.StringType, isEditable: false, cell);
			}
			IDataCell dataCell = CreateEmptyCellData(DataRow.StringType, isEditable: true, cell);
			dataCell.Value = value;
			return dataCell;
		}

		private IDataCell CreateEmptyCellData(Type cellValueType, bool isEditable, DataCellInfo cell)
		{
			IDataCell dataCell = DataRow.CreateDataCell(null, !isEditable, null, CellUIType.Unknown, null, null, cellValueType);
			if (isEditable)
			{
				TdCellMetadata tdCellMetadata = new TdCellMetadata(cell, dataCell);
				tdCellMetadata.CellMetadataQueried += metadata_CellMetadataQueried;
				tdCellMetadata.ValueChanged += metadata_ValueChanged;
				dataCell.Tag = tdCellMetadata;
				dataCell.SetBinding("ItemsSource", new Binding("ItemsSource")
				{
					Source = tdCellMetadata,
					Mode = BindingMode.OneWay
				});
				if (cellValueType == DataRow.DoubleType)
				{
					dataCell.EditTemplate = TdCellMetadata.AesXamComboEditorTemplateForNumber;
				}
				else
				{
					dataCell.EditTemplate = TdCellMetadata.AesXamComboEditorTemplateForText;
				}
				dataCell.ShouldEnterEditModeWhenFocused = true;
				dataCell.Foreground = Brushes.Blue;
			}
			return dataCell;
		}

		private void metadata_CellMetadataQueried(object sender, CellMetadataQueriedEventArgs e)
		{
			TdCellMetadata metadata = sender as TdCellMetadata;
			TdpcGridColumn tdpcGridColumn = metadata.CellInfo.Column as TdpcGridColumn;
			TdpcGridRow tdpcGridRow = metadata.CellInfo.Row as TdpcGridRow;
			if (tdpcGridColumn == null || tdpcGridRow == null)
			{
				return;
			}
			bool flag = tdpcGridRow.RowIndex == gc.DataSource.Rows.Count - 1;
			switch (tdpcGridColumn.ColumnType)
			{
			case TdpcColumnType.Component:
				e.AddRange(_wrapper.GetComponentList());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.Source:
				e.AddRange(_wrapper.GetSourceList(tdpcGridRow.RowIndex));
				if (metadata.CellData != null && !string.IsNullOrEmpty(metadata.CellData.ValueAsString) && !e.Values.Any((TdValueItem x) => string.Equals(x.Value, metadata.CellData.ValueAsString)))
				{
					e.Values.Insert(0, new TdValueItem(metadata.CellData.ValueAsString));
				}
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.TemperatureUnits:
				e.AddRange(_wrapper.GetTemperatureUnitsList());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.PropertyUnits:
				e.AddRange(_wrapper.GetPropertyUnitsList());
				if (!flag)
				{
					e.UpdateSelectedValue(metadata.CellData.ValueAsString);
				}
				break;
			case TdpcColumnType.Value:
				if (!flag)
				{
					e.AddRange(_wrapper.GetValuesList(tdpcGridRow.RowIndex, tdpcGridColumn.ValueIndex.GetValueOrDefault()));
					e.UpdateSelectedValue(_wrapper.GetValueValue(tdpcGridRow.RowIndex, tdpcGridColumn.ValueIndex.GetValueOrDefault()));
				}
				break;
			}
		}

		private void metadata_ValueChanged(object sender, CellMetadataValueChangedEventArgs e)
		{
			TdCellMetadata tdCellMetadata = sender as TdCellMetadata;
			TdpcGridColumn tdpcGridColumn = tdCellMetadata.CellInfo.Column as TdpcGridColumn;
			TdpcGridRow tdpcGridRow = tdCellMetadata.CellInfo.Row as TdpcGridRow;
			if (tdpcGridColumn != null && tdpcGridRow != null && tdpcGridColumn.ColumnType != TdpcColumnType.Value)
			{
				IDataCell dataCell = tdpcGridRow[tdpcGridColumn];
				if (dataCell != null && dataCell.HostControl != null)
				{
					dataCell.HostControl.EndEditModeIfPossible(commitChange: true);
				}
				CommitChange(tdpcGridColumn, tdpcGridRow, tdCellMetadata.SelectedItem);
			}
		}

		private void CommitChange(TdpcGridColumn column, TdpcGridRow row, string newValue)
		{
			UpdatingResult updatingResult = null;
			switch (column.ColumnType)
			{
			case TdpcColumnType.Component:
				updatingResult = UpdateComponent(row, newValue);
				break;
			case TdpcColumnType.Source:
				updatingResult = UpdateSource(column, row, newValue);
				break;
			case TdpcColumnType.TemperatureUnits:
				updatingResult = _wrapper.UpdateTemperatureUnit(row.RowIndex, newValue);
				break;
			case TdpcColumnType.PropertyUnits:
				updatingResult = _wrapper.UpdatePropertyUnit(row.RowIndex, newValue);
				break;
			case TdpcColumnType.Value:
				updatingResult = UpdateValue(column, row, newValue);
				break;
			}
			if (updatingResult != null)
			{
				if (!updatingResult.Succeeded && !string.IsNullOrEmpty(updatingResult.ErrorMessage) && (!_isPastingData || column.ColumnType != TdpcColumnType.Source))
				{
					DispatcherShowErrorMessage(updatingResult.ErrorMessage);
				}
				base.Dispatcher.BeginInvokeOnce(PublishUpdateDisplayEvent);
			}
		}

		private UpdatingResult UpdateComponent(TdpcGridRow row, string newValue)
		{
			UpdatingResult updatingResult = _wrapper.UpdateComponent(row.RowIndex, newValue);
			if (updatingResult.Succeeded && row.DataTable.Columns.FirstOrDefault((DataColumn x) => ((TdpcGridColumn)x).ColumnType == TdpcColumnType.Source) is TdpcGridColumn index)
			{
				string a = row[index]?.ValueAsString;
				row.ClearData();
				IDataCell dataCell = row[index];
				string text = dataCell?.ValueAsString;
				if (dataCell != null && !string.IsNullOrEmpty(text) && !string.Equals(a, text, StringComparison.CurrentCulture) && dataCell.Tag is TdCellMetadata tdCellMetadata)
				{
					tdCellMetadata.EnsureBuiltUp();
					if (tdCellMetadata.ItemsSource != null)
					{
						SyncValueColumnsForSource(row, text, 0);
					}
				}
			}
			return updatingResult;
		}

		private UpdatingResult UpdateSource(TdpcGridColumn sourceColumn, TdpcGridRow row, string newValue)
		{
			UpdatingResult updatingResult = _wrapper.UpdateSource(row.RowIndex, newValue);
			if (updatingResult.Succeeded && row[sourceColumn]?.Tag is TdCellMetadata { ItemsSource: not null } && !string.IsNullOrEmpty(newValue))
			{
				SyncValueColumnsForSource(row, newValue, 1);
			}
			return updatingResult;
		}

		private void SyncValueColumnsForSource(TdpcGridRow row, string newSource, int flag)
		{
			foreach (TdpcGridColumn column in row.DataTable.Columns)
			{
				if (column.ColumnType != TdpcColumnType.Value || !(row[column]?.Tag is TdCellMetadata tdCellMetadata))
				{
					continue;
				}
				tdCellMetadata.EnsureBuiltUp();
				if (tdCellMetadata.ItemsSource != null)
				{
					string value = tdCellMetadata.ItemsSource.FirstOrDefault((string x) => x.EndsWith(newSource, StringComparison.CurrentCultureIgnoreCase));
					if (!string.IsNullOrEmpty(value) && flag == 1)
					{
						_wrapper.UpdateValue(row.RowIndex, column.ValueIndex.GetValueOrDefault(), value);
					}
				}
			}
		}

		private UpdatingResult UpdateValue(TdpcGridColumn valueColumn, TdpcGridRow row, string newValue)
		{
			if (double.TryParse(newValue, out var result))
			{
				newValue = result.ToString(CultureInfo.InvariantCulture);
			}
			UpdatingResult updatingResult = _wrapper.UpdateValue(row.RowIndex, valueColumn.ValueIndex.GetValueOrDefault(), newValue);
			if (updatingResult.Succeeded && row.DataTable.Columns.FirstOrDefault((DataColumn x) => ((TdpcGridColumn)x).ColumnType == TdpcColumnType.Source) is TdpcGridColumn index && row[index]?.Tag is TdCellMetadata tdCellMetadata)
			{
				tdCellMetadata.EnsureBuiltUp();
				if (tdCellMetadata.ItemsSource != null)
				{
					string text = TdpcGridHelpers.ExtracDBValue(newValue);
					if (text != null)
					{
						_wrapper.UpdateSource(row.RowIndex, text);
						return updatingResult;
					}
					string text2 = tdCellMetadata.ItemsSource.FirstOrDefault((string x) => string.Equals(x, "USER", StringComparison.CurrentCultureIgnoreCase));
					if (text2 != null)
					{
						_wrapper.UpdateSource(row.RowIndex, text2);
					}
				}
			}
			return updatingResult;
		}

		private void PublishUpdateDisplayEvent()
		{
			TDependentPureComponent_ViewModel vm = _vm;
			if (vm != null)
			{
				IUnityContainer unityContainer = vm.UnityContainer;
				if (unityContainer != null)
				{
					CxvUnityContainerExtensions.TryResolve<IEventAggregator>(unityContainer)?.GetEvent<UpdateDisplayEvent>().Publish(new UpdateDisplayEventArgs());
				}
			}
		}

		private void DispatcherShowErrorMessage(string errorMessage)
		{
			if (!string.IsNullOrEmpty(errorMessage) && !_errorMessages.Contains(errorMessage))
			{
				_errorMessages.Add(errorMessage);
			}
			if (_showErrMsgOperation != null)
			{
				return;
			}
			_showErrMsgOperation = base.Dispatcher.BeginInvoke((Action)delegate
			{
				try
				{
					if (_errorMessages.Count > 0)
					{
						StringBuilder stringBuilder = new StringBuilder();
						foreach (string errorMessage2 in _errorMessages)
						{
							stringBuilder.AppendLine(errorMessage2);
						}
						_errorMessages.Clear();
						AesMessageBox.Show(Window.GetWindow(this), stringBuilder.ToString(), SystemEnvironment.ApplicationName, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
					}
				}
				finally
				{
					_showErrMsgOperation = null;
				}
			});
		}

		private void gc_CellValueChanged(object sender, CellValueChangedEventArgs e)
		{
			if (e.Data != null)
			{
				CommitChange(e.Data.Column as TdpcGridColumn, e.Data.Row as TdpcGridRow, (e.NewValue == null) ? null : e.NewValue.ToString());
			}
		}

		private void gc_CellValueLoaded(object sender, CellValueLoadedEventArgs e)
		{
			UpdateCellAttributes(e.Cell);
		}

		private void UpdateCellAttributes(IDataCell cd)
		{
			TdpcGridColumn tdpcGridColumn = cd.Column as TdpcGridColumn;
			TdpcGridRow tdpcGridRow = cd.Row as TdpcGridRow;
			if (tdpcGridColumn != null && tdpcGridRow != null && tdpcGridRow.RowIndex != gc.DataSource.Rows.Count - 1)
			{
				switch (tdpcGridColumn.ColumnType)
				{
				case TdpcColumnType.Component:
					UpdateCellIsDefault(cd, _wrapper.IsDefaultComponentValue(tdpcGridRow.RowIndex));
					break;
				case TdpcColumnType.Source:
					UpdateCellIsDefault(cd, _wrapper.IsDefaultSourceValue(tdpcGridRow.RowIndex));
					break;
				case TdpcColumnType.TemperatureUnits:
					UpdateCellIsDefault(cd, _wrapper.IsDefaultTemperatureUnitValue(tdpcGridRow.RowIndex));
					break;
				case TdpcColumnType.PropertyUnits:
					UpdateCellIsDefault(cd, _wrapper.IsDefaultPropertyUnitValue(tdpcGridRow.RowIndex));
					break;
				case TdpcColumnType.Value:
					UpdateCellIsDefault(cd, _wrapper.IsDefaultValueValue(tdpcGridRow.RowIndex, tdpcGridColumn.ValueIndex.GetValueOrDefault()));
					break;
				}
			}
		}

		private void UpdateCellIsDefault(IDataCell cell, bool isDefault)
		{
			cell.FontWeight = (isDefault ? FontWeights.Normal : FontWeights.Bold);
			cell.FontStyle = (isDefault ? FontStyles.Italic : FontStyles.Normal);
		}

		private void gc_CellTooltipChecking(object sender, GridControlCellEventArgs e)
		{
			IDataCell cell = e.GridControlCell.Cell;
			if (cell == null)
			{
				return;
			}
			TdpcGridColumn tdpcGridColumn = cell.Column as TdpcGridColumn;
			TdpcGridRow tdpcGridRow = cell.Row as TdpcGridRow;
			if (tdpcGridColumn != null && tdpcGridRow != null && tdpcGridRow.RowIndex != gc.DataSource.Rows.Count - 1)
			{
				switch (tdpcGridColumn.ColumnType)
				{
				case TdpcColumnType.Component:
					cell.Tooltip = _wrapper.GetComponentDescription(tdpcGridRow.RowIndex);
					break;
				case TdpcColumnType.Source:
					cell.Tooltip = _wrapper.GetSourceDescription(tdpcGridRow.RowIndex);
					break;
				case TdpcColumnType.TemperatureUnits:
					cell.Tooltip = _wrapper.GetTemperatureUnitDescription(tdpcGridRow.RowIndex);
					break;
				case TdpcColumnType.PropertyUnits:
					cell.Tooltip = _wrapper.GetPropertyUnitDescription(tdpcGridRow.RowIndex);
					break;
				case TdpcColumnType.Value:
					cell.Tooltip = _wrapper.GetValueDescription(tdpcGridRow.RowIndex, tdpcGridColumn.ValueIndex.GetValueOrDefault());
					break;
				}
			}
		}

		private void gc_CellControlEditModeChanged(object sender, GridControlCellEventArgs e)
		{
			IDataCell cell = e.GridControlCell.Cell;
			if (cell == null || !(cell.Tag is TdCellMetadata tdCellMetadata))
			{
				return;
			}
			try
			{
				if (e.GridControlCell.IsInEditMode)
				{
					tdCellMetadata.EnsureBuiltUp();
					return;
				}
				TdpcGridColumn tdpcGridColumn = tdCellMetadata.CellInfo.Column as TdpcGridColumn;
				TdpcGridRow tdpcGridRow = tdCellMetadata.CellInfo.Row as TdpcGridRow;
				if (tdpcGridColumn != null && tdpcGridRow != null && tdpcGridColumn.ColumnType == TdpcColumnType.Value && tdCellMetadata.HasSelectedItemEverChanged)
				{
					CommitChange(tdpcGridColumn, tdpcGridRow, tdCellMetadata.SelectedItem);
				}
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message, Category.Exception, Priority.High);
			}
		}

		private void gc_DefaultContextMenuOpening(object sender, DefaultContextMenuEventArgs e)
		{
			if (e.DefaultContextMenu.Items.Count > 0)
			{
				e.DefaultContextMenu.Items.Insert(0, new Separator());
			}
			e.DefaultContextMenu.Items.Add(new MenuItem
			{
				Icon = new Image
				{
					Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Copy16
				},
				Command = ApplicationCommands.Copy,
				CommandTarget = e.GridControl
			});
			if (e.IsOpenFromGridCell || e.IsOpenFromColumnHeader)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = new Image
					{
						Source = AspenTech.Engineering.GridControls.Internal.ImageSourceHelper.Paste16
					},
					Command = ApplicationCommands.Paste,
					CommandTarget = e.GridControl
				});
			}
			if (e.IsOpenFromGridCell)
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("Clear16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strClear,
					Command = new RelayActionCommand(ClearValuesCommand_Executed, ClearValuesCommand_CanExecute)
				});
			}
			if (e.IsOpenFromRowHeader || (e.IsOpenFromGridCell && gc.SelectedColumns.Count() == 0))
			{
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("DeleteRow16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRecord,
					Command = new RelayActionCommand(DeleteRecordCommand_Executed, DeleteRecordCommand_CanExecute)
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Icon = GetContextItemIcon("InsertRow16.ico"),
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertRecord,
					Command = new RelayActionCommand(InsertRecordCommand_Executed, InsertRecordCommand_CanExecute)
				});
				e.DefaultContextMenu.Items.Add(new MenuItem
				{
					Header = AspenTech.AspenPlus.MMControls.Properties.Resources.strReorderRecord,
					Command = new RelayActionCommand(ReorderRecordCommand_Executed, ReorderRecordCommand_CanExecute)
				});
			}
		}

		private void ClearValuesCommand_Executed()
		{
			try
			{
				int lastRowIndex = gc.DataSource.Rows.Count - 1;
				if (gc.IsAllSelected)
				{
					List<int> list = (from x in gc.DataSource.Rows.OfType<TdpcGridRow>()
						where x.RowIndex != lastRowIndex
						select x.RowIndex).ToList();
					if (list.Count <= 0)
					{
						return;
					}
					AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
					if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
					{
						return;
					}
					UpdatingResult updatingResult = null;
					Cursor overrideCursor = Mouse.OverrideCursor;
					try
					{
						Mouse.OverrideCursor = Cursors.Wait;
						updatingResult = _wrapper.DeleteRecords(list);
					}
					finally
					{
						Mouse.OverrideCursor = overrideCursor;
					}
					if (updatingResult != null)
					{
						if (updatingResult.Succeeded)
						{
							PublishUpdateDisplayEvent();
						}
						else
						{
							AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
						}
					}
					return;
				}
				foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
				{
					if ((totalSelectedCell.Row as TdpcGridRow).RowIndex != lastRowIndex && totalSelectedCell.Data != null && !totalSelectedCell.Data.IsReadOnly && (totalSelectedCell.Column as TdpcGridColumn).ColumnType != TdpcColumnType.Source)
					{
						totalSelectedCell.Data.ClearValue();
					}
				}
				PublishUpdateDisplayEvent();
			}
			catch (Exception ex)
			{
				SystemEnvironment.Logger.Log(ex.Message, Category.Exception, Priority.High);
			}
		}

		private bool ClearValuesCommand_CanExecute()
		{
			if (!CanExecuteGeneralCheck())
			{
				return false;
			}
			int num = gc.DataSource.Rows.Count - 1;
			foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
			{
				TdpcGridRow obj = totalSelectedCell.Row as TdpcGridRow;
				TdpcGridColumn tdpcGridColumn = totalSelectedCell.Column as TdpcGridColumn;
				if (obj.RowIndex != num && tdpcGridColumn.ColumnType != TdpcColumnType.Source && tdpcGridColumn.ColumnType != TdpcColumnType.Component)
				{
					return true;
				}
			}
			return false;
		}

		private void DeleteRecordCommand_Executed()
		{
			List<int> list = new List<int>();
			int num = gc.DataSource.Rows.Count - 1;
			foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
			{
				TdpcGridRow tdpcGridRow = totalSelectedCell.Row as TdpcGridRow;
				if (tdpcGridRow.RowIndex != num && !list.Contains(tdpcGridRow.RowIndex))
				{
					list.Add(tdpcGridRow.RowIndex);
				}
			}
			if (list.Count <= 0)
			{
				return;
			}
			AesMessageBoxResult aesMessageBoxResult = AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strConfirmDeleteRecord, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.YesNo, AesMessageBoxImage.Question, showHelpButton: false, 2);
			if (aesMessageBoxResult == AesMessageBoxResult.No || aesMessageBoxResult == AesMessageBoxResult.Cancel)
			{
				return;
			}
			UpdatingResult updatingResult = null;
			Cursor overrideCursor = Mouse.OverrideCursor;
			try
			{
				Mouse.OverrideCursor = Cursors.Wait;
				updatingResult = _wrapper.DeleteRecords(list);
			}
			finally
			{
				Mouse.OverrideCursor = overrideCursor;
			}
			if (updatingResult != null)
			{
				if (updatingResult.Succeeded)
				{
					gc.DeselectAll();
					PublishUpdateDisplayEvent();
				}
				else
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.strDeleteRow, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
				}
			}
		}

		private bool DeleteRecordCommand_CanExecute()
		{
			if (!CanExecuteGeneralCheck())
			{
				return false;
			}
			return HasNoneEmptyRowSelected();
		}

		private void InsertRecordCommand_Executed()
		{
			DataRow dataRow = gc.SelectedRows.FirstOrDefault();
			if (dataRow == null)
			{
				using IEnumerator<DataCellInfo> enumerator = gc.TotalSelectedCells.GetEnumerator();
				if (enumerator.MoveNext())
				{
					dataRow = enumerator.Current.Row;
				}
			}
			if (dataRow == null)
			{
				return;
			}
			int rowIndex = (dataRow as TdpcGridRow).RowIndex;
			UpdatingResult updatingResult = null;
			Cursor overrideCursor = Mouse.OverrideCursor;
			try
			{
				Mouse.OverrideCursor = Cursors.Wait;
				updatingResult = _wrapper.InsertNewReocrd(rowIndex);
			}
			finally
			{
				Mouse.OverrideCursor = overrideCursor;
			}
			if (updatingResult != null)
			{
				if (updatingResult.Succeeded)
				{
					PublishUpdateDisplayEvent();
				}
				else
				{
					AesMessageBox.Show(AspenTech.AspenPlus.MMControls.Properties.Resources.strInsertRowFailed, AspenTech.AspenPlus.MMControls.Properties.Resources.DialogTitle_InsertRecord, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
				}
			}
		}

		private bool InsertRecordCommand_CanExecute()
		{
			if (!CanExecuteGeneralCheck())
			{
				return false;
			}
			if (gc.SelectedRows.Count() == 1)
			{
				return true;
			}
			List<DataRow> list = new List<DataRow>();
			foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
			{
				if (!list.Contains(totalSelectedCell.Row))
				{
					list.Add(totalSelectedCell.Row);
					if (list.Count >= 2)
					{
						break;
					}
				}
			}
			return list.Count == 1;
		}

		private void ReorderRecordCommand_Executed()
		{
			DataReorderWindow dataReorderWindow = new DataReorderWindow(gc.DataSource.Rows.Select((DataRow row) => row[0].ValueAsString));
			dataReorderWindow.Owner = Window.GetWindow(this);
			dataReorderWindow.ItemRecordered += dialog_ItemRecordered;
			dataReorderWindow.ShowDialog();
		}

		private void dialog_ItemRecordered(object sender, PositionChangedEventArgs e)
		{
			UpdatingResult updatingResult = _wrapper.ReorderRow(e.OldPosition, e.NewPosition);
			if (updatingResult != null && updatingResult.Succeeded)
			{
				PublishUpdateDisplayEvent();
			}
		}

		private bool ReorderRecordCommand_CanExecute()
		{
			if (!CanExecuteGeneralCheck())
			{
				return false;
			}
			if (gc.DataSource.Rows.Count <= 1)
			{
				return false;
			}
			return true;
		}

		private bool CanExecuteGeneralCheck()
		{
			if (gc == null)
			{
				return false;
			}
			if (gc.DataSource == null)
			{
				return false;
			}
			if (gc.DataSource.Rows.Count <= 0)
			{
				return false;
			}
			if (_wrapper == null)
			{
				return false;
			}
			return true;
		}

		private bool HasNoneEmptyRowSelected()
		{
			int num = gc.DataSource.Rows.Count - 1;
			foreach (DataCellInfo totalSelectedCell in gc.TotalSelectedCells)
			{
				if ((totalSelectedCell.Row as TdpcGridRow).RowIndex != num)
				{
					return true;
				}
			}
			return false;
		}

		private static Image GetContextItemIcon(string strImage)
		{
			Image image = new Image();
			string text = "pack://application:,,,/" + typeof(MMScrollAreaContextMenu).Assembly.FullName + ";component/Images/";
			image.Source = new BitmapImage(new Uri(text + strImage));
			return image;
		}

		private void gc_DataCopying(object sender, GridControlCopyEventArgs e)
		{
			GridControlClipboardHelper.DoDataCopy(gc, _vm, e, GetCxsMonikerForCopy, GetCellTextForCopy);
		}

		private void gc_DataDragging(object sender, GridControlDataDraggingEventArgs e)
		{
			GridControlClipboardHelper.DoDataDrag(gc, _vm, e, GetCxsMonikerForCopy, GetCellTextForCopy);
		}

		private void Gc_DataPasting(object sender, GridControlPastingEventArgs e)
		{
			DataCellInfo dataCellInfo = gc.TotalOrderedSelectedCells.FirstOrDefault();
			if (dataCellInfo.IsEmpty)
			{
				return;
			}
			_isPastingData = true;
			int num = gc.DataSource.Rows.IndexOf(dataCellInfo.Row) + 1 + e.PastingData.Count - gc.DataSource.Rows.Count;
			int num2 = gc.DataSource.Rows.Count - 1;
			for (int i = 0; i < num; i++)
			{
				_wrapper.InsertNewReocrd(num2 + i);
				UpdatingResult updatingResult = _wrapper.UpdateComponent(num2 + i, e.PastingData[i].ElementAt(0));
				if (updatingResult.ErrorMessage != null)
				{
					AesMessageBox.Show(Window.GetWindow(this), updatingResult.ErrorMessage, SystemEnvironment.ApplicationName, AesMessageBoxButton.OK, AesMessageBoxImage.Error);
					e.Cancel = true;
					List<int> list = new List<int>();
					list.Add(num2 + i);
					_wrapper.DeleteRecords(list);
					break;
				}
			}
			if (num > 0)
			{
				TryRefreshData();
			}
			base.Dispatcher.BeginInvoke((Action)delegate
			{
				_isPastingData = false;
			}, DispatcherPriority.DataBind);
		}

		private string GetCxsMonikerForCopy(DataCellInfo cell)
		{
			TdpcGridColumn tdpcGridColumn = cell.Column as TdpcGridColumn;
			string valueAsString = (cell.Row as TdpcGridRow)[0].ValueAsString;
			if (string.IsNullOrEmpty(valueAsString))
			{
				return null;
			}
			return $"cxs:{_mainNodePath}.Input.{tdpcGridColumn.GetRecordName()}.#0.{valueAsString}";
		}

		private string GetCellTextForCopy(DataCellInfo cell)
		{
			if (cell.Data != null)
			{
				return cell.Data.ValueAsString;
			}
			return null;
		}

		public void InitializeWithParentViewModel(TDependentPureComponent_ViewModel vm)
		{
			if (vm == null)
			{
				throw new ArgumentNullException("vm");
			}
			_vm = vm;
			_mainNodePath = vm.ExpandDataPath("@main");
			_ihNode = _vm.UnityContainer.GetNode(_mainNodePath);
			_wrapper = new TDependentPureComponentWrapper(_ihNode);
			InvalidateData();
		}

		public void InitialUserDefineHeaders(IEnumerable<string> headers)
		{
			_userDefineHeaderList.Clear();
			foreach (string header in headers)
			{
				_userDefineHeaderList.Add(header);
			}
		}

		public void ClearUserDefeineHeader()
		{
			_userDefineHeaderList.Clear();
		}

		public void OnUpdateDisplay()
		{
			InvalidateData();
		}

		public void OnClosed()
		{
			_wrapper?.UnloadMe();
		}

		private void InvalidateData()
		{
			if (_refreshDataOperation != null)
			{
				return;
			}
			_refreshDataOperation = base.Dispatcher.BeginInvoke((Action)delegate
			{
				try
				{
					TryRefreshData();
				}
				finally
				{
					_refreshDataOperation = null;
				}
			});
		}

		private void TryRefreshData()
		{
			if (_vm != null)
			{
				DataTable dataTable = EnsureDataTable();
				gc.DataSource = dataTable;
				int rowsCount = _wrapper.GetRowsCount();
				if (dataTable.Rows.Count != rowsCount)
				{
					dataTable.UpdateRows(rowsCount, GenerateDataRow);
				}
				else
				{
					dataTable.RefreshData();
				}
			}
		}

		private DataTable EnsureDataTable()
		{
			int num = ((_vm.ValuesCount_Var is CxvVariableData cxvVariableData) ? (CxsConverter.ValueToInt32(cxvVariableData.Value) ?? 0) : 0);
			DataTable dataTable = gc.DataSource;
			if (dataTable == null)
			{
				dataTable = new DataTable(RebuildDataColumns(num));
			}
			else if (dataTable.Columns.Count != num + 4)
			{
				dataTable = new DataTable(RebuildDataColumns(num));
			}
			return dataTable;
		}

		private IEnumerable<DataColumn> RebuildDataColumns(int valueColumnsCount)
		{
			List<DataColumn> list = new List<DataColumn>();
			list.Add(new TdpcGridColumn(TdpcColumnType.Component, ApwnResources.MMParam_PureCor_In_Para_MMFLabel0, DataRow.StringType, 140.0));
			list.Add(new TdpcGridColumn(TdpcColumnType.Source, ApwnResources.MMParam_Bi_Cor_Inp_Param_MMFLabel3, DataRow.StringType, 140.0));
			list.Add(new TdpcGridColumn(TdpcColumnType.TemperatureUnits, ApwnResources.MMParam_PureCor_In_Para_MMFLabel1, DataRow.StringType, 140.0));
			list.Add(new TdpcGridColumn(TdpcColumnType.PropertyUnits, ApwnResources.MMParam_PureCor_In_Para_MMFLabel2, DataRow.StringType, 120.0));
			for (int i = 0; i < valueColumnsCount; i++)
			{
				list.Add(TdpcGridColumn.CreateValueColumn(i));
			}
			return list;
		}

		private DataRow GenerateDataRow(int rowIndex)
		{
			return new TdpcGridRow(gc.DataSource, rowIndex);
		}

		private static void OnValueColumnsCountPropertyChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
		{
			(d as TDependentPureComponentGrid).InvalidateData();
		}

