			}
		}

		public FormatSpecification()
		{
		}

		public FormatSpecification(FormatOption formatOption, int precision)
		{
			FormatOption = formatOption;
			Precision = precision;
		}

		public string GetFormatString()
		{
			_ = $"f{Precision}";
			_ = $"e{Precision}";
			if (FormatOption == FormatOption.Fixed)
			{
				return $"f{Precision}";
			}
			if (FormatOption == FormatOption.Exponent)
			{
				return $"e{Precision}";
			}
			return $"g{Precision}";
		}

		public static FormatSpecification ParseShortTermText(string shortTermText)
		{
			FormatSpecification formatSpecification = new FormatSpecification
			{
				Precision = 2
			};
			if (!string.IsNullOrWhiteSpace(shortTermText))
			{
				string text = shortTermText.Trim();
				if (text.StartsWith("%."))
				{
					string text2 = text.Substring(2).Trim();
					if (!string.IsNullOrEmpty(text2))
					{
						string s = text2.Substring(0, text2.Length - 1);
						int result = 0;
						if (int.TryParse(s, out result))
						{
							formatSpecification.Precision = result;
							switch (text2.Last())
							{
							case 'e':
								formatSpecification.FormatOption = FormatOption.Exponent;
								break;
							case 'f':
								formatSpecification.FormatOption = FormatOption.Fixed;
								break;
							case 'g':
								formatSpecification.FormatOption = FormatOption.General;
								break;
							}
						}
					}
				}
			}
			return formatSpecification;
		}
	}
